import Foundation
import AppKit
import Combine
import CryptoKit
import Darwin
import OSLog

/// Durable lifecycle of a user response to a provider interaction. Selection is a completed user
/// action even before delivery is acknowledged; the provider acknowledgement remains a distinct
/// observed fact. This separation lets the authoritative file publish the user's choice before
/// agentd can resume execution without making the UI claim that the provider accepted it early.
enum InteractionResponseStatus: Codable, Equatable {
    case selected
    case accepted
    case rejected
    case acknowledgementMismatch
    case unknown(String)

    private var encodedValue: String {
        switch self {
        case .selected: "selected"
        case .accepted: "accepted"
        case .rejected: "rejected"
        case .acknowledgementMismatch: "acknowledgementMismatch"
        case .unknown(let value): value
        }
    }

    init(from decoder: Decoder) throws {
        let value = try decoder.singleValueContainer().decode(String.self)
        self = switch value {
        case "selected": .selected
        case "accepted": .accepted
        case "rejected": .rejected
        case "acknowledgementMismatch": .acknowledgementMismatch
        default: .unknown(value)
        }
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        try container.encode(encodedValue)
    }
}

/// A provider interaction can end without a response. Stop is cancellation, never an inferred Deny
/// or fabricated answer. Raw provider request handles remain in the private in-memory route; this
/// inert historical fact carries only the provider-neutral outcome and locally observed time.
struct InteractionClosure: Codable, Equatable {
    /// Strings are deliberate tolerant vocabulary: a newer daemon may add an outcome/reason and an
    /// older app must retain the row instead of failing the entire Conversation decode.
    var outcome: String
    var reason: String
    var observedAt: Date
    /// Record-local observation order. Optional for tolerant decode of every pre-C1.4 sidecar.
    var captureOrdinal: UInt64? = nil
}

enum InteractionResponseReleaseOutcome: Equatable {
    case delivered
    case persistenceFailed
    case ownershipLost
    case deliveryFailed
}

/// One composition point for the security-sensitive ordering shared by approvals and questions.
/// The provider-facing write is unreachable until publication succeeds and ownership is rechecked;
/// Stop during the file write therefore produces `ownershipLost`, never a late response.
@MainActor
func releaseInteractionResponseAfterPublication(
    publish: (@escaping (Bool) -> Void) -> Void,
    isStillOwned: @escaping () -> Bool,
    deliver: @escaping () -> Bool,
    completion: @escaping (InteractionResponseReleaseOutcome) -> Void
) {
    publish { published in
        guard published else {
            completion(.persistenceFailed)
            return
        }
        guard isStillOwned() else {
            completion(.ownershipLost)
            return
        }
        completion(deliver() ? .delivered : .deliveryFailed)
    }
}


/// One row in the transcript. A flat, Codable struct so individual fields can be
/// mutated in place by array index as streaming deltas and tool results arrive, and
/// so transcripts can be persisted verbatim.
struct TranscriptEntry: Identifiable, Codable, Equatable {
    enum Kind: String, Codable, Equatable {
        case user, assistant, system, tool, permission, question, compaction, review

        /// Raw values written by an older build that this one no longer models.
        ///
        /// A retired kind is a compatibility problem of the same class as a removed stored
        /// property, and worse in one way: `kind` is a non-optional `let` on a synthesized
        /// `Codable`, and neither read path tolerates a failure. `Conversation.init(from:)`
        /// decodes `[TranscriptEntry]` with no `Failable` wrapper, so one unknown raw value costs
        /// the whole conversation, and `LibraryAuthorityAdapter` throws before the row is ever
        /// reached. Retiring `memoryRecall` naively would therefore quarantine 1,265 rows across
        /// 40 of 146 conversations in a real library. The JSON sidecars hold none of them, so a
        /// sidecar-only test passes while every library-backed conversation breaks.
        static let retiredRawValues: Set<String> = ["memoryRecall"]

        /// Decode a retired kind as `.system` instead of failing the conversation.
        ///
        /// Deliberately narrow. Only a raw value this build does not know lands here, and it lands
        /// on the one kind that renders as a plain informational row. An unknown kind is a row the
        /// product can no longer explain, and showing it plainly is honest; refusing to open the
        /// conversation that contains it is not.
        init(from decoder: Decoder) throws {
            let raw = try decoder.singleValueContainer().decode(String.self)
            self = Kind(rawValue: raw) ?? .system
        }
    }

    enum GuidanceState: String, Codable, Equatable {
        case sending, delivered, queued, sentNext, cancelled
    }

    /// Who wrote a guidance row. Absent means the person typed it.
    ///
    /// **This exists to stop the app forging the person's own words.** A steer is stored as a
    /// `.user` row, and readers treat a `.user` row as something the person typed. App-authored
    /// text delivered through that channel unmarked is indistinguishable from their own message.
    ///
    /// Nothing writes an author today. The case is RETAINED, not vestigial: rows written by the
    /// retired Memory subsystem carry `memory_policy` on disk, and `decodeIfPresent` throws on a
    /// present-but-unknown value, so dropping it would fail every conversation that holds one.
    /// `guide(_:author:)` keeps its drop-rather-than-queue rule for whatever injects next.
    enum GuidanceAuthor: String, Codable, Equatable {
        /// Written by the retired Memory subsystem. Never the person. No longer produced.
        case memoryPolicy = "memory_policy"
    }

    /// Durable tool lifecycle. Older transcripts inferred this solely from a missing result, which
    /// made an interrupted command look permanently live after relaunch. Keep the field optional so
    /// those transcripts still decode; `resolvedToolState` treats a legacy result-less row as stopped.
    enum ToolState: String, Codable, Equatable {
        case running, succeeded, failed, stopped
    }

    var id = UUID()
    let kind: Kind
    var text: String = "" // user/assistant/system text; tool input summary
    /// Wall-clock time when Mechanician locally observed or created this transcript row. This is
    /// capture metadata, not a claim about when the provider-side event occurred. The default stamps
    /// newly constructed rows; the optional type lets synthesized decoding leave this nil when a
    /// historical sidecar has no key, rather than inventing a timestamp for existing history.
    var observedAt: Date? = Date()
    /// Monotonic record-local order assigned when Mechanician captures this row. It is deliberately
    /// independent of `observedAt`: equal or skewed wall clocks never become ordering evidence.
    /// Legacy rows remain nil and are reported as chronology-degraded by the canonical adapter.
    var captureOrdinal: UInt64? = nil
    /// Structured Claude subscription-limit detail. Optional so historical transcripts remain
    /// decodable; `recognizedUsageLimit(for:)` also upgrades old Claude wording in place without
    /// misclassifying a provider-neutral OpenAI/Anthropic API error.
    var usageLimit: UsageLimitError? = nil
    /// Structured non-terminal usage warning. Optional and defaulted, so a transcript written before
    /// this field decodes unchanged rather than quarantining the conversation it sits in — the trap
    /// that once dropped every older sidecar by adding a non-optional field to a persisted struct.
    var usageWarning: UsageWarning? = nil
    /// Provider-neutral terminal failure detail. The route-owned access lane is persisted with the
    /// error so background failures never render as whichever provider is currently selected.
    var providerFailure: ProviderFailure? = nil
    /// App-owned lifecycle notice that must survive navigation and relaunch even though ordinary
    /// system prose is transient. Stop escalation uses it to record a neutral fresh-session
    /// boundary for every conversation affected by one retired provider generation.
    var runtimeRecoveryNotice: Bool? = nil
    /// The exact user row owned by the failed root conversation turn. Provider-native reviews and
    /// other prompt-less operations leave this nil, preventing recovery UI from borrowing an
    /// unrelated historical prompt merely because it happens to be the nearest user row.
    var providerFailurePromptID: UUID? = nil

    /// A provider-native code review is not an ordinary user/model exchange. Keeping its identity
    /// and lifecycle on a distinct transcript row prevents future provider history replay from
    /// turning a Review button click into a fabricated prompt.
    var review: ProviderReview? = nil

    /// The provider frame this row belongs to, so a refusal-fallback can retract exactly the rows it
    /// named. Optional — and every field below is too — because `TranscriptEntry` has fully
    /// synthesized `Codable`: a non-optional field here would fail to decode in every sidecar written
    /// before this build and quarantine those conversations whole (the 0.11.7 bug).
    var providerFrameUUID: String? = nil
    /// Set when the provider retracted this row and named what replaced it. A retracted assistant row
    /// is evicted outright; a retracted TOOL row is kept and marked, because the call may already
    /// have run and deleting it would erase evidence of something that happened on the user's Mac.
    var supersededByFrameUUID: String? = nil
    /// Portable-neutral supersession identity. Provider frame handles above remain private capture
    /// correlation; canonical records link these record-local UUIDs and never expose those handles.
    var supersessionEventID: UUID? = nil
    var supersededByEntryID: UUID? = nil
    var supersessionCaptureOrdinal: UInt64? = nil
    /// Provider attribution for a safety refusal, on the system row that reports it.
    var refusal: ClaudeRefusalRecord? = nil

    // context compaction (optional for backward-compatible transcript decoding)
    var compactionTrigger: String? = nil
    var compactionPreTokens: Int? = nil
    var compactionPostTokens: Int? = nil
    /// Per-turn provider order used to pair Claude's independent hook and stream surfaces when one
    /// turn compacts more than once. Optional for historical rows and payload-free Codex markers.
    var compactionSequence: Int? = nil
    /// Exact provider-authored continuity summary when the provider exposes it. Claude supplies
    /// this through the SDK's PostCompact hook; Codex's compaction item is intentionally opaque.
    var compactionSummary: String? = nil
    /// Open provenance for `compactionSummary` (currently `claude_post_compact`). Keeping this next
    /// to the text prevents an app-derived synopsis from later masquerading as provider state.
    var compactionSummarySource: String? = nil
    /// True only when the daemon applied its control-channel safety cap to an unusually large
    /// provider summary. Nil/false means the persisted text is exact.
    var compactionSummaryTruncated: Bool? = nil
    /// The route that owned this boundary. Optional for historical rows written before compaction
    /// attribution was persisted.
    var compactionAccess: ModelAccess? = nil

    /// App-owned audit marker for a provider result read from the signed Mechanician Help corpus.
    /// The row remains an ordinary `.system` entry so older builds render its concise text rather
    /// than failing to decode a new transcript kind.
    var helpConsultationReceipt: Bool? = nil
    /// App-owned marker for the row that says background agents outlived their turn. It is the only
    /// record of why that run's later tool calls were refused, so it is durable transcript evidence
    /// rather than a transient notice. Optional so older sidecars still decode.
    var backgroundWorkOutlivedTurn: Bool? = nil
    var helpConsultationCorpusID: String? = nil
    var helpConsultationClaimCount: Int? = nil
    var helpConsultationTurnID: String? = nil
    var compactionError: String? = nil
    /// Turn that emitted this compaction marker. Failed markers are provisional until that turn
    /// terminates: a successful fallback removes only its own marker, while a terminal failure
    /// keeps it as audit evidence. Optional for historical transcript compatibility.
    var compactionTurnID: String? = nil

    /// Image files referenced by a USER message (pasted screenshots / attached image files) — the
    /// prompt text carries their PATHS for the agent, but the transcript renders these as inline
    /// previews instead of raw path strings. Optional so older persisted transcripts still decode.
    var imagePaths: [String]? = nil
    /// A user message delivered into an already-running provider turn. Optional so historical
    /// transcripts remain compatible and ordinary user messages keep their existing presentation.
    var guidanceState: GuidanceState? = nil
    /// Provider-owned explanation retained for historical guidance rows. New undelivered guidance
    /// moves out of the transcript and into the durable queue, so it has one canonical presentation.
    var guidanceFailureReason: String? = nil

    // tool
    var toolName: String? = nil
    var toolResult: String? = nil
    var toolIsError = false
    /// Set when this call never ran because the person declined it.
    ///
    /// A declined call still returns a `tool_result` carrying an error, because from the
    /// transport's point of view it did not succeed. Reporting that as a failure says the tool
    /// broke when it never executed. That is the same untruth `Outcome.refused` exists to keep out
    /// of the learning record, surfacing one layer up in the transcript, where the person can
    /// actually see it sitting next to the card that says they denied it.
    ///
    /// Optional so older transcripts decode unchanged, and so a build without this key ignores it
    /// rather than losing the row.
    var toolRefused: Bool? = nil
    var toolUseId: String? = nil // links a Workflow tool call to its run
    /// Private capture alias for the agent that issued this call. Root uses `root`; delegated
    /// callers retain their runtime-derived `subagent:<alias>` identity. Portable export remints
    /// these aliases and never exposes the provider/runtime handle verbatim.
    var toolOwnerAgentID: String? = nil
    /// Private provider turn alias that owned this call. Optional so historical transcript rows
    /// decode tolerantly; portable export remints it into record-local identity.
    var toolTurnID: String? = nil
    var toolState: ToolState? = nil
    /// A tool result or terminal refinement is observed after the call row itself. Retaining that
    /// distinct ordinal avoids pretending the call and result happened at one instant.
    var toolResultCaptureOrdinal: UInt64? = nil
    var toolTerminalCaptureOrdinal: UInt64? = nil
    /// Canonical, content-free proof emitted by an app-owned typed adapter. Ordinary tool output,
    /// assistant prose, and legacy flattened rows never populate it. Optional so every transcript
    /// written before typed receipts existed continues to decode without repair.
    var verifiedKnowledgeReceipt: Data? = nil
    /// Retired. Learned skills are gone, so nothing writes this any more.
    ///
    /// It is kept rather than deleted because transcripts written before the removal carry it, and
    /// `isDurableSystemTranscriptEntry` reads it: dropping the field would quietly reclassify those
    /// historical disclosure rows as disposable session UI and lose them on the next save.
    var learnedSkillApplicationReceipt: Data? = nil
    /// Captured tool media is stored outside the conversation JSON. This lightweight reference is
    /// optional so historical tool images remain decodable and can render an honest unavailable
    /// state instead of pretending their never-persisted image still exists.
    var toolImage: ToolImageReference? = nil

    // permission
    /// Nil means the person authored this row, which is every historical row and every row they
    /// type. Optional so transcripts written before injected guidance existed decode unchanged;
    /// synthesized `Decodable` reads an optional with `decodeIfPresent`.
    var guidanceAuthor: GuidanceAuthor? = nil
    var permissionId: String? = nil
    var permName: String? = nil
    var permDecided = false
    var permAllowed = false
    var permAlways: Bool? = nil
    /// Set when this approval exists only because the write lands outside the workspace. Write
    /// containment deliberately runs ahead of the permission mode, so this card appears in every
    /// mode including Bypass permissions. Without these the card claims the agent "wants to modify
    /// files in this workspace" — the opposite of why it asked — and bypass looks broken.
    /// Optional so older sidecars still decode.
    var permWriteEscapeTarget: String? = nil
    var permWriteEscapeWorkspace: String? = nil
    /// The user's selected response is published before delivery. `permDecided` remains false until
    /// the matching provider route acknowledges it, preserving the existing truthful UI contract.
    var interactionResponseStatus: InteractionResponseStatus? = nil
    var interactionResponseObservedAt: Date? = nil
    var interactionAcknowledgedAt: Date? = nil
    var interactionResponseCaptureOrdinal: UInt64? = nil
    var interactionAcknowledgedCaptureOrdinal: UInt64? = nil
    var interactionClosure: InteractionClosure? = nil

    // question (mcp__ask__Question). All optional so older persisted transcripts, which
    // lack these keys, still decode (synthesized Decodable uses nil for missing optionals).
    var questionId: String? = nil
    var questions: [AskQuestion]? = nil
    var questionDecided: Bool? = nil
    var questionAnswers: [String: String]? = nil // question text -> chosen answer, for display
    /// Free-form "Other" text crosses the provider boundary too; retaining it closes the historical
    /// hole where the provider received an answer that the conversation file silently discarded.
    var questionFreeTextResponse: String? = nil

    var resolvedToolState: ToolState {
        // A real result is authoritative even if a partially persisted older row retained a stale
        // lifecycle value. A result-less legacy row has no live process owner after decode.
        if toolResult != nil { return toolIsError ? .failed : .succeeded }
        return toolState ?? .stopped
    }

    var isSuperseded: Bool {
        supersessionEventID != nil || supersededByEntryID != nil
            || supersededByFrameUUID != nil
    }

    func recognizedUsageLimit(for access: ModelAccess?) -> UsageLimitError? {
        if let usageLimit { return usageLimit }
        // Conversations predating persisted model identity were Claude-only in practice, so retain
        // that migration path. A known non-Claude route must never borrow the Claude card.
        guard access == nil || access == .claudeSubscription else { return nil }
        return UsageLimitError.legacy(message: text)
    }
}

/// Durable presentation and lifecycle for one provider-native code review. The first adapter is
/// Codex `review/start` over the conversation's existing thread; additional providers or targets
/// can extend these enums without changing ordinary transcript history.
struct ProviderReview: Codable, Equatable {
    enum Target: String, Codable, Equatable {
        case uncommittedChanges

        var title: String {
            switch self {
            case .uncommittedChanges: return "Uncommitted Changes"
            }
        }
    }

    enum Status: String, Codable, Equatable {
        case running, completed, failed, stopped
    }

    var provider: ModelAccess
    var providerReviewID: String
    var target: Target
    var status: Status
    var startedAt: Date
    var endedAt: Date? = nil

    var title: String { "Codex Review · \(target.title)" }
}

/// Actionable, persisted detail for a Claude subscription usage-limit error. This is intentionally
/// separate from API billing/rate-limit errors: the SDK emits it only for claude.ai plan limits.
/// The non-terminal usage warning: nothing is blocked, and things have quietly started changing.
///
/// `allowed_warning` is the state where a person is past a threshold of their allowance and every
/// request still succeeds. Claude stops doing some things there — follow-up prompt suggestions are
/// the observed one, skipped by the CLI whenever the status is anything other than `allowed`. So at
/// 75% of a weekly window a feature disappears with no message and no setting.
///
/// That was reported as a bug twice, and two investigations blamed the SDK before the account's own
/// usage turned out to be the cause. It is also the only notice anyone gets BEFORE being cut off,
/// which is worth more than the notice afterwards.
struct UsageWarning: Codable, Equatable {
    var rateLimitType: String? = nil
    /// Fraction of the allowance used, 0–1, as Claude reported it.
    var utilization: Double? = nil
    var resetsAt: Date? = nil
    var isUsingOverage: Bool? = nil

    var title: String {
        switch rateLimitType {
        case "five_hour": return String(localized: "Most of your Claude 5-hour allowance is used")
        case "seven_day_opus": return String(localized: "Most of your weekly Opus allowance is used")
        case "seven_day_sonnet":
            return String(localized: "Most of your weekly Sonnet allowance is used")
        case "seven_day", "seven_day_overage_included":
            return String(localized: "Most of your weekly Claude allowance is used")
        case "overage": return String(localized: "Most of your usage credits are spent")
        default: return String(localized: "Most of your Claude allowance is used")
        }
    }

    /// Whole per cent, or nil when Claude did not say. Never rounded up to 100: a person told they
    /// are at 100% and still working would reasonably think the number is wrong.
    var percentUsed: Int? {
        guard let utilization, utilization > 0 else { return nil }
        return min(99, Int((utilization * 100).rounded()))
    }

    static func from(event: [String: Any]) -> UsageWarning? {
        guard event["status"] as? String == "allowed_warning" else { return nil }
        var resetDate: Date?
        if let raw = (event["resetsAt"] as? NSNumber)?.doubleValue, raw > 0 {
            // Seconds or milliseconds, the same tolerance the terminal error already applies.
            resetDate = Date(timeIntervalSince1970: raw > 10_000_000_000 ? raw / 1_000 : raw)
        }
        return UsageWarning(
            rateLimitType: event["rateLimitType"] as? String,
            utilization: (event["utilization"] as? NSNumber)?.doubleValue,
            resetsAt: resetDate,
            isUsingOverage: event["isUsingOverage"] as? Bool)
    }
}

struct UsageLimitError: Codable, Equatable {
    var rateLimitType: String? = nil
    var resetsAt: Date? = nil
    var overageDisabledReason: String? = nil

    var creditsExhausted: Bool { overageDisabledReason == "out_of_credits" }

    var title: String {
        switch rateLimitType {
        case "five_hour": return "Claude 5-hour usage limit reached"
        case "seven_day_opus": return "Claude weekly Opus limit reached"
        case "seven_day_sonnet": return "Claude weekly Sonnet limit reached"
        case "seven_day", "seven_day_overage_included": return "Claude weekly usage limit reached"
        case "overage": return "Claude usage-credit limit reached"
        default: return "Claude usage limit reached"
        }
    }

    /// Concise causal copy for child runs terminated with the parent. `title` is a complete status
    /// phrase ending in “reached”; interpolating it before “ended the parent turn” produces the
    /// ungrammatical “…limit reached ended…”.
    var delegatedFailureReason: String {
        "Stopped because Claude’s usage limit ended the parent turn."
    }

    static func from(event: [String: Any], message: String) -> UsageLimitError? {
        guard event["errorKind"] as? String == "usage_limit" || legacy(message: message) != nil else {
            return nil
        }
        var resetDate: Date?
        if let raw = (event["resetsAt"] as? NSNumber)?.doubleValue, raw > 0 {
            // Accept either Unix seconds or milliseconds so an SDK wire-format change cannot show
            // a nonsensical reset date.
            resetDate = Date(timeIntervalSince1970: raw > 10_000_000_000 ? raw / 1_000 : raw)
        }
        return UsageLimitError(
            rateLimitType: event["rateLimitType"] as? String ?? legacy(message: message)?.rateLimitType,
            resetsAt: resetDate,
            overageDisabledReason: event["overageDisabledReason"] as? String)
    }

    /// Upgrade already-persisted errors from before structured SDK rate-limit events were wired.
    /// Keep this deliberately narrow so an ordinary API 429 is not mislabeled as plan exhaustion.
    static func legacy(message: String) -> UsageLimitError? {
        let lower = message.lowercased()
        if lower.contains("weekly limit") {
            return UsageLimitError(rateLimitType: "seven_day")
        }
        if lower.contains("5-hour limit") || lower.contains("five-hour limit") {
            return UsageLimitError(rateLimitType: "five_hour")
        }
        if lower.contains("usage limit") && lower.contains("resets") {
            return UsageLimitError()
        }
        return nil
    }
}

/// One selectable choice in an ask-the-user question.
struct AskOption: Codable, Hashable {
    let label: String
    var description: String = ""
    var preview: String? = nil
}

/// One question posed by the mcp__ask__Question tool.
struct AskQuestion: Codable, Hashable {
    let question: String
    var header: String = ""
    var options: [AskOption] = []
    var multiSelect: Bool = false
}

/// One open terminal tab. Its `id` is the termId agentd keys the PTY on.
struct TerminalTab: Identifiable, Equatable {
    let id: String
    var title: String
    var starting = true
    var exited = false
}

/// A developer-tools state that blocks git/build until the user fixes it.
enum DevToolIssue: String, Equatable {
    case xcodeLicense = "xcode_license" // `sudo xcodebuild -license accept`
    case devTools = "dev_tools"         // `xcode-select --install`
}

/// Wait-mode: the agent called `WaitFor` to declare it's waiting for an external event, so the
/// conversation auto-resumes when the trigger fires (a shell `check` succeeds and/or a `deadline`
/// passes) instead of sitting idle forever after "I'll wait for X." Persisted so the ⏳ state
/// survives restarts and syncs across windows.
struct ArmedTrigger: Codable, Equatable {
    var note: String                 // human description ("waiting for notarization to finish")
    var check: String?               // shell command polled in the conv's cwd; fires on exit 0
    var deadline: Date?              // fires when this time passes (from `after`)
    var everySeconds: Double = 30    // poll interval for `check` (floored by the scheduler)
    var armedAt: Date
    var expiresAt: Date              // hard cap so a never-satisfied wait can't poll forever
    var lastCheckedAt: Date? = nil   // throttles polling; runtime-only, deliberately not persisted

    // lastCheckedAt is excluded: persisting it rewrote the entire conversation JSON once per poll
    // interval purely to stamp a throttle. A missing value on relaunch just means the next tick
    // polls immediately, which is the wanted behavior. Legacy sidecars that still contain the key
    // decode fine (unknown keys are ignored).
    private enum CodingKeys: String, CodingKey {
        case note, check, deadline, everySeconds, armedAt, expiresAt
    }

    /// A short "waiting for X" summary for the ⏳ chip / tooltip.
    ///
    /// Callers prefix "Waiting ", and a note written naturally almost always begins with "waiting
    /// for …" — which read as "Waiting waiting for the check to finish". Strip the redundant lead
    /// rather than asking every caller to phrase around it.
    var summary: String {
        if !note.isEmpty { return ArmedTrigger.withoutLeadingWaiting(note) }
        if let d = deadline { return "until \(d.formatted(date: .omitted, time: .shortened))" }
        return check.map { "until `\($0)` succeeds" } ?? "for an event"
    }

    /// "waiting for X" / "Waiting on X" → "for X" / "on X". Only strips a LEADING occurrence, so a
    /// note that merely mentions waiting later is untouched.
    static func withoutLeadingWaiting(_ note: String) -> String {
        let trimmed = note.trimmingCharacters(in: .whitespacesAndNewlines)
        let lowered = trimmed.lowercased()
        guard lowered.hasPrefix("waiting ") else { return trimmed }
        let remainder = String(trimmed.dropFirst("waiting ".count))
            .trimmingCharacters(in: .whitespacesAndNewlines)
        return remainder.isEmpty ? trimmed : remainder
    }
}

enum ModelMaker: String, Codable, Hashable {
    case anthropic
    case openAI = "openai"
}

/// The account/runtime lane through which a model is available. Maker alone is insufficient:
/// Claude subscription and Anthropic API credentials are independent, as are Codex subscription
/// and direct OpenAI API access. Stable raw values make this safe to persist before runtime pooling
/// and the richer catalog UI arrive.
enum ModelAccess: String, Codable, Hashable, Sendable {
    case claudeSubscription = "claude_subscription"
    case anthropicAPI = "anthropic_api"
    case codexSubscription = "codex_subscription"
    case openAIAPI = "openai_api"
    /// Claude served through Google Vertex AI (FR-103, enterprise). A first-class lane distinct from
    /// `claudeSubscription`: same Claude engine + models, but authenticated with Google ADC via a
    /// `vertex` auth mode instead of an Anthropic OAuth login. Being a separate case is what keeps its
    /// sessions, credential namespace, and scoped allowlist from ever bleeding into plain Claude — the
    /// pool, resume guard, and allowlist all key on `ModelAccess`. Present only while the active signed
    /// tenant profile declares a `claude-vertex` route (see ``allCases``); otherwise inert.
    case claudeVertex = "claude_vertex"
    /// Claude served through AWS Bedrock. Like `claudeVertex` it is the same Claude engine reached
    /// through someone else's cloud, but its credentials are ORDINARY AWS credentials — the standard
    /// chain (`AWS_PROFILE`, environment, SSO, instance role) that the user's own `aws` CLI already
    /// resolves. That is why it needs no interactive account flow: unlike Vertex there is no OAuth
    /// loopback and no app-managed credential file to write. Present only while the active signed
    /// tenant profile declares a `claude-bedrock` route.
    case claudeBedrock = "claude_bedrock"

    var maker: ModelMaker {
        switch self {
        case .claudeSubscription, .anthropicAPI, .claudeVertex, .claudeBedrock: return .anthropic
        case .codexSubscription, .openAIAPI: return .openAI
        }
    }

    /// Routes whose credentials are acquired and removed through agentd's browser/account control
    /// protocol. Vertex is not a subscription, but it intentionally shares the same request-owned
    /// connect/reconnect/disconnect state machine as Claude and Codex subscription accounts.
    var usesInteractiveAccountFlow: Bool {
        switch self {
        case .claudeSubscription, .codexSubscription, .claudeVertex: return true
        // Bedrock resolves AWS credentials the way every other AWS tool does; there is nothing for
        // Mechanician to broker, so it behaves like a key-configured lane rather than a login.
        case .anthropicAPI, .openAIAPI, .claudeBedrock: return false
        }
    }

    /// The daemon's `authMode` string for this lane, and the inverse of `init(provider:authMode:)`.
    ///
    /// Exists so route facts can be looked up by the same name in both languages. `ProviderFacts`
    /// is generated from one source and is keyed by the daemon's route names, so anything comparing
    /// against it has to speak them; deriving the name here keeps that translation in one place
    /// rather than letting each call site re-list which cases are Vertex and which are Bedrock.
    var daemonAuthMode: String {
        switch self {
        case .claudeSubscription: return "subscription"
        case .anthropicAPI: return "apikey"
        case .codexSubscription: return "subscription"
        case .openAIAPI: return "apikey"
        case .claudeVertex: return "vertex"
        case .claudeBedrock: return "bedrock"
        }
    }

    init(provider: String, authMode: String) {
        switch provider {
        case "codex": self = .codexSubscription
        case "openai": self = .openAIAPI
        default:
            switch authMode {
            case "subscription": self = .claudeSubscription
            case "vertex": self = .claudeVertex
            case "bedrock": self = .claudeBedrock
            default: self = .anthropicAPI
            }
        }
    }

    init(accountChoice: String) {
        switch accountChoice {
        case "subscription": self = .claudeSubscription
        case "codex": self = .codexSubscription
        case "openai": self = .openAIAPI
        case "vertex": self = .claudeVertex
        case "bedrock": self = .claudeBedrock
        default: self = .anthropicAPI
        }
    }

    /// Maps a tenant-profile route adapter to its enterprise lane. Built-in adapters
    /// (`claude-subscription`, `anthropic-api`, …) return nil — they are always present via
    /// ``builtInCases`` and are never re-added from a profile.
    init?(adapter: String) {
        switch adapter {
        case "claude-vertex": self = .claudeVertex
        case "claude-bedrock": self = .claudeBedrock
        default: return nil
        }
    }
}

/// Durable identity for the model that owns a provider session. A workspace will eventually supply
/// this as the default for new conversations; after the first real turn the conversation owns it.
struct ModelSelection: Codable, Equatable, Hashable, Sendable {
    var access: ModelAccess
    var modelID: String
}

/// The complete model-visible capability surface for one provider session. Keep this closed and
/// typed on the app side: an unknown persisted value is not "standard" and must never regain a
/// broader schema by default.
enum ProviderToolProfile: String, Codable, Equatable, Hashable, Sendable {
    case standard
    case helpExpert = "help-expert"

    /// Help retrieval is useful in ordinary and dedicated Help conversations. The Help expert's
    /// other closed capabilities are signed presentation and, outside Plan, bounded app operation.
    var permitsHelpSearch: Bool {
        self == .standard || self == .helpExpert
    }

    /// A direct, interactive conversation may ask the app to present one signed native guide or
    /// perform one bounded app operation. Review, unattended, and operation-in-Plan restrictions
    /// are enforced independently at the exact root-turn route.
    var permitsMechanicianGuidance: Bool {
        self == .standard || self == .helpExpert
    }

    /// Only ordinary conversations participate in the user's external MCP readiness protocol.
    /// Closed product workspaces mount release-owned tool sets instead.
    var awaitsExternalExtensionReadiness: Bool {
        self == .standard
    }

    /// Keep an ordinary conversation's session revision tied to the configured external server
    /// generation while making Help independent of it. The daemon separately enforces each
    /// mounted schema.
    var includesExternalExtensionRevision: Bool {
        switch self {
        case .standard: true
        case .helpExpert: false
        }
    }
}

/// One conversation-scoped reason a provider/model lane cannot be changed yet. Keeping the
/// projection pure gives the bridge and picker one ordering and one vocabulary for blockers.
enum ConversationAccessChangeBlocker: Equatable {
    case reservedTurn
    case delegatedWork(count: Int)
    case providerAccessRequest
    case queuedPrompts(count: Int)
    case armedWait

    static func project(
        hasReservedTurn: Bool,
        delegatedWorkCount: Int,
        hasProviderAccessRequest: Bool,
        queuedPromptCount: Int,
        hasArmedWait: Bool
    ) -> Self? {
        if hasReservedTurn { return .reservedTurn }
        if delegatedWorkCount > 0 { return .delegatedWork(count: delegatedWorkCount) }
        if hasProviderAccessRequest { return .providerAccessRequest }
        if queuedPromptCount > 0 { return .queuedPrompts(count: queuedPromptCount) }
        if hasArmedWait { return .armedWait }
        return nil
    }

    var notice: String {
        switch self {
        case .reservedTurn:
            return "Finish or stop this conversation's active turn before changing providers."
        case .delegatedWork:
            return "Finish or stop this conversation's active work before changing providers."
        case .providerAccessRequest:
            return "Complete or cancel this conversation's provider-access request before changing providers."
        case .queuedPrompts:
            return "Run or clear this conversation's queued prompts before changing providers."
        case .armedWait:
            return "Cancel this conversation's wait before changing providers."
        }
    }

    var pickerTitle: String {
        switch self {
        case .reservedTurn:
            return "Turn in progress"
        case .delegatedWork(let count):
            return "\(count) active \(count == 1 ? "agent" : "agents")"
        case .providerAccessRequest:
            return "Provider access pending"
        case .queuedPrompts(let count):
            return "\(count) queued \(count == 1 ? "prompt" : "prompts")"
        case .armedWait:
            return "Conversation wait armed"
        }
    }

    var pickerDetail: String {
        switch self {
        case .reservedTurn, .delegatedWork:
            return "Stop active work before changing this conversation’s model provider."
        case .providerAccessRequest:
            return "Complete or cancel the provider request before changing providers."
        case .queuedPrompts:
            return "Run or clear the queue before changing providers."
        case .armedWait:
            return "Cancel the wait before changing providers."
        }
    }

    var canStopActiveWork: Bool {
        switch self {
        case .reservedTurn, .delegatedWork: return true
        case .providerAccessRequest, .queuedPrompts, .armedWait: return false
        }
    }
}

/// A persisted conversation: its transcript plus the SDK session id needed to resume
/// it with full context, and the working directory it ran in.
/// Decodes `T`, but a per-element failure yields nil instead of propagating — so one undecodable
/// dictionary element (a corrupt or schema-incompatible delegate row) can't abort the whole enclosing
/// `Conversation` decode and drop the conversation. The defense-in-depth backstop behind the tolerant
/// `SubagentRun`/`WorkflowRun` decoders: even an unforeseen breakage costs one delegate row, never the
/// conversation and its messages.
private struct Failable<T: Decodable>: Decodable {
    let value: T?
    init(from decoder: Decoder) throws { value = try? T(from: decoder) }
}

enum ConversationSuggestedPromptSource: String, Codable, Equatable, Sendable {
    case provider
    case onDevice
}

/// A follow-up belongs to the conversation that produced it, not to whichever window happens to
/// be visible. The source and exact turn endpoints keep delayed local work from being mistaken for
/// a newer provider suggestion while the text itself remains ready to insert into the message box.
struct ConversationSuggestedPrompt: Codable, Equatable, Sendable {
    /// Version 1 means the record passed the source-appropriate publication policy: provider text
    /// came from the provider's native suggestion surface, while local text passed Mechanician's
    /// assistant-prescribed direct-action policy. A missing value is a legacy local record: the
    /// older generator could publish questions, copied examples, or context-mined actions that the
    /// current UI must not restore.
    static let currentQualityPolicyVersion = 1

    let text: String
    let source: ConversationSuggestedPromptSource
    let rootPromptEntryID: UUID?
    let assistantEntryID: UUID?
    let qualityPolicyVersion: Int

    init(
        text: String,
        source: ConversationSuggestedPromptSource,
        rootPromptEntryID: UUID?,
        assistantEntryID: UUID?,
        qualityPolicyVersion: Int = ConversationSuggestedPrompt.currentQualityPolicyVersion
    ) {
        self.text = text
        self.source = source
        self.rootPromptEntryID = rootPromptEntryID
        self.assistantEntryID = assistantEntryID
        self.qualityPolicyVersion = qualityPolicyVersion
    }

    private enum CodingKeys: String, CodingKey {
        case text
        case source
        case rootPromptEntryID
        case assistantEntryID
        case qualityPolicyVersion
    }

    /// Prompt records predate quality-policy provenance. Decode that absence as legacy without
    /// rejecting the enclosing Conversation; `validated(in:)` then keeps provider-owned text but
    /// retires a pre-policy local presentation hint through the declared normalization path.
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        text = try c.decode(String.self, forKey: .text)
        source = try c.decode(ConversationSuggestedPromptSource.self, forKey: .source)
        rootPromptEntryID = try c.decodeIfPresent(UUID.self, forKey: .rootPromptEntryID)
        assistantEntryID = try c.decodeIfPresent(UUID.self, forKey: .assistantEntryID)
        qualityPolicyVersion = try c.decodeIfPresent(
            Int.self, forKey: .qualityPolicyVersion) ?? 0
    }

    /// A durable suggestion is valid only while both ends of the turn that produced it still exist
    /// in order and while its source provenance is understood. Provider-owned legacy text remains
    /// authoritative; pre-policy local text does not. These checks keep a rewind, compaction, or
    /// partially-written future record from restoring a prompt over a different transcript.
    func validated(in messages: [TranscriptEntry]) -> ConversationSuggestedPrompt? {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        let hasValidSourcePolicy = switch source {
        case .provider:
            (0...Self.currentQualityPolicyVersion).contains(qualityPolicyVersion)
        case .onDevice:
            qualityPolicyVersion == Self.currentQualityPolicyVersion
        }
        guard hasValidSourcePolicy,
              !trimmed.isEmpty,
              let rootPromptEntryID,
              let assistantEntryID,
              let rootIndex = messages.firstIndex(where: {
                  $0.id == rootPromptEntryID && $0.kind == .user
              }),
              let assistantIndex = messages.firstIndex(where: {
                  $0.id == assistantEntryID && $0.kind == .assistant
              }),
              rootIndex < assistantIndex,
              !messages[messages.index(after: assistantIndex)...].contains(where: {
                  $0.kind == .user
                      && SuggestedPromptFallback.shouldRetireExistingSuggestion(for: $0.text)
              }) else { return nil }
        return self
    }
}

struct Conversation: Identifiable, Codable {
    var id = UUID()
    var title: String
    /// Durable provenance prevents a delayed model result from overwriting a title the person chose.
    /// Sidecars written before provenance existed decode as `legacy` and stay untouched unless the
    /// person explicitly asks to regenerate them.
    var titleSource: ConversationTitleSource
    var cwd: String
    var sdkSessionId: String?
    /// Fingerprint of the signed enterprise backend that owns `sdkSessionId`. Built-in provider
    /// sessions leave this nil. Legacy Vertex sessions also decode nil and therefore start fresh.
    var sdkSessionRouteIdentity: String? = nil
    /// Complete built-in + external tool configuration mounted when `sdkSessionId` was created.
    /// Claude's tool schema is session-scoped; resuming under a different revision can advertise a
    /// stale tool without mounting its dispatcher. Optional only for tolerant legacy decoding.
    var sdkSessionExtensionRevision: UUID? = nil
    /// Immutable tool surface mounted when `sdkSessionId` was created. This receipt is deliberately
    /// explicit in addition to being folded into `sdkSessionExtensionRevision`. A missing legacy
    /// receipt retains the historical standard surface; an invalid decoded receipt fails closed
    /// instead of being widened to standard.
    var sdkSessionToolProfile: ProviderToolProfile? = nil
    /// Standing instructions and workspace identity mounted for `sdkSessionId`. Codex threads cache
    /// developer instructions, so a mismatch deliberately starts once with durable history replay;
    /// Claude can update its preset append while resuming and keeps the session.
    var sdkSessionWorkspaceInstructionsRevision: String? = nil
    /// Provider/account route and model used for this conversation's latest real turn. Optional for
    /// tolerant migration: legacy conversations acquire it when they next send instead of guessing
    /// from an opaque provider session id.
    var modelSelection: ModelSelection? = nil
    var messages: [TranscriptEntry]
    var updatedAt: Date
    /// Local branch provenance for today's JSON authority. This is deliberately not a portable
    /// lineage identifier: the record-format review keeps the source Conversation UUID separate from the future
    /// record lineage and private file-instance identities.
    var forkProvenance: ConversationForkProvenance? = nil
    var artifacts: [Artifact] = []
    var workflowRuns: [String: WorkflowRun] = [:]
    var subagents: [String: SubagentRun] = [:]
    /// Bounded, provider-truthful execution history for the Agents activity timeline.
    var agentActivity: [AgentActivityRecord] = []
    /// Highest record-local capture ordinal ever published, including facts later superseded or
    /// compacted away. Persisted with ordinary snapshots so relaunch cannot reuse an old identity.
    var captureOrdinalHighWatermark: UInt64? = nil
    /// Highest capture ordinal owned by a provider access that this Conversation has left.
    ///
    /// User-authored rows on either side remain portable. Provider-generated replies at or below
    /// this boundary stay visible in the durable transcript but never enter another provider's
    /// replay, where they could otherwise carry access-fenced memory or tool results across lanes.
    /// Optional for tolerant legacy decoding; the first cross-access retarget establishes it.
    var providerHistoryReplayCutoffOrdinal: UInt64? = nil
    /// Composer prompts queued behind the current turn — persisted so a queue survives a
    /// window/app restart (the user lost queued confirmations once when a session ended).
    var queuedPrompts: [String] = []
    /// The accepted-but-unacknowledged send: written durably BEFORE the provider request so a
    /// crash between Send and the daemon's turn_started acknowledgement cannot lose the user's
    /// words (previously they lived only in memory until the turn's terminal event). Cleared in
    /// the same durable write that lands the user entry in `messages`; a value found at load is
    /// crash evidence and is healed to the front of the paused queue, never auto-sent. Optional
    /// and tolerant-decoded, so older sidecars and older builds are unaffected (an old build's
    /// re-encode drops it, which degrades to today's behavior).
    var pendingTurnPrompt: String? = nil
    /// Unsent composer text for THIS conversation — persisted so each conversation keeps its own
    /// queued-up message independently (switching conversations swaps the input box). Distinct from
    /// queuedPrompts (prompts parked behind a running turn); this is the live, not-yet-sent draft.
    var draft: String = ""
    /// Provider- or device-authored follow-up for THIS conversation. It survives navigation and
    /// relaunch until the person accepts it, starts a newer turn, or a newer suggestion replaces it.
    var suggestedPrompt: ConversationSuggestedPrompt? = nil
    /// Starred → pinned to the top of the sidebar (favorites-first ordering). Persisted so it
    /// syncs across windows like the title does.
    var favorite: Bool = false
    /// Explicit manual position from drag-to-reorder. nil until the list is hand-ordered, after
    /// which the sidebar honors this instead of recency. Favorites still sort above non-favorites.
    var sortIndex: Int? = nil
    /// Wait-mode: set when the agent armed a `WaitFor` trigger; nil when idle/running. Drives the
    /// ⏳ indicator and the in-app scheduler that auto-resumes the conversation when it fires.
    var armedTrigger: ArmedTrigger? = nil
    /// A new assistant result arrived while this conversation wasn't being viewed (Mail-style unread).
    /// Set when a backgrounded turn finishes; cleared when the user opens it. Persisted so the dot
    /// survives relaunch and syncs across windows.
    var unread: Bool = false
    /// The last turn ended in an error — drives the sidebar error badge. Set on any `error` event
    /// (foreground or background); cleared when a new turn starts for this conversation (a retry/send
    /// supersedes the failure). Persisted so it survives relaunch and syncs across windows.
    var errored: Bool = false
    /// The Project (container) this conversation belongs to; nil = a loose Home conversation (no Project)
    /// (a quick one-off that was never filed into a project). Persisted so grouping syncs across windows.
    var projectID: UUID? = nil
    /// Last authoritative context-window reading reported by the active provider. Codex supplies
    /// these through `thread/tokenUsage/updated`; keeping the requested model alongside the values
    /// prevents a model switch from presenting a stale denominator as current.
    var contextTokens: Int? = nil
    var contextWindow: Int? = nil
    var contextModel: String? = nil
    /// App-owned work waiting for a provider family. Its prompts remain here—not in queuedPrompts—
    /// until the user-selected access route is verified usable, so OAuth callbacks can resume once.
    var providerAccessRequest: ProviderAccessRequest? = nil
    /// Conversation-scoped Claude execution preferences (Opus 5 advisor, Standard/Fast, safety
    /// fallback). Optional so an older sidecar decodes with no key and encodes none back; absent and
    /// all-default are equivalent, and `claudeSessionPreferences` is the single read path.
    var claudePreferences: ClaudeSessionPreferences? = nil
    /// The model actually answering this session after a safety refusal moved it. Distinct from
    /// `modelSelection` on purpose: the user's choice is never rewritten by a refusal, so the picker
    /// keeps showing what they asked for while this records what is really running. Cleared whenever
    /// the provider session is invalidated, because the swap lived on that session.
    var claudeEffectiveModel: String? = nil
    /// A question (mcp__ask__Question) is waiting for the user's answer — drives the amber sidebar
    /// "needs you" dot. Set when a question arrives; cleared when answered or a new turn starts.
    /// Deliberately NOT in `CodingKeys` — a pending question can't be resumed after relaunch, so it
    /// stays in-memory only (syncs across windows via the shared store, clears on restart).
    var awaitingQuestion: Bool = false
    /// `Conversation.init(from:)` must heal provider reviews before callers can accidentally render
    /// them as live. The shared store consumes this transient bit and writes that healed snapshot
    /// back to disk; it is intentionally excluded from `CodingKeys`.
    var needsStaleStatePersistence = false
    /// Members the tolerant decode deliberately discarded from this sidecar, so the authority
    /// migration can tell a product-defined repair apart from an unknown member written by another
    /// build. Undeclared drops still quarantine the source. Excluded from `CodingKeys`: it describes
    /// one decode, not the Conversation.
    var decodeNormalizations: [ConversationDecodeNormalization] = []

    static func isDurableMessage(_ entry: TranscriptEntry) -> Bool {
        entry.kind == .user || entry.kind == .assistant || entry.kind == .review
            || (entry.kind == .system
                && (entry.text.hasPrefix("error: ") || entry.refusal != nil
                    || entry.runtimeRecoveryNotice == true
                    || entry.backgroundWorkOutlivedTurn == true
                    || entry.helpConsultationReceipt == true))
    }

    /// Durable app-owned content that makes this a real conversation sidecar. Provider-native
    /// Review findings are first-class history even when no ordinary user/model turn exists yet.
    /// Draft-only conversations are durable too; otherwise a relaunch could discard unsent work.
    var hasDurableContent: Bool {
        messages.contains(where: Self.isDurableMessage) || !queuedPrompts.isEmpty
            || !draft.isEmpty
            || providerAccessRequest != nil
            // A first send in a brand-new conversation persists only this field before the
            // provider request; without it, the load-time empty-placeholder sweep would DELETE
            // the sidecar holding the user's crash-recovered words.
            || pendingTurnPrompt != nil
    }

    enum CodingKeys: String, CodingKey {
        case id, title, titleSource, cwd, sdkSessionId, sdkSessionRouteIdentity, sdkSessionExtensionRevision, sdkSessionToolProfile, sdkSessionWorkspaceInstructionsRevision, modelSelection, messages, updatedAt, forkProvenance, artifacts, workflowRuns, subagents, agentActivity, captureOrdinalHighWatermark, providerHistoryReplayCutoffOrdinal, queuedPrompts, pendingTurnPrompt, draft, suggestedPrompt, favorite, sortIndex, armedTrigger, unread, errored, projectID, contextTokens, contextWindow, contextModel, providerAccessRequest, claudePreferences, claudeEffectiveModel
    }

    /// The effective Claude preferences: absent and all-default are the same thing.
    var claudeSessionPreferences: ClaudeSessionPreferences {
        claudePreferences ?? ClaudeSessionPreferences()
    }

    init(id: UUID = UUID(), title: String, titleSource: ConversationTitleSource? = nil,
         cwd: String, sdkSessionId: String?,
         sdkSessionRouteIdentity: String? = nil,
         sdkSessionExtensionRevision: UUID? = nil,
         sdkSessionToolProfile: ProviderToolProfile? = nil,
         sdkSessionWorkspaceInstructionsRevision: String? = nil,
         modelSelection: ModelSelection? = nil, messages: [TranscriptEntry], updatedAt: Date,
         forkProvenance: ConversationForkProvenance? = nil,
         artifacts: [Artifact] = [],
         workflowRuns: [String: WorkflowRun] = [:], subagents: [String: SubagentRun] = [:],
         agentActivity: [AgentActivityRecord] = [],
         captureOrdinalHighWatermark: UInt64? = nil,
         providerHistoryReplayCutoffOrdinal: UInt64? = nil,
         queuedPrompts: [String] = [], draft: String = "",
         suggestedPrompt: ConversationSuggestedPrompt? = nil,
         favorite: Bool = false, sortIndex: Int? = nil, armedTrigger: ArmedTrigger? = nil,
         unread: Bool = false, errored: Bool = false, projectID: UUID? = nil,
         contextTokens: Int? = nil, contextWindow: Int? = nil, contextModel: String? = nil,
         providerAccessRequest: ProviderAccessRequest? = nil,
         claudePreferences: ClaudeSessionPreferences? = nil) {
        self.id = id
        self.title = title
        self.titleSource = titleSource
            ?? ((title.isEmpty || title == ConversationTitlePolicy.placeholder)
                ? .placeholder : .legacy)
        self.cwd = cwd
        self.projectID = projectID
        self.sdkSessionId = sdkSessionId
        self.sdkSessionRouteIdentity = sdkSessionRouteIdentity
        self.sdkSessionExtensionRevision = sdkSessionExtensionRevision
        self.sdkSessionToolProfile = sdkSessionToolProfile
        self.sdkSessionWorkspaceInstructionsRevision =
            sdkSessionWorkspaceInstructionsRevision
        self.modelSelection = modelSelection
        self.messages = messages
        self.updatedAt = updatedAt
        self.forkProvenance = forkProvenance
        self.artifacts = artifacts
        self.workflowRuns = workflowRuns
        self.subagents = subagents
        self.agentActivity = agentActivity
        self.captureOrdinalHighWatermark = captureOrdinalHighWatermark
        self.providerHistoryReplayCutoffOrdinal = providerHistoryReplayCutoffOrdinal
        self.queuedPrompts = queuedPrompts
        self.draft = draft
        self.suggestedPrompt = suggestedPrompt
        self.favorite = favorite
        self.sortIndex = sortIndex
        self.armedTrigger = armedTrigger
        self.unread = unread
        self.errored = errored
        self.contextTokens = contextTokens
        self.contextWindow = contextWindow
        self.contextModel = contextModel
        self.providerAccessRequest = providerAccessRequest
        self.claudePreferences = claudePreferences
        self.needsStaleStatePersistence = false
    }

    // Tolerant decode: older saved conversations have no `artifacts`/`workflowRuns`/`subagents`/`queuedPrompts`/`favorite`/`sortIndex` key.
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        id = try c.decode(UUID.self, forKey: .id)
        title = try c.decode(String.self, forKey: .title)
        titleSource = (try? c.decode(ConversationTitleSource.self, forKey: .titleSource))
            ?? .legacy
        cwd = try c.decode(String.self, forKey: .cwd)
        sdkSessionId = try c.decodeIfPresent(String.self, forKey: .sdkSessionId)
        sdkSessionRouteIdentity = try c.decodeIfPresent(
            String.self, forKey: .sdkSessionRouteIdentity)
        sdkSessionExtensionRevision = try c.decodeIfPresent(
            UUID.self, forKey: .sdkSessionExtensionRevision)
        do {
            sdkSessionToolProfile = try c.decodeIfPresent(
                ProviderToolProfile.self, forKey: .sdkSessionToolProfile)
        } catch {
            // A future/invalid capability receipt is never widened to standard. Discard it under
            // the declared normalization contract; resumability then fails closed below.
            sdkSessionToolProfile = nil
            decodeNormalizations.append(.sessionToolProfile)
            needsStaleStatePersistence = true
        }
        sdkSessionWorkspaceInstructionsRevision = try c.decodeIfPresent(
            String.self, forKey: .sdkSessionWorkspaceInstructionsRevision)
        modelSelection = try c.decodeIfPresent(ModelSelection.self, forKey: .modelSelection)
        messages = try c.decode([TranscriptEntry].self, forKey: .messages)
        updatedAt = try c.decode(Date.self, forKey: .updatedAt)
        forkProvenance = try? c.decodeIfPresent(
            ConversationForkProvenance.self, forKey: .forkProvenance)
        // A provider review cannot remain live across process relaunch: its App Server turn owner
        // no longer exists. Preserve the partial row and label it stopped instead of resurrecting a
        // spinner or silently presenting incomplete findings as a completed review. Use the saved
        // conversation timestamp so decoding the same sidecar is deterministic and read-only.
        for index in messages.indices where messages[index].review?.status == .running {
            messages[index].review?.status = .stopped
            messages[index].review?.endedAt = updatedAt
            if messages[index].text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                messages[index].text = "Review stopped before Codex returned findings."
            }
            needsStaleStatePersistence = true
        }
        artifacts = try c.decodeIfPresent([Artifact].self, forKey: .artifacts) ?? []
        // Decode delegate maps element-tolerantly: a single subagent/workflow row that can't be read
        // (truly corrupt, or an unforeseen incompatible schema) must never abort the whole conversation
        // — that is the exact data-loss class this store must not hit. `Failable` yields nil for a bad
        // element; the survivors load and the healed sidecar is rewritten via needsStaleStatePersistence.
        let decodedRunsRaw = (try c.decodeIfPresent([String: Failable<WorkflowRun>].self, forKey: .workflowRuns) ?? [:])
        let decodedRuns = decodedRunsRaw.compactMapValues(\.value)
        // Builds 80–86 manufactured a `Codex delegation` workflow beside the same standalone
        // Codex children. Codex App Server reports child threads, not a native workflow object;
        // discard those legacy duplicate aggregates while preserving genuine Claude workflows.
        workflowRuns = decodedRuns.filter { key, run in
            !key.hasPrefix("codex-workflow:") && run.workflowName != "Codex delegation"
        }
        if workflowRuns.count != decodedRunsRaw.count { needsStaleStatePersistence = true }
        decodeNormalizations += decodedRuns.keys.filter { workflowRuns[$0] == nil }
            .map { .workflowRun(storageKey: $0) }
        let decodedSubsRaw = (try c.decodeIfPresent([String: Failable<SubagentRun>].self, forKey: .subagents) ?? [:])
        let decodedSubs = decodedSubsRaw.compactMapValues(\.value)
        let providerRootPseudoAgents = decodedSubs.filter {
            $0.value.isProviderRootPseudoAgent
        }
        subagents = decodedSubs.filter { !$0.value.isProviderRootPseudoAgent }
        if subagents.count != decodedSubsRaw.count { needsStaleStatePersistence = true }
        decodeNormalizations += providerRootPseudoAgents.keys.map { .subagent(storageKey: $0) }
        agentActivity = (try? c.decodeIfPresent(
            [AgentActivityRecord].self, forKey: .agentActivity)) ?? []
        let subagentsBeforeCollapse = subagents
        let activityBeforeCollapse = agentActivity
        if collapseWorkflowAggregateMirrors(
            workflowRuns: workflowRuns,
            subagents: &subagents,
            agentActivity: &agentActivity
        ) {
            needsStaleStatePersistence = true
            decodeNormalizations += subagentsBeforeCollapse.keys.filter { subagents[$0] == nil }
                .map { .subagent(storageKey: $0) }
            let survivingActivityIDs = Set(agentActivity.map(\.id))
            decodeNormalizations += activityBeforeCollapse
                .filter { !survivingActivityIDs.contains($0.id) }
                .map { .agentActivity(id: $0.id) }
        }
        captureOrdinalHighWatermark = (try? c.decodeIfPresent(
            UInt64.self, forKey: .captureOrdinalHighWatermark)) ?? nil
        providerHistoryReplayCutoffOrdinal = (try? c.decodeIfPresent(
            UInt64.self, forKey: .providerHistoryReplayCutoffOrdinal)) ?? nil
        if !providerRootPseudoAgents.isEmpty {
            let pseudoActivityIDs = Set(providerRootPseudoAgents.flatMap { storageKey, subagent in
                [
                    AgentActivityIdentity.subagent(storageKey),
                    AgentActivityIdentity.subagent(subagent.key),
                    subagent.taskId.map(AgentActivityIdentity.subagent),
                ].compactMap { $0 }
            })
            decodeNormalizations += agentActivity
                .filter { pseudoActivityIDs.contains($0.agentID) }
                .map { .agentActivity(id: $0.id) }
            agentActivity.removeAll { pseudoActivityIDs.contains($0.agentID) }
            needsStaleStatePersistence = true
        }
        queuedPrompts = try c.decodeIfPresent([String].self, forKey: .queuedPrompts) ?? []
        pendingTurnPrompt = try c.decodeIfPresent(String.self, forKey: .pendingTurnPrompt)
        draft = try c.decodeIfPresent(String.self, forKey: .draft) ?? ""
        // A future source, malformed record, or transcript-orphaned endpoint costs only this
        // presentation hint. Declare the repair so authority migration can distinguish it from an
        // unknown member that must still quarantine the conversation.
        if c.contains(.suggestedPrompt) {
            do {
                let decoded = try c.decodeIfPresent(
                    ConversationSuggestedPrompt.self, forKey: .suggestedPrompt)
                suggestedPrompt = decoded?.validated(in: messages)
                if decoded == nil || suggestedPrompt == nil {
                    decodeNormalizations.append(.suggestedPrompt)
                    needsStaleStatePersistence = true
                }
            } catch {
                suggestedPrompt = nil
                decodeNormalizations.append(.suggestedPrompt)
                needsStaleStatePersistence = true
            }
        } else {
            suggestedPrompt = nil
        }
        favorite = try c.decodeIfPresent(Bool.self, forKey: .favorite) ?? false
        sortIndex = try c.decodeIfPresent(Int.self, forKey: .sortIndex)
        armedTrigger = try c.decodeIfPresent(ArmedTrigger.self, forKey: .armedTrigger)
        unread = try c.decodeIfPresent(Bool.self, forKey: .unread) ?? false
        errored = try c.decodeIfPresent(Bool.self, forKey: .errored) ?? false
        projectID = try c.decodeIfPresent(UUID.self, forKey: .projectID)
        contextTokens = try c.decodeIfPresent(Int.self, forKey: .contextTokens)
        contextWindow = try c.decodeIfPresent(Int.self, forKey: .contextWindow)
        contextModel = try c.decodeIfPresent(String.self, forKey: .contextModel)
        providerAccessRequest = try c.decodeIfPresent(
            ProviderAccessRequest.self, forKey: .providerAccessRequest)
        // Tolerant twice over: absent in every sidecar written before this build, and individually
        // tolerant per field inside `ClaudeSessionPreferences`. An unreadable preference costs the
        // preference, never the conversation.
        claudePreferences = (try? c.decodeIfPresent(
            ClaudeSessionPreferences.self, forKey: .claudePreferences)) ?? nil
        claudeEffectiveModel = (try? c.decodeIfPresent(
            String.self, forKey: .claudeEffectiveModel)) ?? nil
    }

    var displayTitle: String { title.isEmpty ? "New conversation" : title }
    var cwdName: String { cwd.isEmpty ? "" : URL(fileURLWithPath: cwd).lastPathComponent }
    /// A workflow or subagent for this conversation is still running — possibly after its turn ended.
    var hasRunningDelegate: Bool {
        hasNonterminalDelegatedWork(
            workflowRuns: workflowRuns,
            subagents: subagents)
    }
}

/// Why one conversation's delegated work is being terminalized outside the provider's ordinary
/// child lifecycle. Provider failures are failures; an explicit user/runtime stop is cancellation.
/// The distinction stays provider-neutral so foreground, background, and runtime-exit paths share
/// exactly one reducer.
enum DelegatedWorkTerminationOutcome: Equatable {
    case providerFailure(String)
    case userStopped

    var status: WorkflowStatus {
        switch self {
        case .providerFailure: return .failed
        case .userStopped: return .stopped
        }
    }

    var activityPhase: AgentActivityPhase {
        switch self {
        case .providerFailure: return .failed
        case .userStopped: return .stopped
        }
    }

    var reason: String? {
        guard case .providerFailure(let message) = self else { return nil }
        let trimmed = message.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? "Stopped because the provider ended the parent turn." : trimmed
    }
}

/// Which delegated lanes one terminal event is allowed to settle.
///
/// User Stop is intentionally conversation-wide. Provider terminals and runtime exits are not:
/// one conversation can retain a delegate from an earlier successful turn while a later turn on a
/// different provider fails. In that case only child lanes owned by the failing turn/runtime may
/// transition.
enum DelegatedWorkTerminationScope: Equatable {
    case conversation
    case owners(
        turnIDs: Set<String>,
        providerAccess: ModelAccess?,
        includesUnattributed: Bool)
}

/// Which clock supplies a synthetic delegated-work terminal boundary.
///
/// Live Stop, provider-failure, and runtime-exit paths observe a real boundary at the call time.
/// Cold-load recovery has no surviving process and must instead close each persisted lane at its
/// own last observation; using the relaunch clock would manufacture activity for the offline gap.
enum DelegatedWorkTerminationBoundary: Equatable {
    case observedAtCall
    case lastPersistedObservation
}

/// Every activity identity under which a standalone child may have been sampled. The provider can
/// replace the provisional tool-use key with an authoritative task id after the lane has opened.
func delegatedActivityIdentities(for subagent: SubagentRun) -> Set<String> {
    var identities = Set([AgentActivityIdentity.subagent(subagent.key)])
    if let taskID = subagent.taskId, !taskID.isEmpty {
        identities.insert(AgentActivityIdentity.subagent(taskID))
    }
    return identities
}

/// The one live child lane allowed to contribute Activity-only detail after its parent route ends.
///
/// Provider callbacks can outlive the root response, but a completed route is not permission to
/// reopen arbitrary transcript handling. Admission therefore requires an exact child identity, one
/// matching nonterminal card, that child's newest observed turn, and an open current lifecycle
/// generation. Ambiguous provider ids and buffered events from an older generation fail closed.
struct PostTerminalDelegateActivityOwner: Equatable {
    var subagentKey: String
    var agentID: String
    var label: String
    var generationStartRecordID: UUID
}

func postTerminalDelegateActivityOwner(
    matchingAgentID: String,
    turnID: String,
    subagents: [String: SubagentRun],
    agentActivity: [AgentActivityRecord]
) -> PostTerminalDelegateActivityOwner? {
    guard !matchingAgentID.isEmpty,
          matchingAgentID != AgentActivityIdentity.root,
          !turnID.isEmpty else { return nil }
    let matches = subagents.values.filter {
        delegatedActivityIdentities(for: $0).contains(matchingAgentID)
    }
    guard matches.count == 1,
          let subagent = matches.first,
          !subagent.status.isTerminal,
          !subagent.isProviderRootPseudoAgent else { return nil }
    let identities = delegatedActivityIdentities(for: subagent)
    guard latestDelegatedActivityLane(
        in: agentActivity,
        matching: identities)?.turnID == turnID else { return nil }
    let ownedTurnLane = agentActivity.filter {
        $0.turnID == turnID && identities.contains($0.agentID)
    }
    let currentGeneration = agentActivityCurrentLifecycleGenerationRecords(ownedTurnLane)
    guard agentActivityLaneIsActive(ownedTurnLane),
          let generationStartRecordID = currentGeneration.first?.id else { return nil }
    return PostTerminalDelegateActivityOwner(
        subagentKey: subagent.key,
        agentID: AgentActivityIdentity.subagent(subagent.key),
        label: subagent.subagentType.isEmpty ? "Agent" : subagent.subagentType,
        generationStartRecordID: generationStartRecordID)
}

/// Find the child's own provider turn before considering any caller-supplied fallback. A later root
/// turn may already have completed by the time an earlier delegate is reconciled, so "latest turn"
/// is not a safe ownership projection.
func latestDelegatedActivityLane(
    in records: [AgentActivityRecord],
    matching identities: Set<String>
) -> AgentActivityRecord? {
    guard !identities.isEmpty else { return nil }
    return records.last {
        identities.contains($0.agentID) && $0.turnID != nil
    }
}

/// Match one canonical delegate identity group to the terminal event that is allowed to settle it.
///
/// Turn identity is authoritative. Provider identity is an additional fail-closed check when the
/// lane reports it; older activity ledgers without provider attribution can still match an exact
/// turn. Lane-less legacy work is included only when the caller has already established one
/// conservative, unambiguous fallback owner.
private func delegatedWorkIsOwned(
    identities: Set<String>,
    activity: [AgentActivityRecord],
    scope: DelegatedWorkTerminationScope
) -> Bool {
    guard case .owners(
        let turnIDs,
        let providerAccess,
        let includesUnattributed) = scope else {
        return true
    }
    guard let lane = latestDelegatedActivityLane(
        in: activity,
        matching: identities),
          let laneTurnID = lane.turnID else {
        return includesUnattributed
    }
    guard turnIDs.contains(laneTurnID) else { return false }
    guard let providerAccess else { return true }
    let attributedAccess = activity.last {
        identities.contains($0.agentID)
            && $0.turnID == laneTurnID
            && $0.providerAccess != nil
    }?.providerAccess ?? lane.providerAccess
    return attributedAccess == nil || attributedAccess == providerAccess
}

/// A fatal turn may claim lane-less legacy delegate rows only when it is the sole delegation turn
/// in the retained ledger. Multiple historical delegation turns are ambiguous, even on the same
/// provider, so exact child-lane evidence is required in that case.
func terminalTurnDelegatedWorkScope(
    turnID: String,
    selection: ModelSelection,
    agentActivity: [AgentActivityRecord]
) -> DelegatedWorkTerminationScope {
    let delegationTurns = rootDelegationTurnIDs(in: agentActivity)
    return .owners(
        turnIDs: [turnID],
        providerAccess: selection.access,
        includesUnattributed: delegationTurns == [turnID])
}

struct ActiveDelegateOwnerTurnProjection: Equatable {
    /// Exact provider turn ids recovered from nonterminal child activity lanes, plus at most one
    /// conservative fallback for delegate groups that have no lane yet.
    var turnIDs: Set<String>
    var unmatchedDelegateGroups: Int
    var usedFallback: Bool
}

/// The exact activity-identity groups that remain provider-live.
///
/// Workflow children can also appear in the standalone subagent map. Overlapping identity sets are
/// merged transitively so one mirrored child cannot manufacture an unmatched duplicate and force an
/// unrelated fallback route to stay alive.
private func activeDelegateActivityIdentityGroups(
    workflowRuns: [String: WorkflowRun],
    subagents: [String: SubagentRun]
) -> [Set<String>] {
    let visibleSubagents = subagents.values
        .filter { !$0.isProviderRootPseudoAgent }
        .sorted { $0.key < $1.key }
    var subagentByIdentity: [String: SubagentRun] = [:]
    for subagent in visibleSubagents {
        subagentByIdentity[subagent.key] = subagent
        if let taskID = subagent.taskId, !taskID.isEmpty {
            subagentByIdentity[taskID] = subagent
        }
    }

    var groups: [Set<String>] = []
    func appendMerged(_ identities: Set<String>) {
        // An empty group represents a live workflow aggregate that has not published a child lane.
        guard !identities.isEmpty else {
            groups.append([])
            return
        }
        var merged = identities
        var index = 0
        while index < groups.count {
            if !groups[index].isEmpty, !groups[index].isDisjoint(with: merged) {
                merged.formUnion(groups.remove(at: index))
                // The larger merged set may now overlap an earlier group; restart for transitivity.
                index = 0
            } else {
                index += 1
            }
        }
        groups.append(merged)
    }

    for subagent in visibleSubagents where !subagent.status.isTerminal {
        appendMerged(delegatedActivityIdentities(for: subagent))
    }

    for storageKey in workflowRuns.keys.sorted() {
        guard let run = workflowRuns[storageKey] else { continue }
        let runKey = run.runKey.isEmpty ? storageKey : run.runKey
        var aggregateIdentities = Set<String>()
        var hasNonterminalChild = false

        for agentKey in run.agents.keys.sorted() {
            guard let agent = run.agents[agentKey] else { continue }
            var identities = Set([
                AgentActivityIdentity.workflow(runKey: runKey, agentKey: agentKey),
            ])
            if let providerID = agent.agentId, !providerID.isEmpty {
                identities.insert(AgentActivityIdentity.subagent(providerID))
                if let mirrored = subagentByIdentity[providerID] {
                    identities.formUnion(delegatedActivityIdentities(for: mirrored))
                }
            }
            aggregateIdentities.formUnion(identities)
            if !agent.state.isTerminal {
                hasNonterminalChild = true
                appendMerged(identities)
            }
        }

        // A live aggregate with no live child lane is still provider work (for example an
        // orchestration run waiting between phases). Its known child identities may recover the
        // owning turn; otherwise the caller's single root-delegation fallback is used.
        if !run.status.isTerminal, !hasNonterminalChild {
            appendMerged(aggregateIdentities)
        }
    }
    return groups
}

/// Project nonterminal delegates onto the exact provider turn lanes that created them.
///
/// `fallbackTurnID` must already be scoped to the same conversation and backed by root delegation
/// activity. It is inserted only once, and only when at least one live delegate group has no child
/// lane of its own.
func activeDelegateOwnerTurnProjection(
    workflowRuns: [String: WorkflowRun],
    subagents: [String: SubagentRun],
    agentActivity: [AgentActivityRecord],
    fallbackTurnID: String? = nil
) -> ActiveDelegateOwnerTurnProjection {
    var turnIDs = Set<String>()
    var unmatched = 0
    for identities in activeDelegateActivityIdentityGroups(
        workflowRuns: workflowRuns,
        subagents: subagents
    ) {
        if let turnID = latestDelegatedActivityLane(
            in: agentActivity,
            matching: identities)?.turnID {
            turnIDs.insert(turnID)
        } else {
            unmatched += 1
        }
    }
    let usedFallback = unmatched > 0 && fallbackTurnID != nil
    if usedFallback, let fallbackTurnID {
        turnIDs.insert(fallbackTurnID)
    }
    return ActiveDelegateOwnerTurnProjection(
        turnIDs: turnIDs,
        unmatchedDelegateGroups: unmatched,
        usedFallback: usedFallback)
}

/// Root activity that proves a turn launched delegated work. This is intentionally narrower than
/// arbitrary root tool activity: a recent Read/Build turn must not become the owner of an older
/// provider's child merely because that child lacks a historical lane.
func rootDelegationTurnIDs(in agentActivity: [AgentActivityRecord]) -> Set<String> {
    Set(agentActivity.compactMap { record in
        guard record.agentID == AgentActivityIdentity.root,
              record.kind == .state || record.kind == .tool,
              let turnID = record.turnID else { return nil }
        let detail = (record.detail ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let normalized = traceToolDisplayName(
            toolName: detail,
            target: record.toolTarget)
            .lowercased()
        let raw = detail.lowercased()
        return normalized == "delegating" || raw.hasPrefix("delegat")
            ? turnID : nil
    })
}

/// Select one evidence-backed fallback for legacy/live aggregates that have no child lane.
func conservativeDelegateFallbackTurnID(
    agentActivity: [AgentActivityRecord],
    completedRoutes: [(
        turnID: String,
        completedAt: Date,
        providerAccess: ModelAccess
    )]
) -> String? {
    let delegationTurns = rootDelegationTurnIDs(in: agentActivity)
    let candidates = completedRoutes
        .filter { delegationTurns.contains($0.turnID) }
    // Without a child lane there is no evidence tying the active delegate graph to one of several
    // provider processes. Guessing the newest provider would let that unrelated lane terminalize
    // another provider's child, so cross-provider ambiguity deliberately has no fallback.
    guard Set(candidates.map { $0.providerAccess }).count <= 1 else { return nil }
    return candidates
        .sorted {
            if $0.completedAt != $1.completedAt {
                return $0.completedAt > $1.completedAt
            }
            return $0.turnID > $1.turnID
        }
        .first?
        .turnID
}

enum SubagentToolResultDisposition: Equatable {
    case launched
    case terminal
}

/// Interpret the provider-neutral result disposition agentd attaches to Agent/Task tool results.
///
/// Claude's Agent tool runs in the background by default. Its first successful tool result is only
/// a launch acknowledgement; the later task notification owns completion. Older agentd builds did
/// not preserve the SDK's structured result, so retain one deliberately narrow compatibility check
/// for their exact internal acknowledgement rather than broadly treating provider prose as policy.
func subagentToolResultDisposition(
    wireDisposition: String?,
    failed: Bool,
    legacyResultText: String?
) -> SubagentToolResultDisposition {
    if failed { return .terminal }
    switch wireDisposition?
        .trimmingCharacters(in: .whitespacesAndNewlines)
        .lowercased() {
    case "launched": return .launched
    case "completed": return .terminal
    default: break
    }
    let legacy = legacyResultText?
        .trimmingCharacters(in: .whitespacesAndNewlines)
        .lowercased() ?? ""
    if legacy.hasPrefix("async agent launched successfully.")
        && legacy.contains("the agent is working in the background") {
        return .launched
    }
    return .terminal
}

/// Fold a foreground Task/Agent tool result into its child card without mistaking an asynchronous
/// launch acknowledgement for the child's terminal result.
///
/// Result text is useful even when it arrives after local recovery, but lifecycle is monotonic:
/// stopped/failed children stay terminal, and the only terminal refinement is completed -> failed
/// when the tool result carries authoritative failure evidence. The return value is the activity
/// phase that should be appended; nil means no lifecycle transition and therefore no new lane mark.
@discardableResult
func applySubagentToolResultState(
    subagents: inout [String: SubagentRun],
    toolUseID: String,
    failed: Bool,
    result: String?,
    disposition: SubagentToolResultDisposition = .terminal,
    taskID: String? = nil,
    at observedAt: Date = Date(),
    captureOrdinal: UInt64? = nil
) -> AgentActivityPhase? {
    guard var subagent = subagents[toolUseID] else { return nil }
    if disposition == .launched {
        if let taskID = taskID?.trimmingCharacters(in: .whitespacesAndNewlines),
           !taskID.isEmpty {
            subagent.taskId = taskID
        }
        // The launch prose is model-directed internal metadata, not the child's result. Keep the
        // card active and empty until progress/notification supplies user-facing work.
        subagents[toolUseID] = subagent
        return nil
    }
    let previous = subagent.status
    let incoming: WorkflowStatus = failed ? .failed : .completed

    if !previous.isTerminal {
        subagent.status = incoming
    } else if previous == .completed, incoming == .failed {
        subagent.status = .failed
    }
    if subagent.status != previous, subagent.endedAt == nil {
        subagent.endedAt = observedAt
        subagent.endedCaptureOrdinal = captureOrdinal
    }
    if let result, !result.isEmpty {
        subagent.resultPreview = String(result.prefix(12_000))
    }
    subagents[toolUseID] = subagent

    guard subagent.status != previous else { return nil }
    return subagent.status == .failed ? .failed : .completed
}

/// Whole-bridge shutdown projection. Every provider process is about to die, so any retained route
/// for a conversation with delegated work is sufficient ownership evidence.
func conversationIDsAffectedByProcessTermination(
    _ routes: [(
        conversationID: UUID,
        reservesConversation: Bool,
        hasRunningDelegates: Bool
    )]
) -> Set<UUID> {
    Set(routes.compactMap { route in
        route.reservesConversation || route.hasRunningDelegates
            ? route.conversationID : nil
    })
}

/// Provider-lane-scoped process termination. Reserved routes are exact by construction; a completed
/// route is affected only when an active child projects back to that precise turn id.
func conversationIDsAffectedByScopedProcessTermination(
    _ routes: [(
        conversationID: UUID,
        turnID: String,
        reservesConversation: Bool
    )],
    delegateOwnerTurnIDs: [UUID: Set<String>]
) -> Set<UUID> {
    Set(routes.compactMap { route in
        if route.reservesConversation { return route.conversationID }
        return delegateOwnerTurnIDs[route.conversationID]?.contains(route.turnID) == true
            ? route.conversationID : nil
    })
}

/// Rank one bridge as the actionable owner for conversation-level Stop.
///
/// Exact child-lane evidence wins over every stale completed route. A conservative legacy
/// delegation fallback is weaker, and an unrelated retained route is weaker still; both remain
/// available for recovery when old activity lacks enough identity detail to prove ownership.
func stoppableWorkOwnershipRank(
    hasReservation: Bool,
    retainedTurnIDs: Set<String>,
    exactDelegateOwnerTurnIDs: Set<String>,
    conservativeDelegateOwnerTurnIDs: Set<String>,
    hasActiveAgentProjection: Bool,
    hasDelegatedWork: Bool,
    isCurrentViewer: Bool
) -> Int? {
    if hasReservation { return 0 }
    guard hasDelegatedWork else { return nil }
    if !retainedTurnIDs.isDisjoint(with: exactDelegateOwnerTurnIDs) { return 1 }
    if hasActiveAgentProjection { return 2 }
    if !retainedTurnIDs.isDisjoint(with: conservativeDelegateOwnerTurnIDs) { return 3 }
    if !retainedTurnIDs.isEmpty { return 4 }
    if isCurrentViewer { return 5 }
    return nil
}

/// Whether one conversation still has provider-delegated work that can publish lifecycle events.
///
/// A terminal workflow aggregate with a nonterminal child is inconsistent but still pending work:
/// shutdown must reconcile that child rather than trusting the stale aggregate. The provider's
/// `/root` pseudo-agent is the parent turn already represented by turn routing, not a delegate.
func hasNonterminalDelegatedWork(
    workflowRuns: [String: WorkflowRun],
    subagents: [String: SubagentRun]
) -> Bool {
    workflowRuns.values.contains { run in
        !run.status.isTerminal
            || run.agents.values.contains { !$0.state.isTerminal }
    } || subagents.values.contains {
        !$0.isProviderRootPseudoAgent && !$0.status.isTerminal
    }
}

/// Pure quit/window-close projection. Current live maps are authoritative for the selected
/// conversation; background conversations belong to this bridge only when a retained turn route
/// says so. Queued prompts keep their existing process-wide persistence behavior.
func agentBridgeHasPendingWork(
    hasRunningConversations: Bool,
    hasPendingTurnStarts: Bool,
    currentConversationID: UUID?,
    currentWorkflowRuns: [String: WorkflowRun],
    currentSubagents: [String: SubagentRun],
    currentQueuedPrompts: [String],
    storedConversations: [Conversation],
    routedConversationIDs: Set<UUID>
) -> Bool {
    if hasRunningConversations || hasPendingTurnStarts || !currentQueuedPrompts.isEmpty {
        return true
    }
    if hasNonterminalDelegatedWork(
        workflowRuns: currentWorkflowRuns,
        subagents: currentSubagents) {
        return true
    }
    if storedConversations.contains(where: { !$0.queuedPrompts.isEmpty }) {
        return true
    }
    return storedConversations.contains { conversation in
        conversation.id != currentConversationID
            && routedConversationIDs.contains(conversation.id)
            && hasNonterminalDelegatedWork(
                workflowRuns: conversation.workflowRuns,
                subagents: conversation.subagents)
    }
}

struct CompletedTurnRoutePruningCandidate: Equatable {
    var turnID: String
    var completedAt: Date
    /// This exact parent turn still owns at least one nonterminal delegate lane.
    var protectsRunningDelegates: Bool
}

/// Completed routes without live delegates are ordinary bounded tombstones. Protected routes do not
/// consume that allowance: evicting one merely because 32 unrelated turns completed later would
/// orphan its child from runtime-exit and shutdown reconciliation.
func completedTurnRouteIDsToPrune(
    _ candidates: [CompletedTurnRoutePruningCandidate],
    unprotectedLimit: Int = 32
) -> Set<String> {
    let limit = max(0, unprotectedLimit)
    let unprotected = candidates
        .filter { !$0.protectsRunningDelegates }
        .sorted {
            if $0.completedAt != $1.completedAt {
                return $0.completedAt < $1.completedAt
            }
            return $0.turnID < $1.turnID
        }
    guard unprotected.count > limit else { return [] }
    return Set(unprotected.prefix(unprotected.count - limit).map(\.turnID))
}

/// How long a delegate may report nothing before it is presumed dead.
///
/// Deliberately generous. Every other way a delegate settles is a process-death event — bridge
/// teardown, runtime restart, runtime exit, or loading a sidecar with no live bridge — and a run
/// that simply goes SILENT matches none of them, because from the daemon's side nothing died. One
/// was observed still counted as active eighteen hours later, which also stretched the activity
/// trace's time axis until the root turn's own work was an invisible sliver.
///
/// The cost of being wrong is asymmetric, so this is far above any real silence: a legitimate run
/// reports progress continuously, and stopping one that was still working would destroy work the
/// user is waiting on. Leaving a dead row a few extra minutes costs nothing.
let delegatedWorkSilenceTimeout: TimeInterval = 30 * 60

/// True when EVERY nonterminal delegate in one conversation has been silent past the timeout.
///
/// All-or-nothing on purpose, and it is what lets this reuse the conversation-scoped reducer below
/// untouched rather than needing per-delegate surgery inside it. One delegate still reporting keeps
/// the others; when it finishes, the silent ones are judged again on the next tick, so a mixed
/// conversation self-heals instead of needing a scoped variant.
///
/// Returns false for a conversation with nothing running, so an idle conversation is never
/// "settled" repeatedly, and false on a clock that has moved backwards — the safe direction.
func delegatedWorkHasGoneSilent(
    workflowRuns: [String: WorkflowRun],
    subagents: [String: SubagentRun],
    now: Date,
    timeout: TimeInterval = delegatedWorkSilenceTimeout
) -> Bool {
    var sawNonterminal = false
    for run in workflowRuns.values where !run.status.isTerminal {
        sawNonterminal = true
        if now.timeIntervalSince(run.lastLivenessAt) < timeout { return false }
    }
    for subagent in subagents.values
    where !subagent.status.isTerminal && !subagent.isProviderRootPseudoAgent {
        sawNonterminal = true
        if now.timeIntervalSince(subagent.lastLivenessAt) < timeout { return false }
    }
    return sawNonterminal
}

/// Reconcile every nonterminal delegate in one conversation and close its open activity lanes.
///
/// This is deliberately a pure inout reducer: error handling can apply it to either the foreground
/// bridge snapshot or a background `Conversation` inside the same durable transaction. It is
/// idempotent, preserves provider-owned errors and aggregate terminal states, and heals any
/// inconsistent nonterminal children still nested beneath a terminal workflow.
@discardableResult
func terminalizeDelegatedWorkState(
    workflowRuns: inout [String: WorkflowRun],
    subagents: inout [String: SubagentRun],
    agentActivity: inout [AgentActivityRecord],
    outcome: DelegatedWorkTerminationOutcome,
    scope: DelegatedWorkTerminationScope = .conversation,
    turnID: String?,
    selection: ModelSelection? = nil,
    boundary: DelegatedWorkTerminationBoundary = .observedAtCall,
    at observedAt: Date = Date(),
    captureOrdinal: UInt64? = nil
) -> Bool {
    var changed = false
    var activity = agentActivity
    let persistedActivity = agentActivity
    let persistedAliases = boundary == .lastPersistedObservation
        ? agentActivityAliases(subagents: subagents, workflowRuns: workflowRuns)
        : [:]
    var recordedAgentIDs = Set<String>()
    let fallbackTurnID = turnID ?? activity.last(where: { $0.turnID != nil })?.turnID

    func canonicalIdentityGroup(_ identities: Set<String>) -> Set<String> {
        guard boundary == .lastPersistedObservation else { return identities }
        let canonicalIDs = Set(identities.map { persistedAliases[$0] ?? $0 })
        return identities.union(persistedAliases.compactMap { identity, canonical in
            canonicalIDs.contains(canonical) ? identity : nil
        })
    }

    func laneEvidence(
        matching identities: Set<String>
    ) -> (
        tail: AgentActivityRecord,
        endedAt: Date,
        attribution: AgentActivityRecord?
    )? {
        let source = boundary == .lastPersistedObservation
            ? persistedActivity
            : activity
        let ownedIdentities = canonicalIdentityGroup(identities)
        guard let tail = latestDelegatedActivityLane(
            in: source,
            matching: ownedIdentities),
              let laneTurnID = tail.turnID else { return nil }
        let lane = source.filter {
            ownedIdentities.contains($0.agentID)
                && $0.turnID == laneTurnID
        }
        let generation = boundary == .lastPersistedObservation
            ? agentActivityCurrentLifecycleGenerationRecords(lane)
            : lane[...]
        guard let generationTail = generation.last,
              let endedAt = generation.map(\.at).max() else { return nil }
        let attribution = generation.last {
            $0.providerAccess != nil || $0.modelID?.isEmpty == false
        } ?? generationTail
        return (generationTail, endedAt, attribution)
    }

    func terminalAt(
        matching identities: Set<String>,
        persistedFallback: Date
    ) -> Date {
        guard boundary == .lastPersistedObservation else { return observedAt }
        return laneEvidence(matching: identities)?.endedAt ?? persistedFallback
    }

    func subagentPersistedObservation(_ subagent: SubagentRun) -> Date {
        ([subagent.startedAt]
            + [subagent.lastUpdateAt].compactMap { $0 }
            + subagent.toolEvents.map(\.at))
            .max() ?? subagent.startedAt
    }

    func workflowAgentPersistedObservation(
        _ agent: WorkflowAgent,
        runStartedAt: Date
    ) -> Date {
        ([agent.startedAt].compactMap { $0 }
            + agent.toolEvents.map(\.at))
            .max() ?? runStartedAt
    }

    func appendTerminalState(
        agentID: String,
        matching identities: Set<String>,
        label: String?,
        detail: String?,
        terminalAt: Date
    ) {
        guard recordedAgentIDs.insert(agentID).inserted else { return }
        let evidence = laneEvidence(matching: identities)
        let ownLane = evidence?.tail
        let recordTurnID = ownLane?.turnID ?? turnID ?? fallbackTurnID
        let laneAttribution = evidence?.attribution
        var terminalRecord = AgentActivityRecord.state(
            outcome.activityPhase,
            turnID: recordTurnID,
            agentID: agentID,
            agentLabel: label,
            detail: detail,
            at: terminalAt)
        terminalRecord.captureOrdinal = captureOrdinal
        if let laneAttribution {
            terminalRecord.providerAccess = laneAttribution.providerAccess
            terminalRecord.modelID = laneAttribution.modelID
            terminalRecord.harnessLaneID = laneAttribution.harnessLaneID
        } else {
            terminalRecord = terminalRecord.attributed(to: selection)
        }
        appendAgentActivityRecord(
            terminalRecord,
            to: &activity)
    }

    // Provider ids are the canonical identity once available. Keep this map for workflow children
    // mirrored in the standalone subagent collection so the synthetic close is emitted only once.
    let mirroredSubagents = Dictionary(
        subagents.values.compactMap { subagent -> (String, SubagentRun)? in
            guard let taskID = subagent.taskId, !taskID.isEmpty else { return nil }
            return (taskID, subagent)
        },
        uniquingKeysWith: { existing, _ in existing })

    for key in subagents.keys.sorted() {
        guard var subagent = subagents[key], !subagent.status.isTerminal else { continue }
        let identities = delegatedActivityIdentities(for: subagent)
        guard delegatedWorkIsOwned(
            identities: identities,
            activity: activity,
            scope: scope) else { continue }
        let laneEndedAt = terminalAt(
            matching: identities,
            persistedFallback: subagentPersistedObservation(subagent))
        subagent.status = outcome.status
        if subagent.endedAt == nil {
            subagent.endedAt = laneEndedAt
            subagent.endedCaptureOrdinal = captureOrdinal
        }
        if subagent.error == nil, let reason = outcome.reason { subagent.error = reason }
        subagents[key] = subagent
        changed = true

        let identity = subagent.taskId.flatMap { $0.isEmpty ? nil : $0 } ?? subagent.key
        appendTerminalState(
            agentID: AgentActivityIdentity.subagent(identity),
            matching: identities,
            label: subagent.subagentType.isEmpty ? "Agent" : subagent.subagentType,
            detail: subagent.error ?? (outcome == .userStopped ? "Stopped by user" : outcome.reason),
            terminalAt: laneEndedAt)
    }

    for runKey in workflowRuns.keys.sorted() {
        guard var run = workflowRuns[runKey] else { continue }
        var runChanged = false
        let initiallyNonterminalAgentKeys = Set(run.agents.compactMap {
            $0.value.state.isTerminal ? nil : $0.key
        })
        var ownedNonterminalAgentKeys = Set<String>()
        var aggregateIdentities = Set<String>()
        var ownedChildTerminalDates: [Date] = []

        for agentKey in run.agents.keys.sorted() {
            guard var agent = run.agents[agentKey], !agent.state.isTerminal else { continue }
            let mirrored = agent.agentId.flatMap { mirroredSubagents[$0] }
            var matchingIdentities = Set([AgentActivityIdentity.workflow(
                runKey: run.runKey.isEmpty ? runKey : run.runKey,
                agentKey: agentKey)])
            if let mirrored {
                matchingIdentities.formUnion(delegatedActivityIdentities(for: mirrored))
            } else if let providerID = agent.agentId, !providerID.isEmpty {
                matchingIdentities.insert(AgentActivityIdentity.subagent(providerID))
            }
            aggregateIdentities.formUnion(matchingIdentities)
            guard delegatedWorkIsOwned(
                identities: matchingIdentities,
                activity: activity,
                scope: scope) else { continue }
            ownedNonterminalAgentKeys.insert(agentKey)
            let laneEndedAt = terminalAt(
                matching: matchingIdentities,
                persistedFallback: workflowAgentPersistedObservation(
                    agent,
                    runStartedAt: run.startedAt))
            ownedChildTerminalDates.append(laneEndedAt)

            agent.state = outcome == .userStopped ? .stopped : .failed
            if agent.endedAt == nil { agent.endedAt = laneEndedAt }
            if agent.error == nil, let reason = outcome.reason { agent.error = reason }
            run.agents[agentKey] = agent
            runChanged = true

            let agentID: String
            if let mirrored {
                let identity = mirrored.taskId.flatMap { $0.isEmpty ? nil : $0 } ?? mirrored.key
                agentID = AgentActivityIdentity.subagent(identity)
            } else {
                agentID = AgentActivityIdentity.workflow(
                    runKey: run.runKey.isEmpty ? runKey : run.runKey,
                    agentKey: agentKey)
            }
            appendTerminalState(
                agentID: agentID,
                matching: matchingIdentities,
                label: agent.label.isEmpty ? "Agent \(agent.index)" : agent.label,
                detail: agent.error ?? (outcome == .userStopped ? "Stopped by user" : outcome.reason),
                terminalAt: laneEndedAt)
        }

        // A workflow aggregate represents all of its live children. Do not terminalize it while an
        // unowned child from another turn/provider remains live. Aggregates with no live child use
        // their known child identities (or the caller's conservative lane-less fallback).
        let ownsWholeAggregate: Bool
        if initiallyNonterminalAgentKeys.isEmpty {
            ownsWholeAggregate = delegatedWorkIsOwned(
                identities: aggregateIdentities,
                activity: activity,
                scope: scope)
        } else {
            ownsWholeAggregate = ownedNonterminalAgentKeys == initiallyNonterminalAgentKeys
        }
        if !run.status.isTerminal, ownsWholeAggregate {
            run.status = outcome.status
            if run.endedAt == nil {
                run.endedAt = boundary == .lastPersistedObservation
                    ? (ownedChildTerminalDates + [run.lastLivenessAt]).max()
                    : observedAt
            }
            if run.error == nil, let reason = outcome.reason { run.error = reason }
            runChanged = true
        }
        if runChanged {
            if run.endedAt == nil {
                run.endedAt = boundary == .lastPersistedObservation
                    ? (ownedChildTerminalDates + [run.lastLivenessAt]).max()
                    : observedAt
            }
            workflowRuns[runKey] = run
            changed = true
        }
    }

    if activity != agentActivity { agentActivity = activity }
    return changed
}

/// Stop exactly one card-addressable workflow/subagent and close only the delegate lanes it owns.
///
/// This is intentionally narrower than `terminalizeDelegatedWorkState`: an individual card must
/// never settle a sibling run. Workflow aggregates are selected even when they are already terminal
/// if one of their nested children is still live, which heals the persisted inconsistency that can
/// otherwise leave a child spinner behind forever.
@discardableResult
func stopDelegatedRunState(
    matching taskID: String,
    workflowRuns: inout [String: WorkflowRun],
    subagents: inout [String: SubagentRun],
    agentActivity: inout [AgentActivityRecord],
    at observedAt: Date = Date(),
    captureOrdinal: UInt64? = nil
) -> Bool {
    guard !taskID.isEmpty else { return false }

    let matchedWorkflowKeys = workflowRuns.keys.sorted().filter { storageKey in
        guard let run = workflowRuns[storageKey] else { return false }
        let identifiers = [storageKey, run.runKey, run.toolUseId, run.runTaskId]
            .compactMap { $0 }
        guard identifiers.contains(taskID) else { return false }
        return !run.status.isTerminal
            || run.agents.values.contains { !$0.state.isTerminal }
    }

    // Provider child ids connect a workflow-tree row to its standalone subagent mirror. Stopping
    // the workflow must settle both projections of that same child, without widening to any other
    // workflow or standalone sibling.
    var workflowIdentitiesByProviderID: [String: Set<String>] = [:]
    for storageKey in matchedWorkflowKeys {
        guard let run = workflowRuns[storageKey] else { continue }
        let runKey = run.runKey.isEmpty ? storageKey : run.runKey
        for (agentKey, agent) in run.agents {
            guard let providerID = agent.agentId, !providerID.isEmpty else { continue }
            workflowIdentitiesByProviderID[providerID, default: []].insert(
                AgentActivityIdentity.workflow(runKey: runKey, agentKey: agentKey))
        }
    }

    var subagentKeyByProviderID: [String: String] = [:]
    for storageKey in subagents.keys.sorted() {
        guard let subagent = subagents[storageKey] else { continue }
        if subagentKeyByProviderID[subagent.key] == nil {
            subagentKeyByProviderID[subagent.key] = storageKey
        }
        if let taskID = subagent.taskId, !taskID.isEmpty,
           subagentKeyByProviderID[taskID] == nil {
            subagentKeyByProviderID[taskID] = storageKey
        }
    }

    var matchedSubagentKeys = Set<String>(subagents.compactMap {
        storageKey, subagent -> String? in
        guard !subagent.status.isTerminal,
              subagent.key == taskID || subagent.taskId == taskID else { return nil }
        return storageKey
    })
    for providerID in workflowIdentitiesByProviderID.keys {
        if let storageKey = subagentKeyByProviderID[providerID],
           subagents[storageKey]?.status.isTerminal == false {
            matchedSubagentKeys.insert(storageKey)
        }
    }

    guard !matchedWorkflowKeys.isEmpty || !matchedSubagentKeys.isEmpty else { return false }

    var changed = false
    var laneOrder: [String] = []
    var laneIdentities: [String: Set<String>] = [:]
    var laneLabels: [String: String] = [:]
    func collectLane(
        agentID: String,
        identities: Set<String>,
        label: String
    ) {
        if laneIdentities[agentID] == nil { laneOrder.append(agentID) }
        laneIdentities[agentID, default: []].formUnion(identities)
        if laneLabels[agentID] == nil { laneLabels[agentID] = label }
    }

    for storageKey in matchedSubagentKeys.sorted() {
        guard var subagent = subagents[storageKey], !subagent.status.isTerminal else { continue }
        subagent.status = .stopped
        if subagent.endedAt == nil {
            subagent.endedAt = observedAt
            subagent.endedCaptureOrdinal = captureOrdinal
        }
        subagents[storageKey] = subagent
        changed = true

        let identity = subagent.taskId.flatMap { $0.isEmpty ? nil : $0 } ?? subagent.key
        var matchingIdentities = delegatedActivityIdentities(for: subagent)
        matchingIdentities.formUnion(workflowIdentitiesByProviderID[subagent.key] ?? [])
        if let providerID = subagent.taskId {
            matchingIdentities.formUnion(workflowIdentitiesByProviderID[providerID] ?? [])
        }
        collectLane(
            agentID: AgentActivityIdentity.subagent(identity),
            identities: matchingIdentities,
            label: subagent.subagentType.isEmpty ? "Agent" : subagent.subagentType)
    }

    for storageKey in matchedWorkflowKeys {
        guard var run = workflowRuns[storageKey] else { continue }
        let runKey = run.runKey.isEmpty ? storageKey : run.runKey
        var runChanged = false
        if !run.status.isTerminal {
            run.status = .stopped
            runChanged = true
        }

        for agentKey in run.agents.keys.sorted() {
            guard var agent = run.agents[agentKey], !agent.state.isTerminal else { continue }
            agent.state = .stopped
            if agent.endedAt == nil { agent.endedAt = observedAt }
            run.agents[agentKey] = agent
            runChanged = true

            let workflowIdentity = AgentActivityIdentity.workflow(
                runKey: runKey,
                agentKey: agentKey)
            var matchingIdentities = Set([workflowIdentity])
            let agentID: String
            if let providerID = agent.agentId,
               let mirroredKey = subagentKeyByProviderID[providerID],
               let mirrored = subagents[mirroredKey] {
                let identity = mirrored.taskId.flatMap { $0.isEmpty ? nil : $0 } ?? mirrored.key
                agentID = AgentActivityIdentity.subagent(identity)
                matchingIdentities.formUnion(delegatedActivityIdentities(for: mirrored))
                matchingIdentities.formUnion(
                    workflowIdentitiesByProviderID[providerID] ?? [])
            } else {
                agentID = workflowIdentity
                if let providerID = agent.agentId, !providerID.isEmpty {
                    matchingIdentities.insert(AgentActivityIdentity.subagent(providerID))
                }
            }
            collectLane(
                agentID: agentID,
                identities: matchingIdentities,
                label: agent.label.isEmpty ? "Agent \(agent.index)" : agent.label)
        }

        if runChanged {
            if run.endedAt == nil { run.endedAt = observedAt }
            workflowRuns[storageKey] = run
            changed = true
        }
    }

    guard changed else { return false }

    // A synthetic terminal state uses the delegate's own historical turn and route attribution.
    // If the card never opened a lane, keep the record unowned instead of attaching it to whichever
    // unrelated root turn happens to be newest in the conversation.
    for agentID in laneOrder {
        let identities = laneIdentities[agentID] ?? [agentID]
        let ownLane = latestDelegatedActivityLane(
            in: agentActivity,
            matching: identities)
        let laneAttribution = ownLane.flatMap { lane -> AgentActivityRecord? in
            agentActivity.last {
                identities.contains($0.agentID)
                    && $0.turnID == lane.turnID
                    && ($0.providerAccess != nil || $0.modelID?.isEmpty == false)
            } ?? lane
        }
        var record = AgentActivityRecord.state(
            .stopped,
            turnID: ownLane?.turnID,
            agentID: agentID,
            agentLabel: laneLabels[agentID],
            detail: "Stopped by user",
            at: observedAt)
        record.captureOrdinal = captureOrdinal
        if let laneAttribution {
            record.providerAccess = laneAttribution.providerAccess
            record.modelID = laneAttribution.modelID
        }
        appendAgentActivityRecord(record, to: &agentActivity)
    }
    return true
}

/// Retire only the authorize request that a successfully written cancel targets. Keeping this
/// mutation independent of AgentBridge's daemon plumbing makes its two safety properties explicit:
/// the old terminal loses its route, while a newer owner (if one exists) is never cleared.
enum MCPAuthorizationCancellationRouting {
    static func retireOriginal<Route, Owner>(
        requestID: String,
        routes: inout [String: Route],
        owner: inout Owner?,
        ownerRequestID: (Owner) -> String
    ) {
        routes.removeValue(forKey: requestID)
        if owner.map(ownerRequestID) == requestID {
            owner = nil
        }
    }
}

/// A launch hydration may finish after a projected first click has selected another row. Keep the
/// publication fence value-only so the last-intent rule is testable without starting a provider.
enum InitialConversationHydrationPublication {
    static func isCurrent(
        targetID: UUID,
        token: UUID,
        pendingID: UUID?,
        pendingToken: UUID?,
        currentID: UUID?
    ) -> Bool {
        currentID == nil && pendingID == targetID && pendingToken == token
    }

    static func shouldPrepareSQLiteWorkspaceInventory(
        conversationUsedSQLiteLaunchInventory: Bool
    ) -> Bool {
        conversationUsedSQLiteLaunchInventory
    }

    static func shouldRetryOpeningHydration(
        initialViewResolutionPending: Bool,
        openingID: UUID?,
        pendingSelectionID: UUID?,
        currentID: UUID?
    ) -> Bool {
        initialViewResolutionPending
            && openingID != nil
            && pendingSelectionID == nil
            && currentID == nil
    }

    static func scopedBootstrapRequiresProviderLoad(
        preferredID: UUID,
        currentID: UUID?,
        hasResidentValue: Bool
    ) -> Bool {
        preferredID == currentID && hasResidentValue
    }
}

/// Process-wide recovery rules for durable queues and waits reconstructed at launch. The selected
/// transcript is deliberately absent: one corrupt inert record may keep its own window in repair,
/// but cannot hold unrelated operative work behind that window's presentation gate.
enum PersistedOperativeRecovery {
    static func unclaimedWaitIDs(
        persistedWaitIDs: Set<UUID>,
        processClaimedWaitIDs: Set<UUID>
    ) -> Set<UUID> {
        persistedWaitIDs.subtracting(processClaimedWaitIDs)
    }

    static func canDrainQueues(
        storeIsReady: Bool,
        workspaceInventoryIsReady: Bool,
        operativeStateWasAdopted: Bool
    ) -> Bool {
        storeIsReady && workspaceInventoryIsReady && operativeStateWasAdopted
    }

    /// Closing the bridge that owns process-local wait timers must not silently unschedule its
    /// durable triggers while other restored windows remain. A deterministic recipient avoids two
    /// survivors racing to take the same handoff; if none is ready yet, its normal launch adoption
    /// callback will claim the now-unowned waits later.
    static func waitHandoffRecipientID(
        departingWaitIDs: Set<UUID>,
        readySurvivingBridgeIDs: Set<UUID>
    ) -> UUID? {
        guard !departingWaitIDs.isEmpty else { return nil }
        return readySurvivingBridgeIDs.min {
            $0.uuidString < $1.uuidString
        }
    }
}

/// One gate shared by every automatic WaitFor path. Keeping the policy decision outside the
/// timer/process plumbing makes the minimum-build half of the restriction testable without
/// constructing a bridge or launching a shell command.
enum AutomaticWaitPolicy {
    static func isAllowed(
        managedPolicy: ManagedEnterprisePolicy?,
        currentBuild: Int = ManagedEnterprisePolicy.currentAppBuild
    ) -> Bool {
        managedPolicy?.allowsUnattendedWork(currentBuild: currentBuild) ?? true
    }

    /// A persisted check predating MDM has not passed through this launch's daemon authorization.
    /// Plan may still resume on a declared deadline, but it must never execute that retained shell.
    static func allowsShellChecks(
        managedPolicy: ManagedEnterprisePolicy?,
        currentBuild: Int = ManagedEnterprisePolicy.currentAppBuild
    ) -> Bool {
        isAllowed(managedPolicy: managedPolicy, currentBuild: currentBuild)
            && managedPolicy?.maximumInteractivePermissionMode != "plan"
    }
}

/// Owns the conversation list + disk persistence, spawns and drives `agentd`, and
/// translates its NDJSON event stream into observable UI state. The app's view-model.
///
/// A presentation consumer may use this descriptor only when its resident transcript generation
/// exactly equals `baseGeneration`. A missed/coalesced publication therefore fails closed to the
/// canonical transcript instead of attempting to replay an incomplete suffix.
struct TranscriptTailAppend: Equatable {
    let conversationID: UUID
    let entryID: UUID
    let baseGeneration: UInt64
    let generation: UInt64
    let baseUTF8Count: Int
    let resultingUTF8Count: Int
    let delta: String
}

/// A bounded, read-only tail shown while the exact Conversation reconstructs off the main actor.
/// It is deliberately not a Conversation and never enters `entries`, so no persistence path can
/// mistake this quick presentation value for a complete transcript.
struct ConversationTranscriptPreview: Equatable {
    let conversationID: UUID
    let entries: [TranscriptEntry]?
    let revision: UUID

    var isLoading: Bool { entries == nil }
}

/// Process-local, content-free evidence for the most recent explicit Conversation selection. The
/// values are intentionally not persisted or published into the SwiftUI graph; tests and runtime
/// logs can still distinguish preview queueing, preview I/O, whole-record hydration, and the final
/// bridge install when a switch feels slow.
struct ConversationSelectionTimingMetrics: Equatable, Sendable {
    var sequence: UInt64 = 0
    var lastPreviewMilliseconds: Double?
    var lastPreviewQueueWaitMilliseconds: Double?
    var lastPreviewReadMilliseconds: Double?
    var lastHydrationMilliseconds: Double?
    var lastHydrationQueueWaitMilliseconds: Double?
    var lastHydrationReadMilliseconds: Double?
    var lastInstallMilliseconds: Double?
    var lastNativePresentationSyncMilliseconds: Double?
    var slowestPreviewMilliseconds: Double?
    var slowestHydrationMilliseconds: Double?
    var slowestHydrationQueueWaitMilliseconds: Double?
    var slowestHydrationReadMilliseconds: Double?
    var slowestInstallMilliseconds: Double?
    var slowestNativePresentationSyncMilliseconds: Double?
}

private struct ConversationSelectionTimingContext {
    let sequence: UInt64
    let destinationID: UUID
    let startedAt: ContinuousClock.Instant
}

/// Process-wide completion barrier for an interactive account reload. Each workspace window owns
/// its own provider daemon, so the first daemon to publish the new account cannot release queues
/// belonging to a slower sibling. Only exact non-secret account identity plus the expected signed-in
/// state retires one target; closing a sibling explicitly retires that target instead of wedging the
/// user-owned operation forever.
struct ProviderAccountReloadBarrier: Equatable {
    enum Acknowledgement: Equatable {
        case accepted
        case unknownRuntime
        case wrongAccountIdentity
        case wrongAccountState
    }

    let accountInstanceID: ProviderAccountInstanceID
    let expectedLoggedIn: Bool
    private(set) var pendingBridgeIDs: Set<UUID>

    var isComplete: Bool { pendingBridgeIDs.isEmpty }

    mutating func acknowledge(
        bridgeID: UUID,
        accountInstanceID: ProviderAccountInstanceID,
        loggedIn: Bool
    ) -> Acknowledgement {
        guard pendingBridgeIDs.contains(bridgeID) else { return .unknownRuntime }
        guard accountInstanceID == self.accountInstanceID else {
            return .wrongAccountIdentity
        }
        guard loggedIn == expectedLoggedIn else { return .wrongAccountState }
        pendingBridgeIDs.remove(bridgeID)
        return .accepted
    }

    mutating func retire(bridgeID: UUID) {
        pendingBridgeIDs.remove(bridgeID)
    }

    mutating func register(bridgeID: UUID) {
        pendingBridgeIDs.insert(bridgeID)
    }
}

struct ProviderRuntimeAccountReloadExpectation: Equatable {
    let accountInstanceID: ProviderAccountInstanceID
    let credentialEpoch: Int

    func accepts(
        rawAccountInstanceID: String?,
        currentAccountInstanceID: ProviderAccountInstanceID,
        currentCredentialEpoch: Int
    ) -> Bool {
        guard let rawAccountInstanceID,
              let uuid = UUID(uuidString: rawAccountInstanceID) else { return false }
        return ProviderAccountInstanceID(rawValue: uuid) == accountInstanceID
            && currentAccountInstanceID == accountInstanceID
            && currentCredentialEpoch == credentialEpoch
    }
}

/// Resolves only the transient click acknowledgement after a saved authorization attempt is
/// reconciled. A different server may win the durable lane between the click and the deferred
/// continuation; that server owns the request, so the originally clicked row must return to idle.
enum MCPAuthorizationPreparationStateResolver {
    static func finishingState(
        clickedServer: String,
        reconciledServer: String,
        launched: Bool,
        currentState: MCPAuthState
    ) -> MCPAuthState? {
        guard currentState == .preparing else { return nil }
        guard clickedServer == reconciledServer else { return .idle }
        return launched
            ? .authorizing
            : .failed("Mechanician could not resume the saved sign-in attempt.")
    }
}

/// A click-accepted preparation is already a provider-session mutation even though its durable
/// write-ahead row is created on the next UI turn. Treat both phases as the same exposure barrier
/// so a queued send, prewarm, or Review cannot enter the old provider session between them.
enum MCPAuthorizationProviderExposurePolicy {
    static func isBlocked(
        preparationInFlight: Bool,
        hasPendingAttempt: Bool
    ) -> Bool {
        preparationInFlight || hasPendingAttempt
    }
}

@MainActor
final class AgentBridge: ObservableObject {
    @Published var entries: [TranscriptEntry] = [] {
        didSet {
            // This observer covers every structural replacement and in-place field mutation, not
            // just the streaming helpers below. The append descriptor is reinstalled only by the
            // exact existing-tail path in `flushAssistant()` after that mutation is complete.
            transcriptEntriesGeneration &+= 1
            transcriptTailAppend = nil
        }
    }
    private(set) var transcriptEntriesGeneration: UInt64 = 0
    private(set) var transcriptTailAppend: TranscriptTailAppend?
    /// Whether the window's foreground transcript/delegate/artifact snapshot differs from the
    /// shared durable conversation. Conversation selection used to rewrite a 30–40 MB sidecar even
    /// after an idle, already-persisted turn; repeated switches saturated the encoder and contended
    /// with the destination table. Turn/user mutations set this, and a full snapshot save clears it.
    private var currentConversationNeedsPersistence = false {
        didSet {
            if currentConversationNeedsPersistence {
                scheduleCurrentConversationCheckpoint()
            } else {
                cancelCurrentConversationCheckpoint()
            }
        }
    }
    /// Foreground assistant bytes live in this bridge until `persistCurrent` folds them into the
    /// shared store. Mirror the store's non-sliding checkpoint deadline here: one timer per dirty
    /// interval, never one encode or timer re-arm per token.
    private var currentConversationCheckpointWork: DispatchWorkItem?
    private var currentConversationCheckpointID: UUID?
    private var currentConversationCheckpointGeneration: UInt64 = 0
    /// The single source of truth for the conversation LIST, shared by every window/tab in the
    /// process. This bridge holds only per-WINDOW view state (currentID, entries, turn state); the
    /// durable list + its persistence live in the store. A create/rename/delete/update in ANY window
    /// republishes here (see the objectWillChange forward in `init`), so every sidebar stays
    /// consistent — no NotificationCenter broadcast, no last-writer-wins races. Streaming-only
    /// resident deltas stay off that process-wide publication plane until their bounded summary or
    /// durable terminal boundary.
    let store: ConversationStore
    var conversations: [Conversation] { store.conversations }
    var conversationSummaries: [ConversationSummary] { store.summaries }
    /// Combine subscriptions (the store→bridge change forward). Cancelled automatically on dealloc.
    private var cancellables = Set<AnyCancellable>()
    /// Drives `reapSilentDelegatedWork`. Time-driven because a delegate going silent emits nothing.
    private var silentDelegateReaper: Timer?
    /// Advances at the actual mutation edge for navigation that beats the asynchronous store load.
    /// Projected sidebar clicks retain this value so a later explicit ⌘N/navigation wins even if
    /// SwiftUI observes both that mutation and store readiness in one render pass.
    private(set) var preReadyNavigationGeneration: UInt64 = 0
    @Published var currentID: UUID? {
        didSet {
            if currentID != oldValue,
               let departingID = oldValue {
                store.retainForBackNavigation(departingID, owner: bridgeID)
            }
            preReadyNavigationGeneration =
                WorkspaceBootstrapReadiness.preReadyNavigationGeneration(
                    after: preReadyNavigationGeneration,
                    storeIsReady: store.isReady,
                    destinationChanged: currentID != oldValue)
            if let id = currentID { UserDefaults.standard.set(id.uuidString, forKey: "lastConversationID") }
            // Landing on a different conversation is always a request to type in it. Doing it here
            // rather than at each call site covers every route — the sidebar, Spotlight, the
            // background-turn jump, the fallback after a delete, workspace switches — instead of
            // relying on each one to remember. `select` used to be the one that forgot.
            if currentID != oldValue {
                cancelProviderSetupRecovery()
                pendingConversationWorkContextIDs = []
                pendingRepositoryWorkContextSources = []
                pendingRepositoryWorkContextTargetID = nil
                focusComposer()
            }
        }
    }
    /// The exact launch/restoration target whose full record is still hydrating. The SQLite launch
    /// inventory can become usable before an inert Conversation's transcript is resident; keeping
    /// that distinction on the window prevents inventory readiness from flashing an empty composer
    /// or manufacturing a replacement Conversation while the saved one is still opening.
    @Published private(set) var openingConversationID: UUID?
    /// True from window construction until its initial target has been conclusively installed (or
    /// an explicit user-created target wins). Inventory readiness alone is not presentation
    /// readiness: Workspace validation and selected-record hydration both cross later async edges.
    @Published private(set) var initialViewResolutionPending = true
    /// A target whose authoritative bytes are loading off-main. It participates in the one-owner
    /// rule before `currentID` changes, preventing two windows from acquiring independent snapshots.
    @Published private(set) var pendingSelectionID: UUID?
    private var pendingSelectionToken: UUID?
    private var pendingSelectionHydrationRequest: ConversationHydrationRequest?
    private var pendingSelectionHydrationTiming: ConversationHydrationTiming?
    private var pendingSelectionTranscriptPageRequest: ConversationTranscriptPageRequest?
    private var pendingSelectionCompletion: ((Bool) -> Void)?
    @Published private(set) var conversationTranscriptPreview: ConversationTranscriptPreview?
    private(set) var conversationSelectionTimingMetrics = ConversationSelectionTimingMetrics()
    private var conversationSelectionTimingContext: ConversationSelectionTimingContext?
    @Published var mode = "starting…"
    @Published var cwd = ""

    /// Bumped when this workspace's inspector tab set changes.
    ///
    /// The choice itself lives in `UserDefaults` (`InspectorTabPreference`) because it is a view
    /// preference, and `UserDefaults` does not publish. Without this the bar would keep drawing the
    /// old set until something else happened to redraw it, which is indistinguishable from the menu
    /// not working.
    @Published var inspectorTabRevision: UInt64 = 0

    /// The directory a turn runs in. Once a conversation exists its own cwd is authoritative:
    /// folderless Home/topic conversations use the neutral home fallback and never inherit whichever
    /// workspace this window happens to display while a queued background turn starts.
    func turnCwd(for conv: Conversation?) -> String {
        let c = conv.map(\.cwd) ?? cwd
        return c.isEmpty ? FileManager.default.homeDirectoryForCurrentUser.path : c
    }

    nonisolated static let standardToolProfile = ProviderToolProfile.standard.rawValue
    nonisolated static let helpExpertToolProfile = ProviderToolProfile.helpExpert.rawValue
    nonisolated static let helpExpertWorkspaceInstructionsRevision = "help-expert-v2-show"

    /// The model-visible capability set follows the conversation's durable workspace identity.
    /// Never infer this from cwd or title: the reserved Help Workspace deliberately has no folder
    /// and shares Home's neutral cwd, while an ordinary conversation may be titled Help.
    static func toolProfile(for conversation: Conversation) -> ProviderToolProfile {
        switch ReservedWorkspace.workspace(for: conversation.projectID) {
        case .help: .helpExpert
        case nil: .standard
        }
    }

    /// A closed product-profile turn is not a repository turn even though the provider protocol
    /// requires a cwd. Remove hostile or stale workspace/repository material at the same boundary
    /// that stamps its fixed profile revision. The daemon independently enforces the mounted schema.
    nonisolated static func applyClosedProfileInstructionBoundary(
        revision: String,
        to request: inout [String: Any]
    ) {
        request["projectInstructions"] = ""
        request["workspaceInstructionsRevision"] = revision
        request["allowRepositoryInstructions"] = false
    }

    /// Import only the workspace-root instruction file that Mechanician explicitly presents in its
    /// UI. The Claude SDK's `project` setting source also loads hooks, permissions, MCP servers, and
    /// nested settings, so enabling it would undo the provider-isolation boundary. Keep the useful
    /// instruction contract while bounding size and refusing symlinks/binary content.
    nonisolated static func folderClaudeInstructions(
        at cwd: String,
        maximumBytes: Int = 256 * 1024
    ) -> String? {
        guard !cwd.isEmpty, maximumBytes >= 0 else { return nil }
        let url = URL(fileURLWithPath: cwd, isDirectory: true)
            .appendingPathComponent("CLAUDE.md", isDirectory: false)
        guard let data = boundedWorkspaceInstructionData(at: url, maximumBytes: maximumBytes),
              !data.contains(0),
              let text = String(data: data, encoding: .utf8) else { return nil }
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    /// CLAUDE.md is an intentionally mutable workspace input. Copy only its bounded bytes after
    /// proving the opened descriptor remains the same regular, non-symlinked file.
    nonisolated private static func boundedWorkspaceInstructionData(
        at url: URL,
        maximumBytes: Int
    ) -> Data? {
        let descriptor = url.withUnsafeFileSystemRepresentation { path -> Int32 in
            guard let path else { return -1 }
            return Darwin.open(path, O_RDONLY | O_NONBLOCK | O_CLOEXEC | O_NOFOLLOW)
        }
        guard descriptor >= 0 else { return nil }
        let handle = FileHandle(fileDescriptor: descriptor, closeOnDealloc: true)
        defer { try? handle.close() }

        var initial = stat()
        guard Darwin.fstat(descriptor, &initial) == 0,
              (initial.st_mode & S_IFMT) == S_IFREG,
              initial.st_size >= 0,
              initial.st_size <= off_t(maximumBytes) else {
            return nil
        }

        var data = Data()
        data.reserveCapacity(Int(initial.st_size))
        while data.count <= maximumBytes {
            let remaining = maximumBytes + 1 - data.count
            guard remaining > 0 else { break }
            let chunk: Data
            do {
                guard let next = try handle.read(upToCount: min(64 * 1_024, remaining)) else {
                    break
                }
                chunk = next
            } catch {
                return nil
            }
            guard !chunk.isEmpty else { break }
            data.append(chunk)
        }

        var final = stat()
        guard data.count <= maximumBytes,
              data.count == Int(initial.st_size),
              Darwin.fstat(descriptor, &final) == 0,
              unchangedWorkspaceInstructionMetadata(initial, final) else {
            return nil
        }
        return data
    }

    nonisolated private static func unchangedWorkspaceInstructionMetadata(
        _ initial: stat,
        _ final: stat
    ) -> Bool {
        initial.st_mode == final.st_mode
            && initial.st_dev == final.st_dev
            && initial.st_ino == final.st_ino
            && initial.st_size == final.st_size
            && initial.st_mtimespec.tv_sec == final.st_mtimespec.tv_sec
            && initial.st_mtimespec.tv_nsec == final.st_mtimespec.tv_nsec
            && initial.st_ctimespec.tv_sec == final.st_ctimespec.tv_sec
            && initial.st_ctimespec.tv_nsec == final.st_ctimespec.tv_nsec
    }

    private struct ClaudeInstructionCacheEntry {
        var modificationDate: Date?
        var fileSize: Int
        var text: String?
    }
    private var claudeInstructionCache: [String: ClaudeInstructionCacheEntry] = [:]

    /// A selected Claude conversation can be prewarmed and then sent repeatedly. Check cheap file
    /// metadata each time so an edited CLAUDE.md is noticed, but read/decode its bounded contents
    /// only on a cache miss. Codex/OpenAI never call this path.
    private func cachedFolderClaudeInstructions(at cwd: String) -> String? {
        let file = URL(fileURLWithPath: cwd, isDirectory: true)
            .appendingPathComponent("CLAUDE.md", isDirectory: false)
        guard let values = try? file.resourceValues(
            forKeys: [
                .isRegularFileKey, .isSymbolicLinkKey, .fileSizeKey,
                .contentModificationDateKey,
            ]),
              values.isRegularFile == true,
              values.isSymbolicLink != true,
              let size = values.fileSize else {
            claudeInstructionCache[cwd] = nil
            return nil
        }
        if let cached = claudeInstructionCache[cwd],
           cached.fileSize == size,
           cached.modificationDate == values.contentModificationDate {
            return cached.text
        }
        let text = Self.folderClaudeInstructions(at: cwd)
        claudeInstructionCache[cwd] = ClaudeInstructionCacheEntry(
            modificationDate: values.contentModificationDate,
            fileSize: size,
            text: text)
        return text
    }

    private struct WorkspaceInstructionResolution {
        let snapshot: WorkspaceInstructionSnapshot?
    }

    /// Resolve from the conversation itself, never the currently visible window binding. Learned
    /// procedures are selected from the same exact Workspace/provider authority read and folded
    /// into this immutable snapshot, so session identity, provider bytes, and the later applied
    /// disclosure cannot drift. Review and closed product-profile turns deliberately opt out.
    private func workspaceInstructionResolution(
        for conversation: Conversation,
        selection: ModelSelection
    ) -> WorkspaceInstructionResolution {
        // Help's closed profile must not even resolve a mutable Project row, repository file, or
        // learned procedure. The final wire boundary below also clears hostile pre-existing keys.
        guard Self.toolProfile(for: conversation) != .helpExpert else {
            return WorkspaceInstructionResolution(snapshot: nil)
        }
        let projects = ProjectStore.shared.projects
        let base = WorkspaceInstructionResolver.snapshot(
            for: conversation,
            access: selection.access,
            projects: projects,
            homeInstructions: ProjectStore.shared.homeSettings.instructions,
            claudeFileReader: cachedFolderClaudeInstructions)
        return WorkspaceInstructionResolution(snapshot: base)
    }

    private func workspaceInstructionSnapshot(
        for conversation: Conversation,
        selection: ModelSelection
    ) -> WorkspaceInstructionSnapshot? {
        workspaceInstructionResolution(
            for: conversation,
            selection: selection).snapshot
    }

    /// A missing/dangling workspace still gets a stable identity. That prevents a deleted Project's
    /// provider session from quietly retaining the old instructions after resolution correctly
    /// refuses to fall through to Home.
    private func workspaceInstructionsRevision(
        snapshot: WorkspaceInstructionSnapshot?,
        conversation: Conversation,
        access: ModelAccess
    ) -> String {
        if let snapshot { return snapshot.sessionRevision(for: access) }
        return WorkspaceInstructionSnapshot.revision(
            for: "workspace-instructions-v1\u{1f}unresolved\u{1f}"
                + (conversation.projectID?.uuidString ?? "") + "\u{1f}" + conversation.cwd
        )!
    }

    /// Resolve configured external-tool identity only for profiles whose historical session
    /// contract includes it. Keeping the resolver lazy proves that Help never even consults the
    /// mutable extension inventory while deriving its provider-session identity.
    nonisolated static func externalExtensionRevision(
        for toolProfile: ProviderToolProfile,
        resolving configuredRevision: () -> UUID?
    ) -> UUID? {
        guard toolProfile.includesExternalExtensionRevision else { return nil }
        return configuredRevision()
    }

    /// Resolve one immutable receipt for everything that determines the provider session's visible
    /// tool/instruction shape. Every send, background send, load, resume, and prewarm uses this
    /// exact helper; no path may independently reconstruct a "close enough" product profile.
    private func providerSessionConfigurationEnvelope(
        for conversation: Conversation,
        selection: ModelSelection,
        instructionSnapshot: WorkspaceInstructionSnapshot?,
        permissionMode effectivePermissionMode: String
    ) -> ProviderSessionConfigurationEnvelope {
        let toolProfile = Self.toolProfile(for: conversation)
        let ordinaryWorkspaceRevision = workspaceInstructionsRevision(
            snapshot: instructionSnapshot,
            conversation: conversation,
            access: selection.access)
        let external = Self.externalExtensionRevision(for: toolProfile) {
            ExtensionsStore.shared.providerSessionConfigurationRevision(for: selection.access)
        }
        let use1M = (UserDefaults.standard.object(forKey: "use1MContext") as? Bool) ?? true
        return Self.providerSessionConfigurationEnvelope(
            for: selection.access,
            externalRevision: external,
            use1M: use1M,
            permissionMode: effectivePermissionMode,
            toolProfile: toolProfile,
            workspaceInstructionsRevision: ordinaryWorkspaceRevision)
    }

    /// Add only the provider-supported instruction payload. `allowRepositoryInstructions` tells
    /// Codex whether App Server may perform native AGENTS.md discovery in the selected workspace;
    /// Home/topic/unresolved conversations run in a fallback cwd but must not inherit that folder.
    nonisolated static func applyWorkspaceInstructionSnapshot(
        _ snapshot: WorkspaceInstructionSnapshot?,
        revision: String,
        access: ModelAccess,
        to request: inout [String: Any]
    ) {
        request["workspaceInstructionsRevision"] = revision
        if access == .codexSubscription {
            request["allowRepositoryInstructions"] =
                snapshot?.allowsCodexRepositoryInstructions == true
        }
        if let instructions = snapshot?.effectiveText(for: access) {
            request["projectInstructions"] = instructions
        }
    }

    /// Put the immutable session envelope on the wire. The profile and effective instruction
    /// revision travel together so prewarm cannot prepare one schema while send asks for another.
    nonisolated static func applyProviderSessionConfiguration(
        _ configuration: ProviderSessionConfigurationEnvelope,
        instructionSnapshot: WorkspaceInstructionSnapshot?,
        access: ModelAccess,
        to request: inout [String: Any]
    ) {
        request["toolProfile"] = configuration.toolProfile.rawValue
        if configuration.toolProfile != .standard {
            applyClosedProfileInstructionBoundary(
                revision: configuration.workspaceInstructionsRevision,
                to: &request)
        } else {
            applyWorkspaceInstructionSnapshot(
                instructionSnapshot,
                revision: configuration.workspaceInstructionsRevision,
                access: access,
                to: &request)
        }
    }

    /// The Project this window is bound to when it cannot be resolved from a folder path (notably a
    /// folderless workspace). `WorkspaceScope` resolves folder-backed windows to the same identity.
    @Published var projectID: UUID?
    /// The shared editor is presented from launcher, toolbar, and menu entry points with one target
    /// identity. nil means closed.
    @Published var workspaceInstructionsEditorTarget: WorkspaceInstructionsTarget?
    var workspaceDisplayTitle: String {
        Self.workspaceDisplayTitle(
            projectID: projectID,
            cwd: cwd,
            projects: ProjectStore.shared.projects)
    }

    static func workspaceDisplayTitle(
        projectID: UUID?,
        cwd: String,
        projects: [Project]
    ) -> String {
        if let projectID, let project = projects.first(where: { $0.id == projectID }) {
            return project.displayName
        }
        if !cwd.isEmpty {
            if let project = projects.first(where: { $0.cwd == cwd }) {
                return project.displayName
            }
            return URL(fileURLWithPath: cwd).lastPathComponent
        }
        return "Home"
    }

