    @Published private(set) var replayContinuationCategories:
        [UUID: [ReplayDegradationCategory]] = [:]
    var currentReplayContinuationCategories: [ReplayDegradationCategory]? {
        currentID.flatMap { replayContinuationCategories[$0] }
