    @Published private var provisionalUserEntry: TranscriptEntry?
    private var provisionalUserConversationID: UUID?
    var provisionalUserEntryForCurrentConversation: TranscriptEntry? {
        provisionalUserConversationID == currentID ? provisionalUserEntry : nil
