    static var turnInactivityTimeout: TimeInterval {
        let requested = ProcessInfo.processInfo.environment["MECHANICIAN_TURN_STALL_SECONDS"]
            .flatMap(Double.init)
        return min(max(requested ?? 180, 10), 30 * 60)
    }
    static var stopAcknowledgementGrace: TimeInterval {
        let requested = ProcessInfo.processInfo.environment[
            "MECHANICIAN_STOP_ACK_GRACE_SECONDS"
        ].flatMap(Double.init)
        // Codex already spends up to roughly seven seconds on its own interrupt/reconciliation
        // path. Ten seconds lets that finish first while still bounding a wedged Claude/OpenAI
        // provider. The small test floor is never selected in production without an explicit env.
        return min(max(requested ?? 10, 0.05), 30)
    }
