    private enum ProviderNeutralControlKind {
        case setFolder(path: String)
        case gitStatus
        /// Background evidence capture for one exact Conversation boundary. It must never replace
        /// the visible Changes snapshot merely because its reply is also `git_status_result`.
        case gitEvidenceCapture(PendingRepositoryEvidenceCapture)
        case gitDiff
        case gitMutation
        case gitPush

        func accepts(_ eventType: String) -> Bool {
            if eventType == "control_error" { return true }
            switch self {
            case .setFolder: return eventType == "cwd"
            case .gitStatus, .gitEvidenceCapture:
                return eventType == "git_status_result"
            case .gitDiff: return eventType == "git_diff_result"
            case .gitMutation: return eventType == "git_done"
            case .gitPush: return eventType == "git_push_result"
            }
        }
    }

