    private enum ExtensionControlKind {
        case mcpAuthorize(name: String, attemptID: String)
        case mcpClearAuth(name: String, attemptID: String)
        case mcpReconcile(name: String, attemptID: String)
        case mcpAuthorizeCancel(name: String, attemptID: String)
        case mcpReload
        case mcpStatus
        case capabilityExecute(name: String)
        case claudePlugins
        case codexPlugins

        func accepts(_ event: [String: Any]) -> Bool {
            guard let type = event["type"] as? String else { return false }
            switch self {
            case .mcpAuthorize(let name, let attemptID):
                return event["name"] as? String == name
                    && Self.attemptID(in: event) == attemptID
                    && ["mcp_authorize_url", "mcp_authorize_ok", "mcp_authorize_error"].contains(type)
            case .mcpClearAuth(let name, let attemptID):
                return event["name"] as? String == name
                    && Self.attemptID(in: event) == attemptID
                    && ["mcp_clear_auth_ok", "mcp_authorize_error"].contains(type)
            case .mcpReconcile(let name, let attemptID):
                return event["name"] as? String == name
                    && Self.attemptID(in: event) == attemptID
                    && [
                        "mcp_authorize_url", "mcp_reconcile_ok", "mcp_reconcile_error",
                    ].contains(type)
            case .mcpAuthorizeCancel(let name, let attemptID):
                return event["name"] as? String == name
                    && Self.attemptID(in: event) == attemptID
                    && type == "mcp_authorize_cancel_ok"
            case .mcpReload:
                return type == "mcp_reload_ok" || type == "mcp_reload_error"
            case .mcpStatus:
                return type == "mcp_status_result"
            case .capabilityExecute(let name):
                return event["name"] as? String == name && type == "capability_execute_result"
            case .claudePlugins:
                return type == "claude_plugins_result"
            case .codexPlugins:
                return type == "codex_plugins_result"
            }
        }

        private static func attemptID(in event: [String: Any]) -> String? {
            (event["attemptId"] as? String) ?? (event["changeId"] as? String)
        }

        func isTerminal(_ eventType: String) -> Bool {
            switch self {
            case .mcpAuthorize:
                return eventType == "mcp_authorize_ok" || eventType == "mcp_authorize_error"
            case .mcpClearAuth:
                return eventType == "mcp_clear_auth_ok" || eventType == "mcp_authorize_error"
            case .mcpReconcile:
                return eventType == "mcp_reconcile_ok" || eventType == "mcp_reconcile_error"
            case .mcpAuthorizeCancel:
                return eventType == "mcp_authorize_cancel_ok"
            case .mcpReload:
                return eventType == "mcp_reload_ok" || eventType == "mcp_reload_error"
            case .mcpStatus:
                return eventType == "mcp_status_result"
            case .capabilityExecute:
                return eventType == "capability_execute_result"
            case .claudePlugins:
                return eventType == "claude_plugins_result"
            case .codexPlugins:
                return eventType == "codex_plugins_result"
            }
        }
    }

