    /// The model backend. Anthropic uses the Claude Agent SDK, direct OpenAI uses
    /// the Responses API, and Codex uses its local App Server with ChatGPT OAuth.
    /// A provider switch restarts only the daemon, never the transcript or workspace.
    @Published var provider = "anthropic" {
        didSet {
            guard !isProjectingModelSelection else { return }
            saveSettings()
            ActiveWorkspace.shared.accessDidChange(self)
        }
    }
    @Published var model = "claude-opus-4-8" {
        didSet {
            guard !isProjectingModelSelection else { return }
            if !availableEfforts.isEmpty, !availableEfforts.contains(effort) {
                effort = Self.preferredDefaultEffort(from: availableEfforts) ?? effort
            }
            syncEmptyConversationModelDefault()
            saveSettings()
        }
    }
    /// Codex deliberately supplies this list at runtime: entitlement and availability
    /// are account-specific, so hard-coding a public model catalog would be misleading.
    @Published private(set) var codexModels: [(String, String)] = []
    private var codexDefaultModel: String?
    private var codexEffortsByModel: [String: [String]] = [:]
    private var homeModelSelection: ModelSelection?
    /// App-wide account route used when a new conversation is created. This is deliberately
    /// independent from `currentModelAccess`: Settings may change the future default without
    /// retargeting any conversation that is already open.
    @Published private(set) var defaultConversationAccess: ModelAccess = .anthropicAPI
    private static let defaultConversationAccessPreferenceKey =
        "providerAccounts.defaultConversationAccess.v1"
    private var isProjectingModelSelection = false
    /// One explicit hand-off from this conversation's setup card into Providers. Generic account
    /// changes remain route-neutral; only an account action chosen while this intent exists may
    /// replace the otherwise-hidden model-picker step after the account is verified.
    @Published private(set) var providerSetupRecovery = ProviderSetupRecovery()
    private var isResolvingProviderSetupRecovery = false
    private var currentModelSelection: ModelSelection {
        ModelSelection(access: ModelAccess(provider: provider, authMode: authMode), modelID: model)
    }
    var selectedModelSelection: ModelSelection { currentModelSelection }
    var hasPendingProviderSetupRecovery: Bool { providerSetupRecovery.isPending }
    var pendingProviderSetupRecoveryDestination: ModelAccess? {
        providerSetupRecovery.intent?.destination
    }
    var pendingProviderSetupRecoveryOriginAccess: ModelAccess? {
        providerSetupRecovery.intent?.originalSelection.access
    }
    var pendingProviderSetupRecoveryProgressLabel: String? {
        guard let access = pendingProviderSetupRecoveryDestination else { return nil }
        if let operation = ProviderAccountStore.shared.operation(for: access) {
            return operation.progressLabel
        }
        let runtimeEvidence = ProviderSetupRecovery.runtimeEvidence(
            accountOperationInFlight: false,
            runtimeIsReady: isRuntimeReady(access),
            runtimeIsUsable: isRuntimeUsable(access))
        // A ready-but-rejected lane has reached a terminal answer. Keep the action visible so the
        // user can reconnect or choose another route; there is no future ready event to wait for.
        if runtimeEvidence == .rejected { return nil }
        let snapshot = pendingProviderSetupRecoveryCatalogSnapshot(for: access)
        if snapshot.phase == .loading {
            return "Preparing \(access.displayName)…"
        }
        if runtimes[access]?.isRunning == true, !isRuntimeReady(access) {
            return "Checking \(access.displayName)…"
        }
        return nil
    }
    var pendingProviderSetupRecoveryError: String? {
        guard let access = pendingProviderSetupRecoveryDestination else { return nil }
        // `disableCatalog` deliberately marks old rows failed while credentials are mutating.
        // The account operation already owns the banner's progress state, so that internal
        // invalidation is not a user-facing failure.
        guard ProviderAccountStore.shared.operation(for: access) == nil else { return nil }
        let snapshot = pendingProviderSetupRecoveryCatalogSnapshot(for: access)
        switch snapshot.phase {
        case .failed(let message):
            return message
        case .ready where snapshot.entries.isEmpty
            && access != pendingProviderSetupRecoveryOriginAccess:
            return "\(access.displayName) did not report any available models."
        case .idle, .loading, .ready:
            return nil
        }
    }

    /// A legacy conversation has no trustworthy provider identity for its opaque SDK session. The
    /// first explicit route it acquires must therefore start fresh instead of handing a Claude
    /// session ID to Codex/OpenAI (or the reverse).
    private static func stampLegacySelection(
        _ selection: ModelSelection,
        on conversation: inout Conversation
    ) {
        guard conversation.modelSelection == nil else { return }
        conversation.modelSelection = selection
        retireProviderSession(on: &conversation)
    }

    /// Retire every fact whose meaning is scoped to one opaque provider session. Keeping any one of
    /// these after a model/context variant change made the UI describe the old session while the
    /// next request silently resumed it. This is intentionally a persisted-record mutation so a
    /// second window, a background queue, or a relaunch observes the same fresh-session boundary.
    nonisolated static func retireProviderSession(on conversation: inout Conversation) {
        conversation.sdkSessionId = nil
        conversation.sdkSessionRouteIdentity = nil
        conversation.sdkSessionExtensionRevision = nil
        conversation.sdkSessionToolProfile = nil
        conversation.sdkSessionWorkspaceInstructionsRevision = nil
        conversation.claudeEffectiveModel = nil
        conversation.contextTokens = nil
        conversation.contextWindow = nil
        conversation.contextModel = nil
    }

    /// Apply an explicit same-lane model choice to durable state. An exact no-op is deliberately a
    /// no-op for the provider session too: merely reopening or re-clicking the selected row must not
    /// force a costly transcript replay. The caller has already enforced the active-work blocker.
    @discardableResult
    nonisolated static func applyExplicitSameAccessModelSelection(
        _ selection: ModelSelection,
        to conversation: inout Conversation
    ) -> Bool {
        guard conversation.modelSelection != selection else { return false }
        guard conversation.modelSelection == nil
                || conversation.modelSelection?.access == selection.access else { return false }
        retireProviderSession(on: &conversation)
        conversation.modelSelection = selection
        return true
    }

    /// Catalog healing is an automatic same-lane model change, but it crosses the same opaque
    /// provider-session boundary as an explicit picker change. The caller must send the healed
    /// request fresh; clearing the durable session here also keeps a relaunch or background drain
    /// from reviving the unavailable model's session after this turn.
    @discardableResult
    nonisolated static func applyAutomaticModelHealing(
        _ healed: ModelSelection,
        replacing stamped: ModelSelection,
        to conversation: inout Conversation
    ) -> Bool {
        guard healed != stamped,
              healed.access == stamped.access,
              conversation.modelSelection == nil
                || conversation.modelSelection == stamped else { return false }
        retireProviderSession(on: &conversation)
        conversation.modelSelection = healed
        return true
    }

    /// An opaque enterprise session may resume only against the exact signed backend that created
    /// it. Built-in providers retain their existing access-lane resume behavior.
    nonisolated static func resumableSessionID(
        for conversation: Conversation,
        access: ModelAccess,
        profile: TenantProfile,
        extensionRevision: UUID? = nil,
        workspaceInstructionsRevision: String? = nil,
        toolProfile: ProviderToolProfile = .standard
    ) -> String? {
        guard let sessionID = conversation.sdkSessionId else { return nil }
        // Sessions created before the profile receipt existed necessarily used the historical
        // standard surface, so preserve their ordinary resume behavior. Absence can never authorize
        // either closed product surface, and a value discarded by tolerant decoding remains an
        // explicit fail-closed mismatch instead of being mistaken for genuine legacy absence.
        switch conversation.sdkSessionToolProfile {
        case .some(let mountedProfile) where mountedProfile == toolProfile:
            break
        case nil where toolProfile == .standard
            && !conversation.decodeNormalizations.contains(.sessionToolProfile):
            break
        default:
            return nil
        }
        // Every lane, not just Anthropic. Measured against the pinned Codex binary: a thread binds
        // its MCP server set when it is created — after adding a server, `mcpServerStatus/list`
        // shows it process-wide while the existing thread still answers "unknown MCP server". So a
        // Codex conversation that resumes its thread could never reach a server the user just
        // added. Different mechanism from Claude's session-baked tool schema, same remedy.
        if conversation.sdkSessionExtensionRevision != extensionRevision { return nil }
        // Codex 0.144.6 ignores changed developerInstructions on an already-loaded thread (and its
        // cold-resume path can expose stale text on the first turn), so only an exact revision may
        // resume. Claude 0.3.219 accepts a new preset append while resuming the same session; its
        // warm-process identity already includes the bytes, so avoid an unnecessary history replay.
        if access == .codexSubscription,
           conversation.sdkSessionWorkspaceInstructionsRevision
            != workspaceInstructionsRevision { return nil }
        switch access {
        case .claudeVertex, .claudeBedrock:
            guard let activeIdentity = profile.routeIdentity(for: access),
                  conversation.sdkSessionRouteIdentity == activeIdentity
            else { return nil }
            return sessionID
        case .claudeSubscription, .anthropicAPI, .codexSubscription, .openAIAPI:
            return sessionID
        }
    }

    /// Claude persists a tool schema inside its opaque session. Fold a release-controlled built-in
    /// generation together with the user's external MCP/plugin generation so either kind of tool
    /// wiring change forces one fresh transcript replay. Plan now withholds OperateMechanician from
    /// the Help server, so the immutable session also distinguishes Plan from the one shared
    /// non-Plan schema class. Older sessions must replay once under this release generation.
    nonisolated static func anthropicSessionConfigurationRevision(
        externalRevision: UUID?,
        use1M: Bool,
        permissionMode: String
    ) -> UUID {
        // The material is load-bearing history: changing it rebases every existing Anthropic
        // session and costs one transcript replay each. The context variant is also session-scoped:
        // a daemon relaunched with the opposite 1M policy must never resume the opaque session that
        // the old model variant created. Both variants need the same Help schema generation bump.
        let generation = use1M
            ? "mechanician-anthropic-tools-v5-plan-help-surface"
            : "mechanician-anthropic-tools-v5-plan-help-surface-no-1m"
        // Default, Accept edits, and Full access expose the same Help tools. Coalescing them avoids
        // unnecessary transcript replay while preserving the one boundary that changes the schema.
        let permissionSchemaClass = permissionMode == "plan" ? "plan" : "non-plan"
        return sessionConfigurationRevision(
            builtInGeneration: "\(generation):\(permissionSchemaClass)",
            externalRevision: externalRevision)
    }

    private nonisolated static func sessionConfigurationRevision(
        builtInGeneration: String,
        externalRevision: UUID?
    ) -> UUID {
        let material = [
            builtInGeneration,
            externalRevision?.uuidString.lowercased() ?? "no-external-tools",
        ].joined(separator: "\u{0}")
        var bytes = Array(SHA256.hash(data: Data(material.utf8)).prefix(16))
        bytes[6] = (bytes[6] & 0x0f) | 0x50
        bytes[8] = (bytes[8] & 0x3f) | 0x80
        return UUID(uuid: (
            bytes[0], bytes[1], bytes[2], bytes[3],
            bytes[4], bytes[5], bytes[6], bytes[7],
            bytes[8], bytes[9], bytes[10], bytes[11],
            bytes[12], bytes[13], bytes[14], bytes[15]))
    }

    /// Resolve the session-scoped provider configuration without consulting process state. The
    /// global 1M opt-out changes only Anthropic's first-party model alias. Managed Vertex and
    /// Bedrock routes pass model ids through unchanged, so toggling it must not retire their
    /// otherwise-compatible sessions.
    nonisolated static func providerSessionConfigurationRevision(
        for access: ModelAccess,
        externalRevision: UUID?,
        use1M: Bool,
        permissionMode: String,
        toolProfile: ProviderToolProfile = .standard
    ) -> UUID {
        let providerRevision: UUID
        switch access {
        case .claudeSubscription, .anthropicAPI:
            providerRevision = anthropicSessionConfigurationRevision(
                externalRevision: externalRevision,
                use1M: use1M,
                permissionMode: permissionMode)
        case .claudeVertex, .claudeBedrock:
            providerRevision = anthropicSessionConfigurationRevision(
                externalRevision: externalRevision,
                use1M: true,
                permissionMode: permissionMode)
        case .codexSubscription:
            let codexRevision = codexSessionConfigurationRevision(
                externalRevision: externalRevision)
            // App Server fixes dynamic tools at thread/start and thread/resume cannot replace them.
            // Its in-process proof catches a toolbar change while the daemon stays alive, but the
            // durable app receipt must protect the same boundary after a daemon/app relaunch. Keep
            // the historical non-Plan receipt byte-for-byte because that schema already includes
            // OperateMechanician; only Plan needs a new, narrower receipt.
            providerRevision = permissionMode == "plan"
                ? sessionConfigurationRevision(
                    builtInGeneration: "mechanician-codex-permission-schema-v1:plan",
                    externalRevision: codexRevision)
                : codexRevision
        case .openAIAPI:
            // Responses requests are stateless and receive their tool schema on every turn.
            providerRevision = codexSessionConfigurationRevision(
                externalRevision: externalRevision)
        }
        // Preserve the standard profile's historical receipt byte-for-byte. Each closed profile
        // derives a different receipt so a workspace move cannot revive a session with another
        // capability surface, even when its provider generation is otherwise identical.
        guard toolProfile != .standard else { return providerRevision }
        return sessionConfigurationRevision(
            builtInGeneration: "mechanician-tool-profile-v1:\(toolProfile.rawValue)",
            externalRevision: providerRevision)
    }

    struct ProviderSessionConfigurationEnvelope: Equatable, Sendable {
        let toolProfile: ProviderToolProfile
        let revision: UUID
        let workspaceInstructionsRevision: String
    }

    nonisolated static func providerSessionConfigurationEnvelope(
        for access: ModelAccess,
        externalRevision: UUID?,
        use1M: Bool,
        permissionMode: String,
        toolProfile: ProviderToolProfile,
        workspaceInstructionsRevision: String
    ) -> ProviderSessionConfigurationEnvelope {
        let effectiveWorkspaceInstructionsRevision: String
        switch toolProfile {
        case .standard:
            effectiveWorkspaceInstructionsRevision = workspaceInstructionsRevision
        case .helpExpert:
            effectiveWorkspaceInstructionsRevision = helpExpertWorkspaceInstructionsRevision
        }
        return ProviderSessionConfigurationEnvelope(
            toolProfile: toolProfile,
            revision: providerSessionConfigurationRevision(
                for: access,
                externalRevision: externalRevision,
                use1M: use1M,
                permissionMode: permissionMode,
                toolProfile: toolProfile),
            workspaceInstructionsRevision: effectiveWorkspaceInstructionsRevision)
    }

    nonisolated static func mcpRouteIdentity(
        for access: ModelAccess,
        profile: TenantProfile
    ) -> String {
        let provider = access == .codexSubscription ? "codex"
            : access == .openAIAPI ? "openai" : "anthropic"
        return "\(provider):\(access.daemonAuthMode):\(profile.routeIdentity(for: access) ?? "builtin")"
    }

    /// The Codex equivalent. Deliberately a DIFFERENT material string from the Anthropic one: the
    /// two lanes must never derive the same revision from the same extension set, or a change on
    /// one would silently look like no change on the other. The built-in generation is separate
    /// too, because Codex's tool wiring is not Claude's.
    nonisolated static func codexSessionConfigurationRevision(externalRevision: UUID?) -> UUID {
        sessionConfigurationRevision(
            builtInGeneration: "mechanician-codex-tools-v4-show-mechanician",
            externalRevision: externalRevision)
    }

    private func workspaceProjectID(projectID explicitID: UUID?, cwd workspaceCwd: String) -> UUID? {
        if let explicitID { return explicitID }
        guard !workspaceCwd.isEmpty else { return nil }
        return ProjectStore.shared.projectID(forCwd: workspaceCwd, createIfMissing: false)
    }

    private func workspaceDefaultSelection(projectID explicitID: UUID?, cwd workspaceCwd: String) -> ModelSelection? {
        if let id = workspaceProjectID(projectID: explicitID, cwd: workspaceCwd) {
            return ProjectStore.shared.project(id)?.defaultModelSelection
        }
        return workspaceCwd.isEmpty ? homeModelSelection : nil
    }

    /// Resolve the model stamped on a brand-new conversation before any provider request exists.
    ///
    /// A managed declaration is deployment authority, so it also validates a persisted workspace
    /// default. Without this check, selecting 4.8 in one established managed-tenant conversation left an
    /// older project default of Opus 5 untouched and the very next conversation reverted to the
    /// model that Vertex rejects. Unmanaged lanes preserve their existing provider-default behavior.
    static func initialModelSelection(
        for access: ModelAccess,
        workspaceSelection: ModelSelection?,
        catalogEntries: [ModelCatalogEntry],
        profile: TenantProfile = .current
    ) -> ModelSelection {
        let declared = profile.declaredModels(for: access)
        if !declared.isEmpty {
            let authoritative = builtInCatalogEntries(for: access, profile: profile)
            if let workspaceSelection,
               workspaceSelection.access == access,
               authoritative.contains(where: {
                   $0.selection.modelID == workspaceSelection.modelID
                       || $0.resolvedModelID == workspaceSelection.modelID
               }) {
                return workspaceSelection
            }
            if let selected = authoritative.first(where: \.isDefault) ?? authoritative.first {
                return largestContextVariant(of: selected, among: authoritative, for: access)
                    .selection
            }
        }

        if let workspaceSelection, workspaceSelection.access == access {
            return workspaceSelection
        }
        if let entry = catalogEntries.first(where: \.isDefault) ?? catalogEntries.first {
            return largestContextVariant(of: entry, among: catalogEntries, for: access).selection
        }
        return ModelSelection(access: access, modelID: "")
    }

    /// Default to the biggest context window this route actually publishes for the same model.
    ///
    /// Applied to a managed profile's declaration as well as a provider catalog, which is the point:
    /// a deployment that declares both `Opus 4.8` and `Opus 4.8 (1M)` was defaulting new
    /// conversations to the 200K one. It selects only among ids the route already offers, so a
    /// deployment without the variant is unaffected.
    ///
    /// A managed profile can still force the smaller window by simply not declaring the larger
    /// variant; that remains the admin's control, and it is a subtraction, which is how every other
    /// managed model decision works.
    private nonisolated static func largestContextVariant(
        of chosen: ModelCatalogEntry,
        among entries: [ModelCatalogEntry],
        for access: ModelAccess
    ) -> ModelCatalogEntry {
        guard access.maker == .anthropic else { return chosen }
        let thirdParty = ProviderFacts.thirdPartyRoutes.contains(access.daemonAuthMode)
        let use1M = (UserDefaults.standard.object(forKey: "use1MContext") as? Bool) ?? true
        guard use1M else { return chosen }
        return LargestContextWindowVariant.preferred(
            among: entries,
            chosen: chosen,
            family: canonicalClaudeModelID,
            window: { entry in
                anthropicContextWindow(
                    selectedModelID: entry.selection.modelID,
                    resolvedModelID: entry.resolvedModelID,
                    use1M: true,
                    automaticallyUpgradesBareOpus: !thirdParty,
                    thirdPartyRoute: thirdParty)
            })
    }

    /// The selected conversation is a direct, explicit inheritance edge for "New Conversation"
    /// in the same Workspace. It deliberately does not cross a Workspace boundary: entering an
    /// otherwise empty Workspace still belongs to that Workspace's saved default (or the app-wide
    /// fallback), rather than whichever conversation happened to be open before the switch.
    static func currentWorkspaceNewConversationSelection(
        source: Conversation?,
        destinationScope: WorkspaceScope,
        projectedSelection: ModelSelection,
        projects: [Project]
    ) -> ModelSelection? {
        guard let source,
              destinationScope.contains(source, projects: projects) else { return nil }
        // Legacy rows without a stamped identity have always run on the window's projected
        // provider/model. Preserve that effective selection rather than making an empty stamp
        // send the new conversation back through a potentially unrelated global default.
        return source.modelSelection ?? projectedSelection
    }

    private func inheritedModelSelection(
        projectID explicitID: UUID?,
        cwd workspaceCwd: String,
        preferredSelection: ModelSelection? = nil
    ) -> ModelSelection {
        let access = preferredSelection?.access ?? defaultConversationAccess
        let scope = access.maker == .anthropic ? workspaceCwd : ""
        let snapshot = ModelCatalogStore.shared.snapshot(for: access, scope: scope)
        // Settings chooses an account route, not a model. An unmanaged lane still uses a ready
        // provider default (or an empty provider-default placeholder) exactly as before. The
        // current Conversation's selection gets the same managed-route validation as a persisted
        // Workspace default, so a newly withdrawn managed model cannot be copied forward.
        return Self.initialModelSelection(
            for: access,
            workspaceSelection: preferredSelection ?? workspaceDefaultSelection(
                projectID: explicitID, cwd: workspaceCwd),
            catalogEntries: snapshot.phase == .ready ? snapshot.entries : [],
            profile: TenantProfile.current)
    }

    private func persistWorkspaceDefault(_ selection: ModelSelection,
                                         projectID explicitID: UUID?, cwd workspaceCwd: String) {
        if let id = workspaceProjectID(projectID: explicitID, cwd: workspaceCwd) {
            guard ProjectStore.shared.project(id)?.defaultModelSelection != selection else { return }
            ProjectStore.shared.update(id) { $0.defaultModelSelection = selection }
        } else if workspaceCwd.isEmpty, homeModelSelection != selection {
            homeModelSelection = selection
        }
    }

    /// The current picker remains editable only as a global control for now. While the active
    /// conversation is still empty, treat a model change as choosing this workspace's default and
    /// stamp the placeholder so the next routing phase has an honest identity to inherit.
    private func syncEmptyConversationModelDefault() {
        guard !isStreaming, !isWorking, let id = currentID,
              !conversationHasReservedTurn(id),
              let conversation = store.conversation(id), conversation.sdkSessionId == nil,
              conversation.queuedPrompts.isEmpty,
              conversation.providerAccessRequest == nil,
              !entries.contains(where: { $0.kind == .user || $0.kind == .assistant }) else { return }
        let selection = currentModelSelection
        if conversation.modelSelection != selection {
            store.update(id) { $0.modelSelection = selection }
        }
        persistWorkspaceDefault(selection, projectID: conversation.projectID, cwd: conversation.cwd)
    }

    /// Project a conversation's durable provider/model identity into the existing controls and
    /// ensure its lane exists. Selecting a conversation never rewrites that identity or stops a
    /// different provider; it merely changes which lane the window is presenting.
    private func applyModelSelectionIfCompatible(_ selection: ModelSelection?) {
        guard let selection else { return }
        let previousAccess = currentModelAccess
        let settings = providerSettings(for: selection.access)
        if provider != settings.provider { provider = settings.provider }
        if authMode != settings.authMode { authMode = settings.authMode }
        projectTurnPreferences(for: selection.access)
        var resolvedSelection = selection
        if selection.access == .codexSubscription, selection.modelID.isEmpty {
            // A background Codex lane may already have supplied its entitled catalog. Selecting a
            // fresh Codex conversation later must not leave a Claude/OpenAI model projected under
            // the Codex provider merely because no second `models` event is guaranteed.
            let catalog = ModelCatalogStore.shared.snapshot(
                for: selection.access, scope: catalogScope(for: selection.access))
            let resolved = catalog.entries.first(where: { $0.isDefault })?.selection.modelID
                ?? codexDefaultModel ?? ""
            if model != resolved { model = resolved }
            if !resolved.isEmpty, let id = currentID,
               let conversation = store.conversation(id), conversation.sdkSessionId == nil {
                resolvedSelection.modelID = resolved
                store.update(id) { $0.modelSelection = resolvedSelection }
            }
        } else if model != selection.modelID {
            model = selection.modelID
        }
        projectLaneState(selection.access)
        ensureRuntime(for: selection.access)
        if previousAccess != selection.access {
            reconcileProviderResidency([previousAccess, selection.access])
        }
        // A model catalog is workspace-scoped for Claude/Vertex. Projecting a conversation is the
        // one lifecycle edge shared by new conversations, sidebar selection, and in-place workspace
        // switches, so prime its exact scope here instead of waiting for either picker to open.
        // This also lets the effort control become useful from the same publication as the model
        // label, without making the model picker an accidental prerequisite.
        prepareModelCatalog(for: selection.access, force: false)
    }

    private func providerSettings(for access: ModelAccess) -> (provider: String, authMode: String) {
        switch access {
        case .claudeSubscription: return ("anthropic", "subscription")
        case .anthropicAPI: return ("anthropic", "apikey")
        case .codexSubscription: return ("codex", "subscription")
        case .openAIAPI: return ("openai", "apikey")
        case .claudeVertex: return ("anthropic", "vertex")
        case .claudeBedrock: return ("anthropic", "bedrock")
        }
    }

    nonisolated static func providerResidencyActivity(
        for candidate: ModelAccess,
        selectedAccess: ModelAccess
    ) -> Bool? {
        guard candidate == .codexSubscription else { return nil }
        return selectedAccess == .codexSubscription
    }

    private func reconcileProviderResidency(_ candidates: Set<ModelAccess>) {
        for access in candidates {
            guard let active = Self.providerResidencyActivity(
                for: access, selectedAccess: currentModelAccess) else { continue }
            _ = write(["type": "provider_residency", "active": active], to: access)
        }
    }

    nonisolated static func startupAccess(
        savedAccess: ModelAccess,
        availableAccesses: [ModelAccess],
        profileDefault: ModelAccess?
    ) -> ModelAccess {
        if availableAccesses.contains(savedAccess) { return savedAccess }
        if let profileDefault, availableAccesses.contains(profileDefault) { return profileDefault }
        // Preserve the historical unmanaged fallback when it remains selectable. Managed policy
        // can remove that lane, in which case prefer the first allowed configured lane. An empty
        // invalid inventory preserves the old stamp so the runtime guard can block it without
        // rewriting persisted identity.
        if availableAccesses.contains(.anthropicAPI) { return .anthropicAPI }
        return availableAccesses.first ?? savedAccess
    }

    /// Catalog scope is provider-defined. Claude availability may vary by workspace; OpenAI and
    /// Codex currently expose account-wide catalogs and therefore require the empty wire scope.
    ///
    /// `conversation` names the one being scoped when that is not the one on screen — a background
    /// turn belongs to its own workspace, and judging its models against the foreground workspace's
    /// catalog would be reading the wrong list. Omitted, this behaves exactly as it always has.
    func catalogScope(for access: ModelAccess, conversation: Conversation? = nil) -> String {
        switch access {
        case .claudeSubscription, .anthropicAPI, .claudeVertex, .claudeBedrock:
            return turnCwd(for: conversation ?? currentConversation)
        case .codexSubscription, .openAIAPI:
            return ""
        }
    }

    private func capabilityWorkspace(for conversation: Conversation?) -> ProviderCapabilityWorkspace {
        if let projectID = conversation?.projectID ?? projectID {
            return ProviderCapabilityWorkspace(
                identity: "project:" + projectID.uuidString,
                policyRevision: 0)
        }
        let path = turnCwd(for: conversation)
        let canonical = URL(fileURLWithPath: path).standardizedFileURL.path
        // Workspace policy does not yet have an independent revision owner. Revision zero is
        // explicit and safe for diagnostics; permission-sensitive controls must not consume this
        // snapshot until that policy source exists.
        return ProviderCapabilityWorkspace(
            identity: canonical.isEmpty ? "home" : "cwd:" + canonical,
            policyRevision: 0)
    }

    private func providerCapabilityKey(
        selection: ModelSelection,
        conversation: Conversation?
    ) -> ProviderCapabilityKey {
        let accounts = ProviderAccountStore.shared
        return ProviderCapabilityKey(
            access: selection.access,
            accountInstanceID: accounts.accountInstanceID(for: selection.access),
            credentialEpoch: accounts.credentialEpoch(for: selection.access),
            modelID: selection.modelID,
            workspace: capabilityWorkspace(for: conversation))
    }

    private func normalizedProviderCapabilitySelection(
        _ selection: ModelSelection,
        conversation: Conversation?
    ) -> ModelSelection {
        guard selection.modelID.isEmpty else { return selection }
        var normalized = selection
        let wireScope = selection.access.maker == .anthropic ? turnCwd(for: conversation) : ""
        let catalog = ModelCatalogStore.shared.snapshot(for: selection.access, scope: wireScope)
        normalized.modelID = (catalog.entries.first(where: { $0.isDefault })
            ?? catalog.entries.first)?.selection.modelID ?? ""
        return normalized
    }

    func currentProviderCapabilityKey() -> ProviderCapabilityKey {
        let conversation = currentConversation
        let selection = normalizedProviderCapabilitySelection(
            conversation?.modelSelection ?? currentModelSelection,
            conversation: conversation)
        return providerCapabilityKey(
            selection: selection,
            conversation: conversation)
    }

    var currentProviderCapabilitySnapshot: ProviderCapabilitySnapshot {
        ProviderCapabilityStore.shared.snapshot(for: currentProviderCapabilityKey())
    }

    /// A provider claim alone never enables a product control. Review is actionable only when the
    /// exact capability record also says this Mechanician adapter implements the stable operation.
    static func supportsNativeCodexReview(_ snapshot: ProviderCapabilitySnapshot) -> Bool {
        guard case .ready = snapshot.phase else { return false }
        return snapshot.capabilities.contains {
            $0.id == "native_review"
                && $0.providerAvailability == .available
                && $0.mechanicianSupport == .implemented
                && $0.operation == "review/start"
        }
    }

    /// A conversation switch cannot restore a provider's transient detailed status, but it must
    /// restore a truthful purpose-specific baseline instead of leaking the previous conversation's
    /// label into this one.
    static func restoredRunningStatusLabel(isReview: Bool) -> String {
        isReview ? "Reviewing changes…" : "Thinking…"
    }

    var currentProviderSupportsNativeReview: Bool {
        guard selectedModelSelection.access == .codexSubscription else { return false }
        return Self.supportsNativeCodexReview(currentProviderCapabilitySnapshot)
    }

    var currentReviewIsRunning: Bool {
        guard let conversationID = currentID else { return false }
        return AgentBridge.live.allObjects.contains { bridge in
            bridge.turnRoutes.values.contains { route in
                guard route.conversationID == conversationID,
                      route.phase.reservesConversation else { return false }
                if case .codexReview = route.purpose { return true }
                return false
            }
        }
    }

    var canStartCodexReviewCurrentChanges: Bool {
        let extensions = ExtensionsStore.shared
        let authorizationBlocked = MCPAuthorizationProviderExposurePolicy.isBlocked(
            preparationInFlight: Self.hasMCPAuthorizationPreparation(
                for: .codexSubscription),
            hasPendingAttempt: !extensions.pendingMCPAuthorizationAttempts(
                for: .codexSubscription).isEmpty)
        guard let conversation = currentConversation,
              store.isDurablyCurrent(conversation.id),
              (conversation.modelSelection ?? currentModelSelection).access == .codexSubscription,
              currentProviderSupportsNativeReview,
              ProviderAccountStore.shared.operation(for: .codexSubscription) == nil,
              !authorizationBlocked,
              extensions.pendingMCPReadinessClaims(for: .codexSubscription).isEmpty,
              isRuntimeUsable(.codexSubscription),
              git.belongs(to: cwd), git.isRepo, !git.files.isEmpty,
              !conversationHasReservedTurn(conversation.id),
              conversation.providerAccessRequest == nil else { return false }
        return true
    }

    var canExportCodexLifecycleDiagnostics: Bool {
        ProviderAccountStore.shared.operation(for: .codexSubscription) == nil
            && isRuntimeReady(.codexSubscription)
    }

    func exportCodexLifecycleDiagnostics(
        to destination: URL,
        completion: @escaping (Result<URL, Error>) -> Void
    ) {
        let access = ModelAccess.codexSubscription
        guard canExportCodexLifecycleDiagnostics else {
            completion(.failure(CodexDiagnosticsExportError.unavailable))
            return
        }
        let requestID = UUID().uuidString
        codexDiagnosticsRoutes[requestID] = CodexDiagnosticsRoute(
            access: access,
            destination: destination,
            completion: completion)
        guard write(["type": "codex_diagnostics", "id": requestID], to: access) else {
            codexDiagnosticsRoutes.removeValue(forKey: requestID)?
                .completion(.failure(CodexDiagnosticsExportError.runtimeStopped))
            return
        }
        Task { @MainActor [weak self] in
            try? await Task.sleep(nanoseconds: 10_000_000_000)
            guard let route = self?.codexDiagnosticsRoutes.removeValue(forKey: requestID) else {
                return
            }
            route.completion(.failure(CodexDiagnosticsExportError.timedOut))
        }
    }

    /// Claude may persist a canonical resolved model id while its provider catalog is addressed by
    /// an alias. Capability requests use the provider-owned wire id, while the local cache remains
    /// keyed by the exact model identity stored on the conversation.
    static func providerCapabilityWireModelID(
        for selection: ModelSelection,
        catalog: [ModelCatalogEntry]
    ) -> String {
        if selection.modelID.isEmpty {
            return (catalog.first(where: { $0.isDefault }) ?? catalog.first)?
                .selection.modelID ?? ""
        }
        return catalog.first(where: {
            $0.selection.modelID == selection.modelID || $0.resolvedModelID == selection.modelID
        })?.selection.modelID ?? selection.modelID
    }

    /// Request diagnostic capability evidence for the selected route/model/workspace. This does not
    /// enable any control; later product slices must separately require adapter implementation.
    func prepareProviderCapabilities(force: Bool = false) {
        let conversation = currentConversation
        var selection = normalizedProviderCapabilitySelection(
            conversation?.modelSelection ?? currentModelSelection,
            conversation: conversation)
        let access = selection.access
        let accounts = ProviderAccountStore.shared
        guard accounts.operation(for: access) == nil,
              accounts.state(for: access).isAvailable else {
            ProviderCapabilityStore.shared.invalidate(access: access)
            return
        }
        let wireScope = access.maker == .anthropic ? turnCwd(for: conversation) : ""
        let catalog = ModelCatalogStore.shared.snapshot(for: access, scope: wireScope)
        guard catalog.phase == .ready else {
            pendingProviderCapabilityRefreshes[access] =
                force || (pendingProviderCapabilityRefreshes[access] ?? false)
            prepareModelCatalogs(force: force)
            return
        }
        selection = normalizedProviderCapabilitySelection(selection, conversation: conversation)
        let key = providerCapabilityKey(selection: selection, conversation: conversation)
        guard ProviderCapabilityStore.shared.setCurrentOwner(
            access: access,
            accountInstanceID: key.accountInstanceID,
            credentialEpoch: key.credentialEpoch) else { return }
        let existing = ProviderCapabilityStore.shared.snapshot(for: key)
        if !force, existing.phase == .ready || existing.phase == .loading { return }
        pendingProviderCapabilityRefreshes[access] = force
        _ = ensureRuntime(for: access)
        flushPendingProviderCapabilities(for: access)
    }

    private func flushPendingProviderCapabilities(for access: ModelAccess) {
        let accounts = ProviderAccountStore.shared
        let credentialEpoch = accounts.credentialEpoch(for: access)
        guard pendingProviderCapabilityRefreshes[access] != nil,
              accounts.operation(for: access) == nil,
              accounts.state(for: access).isAvailable,
              isRuntimeReady(access),
              runtimeCredentialEpochs[access] == credentialEpoch,
              !providerCapabilityRequestRoutes.values.contains(where: { $0.access == access })
        else { return }

        let conversation = currentConversation
        var selection = normalizedProviderCapabilitySelection(
            conversation?.modelSelection ?? currentModelSelection,
            conversation: conversation)
        guard selection.access == access else {
            pendingProviderCapabilityRefreshes[access] = nil
            return
        }
        let wireScope = access.maker == .anthropic ? turnCwd(for: conversation) : ""
        let catalog = ModelCatalogStore.shared.snapshot(for: access, scope: wireScope)
        guard catalog.phase == .ready else { return }
        selection = normalizedProviderCapabilitySelection(selection, conversation: conversation)
        let key = providerCapabilityKey(selection: selection, conversation: conversation)
        guard ProviderCapabilityStore.shared.setCurrentOwner(
            access: access,
            accountInstanceID: key.accountInstanceID,
            credentialEpoch: key.credentialEpoch) else { return }
        let wireModelID = Self.providerCapabilityWireModelID(
            for: selection, catalog: catalog.entries)
        let requestID = UUID().uuidString
        guard write([
            "type": "provider_capabilities",
            "id": requestID,
            "scope": wireScope,
            "model": wireModelID,
            "workspacePolicyRevision": key.workspace.policyRevision,
        ], to: access),
              let ticket = ProviderCapabilityStore.shared.beginRequest(for: key) else { return }
        providerCapabilityRequestRoutes[requestID] = ProviderCapabilityRequestRoute(
            access: access,
            wireScope: wireScope,
            modelID: wireModelID,
            credentialEpoch: key.credentialEpoch,
            ticket: ticket)
        pendingProviderCapabilityRefreshes[access] = nil
    }

    private func consumeProviderCapabilityEvent(
        _ event: [String: Any],
        from access: ModelAccess,
        credentialEpoch: Int
    ) -> Bool {
        guard let type = event["type"] as? String,
              type == "provider_capabilities" || type == "provider_capabilities_error"
        else { return false }
        guard let requestID = event["id"] as? String,
              let route = providerCapabilityRequestRoutes.removeValue(forKey: requestID)
        else { return true }
        guard route.access == access,
              route.credentialEpoch == credentialEpoch,
              ProviderAccountStore.shared.credentialEpoch(for: access) == credentialEpoch
        else { return true }
        // A force refresh or model/workspace change may have queued behind this serialized request.
        // Every terminal response path must release that newer work, including malformed evidence.
        defer { flushPendingProviderCapabilities(for: access) }
        let eventScope = event["scope"] as? String ?? ""
        let eventModel = event["model"] as? String ?? ""
        guard ModelCatalogStore.normalizedScope(eventScope)
                == ModelCatalogStore.normalizedScope(route.wireScope),
              eventModel == route.modelID else {
            _ = ProviderCapabilityStore.shared.fail(
                route.ticket, message: "Provider returned capability evidence for the wrong model or workspace.")
            return true
        }
        if type == "provider_capabilities_error" {
            _ = ProviderCapabilityStore.shared.fail(
                route.ticket,
                message: event["message"] as? String ?? "Provider capabilities are unavailable.")
            return true
        }
        guard let raw = event["capabilities"], JSONSerialization.isValidJSONObject(raw),
              let data = try? JSONSerialization.data(withJSONObject: raw),
              let capabilities = try? JSONDecoder().decode([ProviderCapability].self, from: data),
              let adapterRevision = event["adapterRevision"] as? String,
              !adapterRevision.isEmpty else {
            _ = ProviderCapabilityStore.shared.fail(
                route.ticket, message: "Provider returned invalid capability evidence.")
            return true
        }
        _ = ProviderCapabilityStore.shared.publish(
            capabilities,
            ticket: route.ticket,
            adapterRevision: adapterRevision,
            sourceRevision: event["sourceRevision"] as? String,
            rawEvidenceDigest: event["rawEvidenceDigest"] as? String)
        return true
    }

    func modelDisplayName(for selection: ModelSelection) -> String {
        let store = ModelCatalogStore.shared
        let scope = catalogScope(for: selection.access)
        let snapshot = store.snapshot(for: selection.access, scope: scope)
        let entries = snapshot.phase == .ready
            ? snapshot.entries
            : store.lastKnownEntries(for: selection.access, scope: scope)
        if let entry = entries.first(where: {
            $0.selection == selection || $0.resolvedModelID == selection.modelID
        }) {
            return entry.versionedDisplayName
        }
        return selection.modelID.isEmpty ? selection.access.displayName : selection.modelID
    }

    /// Load every currently usable account lane when the unified picker opens. Ineligible lanes do
    /// not start a daemon, and their old rows are cleared immediately rather than advertised from a
    /// previous login. Runtime startup remains lazy outside this explicit picker action.
    func prepareModelCatalogs(force: Bool = false) {
        for access in ModelAccess.selectableCases {
            prepareModelCatalog(for: access, force: force)
        }
    }

    /// Prime the selected workspace's catalog without requiring either picker to be opened. The
    /// effort control also calls this after an account transition so it can recover from a launch
    /// race independently of the model picker.
    func prepareCurrentModelCatalog(force: Bool = false) {
        prepareModelCatalog(for: currentModelAccess, force: force)
    }

    private func prepareModelCatalog(for access: ModelAccess, force: Bool) {
        guard access.isAllowedByEnterprisePolicy else { return }
        let accounts = ProviderAccountStore.shared
        let epoch = accounts.credentialEpoch(for: access)
        let scope = catalogScope(for: access)
        let accountState = accounts.state(for: access)
        let needsAccountProbe = accountState == .checking
            && access.usesInteractiveAccountFlow
        guard accounts.operation(for: access) == nil,
              ModelPickerProviderPolicy.shouldPrepareCatalog(
                for: access,
                state: accountState,
                hasUsableRuntime: isRuntimeUsable(access)) else {
            ModelCatalogStore.shared.disable(
                access: access, credentialEpoch: epoch,
                message: accounts.operation(for: access) == nil ? nil : "Account change in progress")
            return
        }
        let snapshot = ModelCatalogStore.shared.snapshot(for: access, scope: scope)
        if !force, !TenantProfile.current.declaredModels(for: access).isEmpty {
            // The signed deployment declaration is immediately authoritative. Do not launch a
            // disposable Claude process merely to enrich it during workspace startup; that probe
            // competed directly with the user's first turn on managed corporate Macs. A manual
            // Retry (`force`) remains available when capability metadata is actually wanted.
            if snapshot.phase != .ready {
                if ModelCatalogStore.shared.publishDeclared(
                    access: access,
                    scope: scope,
                    credentialEpoch: epoch
                ) {
                    // A managed route intentionally has no later live-catalog event. Treat the
                    // signed declaration as the authoritative catalog edge it is, otherwise an
                    // account reload can verify Vertex yet leave its preserved prompt stranded
                    // until relaunch happens to republish this declaration first.
                    Self.resumeProviderAccessRequestsProcessWide(for: access)
                    Self.attemptProviderSetupRecoveriesProcessWide(for: access)
                }
            }
            if needsAccountProbe { _ = ensureRuntime(for: access) }
            return
        }
        // SwiftUI may project the same selection and mount both controls during one launch. Keep
        // those lifecycle calls idempotent within this bridge, especially while Vertex's passive
        // account row is still `checking` (which intentionally permits replacing a cached result).
        // A later workspace scope is different and remains free to replace an older unsent scope.
        let normalizedScope = ModelCatalogStore.normalizedScope(scope)
        let alreadyPendingHere = pendingModelCatalogScopes[access]?.contains(where: {
            ModelCatalogStore.normalizedScope($0) == normalizedScope
        }) == true
        let alreadyRequestedHere = modelCatalogRequestRoutes.values.contains {
            $0.access == access
                && ModelCatalogStore.normalizedScope($0.scope) == normalizedScope
        }
        // `force` bypasses a completed READY snapshot; it does not mean the same scope should be
        // queued twice. In particular, an effort-picker click and Vertex's subsequent account-state
        // publication can both explicitly request enrichment before the first request completes.
        if alreadyPendingHere {
            // A forced picker click may have queued this scope while Vertex ADC was still checking.
            // An account-state-only recovery does not guarantee another daemon `ready` event, so
            // actively release the existing request instead of returning with it stranded.
            _ = ensureRuntime(for: access)
            flushPendingModelCatalogs(for: access)
            return
        }
        if alreadyRequestedHere { return }
        if !force, !needsAccountProbe,
           snapshot.phase == .ready || snapshot.phase == .loading { return }
        // One picker in one window has only one active workspace scope. Replacing an older unsent
        // scope prevents a slow runtime from accumulating every project ever visited.
        pendingModelCatalogScopes[access] = [scope]
        ModelCatalogStore.shared.beginLoading(
            access: access, scope: scope, credentialEpoch: epoch)
        _ = ensureRuntime(for: access)
        flushPendingModelCatalogs(for: access)
    }

    private static func strictPublicResearchText(
        _ value: String,
        minimum: Int,
        maximum: Int
    ) -> String? {
        let text = value.trimmingCharacters(in: .whitespacesAndNewlines)
            .precomposedStringWithCanonicalMapping
        guard text.count >= minimum, text.count <= maximum,
              !text.unicodeScalars.contains(where: {
                  CharacterSet.controlCharacters.contains($0)
                      || $0.value == 0x2028 || $0.value == 0x2029
              }) else { return nil }
        return text
    }

    private static func containsPublicURL(_ value: String) -> Bool {
        value.range(
            of: #"(?:https?://|www\.)\S+"#,
            options: [.regularExpression, .caseInsensitive]) != nil
    }

    private static func strictPublicHTTPURL(_ value: String) -> String? {
        guard let text = strictPublicResearchText(value, minimum: 1, maximum: 2_048),
              !text.contains(where: \.isWhitespace),
              let components = URLComponents(string: text),
              let scheme = components.scheme?.lowercased(),
              scheme == "http" || scheme == "https",
              components.host?.isEmpty == false,
              components.user == nil, components.password == nil else { return nil }
        return text
    }



    /// Answer one provider request from the app-bundled, signed Help authority.
    ///
    /// `agentd` supplies only a query and an optional history flag. It never receives a database
    /// path and cannot turn an absent or rejected corpus into an apparently successful empty search.
    private func applyHelpSearchRequest(
        _ event: [String: Any],
        turnID: String,
        route: TurnRoute
    ) {
        guard let requestID = event["reqId"] as? String,
              !requestID.isEmpty,
              requestID.utf8.prefix(257).count <= 256 else { return }
        let interaction = InteractionRoute(turnID: turnID, route: route)
        func unavailableResponse() -> [String: Any] {
            [
                "type": "help_search_response",
                "id": turnID,
                "reqId": requestID,
                "ok": false,
                "empty": false,
                "text": "Signed Mechanician Help is unavailable for this turn.",
            ]
        }
        let baseKeys: Set<String> = ["type", "id", "reqId", "query"]
        guard Set(event.keys) == baseKeys
                || Set(event.keys) == baseKeys.union(["includeHistory"]),
              event["type"] as? String == "help_search_request",
              event["id"] as? String == turnID,
              route.toolProfile.permitsHelpSearch,
              store.conversation(route.conversationID) != nil,
              let query = event["query"] as? String,
              event["includeHistory"] == nil || event["includeHistory"] is Bool else {
            _ = write(unavailableResponse(), to: interaction)
            return
        }
        let includeHistory = event["includeHistory"] as? Bool == true
        Task { [weak self] in
            guard let self else { return }
            let answer: MechanicianHelpProviderAnswer
            do {
                answer = try await MechanicianHelpProviderRetrieval.shared.search(
                    query: query,
                    includeHistory: includeHistory)
            } catch {
                _ = self.write(unavailableResponse(), to: interaction)
                return
            }
            // Search crosses an actor boundary and may outlive its caller. Revalidate every route
            // coordinate before either returning the result or staging its visible receipt.
            guard let currentRoute = self.turnRoutes[turnID],
                  currentRoute.phase.isActive,
                  !self.stopRequestedTurnIDs.contains(turnID),
                  self.routesMatch(currentRoute, route),
                  currentRoute.toolProfile.permitsHelpSearch else {
                _ = self.write(unavailableResponse(), to: interaction)
                return
            }
            var stagedDelivery = false
            if let receipt = answer.receipt {
                // The acknowledgement is both the transcript-receipt boundary and the only seam
                // allowed to release app-private guide IDs. A socket write alone proves neither.
                guard self.pendingHelpConsultationReceipts.stage(
                    PendingHelpConsultationReceipt(
                        conversationID: route.conversationID,
                        selection: route.selection,
                        toolProfile: route.toolProfile,
                        receipt: receipt,
                        guideAdmission: answer.guideAdmission),
                    turnID: turnID,
                    requestID: requestID
                ) else {
                    _ = self.write(unavailableResponse(), to: interaction)
                    return
                }
                stagedDelivery = true
            }
            let response: [String: Any] = [
                "type": "help_search_response",
                "id": turnID,
                "reqId": requestID,
                "ok": true,
                "empty": answer.empty,
                "text": answer.text,
            ]
            if !self.write(response, to: interaction), stagedDelivery {
                self.pendingHelpConsultationReceipts.discard(
                    turnID: turnID,
                    requestID: requestID)
            }
        }
    }

    /// Commit a concise audit row only after the daemon proves that this exact result crossed the
    /// provider-facing tool-result boundary. Unknown, late, duplicate and cross-turn acks do nothing.
    private func applyHelpSearchAcknowledgement(
        _ event: [String: Any],
        turnID: String,
        route: TurnRoute
    ) {
        guard Set(event.keys) == ["type", "id", "reqId"],
              event["type"] as? String == "help_search_ack",
              event["id"] as? String == turnID,
              let requestID = event["reqId"] as? String,
              let pending = pendingHelpConsultationReceipts.take(
                turnID: turnID,
                requestID: requestID),
              pending.conversationID == route.conversationID,
              pending.selection == route.selection,
              pending.toolProfile == route.toolProfile,
              let current = turnRoutes[turnID],
              current.phase.isActive,
              !stopRequestedTurnIDs.contains(turnID),
              routesMatch(current, route) else { return }
        showMechanicianGuideAdmissions.acknowledge(
            pending.guideAdmission,
            turnID: turnID,
            route: .init(
                conversationID: pending.conversationID,
                selection: pending.selection,
                toolProfile: pending.toolProfile))
        discloseHelpConsultation(
            pending.receipt,
            turnID: turnID,
            conversationID: pending.conversationID)
    }

    /// Take a turn's offer before any asynchronous app navigation. Reservation makes a forged or
    /// duplicated Show request fail closed while still allowing a failed presentation to restore
    /// the exact ID if its acknowledged search generation and route remain current.
    private func reserveShowMechanicianGuide(
        _ guideID: String,
        turnID: String,
        route: TurnRoute
    ) -> MechanicianGuidanceSearchAdmissionLedger.Reservation? {
        showMechanicianGuideAdmissions.reserve(
            guideID: guideID,
            turnID: turnID,
            route: .init(
                conversationID: route.conversationID,
                selection: route.selection,
                toolProfile: route.toolProfile))
    }

    private nonisolated static func showMechanicianGuideIDIsAdmissible(_ value: String) -> Bool {
        value.utf8.prefix(97).count <= 96
            && value.range(
                of: #"^[a-z0-9][a-z0-9.-]{0,95}$"#,
                options: .regularExpression) != nil
    }

    /// Start one signed, app-owned native guide from the exact accepted root turn.
    ///
    /// The daemon can choose only a bounded stable guide id. It cannot echo or invent a workspace,
    /// window, conversation, target, selector, coordinate, script, URL, or input event; the sealed
    /// guide's surface is the sole destination authority.
    private func applyShowMechanicianRequest(
        _ event: [String: Any],
        turnID: String,
        route: TurnRoute
    ) {
        guard let requestID = event["reqId"] as? String,
              !requestID.isEmpty,
              requestID.utf8.prefix(257).count <= 256 else { return }
        let interaction = InteractionRoute(turnID: turnID, route: route)
        func unavailableResponse() -> [String: Any] {
            [
                "type": "show_mechanician_response",
                "id": turnID,
                "reqId": requestID,
                "ok": false,
                "state": "unavailable",
                "text": "The signed Mechanician guide could not be started for this turn.",
            ]
        }

        let exactKeys: Set<String> = ["type", "id", "reqId", "guideID"]
        guard Set(event.keys) == exactKeys,
              event["type"] as? String == "show_mechanician_request",
              event["id"] as? String == turnID,
              let guideID = event["guideID"] as? String,
              Self.showMechanicianGuideIDIsAdmissible(guideID),
              route.phase.isActive,
              !stopRequestedTurnIDs.contains(turnID),
              route.purpose == .conversation,
              route.toolProfile.permitsMechanicianGuidance,
              store.conversation(route.conversationID) != nil,
              currentID == route.conversationID,
              let sourceWindow = window,
              sourceWindow === self.window else {
            _ = write(unavailableResponse(), to: interaction)
            return
        }
        guard let guideReservation = reserveShowMechanicianGuide(
            guideID,
            turnID: turnID,
            route: route) else {
            _ = write(unavailableResponse(), to: interaction)
            return
        }
        guard let source = MechanicianGuidanceSourceAdmission(
                bridge: self,
                window: sourceWindow,
                conversationID: route.conversationID,
                toolProfile: route.toolProfile,
                guideID: guideReservation.guideID,
                corpusContentSHA256: guideReservation.corpusContentSHA256,
                revalidateTurn: { [weak self, weak sourceWindow] in
                    guard let self, let sourceWindow,
                          self.window === sourceWindow,
                          self.currentID == route.conversationID,
                          self.store.conversation(route.conversationID) != nil,
                          let current = self.turnRoutes[turnID],
                          current.phase.isActive,
                          !self.stopRequestedTurnIDs.contains(turnID),
                          current.purpose == .conversation,
                          current.toolProfile.permitsMechanicianGuidance,
                          self.showMechanicianGuideAdmissions.isCurrent(guideReservation),
                          self.routesMatch(current, route) else { return false }
                    return true
                }) else {
            showMechanicianGuideAdmissions.restore(guideReservation)
            _ = write(unavailableResponse(), to: interaction)
            return
        }

        let provisional = PendingShowMechanicianAcknowledgement(
            conversationID: route.conversationID,
            selection: route.selection,
            toolProfile: route.toolProfile,
            guideID: guideID,
            guideReservation: guideReservation,
            sessionToken: nil)
        guard pendingShowMechanicianAcknowledgements.stage(
            provisional,
            turnID: turnID,
            requestID: requestID) else {
            showMechanicianGuideAdmissions.restore(guideReservation)
            _ = write(unavailableResponse(), to: interaction)
            return
        }

        Task { [weak self, source] in
            guard let self else { return }
            let result = await MechanicianGuidanceRouter.shared.start(
                guideID: guideID,
                source: source)
            switch result {
            case .failed:
                self.pendingShowMechanicianAcknowledgements.discard(
                    turnID: turnID,
                    requestID: requestID)
                self.showMechanicianGuideAdmissions.restore(guideReservation)
                _ = self.write(unavailableResponse(), to: interaction)
            case let .started(title, sessionToken):
                guard let pending = self.pendingShowMechanicianAcknowledgements.take(
                        turnID: turnID,
                        requestID: requestID),
                      pending.conversationID == route.conversationID,
                      pending.selection == route.selection,
                      pending.toolProfile == route.toolProfile,
                      pending.guideID == guideID,
                      pending.guideReservation == guideReservation,
                      pending.sessionToken == nil,
                      source.isCurrent,
                      self.pendingShowMechanicianAcknowledgements.stage(
                        PendingShowMechanicianAcknowledgement(
                            conversationID: pending.conversationID,
                            selection: pending.selection,
                            toolProfile: pending.toolProfile,
                            guideID: pending.guideID,
                            guideReservation: pending.guideReservation,
                            sessionToken: sessionToken),
                        turnID: turnID,
                        requestID: requestID) else {
                    MechanicianGuidanceRouter.shared.cancel(sessionToken: sessionToken)
                    self.showMechanicianGuideAdmissions.restore(guideReservation)
                    _ = self.write(unavailableResponse(), to: interaction)
                    return
                }
                self.pendingShowMechanicianSessionTokens[
                    PendingShowMechanicianSessionKey(
                        turnID: turnID,
                        requestID: requestID)] = sessionToken
                let response: [String: Any] = [
                    "type": "show_mechanician_response",
                    "id": turnID,
                    "reqId": requestID,
                    "ok": true,
                    "state": "started",
                    "text": "Mechanician started the signed \(title) guide. The guide remains app-owned; do not claim the person completed it.",
                ]
                if !self.write(response, to: interaction) {
                    self.showMechanicianGuideAdmissions.restore(guideReservation)
                    self.discardPendingShowMechanician(
                        turnID: turnID,
                        requestID: requestID)
                }
            }
        }
    }

    /// Perform one bounded, app-owned interface operation for the accepted turn.
    ///
    /// Unlike a signed guide this has no corpus to re-resolve against, so the whole boundary is the
    /// closed operation vocabulary plus this route check. The request and verified outcome use one
    /// correlated operation/result exchange; there is no later acknowledgement round trip because
    /// no consultation receipt or provisional presentation remains after the response.
    private func applyOperateMechanicianRequest(
        _ event: [String: Any],
        turnID: String,
        route: TurnRoute
    ) {
        guard let requestID = event["reqId"] as? String,
              !requestID.isEmpty,
              requestID.utf8.prefix(257).count <= 256 else { return }
        let interaction = InteractionRoute(turnID: turnID, route: route)
        func respond(ok: Bool, text: String) {
            _ = write([
                "type": "operate_mechanician_response",
                "id": turnID,
                "reqId": requestID,
                "ok": ok,
                "text": text,
            ], to: interaction)
        }

        let exactKeys: Set<String> = ["type", "id", "reqId", "operation", "target"]
        let requiredKeys: Set<String> = ["type", "id", "reqId", "operation"]
        let keys = Set(event.keys)
        guard keys == exactKeys || keys == requiredKeys,
              event["type"] as? String == "operate_mechanician_request",
              event["id"] as? String == turnID,
              let operationName = event["operation"] as? String,
              let operation = MechanicianOperationKind(rawValue: operationName),
              route.phase.isActive,
              !stopRequestedTurnIDs.contains(turnID),
              route.purpose == .conversation,
              route.permissionMode != "plan",
              route.toolProfile.permitsMechanicianGuidance,
              store.conversation(route.conversationID) != nil,
              currentID == route.conversationID,
              let sourceWindow = window,
              sourceWindow === self.window else {
            respond(ok: false, text: MechanicianOperationRefusal.sourceInvalidated.text)
            return
        }
        let target = event["target"] as? String
        if let target, target.utf8.prefix(257).count > 256 {
            respond(ok: false, text: MechanicianOperationRefusal.unsupportedTarget.text)
            return
        }
        guard let source = MechanicianOperationAdmission(
            bridge: self,
            window: sourceWindow,
            conversationID: route.conversationID,
            toolProfile: route.toolProfile,
            turnID: turnID,
            revalidateTurn: { [weak self, weak sourceWindow] in
                guard let self, let sourceWindow,
                      self.window === sourceWindow,
                      self.currentID == route.conversationID,
                      self.store.conversation(route.conversationID) != nil,
                      let current = self.turnRoutes[turnID],
                      current.phase.isActive,
                      !self.stopRequestedTurnIDs.contains(turnID),
                      current.purpose == .conversation,
                      current.permissionMode != "plan",
                      current.toolProfile.permitsMechanicianGuidance,
                      self.routesMatch(current, route) else { return false }
                return true
            }) else {
            respond(ok: false, text: MechanicianOperationRefusal.sourceInvalidated.text)
            return
        }

        // A window scene opens on a later run-loop pass, so the router proves the result rather
        // than reporting the attempt. The daemon waits for this response and gives up on its own
        // deadline, so a slow surface reports honestly instead of hanging the turn.
        Task { [weak self] in
            let outcome = await MechanicianOperationRouter.shared.perform(
                operation,
                target: target,
                source: source)
            guard let self else { return }
            _ = self.write([
                "type": "operate_mechanician_response",
                "id": turnID,
                "reqId": requestID,
                "ok": !outcome.reportsAsError,
                "text": outcome.text,
            ], to: interaction)
        }
    }

    /// Consume only the acknowledgement for the exact started session. The acknowledgement is a
    /// transport proof, not permission and not evidence that the person advanced or completed it.
    private func applyShowMechanicianAcknowledgement(
        _ event: [String: Any],
        turnID: String,
        route: TurnRoute
    ) {
        guard Set(event.keys) == ["type", "id", "reqId"],
              event["type"] as? String == "show_mechanician_ack",
              event["id"] as? String == turnID,
              let requestID = event["reqId"] as? String,
              !requestID.isEmpty,
              requestID.utf8.prefix(257).count <= 256 else { return }
        let key = PendingShowMechanicianSessionKey(
            turnID: turnID,
            requestID: requestID)
        let sessionToken = pendingShowMechanicianSessionTokens.removeValue(forKey: key)
        let pending = pendingShowMechanicianAcknowledgements.take(
                turnID: turnID,
                requestID: requestID)
        guard let pending,
              let sessionToken,
              pending.sessionToken == sessionToken,
              pending.conversationID == route.conversationID,
              pending.selection == route.selection,
              pending.toolProfile == route.toolProfile,
              let current = turnRoutes[turnID],
              current.phase.isActive,
              current.purpose == .conversation,
              current.toolProfile.permitsMechanicianGuidance,
              currentID == route.conversationID,
              !stopRequestedTurnIDs.contains(turnID),
              routesMatch(current, route) else {
            if let sessionToken {
                MechanicianGuidanceRouter.shared.cancel(sessionToken: sessionToken)
            }
            return
        }
    }

    /// Discard a provisional native guide and cancel only the exact session token that belongs to
    /// the affected request. A token from an older response is harmless against a newer guide.
    private func discardPendingShowMechanician(
        turnID: String,
        requestID: String? = nil
    ) {
        let keys = pendingShowMechanicianSessionTokens.keys.filter { key in
            key.turnID == turnID && (requestID == nil || key.requestID == requestID)
        }
        let tokens = keys.compactMap {
            pendingShowMechanicianSessionTokens.removeValue(forKey: $0)
        }
        if let requestID {
            pendingShowMechanicianAcknowledgements.discard(
                turnID: turnID,
                requestID: requestID)
        } else {
            pendingShowMechanicianAcknowledgements.discard(turnID: turnID)
        }
        tokens.forEach { MechanicianGuidanceRouter.shared.cancel(sessionToken: $0) }
    }

    private func discardAllPendingShowMechanician() {
        let tokens = Array(pendingShowMechanicianSessionTokens.values)
        pendingShowMechanicianSessionTokens.removeAll()
        pendingShowMechanicianAcknowledgements.removeAll()
        tokens.forEach { MechanicianGuidanceRouter.shared.cancel(sessionToken: $0) }
    }

    /// Return reviewed signed demonstrations relevant to a goal, assessed only against this root
    /// turn's exact active standard-provider surface. The caller supplies no route or requirements.
    private func applyWorkflowAdviceRequest(
        _ event: [String: Any],
        turnID: String,
        route: TurnRoute
    ) {
        guard let requestID = event["reqId"] as? String,
              !requestID.isEmpty,
              requestID.utf8.prefix(257).count <= 256 else { return }
        let interaction = InteractionRoute(turnID: turnID, route: route)
        func unavailableResponse() -> [String: Any] {
            [
                "type": "workflow_advice_response",
                "id": turnID,
                "reqId": requestID,
                "ok": false,
                "empty": false,
                "text": "Reviewed Mechanician workflow advice is unavailable for this turn.",
            ]
        }
        let baseKeys: Set<String> = ["type", "id", "reqId", "goal"]
        let eventKeys = Set(event.keys)
        let carriesDemonstrationID = eventKeys.contains("demonstrationID")
        let demonstrationID = event["demonstrationID"] as? String
        guard eventKeys == baseKeys
                || eventKeys == baseKeys.union(["demonstrationID"]),
              event["type"] as? String == "workflow_advice_request",
              event["id"] as? String == turnID,
              route.phase.isActive,
              route.purpose == .conversation,
              route.toolProfile == .standard,
              store.conversation(route.conversationID) != nil,
              let goal = event["goal"] as? String,
              goal.utf8.prefix(4 * 1_024 + 1).count <= 4 * 1_024,
              !carriesDemonstrationID || demonstrationID != nil,
              (demonstrationID?.utf8.prefix(97).count ?? 0) <= 96,
              let surfaceIdentity = route.toolSurfaceRoute else {
            _ = write(unavailableResponse(), to: interaction)
            return
        }

        Task { [weak self] in
            guard let self else { return }
            let source: MechanicianHelpWorkflowSource
            do {
                source = try await MechanicianHelpProviderRetrieval.shared.workflowMatches(
                    goal: goal,
                    demonstrationID: demonstrationID)
            } catch {
                _ = self.write(unavailableResponse(), to: interaction)
                return
            }

            // Corpus retrieval crosses an actor boundary. Re-admit the immutable root route before
            // reading capability evidence or staging a provider-visible receipt.
            guard let current = self.turnRoutes[turnID],
                  current.phase.isActive,
                  self.routesMatch(current, route),
                  current.purpose == .conversation,
                  current.toolProfile == .standard,
                  current.toolSurfaceRoute == surfaceIdentity else {
                _ = self.write(unavailableResponse(), to: interaction)
                return
            }
            let exactSnapshot: AgentToolSurfaceSnapshot? = {
                guard let snapshot = self.agentToolCatalog.snapshot(
                        for: current.conversationID),
                      snapshot.route == surfaceIdentity,
                      snapshot.isActiveEvidence,
                      snapshot.phase == .ready else { return nil }
                return snapshot
            }()
            let assessments = Dictionary(uniqueKeysWithValues: source.matches.map { match in
                (
                    match.demonstration.id,
                    self.agentToolCatalog.workflowAssessment(
                        for: match.demonstration,
                        snapshot: exactSnapshot)
                )
            })
            let answer: MechanicianWorkflowProviderAnswer
            do {
                answer = try MechanicianWorkflowProviderAdvice.providerAnswer(
                    source: source,
                    assessments: assessments,
                    routeEvidence: MechanicianWorkflowRouteEvidence(
                        permissionMode: current.permissionMode,
                        surfaceReported: exactSnapshot != nil,
                        coverage: exactSnapshot?.coverage))
            } catch {
                _ = self.write(unavailableResponse(), to: interaction)
                return
            }

            var stagedReceipt = false
            if let receipt = answer.receipt {
                guard self.pendingWorkflowAdviceReceipts.stage(
                    PendingWorkflowAdviceReceipt(
                        conversationID: current.conversationID,
                        selection: current.selection,
                        toolProfile: current.toolProfile,
                        toolSurfaceRoute: surfaceIdentity,
                        receipt: receipt),
                    turnID: turnID,
                    requestID: requestID
                ) else {
                    _ = self.write(unavailableResponse(), to: interaction)
                    return
                }
                stagedReceipt = true
            }
            let response: [String: Any] = [
                "type": "workflow_advice_response",
                "id": turnID,
                "reqId": requestID,
                "ok": true,
                "empty": answer.empty,
                "text": answer.text,
            ]
            if !self.write(response, to: interaction), stagedReceipt {
                self.pendingWorkflowAdviceReceipts.discard(
                    turnID: turnID,
                    requestID: requestID)
            }
        }
    }

    /// Commit a signed-Help audit row only after the exact workflow result crosses the provider's
    /// result boundary. This registry is deliberately disjoint from ordinary Help searches.
    private func applyWorkflowAdviceAcknowledgement(
        _ event: [String: Any],
        turnID: String,
        route: TurnRoute
    ) {
        guard Set(event.keys) == ["type", "id", "reqId"],
              event["type"] as? String == "workflow_advice_ack",
              event["id"] as? String == turnID,
              let requestID = event["reqId"] as? String,
              !requestID.isEmpty,
              requestID.utf8.prefix(257).count <= 256,
              let pending = pendingWorkflowAdviceReceipts.take(
                turnID: turnID,
                requestID: requestID),
              pending.conversationID == route.conversationID,
              pending.selection == route.selection,
              pending.toolProfile == route.toolProfile,
              pending.toolSurfaceRoute == route.toolSurfaceRoute,
              let current = turnRoutes[turnID],
              current.phase.isActive,
              current.purpose == .conversation,
              routesMatch(current, route),
              current.toolSurfaceRoute == pending.toolSurfaceRoute else { return }
        discloseHelpConsultation(
            pending.receipt,
            turnID: turnID,
            conversationID: pending.conversationID)
    }







    /// Say, once, that most of the allowance is gone — and what quietly changes because of it.
    ///
    /// ONCE PER CONVERSATION PER LIMIT. The daemon already says it once per turn; a person working
    /// through a week at 87% would otherwise collect one of these on every turn, which is noise they
    /// learn to skip, which is the same as never saying it.
    private func discloseUsageWarning(_ event: [String: Any], route: TurnRoute?) {
        guard let warning = UsageWarning.from(event: event) else { return }
        let conversationID = route?.conversationID ?? currentID
        guard let conversationID else { return }
        let key = warning.rateLimitType ?? "claude"
        guard usageWarningsSaid[conversationID] != key else { return }
        usageWarningsSaid[conversationID] = key

        var entry = TranscriptEntry(kind: .system, text: warning.title)
        entry = capturedTranscriptEntry(entry, conversationID: conversationID)
        entry.usageWarning = warning
        if conversationID == currentID {
            closeAssistantBeforeStructuralEntry()
            entries.append(entry)
            currentConversationNeedsPersistence = true
            return
        }
        openAssistantEntryByConversation[conversationID] = nil
        store.update(conversationID) { $0.messages.append(entry) }
    }

    /// Which conversations have already been told, per limit. Not durable: after a relaunch the
    /// warning is worth repeating once, because the state is still true and they may not have seen
    /// it. Costs one row per conversation per launch at most.
    private var usageWarningsSaid: [UUID: String] = [:]

    /// Background agents that are still expected to act after the turn that started them ends.
    ///
    /// Deliberately the same count the Stop button and the Agents tab use, rather than a second
    /// opinion: a workflow aggregate can arrive terminal before its last child does, so counting
    /// aggregate statuses alone reports zero in exactly the case this disclosure exists to describe.
    ///
    /// Internal so a test can assert the count without driving a provider turn.
    func outstandingBackgroundAgentCount(in conversationID: UUID) -> Int {
        blockingDelegateCount(for: conversationID)
    }

    /// Say when background agents outlive the turn that started them.
    ///
    /// A Workflow, or a Task started in the background, keeps running inside the provider session
    /// after the turn ends. The session's permission context does not: every tool call those agents
    /// make afterwards is refused by the engine with its standard decline message, the one that
    /// reads as though the person denied it. Nothing in Mechanician denies them, nothing logs it,
    /// and the run keeps spending tokens until it gives up.
    ///
    /// Measured on a real run: a workflow's agents made 21 successful tool calls, the root turn
    /// posted its answer at 12:38:54, and every one of the 32 calls after that instant was refused.
    /// Three separate agents, reading only their own transcripts, concluded that Mechanician's
    /// permission layer was broken. It was not, and there was nothing on screen to tell them.
    ///
    /// This is the honest half of the fix. Keeping the session authorized past its turn is the
    /// engine's decision to make, so say plainly what happened instead of leaving it silent.
    ///
    /// ONCE PER CONVERSATION PER LAUNCH, like `discloseUsageWarning` above and for the same reason.
    /// The count is conversation-scoped state, not turn-scoped: a run that outlives turn 3 is still
    /// outstanding when turns 4, 5 and 6 end, and one row per turn about the same run is noise a
    /// person learns to skip, which is the same as never saying it.
    private func discloseBackgroundAgentsOutlivingTurn(conversationID: UUID) {
        guard !backgroundOutlivingSaid.contains(conversationID) else { return }
        let count = outstandingBackgroundAgentCount(in: conversationID)
        guard count > 0 else { return }
        backgroundOutlivingSaid.insert(conversationID)
        let noun = count == 1 ? "agent was" : "agents were"
        let summary = "\(count) background \(noun) still running when this turn ended. "
            + "Their tool calls will be refused, because a background run cannot outlive the turn "
            + "that started it. Ask for that work again in a turn that stays open until it finishes."

        var entry = TranscriptEntry(kind: .system, text: summary)
        entry = capturedTranscriptEntry(entry, conversationID: conversationID)
        entry.backgroundWorkOutlivedTurn = true
        if conversationID == currentID {
            closeAssistantBeforeStructuralEntry()
            entries.append(entry)
            currentConversationNeedsPersistence = true
            return
        }
        openAssistantEntryByConversation[conversationID] = nil
        store.update(conversationID) { $0.messages.append(entry) }
    }

    /// Which conversations have already been told. Recorded only when a row was actually appended,
    /// so an ordinary turn never consumes an entry. Not durable: after a relaunch the state is worth
    /// saying once more, because it is still true and they may not have seen it.
    private var backgroundOutlivingSaid: Set<UUID> = []

#if DEBUG
    /// Run the same disclosure the `done` handlers call, without a provider turn.
    func discloseBackgroundAgentsOutlivingTurnForTesting(conversationID: UUID) {
        discloseBackgroundAgentsOutlivingTurn(conversationID: conversationID)
    }
#endif





    private func discloseHelpConsultation(
        _ receipt: MechanicianHelpConsultationReceipt,
        turnID: String,
        conversationID: UUID
    ) {
        guard receipt.claimCount > 0, !receipt.articleTitles.isEmpty else { return }
        let noun = receipt.claimCount == 1 ? "claim" : "claims"
        let summary = "Consulted Mechanician Help: "
            + receipt.articleTitles.joined(separator: ", ")
            + " (\(receipt.claimCount) signed \(noun))."
        if conversationID != currentID {
            var entry = TranscriptEntry(kind: .system, text: summary)
            entry = capturedTranscriptEntry(entry, conversationID: conversationID)
            entry.helpConsultationReceipt = true
            entry.helpConsultationCorpusID = receipt.corpusID
            entry.helpConsultationClaimCount = receipt.claimCount
            entry.helpConsultationTurnID = turnID
            openAssistantEntryByConversation[conversationID] = nil
            store.update(conversationID) { $0.messages.append(entry) }
            return
        }
        closeAssistantBeforeStructuralEntry()
        var entry = TranscriptEntry(kind: .system, text: summary)
        entry = capturedTranscriptEntry(entry, conversationID: conversationID)
        entry.helpConsultationReceipt = true
        entry.helpConsultationCorpusID = receipt.corpusID
        entry.helpConsultationClaimCount = receipt.claimCount
        entry.helpConsultationTurnID = turnID
        openAssistantEntryByConversation[conversationID] = nil
        entries.append(entry)
        currentConversationNeedsPersistence = true
        persistCurrent()
    }









    private func flushPendingModelCatalogs(for access: ModelAccess) {
        guard isRuntimeUsable(access),
              let scopes = pendingModelCatalogScopes[access], !scopes.isEmpty else { return }
        // Serialize discovery per lane. Claude uses a short-lived SDK subprocess for every distinct
        // cwd, so emitting all scopes together can turn project traversal into a process burst.
        guard !modelCatalogRequestRoutes.values.contains(where: { $0.access == access }) else {
            return
        }
        let epoch = ProviderAccountStore.shared.credentialEpoch(for: access)
        guard runtimeCredentialEpochs[access] == epoch else { return }
        let activeScope = catalogScope(for: access)
        let scope = scopes.contains(activeScope) ? activeScope : scopes.sorted().first!
        pendingModelCatalogScopes[access]?.remove(scope)
        let requestID = UUID().uuidString
        let requestCwd = access.maker == .anthropic
            ? scope : turnCwd(for: currentConversation)
        var request: [String: Any] = [
            "type": "model_catalog",
            "id": requestID,
            "cwd": requestCwd,
            "scope": scope,
        ]
        // A managed Vertex catalog query must initialize on a model the deployment actually
        // carries. Omitting this lets Claude's local runtime choose its newest first-party default,
        // which can 404 before supportedModels() has a chance to answer.
        if let declared = TenantProfile.current.declaredModels(for: access).first {
            request["model"] = declared.id
        }
        guard write(request, to: access) else {
            pendingModelCatalogScopes[access, default: []].insert(scope)
            return
        }
        // Allocate process-wide ownership only after the request bytes were accepted by the pipe.
        guard let ticket = ModelCatalogStore.shared.beginExplicitRequest(
            access: access, scope: scope, credentialEpoch: epoch) else {
            pendingModelCatalogScopes[access, default: []].insert(scope)
            return
        }
        modelCatalogRequestRoutes[requestID] = ModelCatalogRequestRoute(
            access: access, scope: scope, credentialEpoch: epoch, ticket: ticket)
        latestModelCatalogRequestIDs[ticket.key] = requestID
        armModelCatalogRequestTimeout(requestID)
    }

    /// The daemon bounds provider control calls, but the app owns the request lifecycle. A daemon
    /// generation can lose a terminal event without exiting, and before this watchdog that left the
    /// process-wide snapshot in `.loading` forever. The picker remains usable from its safe local
    /// projection while this timer converts abandoned enrichment into a retryable error.
    private func armModelCatalogRequestTimeout(_ requestID: String) {
        modelCatalogRequestTimeouts.removeValue(forKey: requestID)?.cancel()
        modelCatalogRequestTimeouts[requestID] = Task { @MainActor [weak self] in
            try? await Task.sleep(nanoseconds: Self.modelCatalogRequestTimeoutNanoseconds)
            guard !Task.isCancelled, let self else { return }
            self.modelCatalogRequestTimeouts[requestID] = nil
            guard let route = self.modelCatalogRequestRoutes.removeValue(forKey: requestID) else {
                return
            }
            if self.latestModelCatalogRequestIDs[route.ticket.key] == requestID {
                self.latestModelCatalogRequestIDs[route.ticket.key] = nil
            }
            _ = ModelCatalogStore.shared.fail(
                ticket: route.ticket,
                message: "Model refresh timed out. Declared and cached models remain available.")
            self.flushPendingModelCatalogs(for: route.access)
        }
    }

    private func consumeModelCatalogEvent(
        _ event: [String: Any], from access: ModelAccess, credentialEpoch: Int
    ) -> Bool {
        guard let eventType = event["type"] as? String,
              eventType == "model_catalog" || eventType == "model_catalog_error" else {
            return false
        }
        let accounts = ProviderAccountStore.shared
        guard credentialEpoch == accounts.credentialEpoch(for: access),
              accounts.operation(for: access) == nil else { return true }

        let requestID = event["id"] as? String
        let route: ModelCatalogRequestRoute?
        var shouldFlushNextRequest = false
        defer {
            if shouldFlushNextRequest { flushPendingModelCatalogs(for: access) }
        }
        if let requestID {
            modelCatalogRequestTimeouts.removeValue(forKey: requestID)?.cancel()
            route = modelCatalogRequestRoutes.removeValue(forKey: requestID)
            guard let route, route.access == access,
                  route.credentialEpoch == credentialEpoch else { return true }
            shouldFlushNextRequest = true
            if latestModelCatalogRequestIDs[route.ticket.key] == requestID {
                latestModelCatalogRequestIDs[route.ticket.key] = nil
            }
        } else {
            route = nil
        }
        let eventScope = event["scope"] as? String ?? route?.scope ?? catalogScope(for: access)
        if let route,
           ModelCatalogStore.normalizedScope(route.scope)
            != ModelCatalogStore.normalizedScope(eventScope) {
            _ = ModelCatalogStore.shared.fail(
                ticket: route.ticket, message: "Provider returned the wrong model catalog scope")
            return true
        }

        if eventType == "model_catalog_error" {
            let message = event["message"] as? String ?? "Model catalog unavailable"
            let accepted: Bool
            if let route {
                accepted = ModelCatalogStore.shared.fail(ticket: route.ticket, message: message)
            } else {
                accepted = ModelCatalogStore.shared.failAutomatic(
                    access: access, scope: eventScope, credentialEpoch: credentialEpoch,
                    message: message)
            }
            guard accepted else { return true }
            // A lane still `checking` has just been told its provider is unreachable, and that is
            // the answer. Leaving it `checking` leaves the exact condition `prepareModelCatalog`
            // treats as "probe this lane", so the next picker projection launches another daemon —
            // a provider the app cannot reach was getting a fresh one every few minutes for as long
            // as the app was in use.
            accounts.reportProbeUnavailable(access: access, message: message)
            if access == .codexSubscription {
                codexModels = []
                codexEffortsByModel = [:]
                codexDefaultModel = nil
            }
            return true
        }

        let defaultID = event["defaultModelID"] as? String
        let decoded = (event["models"] as? [[String: Any]] ?? []).compactMap {
            item -> ModelCatalogEntry? in
            guard let modelID = item["id"] as? String, !modelID.isEmpty else { return nil }
            return ModelCatalogEntry(
                selection: ModelSelection(access: access, modelID: modelID),
                displayName: item["label"] as? String ?? modelID,
                description: item["description"] as? String ?? "",
                resolvedModelID: item["resolvedModelID"] as? String,
                isDefault: item["isDefault"] as? Bool ?? (defaultID == modelID),
                supportedEfforts: item["efforts"] as? [String] ?? [],
                capabilities: item["capabilities"] as? [String] ?? [])
        }
        let accepted: Bool
        if let route {
            accepted = ModelCatalogStore.shared.publish(decoded, ticket: route.ticket)
        } else {
            accepted = ModelCatalogStore.shared.publishAutomatic(
                decoded, access: access, scope: eventScope, credentialEpoch: credentialEpoch)
        }
        guard accepted else { return true }
        if access.usesInteractiveAccountFlow, !decoded.isEmpty {
            // A provider-owned catalog is authenticated evidence. Let the runtime that supplied it
            // repair a stale process-wide account row even if another window's launch probe failed.
            updateLaneState(access, reportAccount: true) { state in
                state.loggedIn = true
                state.loginError = nil
            }
        }
        // The same evidence answers a separate question: if new conversations are still inheriting a
        // lane with no credentials, this account is a better default than the one that blocks them.
        if !decoded.isEmpty { adoptDefaultConversationAccessIfUnusable(access) }
        let capabilityStore = ProviderCapabilityStore.shared
        let hadCapabilityEvidence = capabilityStore.hasSnapshot(for: access)
        if hadCapabilityEvidence {
            // Every accepted provider catalog replaces the evidence capabilities were derived
            // from. Clear the old snapshot even when the model id is unchanged; if this window is
            // showing that access, transparently refresh its diagnostics from the new catalog.
            capabilityStore.invalidate(access: access)
            if access == currentModelAccess, !decoded.isEmpty {
                pendingProviderCapabilityRefreshes[access] = true
            }
        }
        if access == .codexSubscription {
            codexModels = decoded.map { ($0.displayName, $0.selection.modelID) }
            codexEffortsByModel = Dictionary(uniqueKeysWithValues: decoded.map {
                ($0.selection.modelID, $0.supportedEfforts)
            })
            codexDefaultModel = decoded.first(where: { $0.isDefault })?.selection.modelID
                ?? decoded.first?.selection.modelID
        }
        // A capability refresh waits for the exact provider-owned model snapshot. Once that
        // catalog is authoritative, issue the diagnostic request without changing any controls.
        flushPendingProviderCapabilities(for: access)
        // Provider-access work cannot transfer until a real model id is available. Catalog
        // publication is the authoritative retry point after a cold ready-before-catalog launch.
        Self.resumeProviderAccessRequestsProcessWide(for: access)
        // Banner-originated account recovery has the same two asynchronous edges. A catalog
        // published by any window may be the final proof needed by the exact origin bridge.
        Self.attemptProviderSetupRecoveriesProcessWide(for: access)
        // Only a never-started placeholder may acquire the provider default implicitly. An
        // established unavailable selection remains visible and is never silently substituted.
        guard access == currentModelAccess, model.isEmpty,
              let selected = decoded.first(where: { $0.isDefault }) ?? decoded.first,
              let id = currentID, let conversation = store.conversation(id),
              conversation.sdkSessionId == nil,
              conversation.queuedPrompts.isEmpty,
              conversation.providerAccessRequest == nil,
              !conversation.messages.contains(where: { $0.kind == .user || $0.kind == .assistant })
        else { return true }
        isProjectingModelSelection = true
        model = selected.selection.modelID
        isProjectingModelSelection = false
        store.update(id) { $0.modelSelection = selected.selection }
        persistWorkspaceDefault(
            selected.selection, projectID: conversation.projectID, cwd: conversation.cwd)
        normalizeVisibleEffort(for: selected.selection)
        saveSettings()
        return true
    }

    private func markModelCatalogRuntimeUnavailable(_ access: ModelAccess, message: String) {
        let ownedRoutes = modelCatalogRequestRoutes.filter { $0.value.access == access }
        for (requestID, route) in ownedRoutes {
            modelCatalogRequestRoutes[requestID] = nil
            modelCatalogRequestTimeouts.removeValue(forKey: requestID)?.cancel()
            if latestModelCatalogRequestIDs[route.ticket.key] == requestID {
                latestModelCatalogRequestIDs[route.ticket.key] = nil
            }
            // A different window may already own a newer ticket for this key. The process-wide
            // store rejects this failure in that case, preserving its newer ready snapshot.
            _ = ModelCatalogStore.shared.fail(ticket: route.ticket, message: message)
        }
        latestModelCatalogRequestIDs = latestModelCatalogRequestIDs.filter { $0.key.access != access }

        // Retain only work that was active or outstanding in this lane. At most one request is sent
        // concurrently and one newer active scope can be pending, so this set stays bounded at two.
        var scopes = pendingModelCatalogScopes[access] ?? []
        scopes.formUnion(ownedRoutes.values.map(\.scope))
        let activeScope = catalogScope(for: access)
        var ordered: [String] = []
        if scopes.contains(activeScope) { ordered.append(activeScope) }
        ordered.append(contentsOf: ownedRoutes.values.map(\.scope).sorted())
        ordered.append(contentsOf: scopes.sorted())
        var bounded: [String] = []
        for scope in ordered where !bounded.contains(scope) {
            bounded.append(scope)
            if bounded.count == 2 { break }
        }
        pendingModelCatalogScopes[access] = Set(bounded)

        let epoch = ProviderAccountStore.shared.credentialEpoch(for: access)
        for scope in pendingModelCatalogScopes[access] ?? [] {
            _ = ModelCatalogStore.shared.failAutomatic(
                access: access, scope: scope, credentialEpoch: epoch, message: message)
        }

        let capabilityRoutes = providerCapabilityRequestRoutes.filter { $0.value.access == access }
        for (requestID, route) in capabilityRoutes {
            providerCapabilityRequestRoutes[requestID] = nil
            _ = ProviderCapabilityStore.shared.fail(route.ticket, message: message)
        }
        // Preserve an explicit diagnostic refresh across one bounded runtime replacement. A late
        // response from the stopped generation cannot publish through its removed ticket route.
        if !capabilityRoutes.isEmpty {
            pendingProviderCapabilityRefreshes[access] = true
        }
    }

    var availableModels: [(String, String)] {
        let snapshot = ModelCatalogStore.shared.snapshot(
            for: currentModelAccess, scope: catalogScope(for: currentModelAccess))
        if snapshot.phase == .ready {
            return snapshot.entries.map { ($0.versionedDisplayName, $0.selection.modelID) }
        }
        switch provider {
        case "codex":
            return codexModels.isEmpty ? [("Codex default", "")] : codexModels
        default:
            // Use the SAME profile-aware source the picker and `selectModel` use. Reaching for the
            // generic built-in list here was a real enterprise bug: several cold-start paths take
            // `availableModels[0]` as the default selection, so a managed Vertex tenant whose
            // catalog had not published yet silently selected the newest first-party model — which
            // its deployment answers with a 404 — and `modelIsKnownForCurrentAccess` then treated
            // that undeclared id as valid, so it was never corrected.
            return Self.fallbackEntries(
                for: currentModelAccess,
                scope: catalogScope(for: currentModelAccess)
            ).map { ($0.versionedDisplayName, $0.selection.modelID) }
        }
    }

    /// The models a lane offers when its provider's live catalog is unavailable.
    ///
    /// Order matters: several cold-start paths take `availableModels[0]` as the default selection.
    ///
    /// Opus 4.8 is here because it is the app's own default model (`model`, and agentd's
    /// DEFAULT_MODEL) and because a managed deployment may not carry the newest generation at all —
    /// an enterprise Vertex project that has only 4.8 answers `claude-opus-5` with a 404, so a list
    /// without 4.8 leaves that account no working choice.
    static func builtInModels(for access: ModelAccess) -> [(String, String)] {
        // A managed Vertex deployment is provisioned per project and lags first-party availability,
        // so guessing the NEWEST generation for it is guessing wrong: an enterprise project that
        // carries only 4.8 answers `claude-opus-5` with a 404 and the account has no working turn.
        // A profile that declares its own models overrides this entirely (`builtInCatalogEntries`);
        // this ordering is only the last resort for a Vertex route that declared none.
        // Bedrock model ids, VERIFIED by invoking them against a live account — not derived from
        // any list, because two different lists each gave a wrong answer:
        //   * `claude-opus-4-8` (Anthropic's id) — Bedrock has never heard of it.
        //   * `anthropic.claude-opus-4-8` (from list-foundation-models) — ValidationException,
        //     "on-demand throughput isn't supported". A bare foundation id is not invokable for the
        //     current generation.
        //   * `global.anthropic.claude-opus-4-8` (an inference profile) — accepted.
        // So the invokable id is a CROSS-REGION INFERENCE PROFILE. `global.` is used because it is
        // what succeeded; `us.` profiles exist too and are equivalent for a US account.
        //
        // Access is granted per model family, so an account may hold some of these and not others —
        // which is exactly why a configuration declares what it carries and this list is only the
        // starting point for that choice.
        if access == .claudeBedrock {
            return [
                ("Opus 4.8", "global.anthropic.claude-opus-4-8"),
                ("Opus 5", "global.anthropic.claude-opus-5"),
                ("Sonnet 5", "global.anthropic.claude-sonnet-5"),
                ("Sonnet 4.6", "global.anthropic.claude-sonnet-4-6"),
                ("Haiku 4.5", "global.anthropic.claude-haiku-4-5-20251001-v1:0"),
            ]
        }
        if access == .claudeVertex {
            return [
                ("Opus 4.8", "claude-opus-4-8"),
                ("Opus 5", "claude-opus-5"),
                ("Fable 5.1", "claude-fable-5-1"),
                ("Sonnet 5", "sonnet"),
                ("Haiku 4.5", "claude-haiku-4-5"),
            ]
        }
        // The two OpenAI lanes do NOT share an id namespace, and offering one lane's ids on the
        // other is offering rows that fail on click. The Codex subscription serves the ChatGPT
        // catalog (`model/list`), where the 5.6 generation ships as -Sol/-Terra/-Luna and there is
        // no bare `gpt-5.6`; the API key lane serves `/v1/models`, which carries neither those
        // suffixed ids nor `-codex-spark`. Both lists below are transcribed from a live answer on
        // the lane they belong to, not from a release note.
        if access == .codexSubscription {
            return [
                ("GPT-5.6 Sol", "gpt-5.6-sol"),
                ("GPT-5.6 Terra", "gpt-5.6-terra"),
                ("GPT-5.6 Luna", "gpt-5.6-luna"),
                ("GPT-5.5", "gpt-5.5"),
                ("GPT-5.4", "gpt-5.4"),
                ("GPT-5.4 Mini", "gpt-5.4-mini"),
            ]
        }
        switch access.maker {
        case .openAI:
            return [
                ("GPT-5.5", "gpt-5.5"),
                ("GPT-5.4", "gpt-5.4"),
                ("GPT-5.4 Pro", "gpt-5.4-pro"),
                ("GPT-5.3 Codex", "gpt-5.3-codex"),
                ("GPT-5 mini", "gpt-5-mini"),
            ]
        case .anthropic:
            return [
                ("Opus 5", "claude-opus-5"),
                ("Opus 4.8", "claude-opus-4-8"),
                ("Fable 5.1", "claude-fable-5-1"),
                ("Fable 5", "claude-fable-5"),
                ("Sonnet 5", "sonnet"),
                ("Haiku 4.5", "claude-haiku-4-5"),
            ]
        }
    }

    /// What a lane offers when its live catalog FAILED: whatever it last published, else the
    /// built-in list. One definition, used by both the picker (what it renders) and `selectModel`
    /// (what it accepts) — otherwise the rows are visible but refused on click.
    static func fallbackEntries(
        for access: ModelAccess,
        scope: String,
        profile: TenantProfile = .current
    ) -> [ModelCatalogEntry] {
        let known = ModelCatalogStore.shared.lastKnownEntries(for: access, scope: scope)
        return known.isEmpty ? builtInCatalogEntries(for: access, profile: profile) : known
    }

    /// The built-in list as catalog entries, so a lane whose live catalog failed still presents a
    /// usable picker instead of an empty one. Deliberately claims no capabilities or efforts: these
    /// are known model IDs, not a discovered catalog, and must not pretend otherwise.
    ///
    /// A managed deployment gets its OWN declared models here rather than the generic list: an
    /// enterprise Vertex project that carries only 4.8 should never be offered a newest-generation
    /// model that answers 404. See `TenantProfile.Route.models` for why this is additive only.
    static func builtInCatalogEntries(
        for access: ModelAccess,
        profile: TenantProfile = .current
    ) -> [ModelCatalogEntry] {
        let declared = profile.declaredModels(for: access)
        if !declared.isEmpty {
            return declared.map { model in
                ModelCatalogEntry(
                    selection: ModelSelection(access: access, modelID: model.id),
                    displayName: model.displayName ?? model.id,
                    description: "",
                    resolvedModelID: nil,
                    isDefault: model.isDefault,
                    supportedEfforts: [],
                    capabilities: [])
            }
        }
        return builtInModels(for: access).map { name, id in
            ModelCatalogEntry(
                selection: ModelSelection(access: access, modelID: id),
                displayName: name,
                description: "",
                resolvedModelID: nil,
                isDefault: false,
                supportedEfforts: [],
                capabilities: [])
        }
    }

    /// The models a lane can be held to. Only two sources are authoritative: a live catalog the
    /// provider actually published, and a managed deployment's own declared models. The generic
    /// built-in list is deliberately NOT authoritative — it is a guess used to keep a picker usable,
    /// and treating a guess as authority is what stamped `claude-opus-5` onto a Vertex tenant that
    /// never carried it. Empty means "no authority", and callers must then change nothing.
    private func authoritativeEntries(
        for access: ModelAccess,
        scope: String,
        profile: TenantProfile = .current
    ) -> [ModelCatalogEntry] {
        let snapshot = ModelCatalogStore.shared.snapshot(for: access, scope: scope)
        if snapshot.phase == .ready, !snapshot.entries.isEmpty { return snapshot.entries }
        // A declared route is authoritative even with no live catalog: the deployment's contract is
        // what it says it carries, and it is the reason a 404 is predictable rather than transient.
        return profile.declaredModels(for: access).isEmpty
            ? []
            : Self.builtInCatalogEntries(for: access, profile: profile)
    }

    /// A conversation stamped with a model its own route does not offer can never produce a turn:
    /// the provider answers every send with a 404, and nothing in the app corrects it, so the
    /// conversation is dead for as long as it exists. Re-point it to the route's default.
    ///
    /// This is not the app overriding a user's choice. A stamp only becomes wrong when it was never
    /// offered by this lane in the first place — a cold-start default, or a profile that changed
    /// under an existing conversation — so there is no choice here to preserve. An explicit pick
    /// still cannot be rewritten, because a picked model is by construction one the lane offered.
    ///
    /// Returns nil whenever nothing should change, including the important case of no authority at
    /// all: guessing is what caused the original defect, and guessing twice would not fix it.
    static func healedSelection(
        stamped: ModelSelection,
        authoritativeEntries entries: [ModelCatalogEntry]
    ) -> ModelSelection? {
        guard !entries.isEmpty else { return nil }
        // Codex spells "the account default" as an empty id; it is not an unavailable model.
        // Other lanes use concrete wire ids. An old managed Vertex placeholder with an empty id
        // otherwise delegates selection back to Claude's moving first-party default and can revive
        // the same Opus 5 failure this authority is meant to prevent.
        if stamped.modelID.isEmpty {
            guard stamped.access != .codexSubscription,
                  let replacement = entries.first(where: \.isDefault) ?? entries.first,
                  !replacement.selection.modelID.isEmpty,
                  replacement.selection != stamped else { return nil }
            return replacement.selection
        }
        // Match aliases the way the picker does — `sonnet` and its resolved generation are the same
        // model, and rewriting one to the other would be a change with no cause.
        let offered = entries.contains {
            $0.selection.modelID == stamped.modelID || $0.resolvedModelID == stamped.modelID
        }
        guard !offered else { return nil }
        let replacement = entries.first(where: \.isDefault) ?? entries[0]
        guard replacement.selection != stamped else { return nil }
        return replacement.selection
    }

    private struct ModelHealingResult {
        var selection: ModelSelection
        /// True means the durable opaque-session facts were retired by this exact call. The send
        /// boundary still carries this bit explicitly so it cannot accidentally derive a resumable
        /// id from the stale pre-heal Conversation snapshot held by its caller.
        var requiresFreshSession: Bool
    }

    /// Apply `healedSelection` to one conversation, persist it, and say so. Automatic replacement
    /// of an established model is a provider-session boundary: durable session/context facts and
    /// every visible meter retire before the caller constructs its request.
    private func healStampedSelection(
        _ stamped: ModelSelection,
        in target: Conversation
    ) -> ModelHealingResult? {
        let conversationID = target.id
        let entries = authoritativeEntries(
            for: stamped.access,
            scope: catalogScope(for: stamped.access, conversation: target))
        guard let healed = Self.healedSelection(stamped: stamped, authoritativeEntries: entries)
        else { return ModelHealingResult(selection: stamped, requiresFreshSession: false) }
        var didHeal = false
        guard store.update(conversationID, { conversation in
            didHeal = Self.applyAutomaticModelHealing(
                healed,
                replacing: stamped,
                to: &conversation)
        }) != nil, didHeal else {
            // A newer main-actor mutation won between the caller's snapshot and this update. Do not
            // send either stale choice; the ordinary queue recovery path will retry from authority.
            return nil
        }
        for bridge in Self.live.allObjects where bridge.currentID == conversationID {
            bridge.clearLiveProviderSessionContext()
            bridge.lastComposerPrewarm = nil
            bridge.pendingConversationLoads[healed.access] = nil
            bridge.isProjectingModelSelection = true
            bridge.model = healed.modelID
            bridge.isProjectingModelSelection = false
            bridge.projectTurnPreferences(for: healed.access)
            bridge.normalizeVisibleEffort(for: healed)
        }
        let replacementName = entries
            .first(where: { $0.selection == healed })?
            .versionedDisplayName ?? healed.modelID
        let note = "\(stamped.modelID) isn't available on this \(stamped.access.displayName) "
            + "deployment. Switched to \(replacementName)."
        if currentID == conversationID {
            appendSystem(note)
        } else {
            // A background conversation has no live transcript buffer to append to, so the note goes
            // straight to its durable messages. It is intentionally not part of the history sent to
            // the provider: it is a record of what the app did, not something Claude said or heard.
            store.update(conversationID) { conversation in
                let entry = capturedTranscriptEntry(
                    TranscriptEntry(kind: .system, text: note),
                    conversationID: conversationID)
                conversation.messages.append(entry)
            }
        }
        return ModelHealingResult(selection: healed, requiresFreshSession: true)
    }

    /// A cold launch starts before a provider can publish a fresh workspace catalog. Preserve an
    /// exact selection already present in the last account-scoped catalog—including stable aliases
    /// such as `sonnet`—instead of replacing it with the first hard-coded fallback.
    private func modelIsKnownForCurrentAccess(_ modelID: String) -> Bool {
        let access = currentModelAccess
        let store = ModelCatalogStore.shared
        let scope = catalogScope(for: access)
        let snapshot = store.snapshot(for: access, scope: scope)
        let entries = snapshot.phase == .ready
            ? snapshot.entries
            : store.lastKnownEntries(for: access, scope: scope)
        if entries.contains(where: {
            $0.selection.modelID == modelID || $0.resolvedModelID == modelID
        }) {
            return true
        }
        return availableModels.contains(where: { $0.1 == modelID })
    }

    /// Apply an explicit model choice to the current conversation. Projecting a restored
    /// conversation into the toolbar still assigns `model` directly; only this user-action path
    /// changes an established conversation's durable model identity.
    func selectModel(_ modelID: String) {
        let candidate = ModelSelection(access: currentModelAccess, modelID: modelID)
        let snapshot = ModelCatalogStore.shared.snapshot(
            for: candidate.access, scope: catalogScope(for: candidate.access))
        if snapshot.phase == .ready,
           snapshot.entries.contains(where: { $0.selection == candidate }) {
            selectModel(candidate)
            return
        }
        let access = currentModelAccess
        if let id = currentID,
           let blocker = conversationWorkBlocker(for: id, includeNonWorkBlockers: false) {
            if let stored = currentConversation?.modelSelection?.modelID, model != stored {
                model = stored
            }
            appendSystem(blocker.notice)
            return
        }
        let selection = ModelSelection(access: access, modelID: modelID)
        guard applyExplicitSameAccessModelSelection(selection) else { return }
        if !isResolvingProviderSetupRecovery { cancelProviderSetupRecovery() }
    }

    /// Atomically apply one entitled composite selection. Model IDs are not globally unique, so
    /// membership, account state, active-turn safety, provider projection and persistence are
    /// checked as one user action rather than a series of scalar picker writes.
    @discardableResult
    func selectModel(_ selection: ModelSelection) -> Bool {
        guard selection.access.isAllowedByEnterprisePolicy else {
            appendSystem(String(localized: "That provider is blocked by your organization."))
            return false
        }
        let accounts = ProviderAccountStore.shared
        guard accounts.operation(for: selection.access) == nil,
              accounts.state(for: selection.access).isAvailable else {
            appendSystem("Finish or reconnect \(selection.access.displayName) before choosing its models.")
            return false
        }
        let scope = catalogScope(for: selection.access)
        let snapshot = ModelCatalogStore.shared.snapshot(for: selection.access, scope: scope)
        let isSelectable: Bool
        switch snapshot.phase {
        case .ready:
            isSelectable = snapshot.entries.contains { $0.selection == selection }
        case .failed:
            // The picker offers last-known/built-in rows for a connected lane whose catalog request
            // failed. Refusing them here would make those rows decorative and leave the account
            // with no selectable model at all.
            isSelectable = Self.fallbackEntries(for: selection.access, scope: scope)
                .contains { $0.selection == selection }
        case .idle, .loading:
            isSelectable = false
        }
        guard isSelectable else {
            appendSystem("That model is not available from \(selection.access.displayName) in this workspace.")
            return false
        }
        let previousAccess = currentModelAccess
        if previousAccess != selection.access {
            guard allowAccessChange(to: selection.access) else { return false }
        } else if let blocker = modelSelectionBlocker(for: selection) {
            appendSystem(blocker.notice)
            return false
        }
        if previousAccess == selection.access {
            guard applyExplicitSameAccessModelSelection(selection) else { return false }
            if !isResolvingProviderSetupRecovery { cancelProviderSetupRecovery() }
            return true
        }
        let settings = providerSettings(for: selection.access)
        isProjectingModelSelection = true
        provider = settings.provider
        authMode = settings.authMode
        model = selection.modelID
        isProjectingModelSelection = false
        // Restore the target lane before validating the selected model. Otherwise the visible
        // provider's effort can be normalized first and a stale, unsupported target value can be
        // projected immediately afterward.
        projectTurnPreferences(for: selection.access)
        normalizeVisibleEffort(for: selection)

        if previousAccess != selection.access {
            saveSettings()
            ActiveWorkspace.shared.accessDidChange(self)
            activateAccessChange(from: previousAccess)
            if !isResolvingProviderSetupRecovery { cancelProviderSetupRecovery() }
            return true
        }
        return false
    }

    /// Cross the durable fresh-session boundary before projecting the new picker value. That order
    /// matters: projection can trigger composer prewarm, and an old prewarm must never be eligible
    /// to race a model/context-variant change. Every bridge showing the same record clears its live
    /// meter and asks its own lane to prepare the newly selected, explicitly fresh session.
    @discardableResult
    private func applyExplicitSameAccessModelSelection(_ selection: ModelSelection) -> Bool {
        guard selection.access == currentModelAccess else { return false }
        guard let conversationID = currentID,
              let before = store.conversation(conversationID),
              before.modelSelection == nil || before.modelSelection?.access == selection.access
        else { return false }

        if before.modelSelection == selection {
            // Exact no-op: preserve the opaque session, live context meter, and any provider spare.
            if model != selection.modelID { model = selection.modelID }
            return true
        }

        var changed = false
        let selectionStore = store
        guard let updated = store.updateAwaitingPersistence(conversationID, { conversation in
            changed = Self.applyExplicitSameAccessModelSelection(selection, to: &conversation)
        }, completion: { [weak self] committed in
            // Provider load/prewarm is itself session exposure. Wait for the model/session
            // retirement to reach authority, then revalidate against a newer click before any
            // daemon can observe it. A failed commit leaves the provisional selection visible but
            // inert behind the store's ordinary persistence recovery surface.
            guard committed,
                  let canonical = selectionStore.conversation(conversationID),
                  canonical.modelSelection == selection,
                  canonical.sdkSessionId == nil else { return }
            var peers = Self.live.allObjects.filter { $0.currentID == conversationID }
            if let self, !peers.contains(where: { $0 === self }) { peers.append(self) }
            for bridge in peers {
                bridge.loadConversation(canonical, cwd: canonical.cwd, forceFresh: true)
            }
            guard let self,
                  before.sdkSessionId == nil,
                  before.queuedPrompts.isEmpty,
                  before.providerAccessRequest == nil,
                  !before.messages.contains(where: {
                      $0.kind == .user || $0.kind == .assistant
                  }) else { return }
            self.persistWorkspaceDefault(
                selection, projectID: before.projectID, cwd: before.cwd)
        }), changed else { return false }

        var affected = Self.live.allObjects.filter { $0.currentID == conversationID }
        if !affected.contains(where: { $0 === self }) { affected.append(self) }
        for bridge in affected {
            bridge.clearLiveProviderSessionContext()
            bridge.lastComposerPrewarm = nil
            bridge.pendingConversationLoads[selection.access] = nil
            bridge.stagePendingHistoryReplay(updated.messages, for: updated)

            bridge.isProjectingModelSelection = true
            bridge.model = selection.modelID
            bridge.isProjectingModelSelection = false
            bridge.projectTurnPreferences(for: selection.access)
            bridge.normalizeVisibleEffort(for: selection)
        }
        saveSettings()
        return true
    }

    nonisolated static func catalogResolvedModelID(
        for selection: ModelSelection,
        catalogEntry: ModelCatalogEntry?
    ) -> String? {
        guard selection.access.maker == .anthropic,
              let catalogEntry,
              catalogEntry.selection == selection
                || catalogEntry.resolvedModelID == selection.modelID,
              let raw = catalogEntry.resolvedModelID else { return nil }
        let resolved = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        return resolved.isEmpty ? nil : resolved
    }

    private func catalogEntry(
        for selection: ModelSelection,
        conversation: Conversation? = nil
    ) -> ModelCatalogEntry? {
        ModelCatalogStore.shared.snapshot(
            for: selection.access,
            scope: catalogScope(for: selection.access, conversation: conversation))
            .entries.first(where: {
                $0.selection == selection || $0.resolvedModelID == selection.modelID
            })
    }

    private func catalogResolvedModelID(
        for selection: ModelSelection,
        conversation: Conversation
    ) -> String? {
        Self.catalogResolvedModelID(
            for: selection,
            catalogEntry: catalogEntry(for: selection, conversation: conversation))
    }

    private func efforts(for selection: ModelSelection) -> [String] {
        guard let entry = catalogEntry(for: selection) else { return [] }
        // Effort choices are exact provider metadata. Codex reports native `ultra` on eligible
        // models; Claude's Ultracode contract is still discovered separately from xhigh support.
        return normalizedEfforts(entry.supportedEfforts)
    }

    private func normalizeVisibleEffort(for selection: ModelSelection) {
        let supported = efforts(for: selection)
        guard !supported.isEmpty else { return }
        let ordinary = supported.filter { $0 != "ultra" }
        let needsEffortNormalization = !ordinary.isEmpty && !ordinary.contains(effort)
        let ultraSupported = Self.supportsUltra(
            access: selection.access, efforts: supported)
        let needsUltraNormalization = ultracode && !ultraSupported
        guard needsEffortNormalization || needsUltraNormalization else { return }
        isProjectingTurnPreferences = true
        if needsEffortNormalization {
            effort = Self.preferredDefaultEffort(from: ordinary) ?? ordinary[0]
        }
        if needsUltraNormalization { ultracode = false }
        isProjectingTurnPreferences = false
        rememberTurnPreferences(for: selection.access)
    }

    var availableEfforts: [String] {
        // A restored preference is not a model catalog. Advertising it as the only selectable
        // level made a cold Codex conversation show a one-row "Max" menu until some unrelated
        // bridge publication happened to redraw the controls. Stay empty until the provider has
        // answered; the effort trigger explicitly requests a refresh and observes the shared
        // catalog store.
        guard let entry = catalogEntry(for: currentModelSelection) else {
            return Self.visibleEffortChoices(reported: nil)
        }
        var choices = Self.visibleEffortChoices(reported: entry.supportedEfforts)
        // Codex exposes native Ultra as the top reasoning level in the picker. Claude keeps Ultra
        // on its own orchestration pill (it maps to Extra High + workflows, not a raw level), so
        // Ultra is surfaced as a selectable level here only for Codex.
        if currentModelAccess == .codexSubscription,
           entry.supportedEfforts.contains(where: { $0.lowercased() == "ultra" }) {
            choices.append("ultra")
        }
        return choices
    }

    /// Ladder order for the levels this build knows, then anything else the provider reported. It
    /// used to be `canonical.filter { reported.contains($0) }`, which silently dropped a level
    /// shipped after this build — so a new provider tier could not be selected until an app release.
    /// `ultra` stays out: it is added above, for Codex only, because on Claude it is not a level.
    static func visibleEffortChoices(reported: [String]?) -> [String] {
        guard let reported else { return [] }
        return EffortLevels.ordered(reported: reported, includingReserved: false)
    }

    /// Pick a safe first-use or incompatibility fallback without accidentally selecting the
    /// provider's cheapest tier merely because it is first in the catalog. Medium is the product
    /// baseline; if it is unavailable, prefer the nearest stronger ordinary level. A provider that
    /// offers only lighter levels still gets its strongest reported choice. Ultra remains an
    /// explicit, separate opt-in and is never selected by this policy.
    static func preferredDefaultEffort(from reported: [String]) -> String? {
        let supported = Set(reported.map { $0.lowercased() })
        for candidate in ["medium", "high", "xhigh", "max"] where supported.contains(candidate) {
            return candidate
        }
        for candidate in ["low", "minimal", "none"] where supported.contains(candidate) {
            return candidate
        }
        return nil
    }

    private static let firstUseEffort = "medium"

    private struct TurnPreferences: Codable {
        var effort: String
        var ultracode: Bool
    }

    private var turnPreferencesByAccess: [ModelAccess: TurnPreferences] = [:]
    private var isProjectingTurnPreferences = false
    private var isLoadingSettings = false

    @Published var effort = "medium" {
        didSet {
            // Choosing any ordinary effort is an explicit exit from the separate Ultra control.
            if !isProjectingTurnPreferences, !isLoadingSettings, ultracode { ultracode = false }
            guard !isProjectingTurnPreferences, !isLoadingSettings else { return }
            rememberTurnPreferences(for: currentModelAccess)
            saveSettings()
        }
    }
    /// Provider Ultra is stored per access lane so switching conversations/providers cannot leak
    /// the orchestration mode to another account. The wire mapping remains provider-native:
    /// Claude gets `ultracode`, while Codex gets effort `ultra`.
    @Published var ultracode = false {
        didSet {
            guard !isProjectingTurnPreferences, !isLoadingSettings else { return }
            rememberTurnPreferences(for: currentModelAccess)
            saveSettings()
        }
    }
    private func rememberTurnPreferences(for access: ModelAccess) {
        turnPreferencesByAccess[access] = TurnPreferences(effort: effort, ultracode: ultracode)
    }

    private func projectTurnPreferences(for access: ModelAccess) {
        let preferences: TurnPreferences
        if let stored = turnPreferencesByAccess[access] {
            preferences = stored
        } else {
            preferences = TurnPreferences(effort: Self.firstUseEffort, ultracode: false)
            turnPreferencesByAccess[access] = preferences
        }
        isProjectingTurnPreferences = true
        effort = preferences.effort
        ultracode = preferences.ultracode
        isProjectingTurnPreferences = false
        saveSettings()
    }

    var canUseUltra: Bool {
        // Keep a restored, previously verified choice visible while the catalog refreshes so the
        // user can turn it off and the selection survives relaunch. New enablement still requires
        // the exact current model catalog to advertise support.
        ultracode || Self.supportsUltra(
            access: currentModelAccess, efforts: efforts(for: currentModelSelection))
    }

    /// Codex surfaces Ultra as an effort level, so its effort trigger/menu selects "ultra" while
    /// Ultra is on. Claude keeps Ultra on its own pill, so its effort control still tracks the raw
    /// reasoning level underneath.
    var effortSelectionID: String {
        (ultracode && currentModelAccess == .codexSubscription) ? "ultra" : effort
    }

    /// The standalone Ultra pill is Claude-only; Codex exposes Ultra inside the effort picker.
    ///
    /// Every Claude lane, not just the first-party two. This was written as a Claude-versus-Codex
    /// distinction with a `default:` catch-all, and the two managed Claude lanes were swept up by
    /// it — so Ultra was unreachable on Vertex and Bedrock with nothing stating a reason. Nothing
    /// else agreed with that exclusion: `ultraTurnConfiguration` below already returns a
    /// configuration for all four Claude lanes, and the daemon has an explicit "not available on
    /// this Claude route" gate that it applies to the advisor and Fast mode and deliberately does
    /// not apply to `ultracode`. Listed exhaustively now so a new lane has to be classified rather
    /// than quietly excluded again.
    var showsUltraPill: Bool {
        Self.laneUsesUltraPill(currentModelAccess) && canUseUltra
    }

    /// Split out from ``showsUltraPill`` so the lane rule can be asserted on its own. The exclusion
    /// this replaced was never covered by a test, which is part of why it survived.
    static func laneUsesUltraPill(_ access: ModelAccess) -> Bool {
        switch access {
        case .claudeSubscription, .anthropicAPI, .claudeVertex, .claudeBedrock: return true
        case .codexSubscription, .openAIAPI: return false
        }
    }

    static func supportsUltra(access: ModelAccess, efforts: [String]) -> Bool {
        ultraTurnConfiguration(access: access, efforts: efforts) != nil
    }

    static func ultraTurnConfiguration(
        access: ModelAccess,
        efforts: [String]
    ) -> (effort: String, ultracode: Bool)? {
        switch access {
        case .claudeSubscription, .anthropicAPI, .claudeVertex, .claudeBedrock:
            return efforts.contains("xhigh") ? ("xhigh", true) : nil
        case .codexSubscription:
            return efforts.contains("ultra") ? ("ultra", false) : nil
        case .openAIAPI:
            return nil
        }
    }

    /// Before Codex exposed native Ultra, the persisted `ultracode` bit was Claude-only. Do not
    /// reinterpret a dormant non-Claude value as a newly enabled, more expensive provider mode on
    /// upgrade. Once settings carry the Ultra schema version, each route's explicit choice is kept.
    static func migratedLegacyUltraPreference(
        access: ModelAccess,
        effort: String,
        enabled: Bool
    ) -> (effort: String, enabled: Bool) {
        guard (access == .claudeSubscription || access == .anthropicAPI), enabled else {
            return (effort, false)
        }
        return ("xhigh", true)
    }

    func setUltra(_ enabled: Bool) {
        guard !enabled || Self.supportsUltra(
            access: currentModelAccess, efforts: efforts(for: currentModelSelection)) else { return }
        isProjectingTurnPreferences = true
        ultracode = enabled
        isProjectingTurnPreferences = false
        rememberTurnPreferences(for: currentModelAccess)
        saveSettings()
    }

    /// The picker is still a window-level control, but a background turn must never inherit a
    /// setting its own provider cannot understand. Normalize the visible choice against the exact
    /// durable route that will receive the request and send the provider's raw effort value.
    private func turnConfiguration(for selection: ModelSelection) -> (effort: String?, ultracode: Bool) {
        let preferences = turnPreferencesByAccess[selection.access]
            ?? TurnPreferences(effort: Self.firstUseEffort, ultracode: false)
        let requested = preferences.effort.lowercased()
        if let entry = catalogEntry(for: selection) {
            let supported = normalizedEfforts(entry.supportedEfforts)
            guard !supported.isEmpty else {
                // Empty authoritative metadata is provider-default behavior, not permission to
                // invent a conventional or Ultra effort value.
                return (nil, false)
            }
            if preferences.ultracode,
               let ultra = Self.ultraTurnConfiguration(
                access: selection.access, efforts: supported) {
                return ultra
            }
            let ordinary = supported.filter { $0 != "ultra" }
            guard !ordinary.isEmpty else { return (nil, false) }
            if ordinary.contains(requested) { return (requested, false) }
            return (Self.preferredDefaultEffort(from: ordinary), false)
        }

        // Restored conversations can send before a catalog refresh. The settings schema migration
        // has already removed dormant pre-Codex Ultra bits, so an enabled choice here is explicit.
        switch selection.access {
        case .claudeSubscription, .anthropicAPI, .claudeVertex, .claudeBedrock:
            let supported = ["low", "medium", "high", "xhigh", "max"]
            if preferences.ultracode { return ("xhigh", true) }
            return (supported.contains(requested)
                    ? requested
                    : (Self.preferredDefaultEffort(from: supported) ?? Self.firstUseEffort), false)
        case .openAIAPI:
            let supported = ["none", "minimal", "low", "medium", "high", "xhigh", "max"]
            let normalized = supported.contains(requested)
                ? requested
                : (Self.preferredDefaultEffort(from: supported) ?? Self.firstUseEffort)
            return (normalized, false)
        case .codexSubscription:
            if preferences.ultracode { return ("ultra", false) }
            let modelID = selection.modelID.isEmpty ? (codexDefaultModel ?? "") : selection.modelID
            let resolvedSelection = ModelSelection(access: selection.access, modelID: modelID)
            let catalogEfforts = catalogEntry(for: resolvedSelection)?.supportedEfforts ?? []
            let supported = normalizedEfforts(
                catalogEfforts.isEmpty ? (codexEffortsByModel[modelID] ?? []) : catalogEfforts)
            let normalized: String
            if supported.contains(requested) {
                normalized = requested
            } else {
                normalized = Self.preferredDefaultEffort(from: supported) ?? Self.firstUseEffort
            }
            return (normalized, false)
        }
    }

    /// The sending path, so `ultra` survives here: `ultraTurnConfiguration` reads it out of this
    /// list. Unknown reported levels survive too, which is the point — this filter is what made a
    /// new provider tier unsendable even after the picker could show it.
    private func normalizedEfforts(_ efforts: [String]) -> [String] {
        EffortLevels.ordered(reported: efforts, includingReserved: true)
    }

    static func effortLabel(_ effort: String, access: ModelAccess? = nil) -> String {
        switch effort {
        // Codex's product UI calls its low tier Light; Claude Code and the APIs call it Low.
        case "low" where access == .codexSubscription: return "Light"
        case "xhigh": return "Extra High"
        case "ultra": return "Ultra"
        default: return effort.capitalized
        }
    }

    static func effortDescription(_ effort: String, access: ModelAccess? = nil) -> String {
        switch effort {
        case "none":
            return "No deliberate reasoning; best for direct, deterministic requests."
        case "minimal":
            return "Minimal reasoning for very simple tasks and the fastest turnaround."
        case "low" where access == .codexSubscription:
            return "Light reasoning for routine questions and small edits."
        case "low":
            return "Fast reasoning for routine questions and small edits."
        case "medium":
            return "Balanced speed and depth for everyday work."
        case "high":
            return "More deliberate reasoning for complex, multi-step work."
        case "xhigh":
            return "Deep reasoning for difficult problems and careful implementation."
        case "max":
            return "The strongest standard reasoning level for demanding work."
        case "ultra" where access == .codexSubscription:
            return "Codex’s native Ultra reasoning for the hardest, longest-running tasks."
        case "ultra":
            return "Maximum reasoning with proactive agent orchestration."
        default:
            // Reached only by a level this build does not know. Say that plainly rather than
            // describing it: the list is ordered, so an unexplained row between two familiar ones
            // would imply a position on the cost ladder we have no basis to claim.
            return "Reported by the selected model provider. This version of Mechanician does not "
                 + "know how it compares to the other levels."
        }
    }

    // MARK: Delegated work (workflows / subagents)
    // Surfaced so the UI can show "waiting on a workflow/agent" even after the turn's own streaming
    // ends — the Workflow/Task tools run in the BACKGROUND, so isStreaming/isWorking go false while
    // the delegated work keeps going, which otherwise reads as idle.

    /// How many delegated agents/workflows are in flight — mirrors the Agents tab's count.
    var runningDelegateCount: Int {
        max(
            activeAgents,
            blockingDelegatedAgentCount(
                subagents: subagents,
                workflowRuns: workflowRuns))
    }
    var hasRunningDelegate: Bool { runningDelegateCount > 0 }

    /// Whether the suggested follow-up may be OFFERED right now.
    ///
    /// Separate from whether one exists. The provider authors its suggestion from the root agent's
    /// closing text and the SDK delivers it at that root turn's terminal — but the Workflow and
    /// Agent tools run in the background, so the root turn reaches terminal while the agents it
    /// started keep working. Publishing the record then is right: it is durable, and it belongs to
    /// a real finished answer. Offering it is not, because the same frame is still showing a
    /// running status strip and a Stop button. Ask for the next thing only when nothing is still
    /// doing the last thing.
    var mayPresentSuggestedPrompt: Bool {
        !currentConversationHasPendingUserWork && !hasRunningDelegate
    }
    /// The root turn can finish before its delegated work. Conversation-level Stop therefore stays
    /// available for either source of live work, while Guide/Send Next remain root-turn-only. A
    /// duplicate viewer projects the exact conversation's live owner so its Stop is actionable.
    var hasStoppableConversationWork: Bool {
        guard let conversationID = currentID else { return false }
        return Self.stoppableWorkOwner(of: conversationID, including: self) != nil
    }

    /// Actual executing child agents. Unlike `runningDelegateCount`, this expands workflow trees
    /// and de-duplicates provider children mirrored as both subagents and workflow members.
    var runningAgentCount: Int {
        runningDelegatedAgentCount(subagents: subagents, workflowRuns: workflowRuns)
    }

    /// A live "waiting on…" line for the status surfaces, or nil when nothing is delegated.
    var delegateStatus: String? {
        let runs = workflowRuns.values.filter { !$0.status.isTerminal }
        if let wf = runs.max(by: { $0.startedAt < $1.startedAt }) {
            let name = wf.workflowName ?? "workflow"
            let more = runs.count > 1 ? " (+\(runs.count - 1))" : ""
            if let s = wf.summary, !s.isEmpty { return "Workflow “\(name)”\(more) — \(s)" }
            return "Running workflow “\(name)”\(more)…"
        }
        let subs = subagents.values.filter { !$0.status.isTerminal }
        let n = max(activeAgents, subs.count)
        guard n > 0 else { return nil }
        if let sub = subs.max(by: { $0.startedAt < $1.startedAt }), let s = sub.summary, !s.isEmpty {
            return n > 1 ? "\(n) agents working — \(s)" : "Waiting on a subagent — \(s)"
        }
        return n == 1 ? "Waiting on a subagent…" : "Waiting on \(n) agents…"
    }

    /// Activity identities used only for the inspector reveal policy. The transition from no
    /// delegate to delegated work is the moment one agent becomes multiple agents and should reveal
    /// Agents. Later children and progress belong to that already-visible activity cycle and must
    /// not keep pulling the user away from Files/Changes/Artifacts.
    private func activeDelegateRevealKeys() -> Set<String> {
        var keys = Set<String>()
        for (storageKey, subagent) in subagents where subagent.status == .running {
            keys.insert("sub:\(storageKey)")
        }
        for (runKey, run) in workflowRuns {
            if run.status == .running {
                keys.insert("run:\(runKey)")
            }
            // Providers may terminalize the aggregate before the final child lifecycle update.
            // The Agents UI, pending-work projection, and Stop policy all continue treating that
            // child as live; the reveal policy must use the same truth instead of hiding it behind
            // the aggregate status.
            for (agentKey, agent) in run.agents where agent.state.isRunning {
                keys.insert("child:\(runKey):\(agentKey)")
            }
        }
        return keys
    }

    /// Reveal Agents only on the transition from no delegated work to delegated work.
    /// Keeping this edge in one testable seam prevents metadata-only events and later children in
    /// the same activity cycle from overriding a tab the person chose after the first announcement.
    func revealAgentsInspectorIfNewDelegateAppeared(since previous: Set<String>) {
        guard previous.isEmpty, !activeDelegateRevealKeys().isEmpty else { return }
        revealAgentsInspector()
    }

    /// Fold one provider workflow event into the foreground delegate maps and apply the inspector
    /// announcement edge. Keeping classification, reduction, and reveal together makes the actual
    /// event-ingress path directly testable; timeline attribution and persistence remain owned by
    /// the routed caller around this mutation.
    @discardableResult
    func applyForegroundWorkflowIngress(
        _ update: WorkflowUpdate
    ) -> (subagentsBefore: [String: SubagentRun], runsBefore: [String: WorkflowRun]) {
        var activityBefore = activeDelegateRevealKeys()
        let subagentsBefore = subagents
        let runsBefore = workflowRuns
        // A later event (e.g. the completion notification) can lack the workflow flags, so also
        // match it to an EXISTING run by task/tool id. Otherwise it would be misrouted into the
        // standalone-subagent store (phantom agent + workflow stuck running).
        let matchesRun = workflowRuns[update.taskId] != nil
            || (update.toolUseId.map { workflowRuns[$0] != nil } ?? false)
            || workflowRuns.values.contains {
                $0.runTaskId == update.taskId
                    || (update.toolUseId != nil && $0.toolUseId == update.toolUseId)
            }
        if isWorkflowUpdate(update) || matchesRun {
            workflowRuns = applyWorkflowUpdate(
                workflowRuns,
                update,
                sessionId: currentConversation?.sdkSessionId)
            // Promoting the provisional Task card into its workflow run is one identity transition,
            // not a second delegation. Carry both the announcement edge and any user dismissal
            // across that promotion so a slow workflow update cannot reopen a panel they closed.
            for (runKey, run) in workflowRuns {
                let aggregateIDs = Set([run.toolUseId, run.runTaskId].compactMap { raw in
                    raw?.trimmingCharacters(in: .whitespacesAndNewlines)
                }.filter { !$0.isEmpty })
                let provisionalRevealKeys = Set(subagentsBefore.compactMap {
                    storageKey, subagent -> String? in
                    guard aggregateIDs.contains(storageKey)
                            || aggregateIDs.contains(subagent.key)
                            || subagent.taskId.map(aggregateIDs.contains) == true
                    else { return nil }
                    return "sub:\(storageKey)"
                })
                guard !provisionalRevealKeys.isEmpty else { continue }
                let runRevealKey = "run:\(runKey)"
                activityBefore.insert(runRevealKey)
                if !dismissedDelegateRevealKeys.isDisjoint(with: provisionalRevealKeys) {
                    dismissedDelegateRevealKeys.insert(runRevealKey)
                }
            }
            _ = collapseWorkflowAggregateMirrors(
                workflowRuns: workflowRuns,
                subagents: &subagents,
                agentActivity: &agentActivity)
            activeAgents = subagents.values.filter { !$0.status.isTerminal }.count
        } else {
            subagents = applySubagentUpdate(
                subagents,
                update,
                captureOrdinal: currentID.map { captureOrdinal(for: $0) })
            activeAgents = subagents.values.filter { !$0.status.isTerminal }.count
        }
        revealAgentsInspectorIfNewDelegateAppeared(since: activityBefore)
        // Delegated work exists on this bridge now, so the silence reaper has something to watch.
        // Started here rather than in `init` so a conversation that never delegates never schedules
        // a timer, and stopped again once everything has settled.
        if hasNonterminalDelegatedWork(workflowRuns: workflowRuns, subagents: subagents) {
            ensureSilentDelegateReaper()
        } else {
            stopSilentDelegateReaperIfIdle()
        }
        return (subagentsBefore, runsBefore)
    }

    /// Surface the transition from one agent to multiple agents.
    ///
    /// Two rules keep that one useful interruption from becoming harassment:
    ///  - The transition selects Agents even when the inspector is already open, because the point
    ///    of the announcement is to make newly parallel work visible. Repeated updates and later
    ///    children in the same cycle never call this method again.
    ///  - If they closed it while delegated work was active, that dismissal covers those active
    ///    identities (and overlapping additions). It must not permanently silence the first agent
    ///    of a later, disjoint activity cycle—or a first agent after the panel was closed while idle.
    func revealAgentsInspector() {
        guard visibleInspectorTabs().contains(.agents) else { return }
        let activeKeys = activeDelegateRevealKeys()
        if !showInspector, !dismissedDelegateRevealKeys.isDisjoint(with: activeKeys) {
            // A child that joins while dismissed work is still active belongs to the same visible
            // activity cycle. Include it so the panel does not reopen as soon as the original child
            // finishes while its overlapping sibling keeps running.
            dismissedDelegateRevealKeys.formUnion(activeKeys)
            return
        }
        dismissedDelegateRevealKeys.removeAll()
        inspectorAutoRevealSuppressed = false
        inspectorTab = .agents
        showInspector = true
    }

    /// Non-agent auto-reveals (currently artifacts) retain the broad "closed means closed" policy.
    /// Delegated work uses identity-scoped dismissal instead, because otherwise closing an idle
    /// Inspector disabled the first-agent announcement for the rest of the window's lifetime.
    @Published private(set) var inspectorAutoRevealSuppressed = false
    private var dismissedDelegateRevealKeys = Set<String>()

    /// Call from user-driven inspector toggles only — never from an auto-reveal path, or the flag
    /// would record the app's own decision as the user's.
    func userToggledInspector() {
        showInspector.toggle()
        if showInspector {
            restoreInspectorTabSelection()
            inspectorAutoRevealSuppressed = false
            dismissedDelegateRevealKeys.removeAll()
        } else {
            inspectorAutoRevealSuppressed = true
            dismissedDelegateRevealKeys = activeDelegateRevealKeys()
        }
    }
    /// The toolbar exposes the effective permission for this launch. Keep the person's durable
    /// preference separately so a temporary managed ceiling is an overlay, not a destructive
    /// rewrite of the setting that should return after policy is relaxed or removed.
    private var preferredPermissionMode = "default"
    private var isProjectingPermissionMode = false
    @Published var permissionMode = "default" {
        didSet {
            guard !isProjectingPermissionMode else { return }
            let requested = PermissionPresentation.normalized(permissionMode)
            guard managedEnterprisePolicy?.allowsPermissionMode(requested) ?? true else {
                projectEffectivePermissionMode()
                return
            }
            preferredPermissionMode = requested
            projectEffectivePermissionMode()
            saveSettings()
        }
    }

    var canExitPlanMode: Bool {
        managedEnterprisePolicy?.allowsPermissionMode("default") ?? true
    }

    private func projectEffectivePermissionMode() {
        let effective = managedEnterprisePolicy?.clampedPermissionMode(preferredPermissionMode)
            ?? preferredPermissionMode
        guard permissionMode != effective else { return }
        isProjectingPermissionMode = true
        permissionMode = effective
        isProjectingPermissionMode = false
    }
    /// Anthropic authentication: "apikey" (metered ANTHROPIC_API_KEY) or
    /// "subscription" (the user's Claude Code login). Codex always uses its managed
    /// ChatGPT subscription login; direct OpenAI remains a separate metered API option.
    @Published var authMode = "apikey" {
        didSet {
            guard !isProjectingModelSelection else { return }
            saveSettings()
            ActiveWorkspace.shared.accessDidChange(self)
        }
    }
    /// In subscription mode, whether agentd has a usable subscription login. Reported by
    /// the "ready" event.
    @Published var loggedIn = true
    /// The ChatGPT plan reported by Codex (for example Pro, Plus, or Business). This
    /// is display-only; usage and rate limits continue to be enforced by Codex.
    @Published var codexPlanType: String?
    /// OAuth login in progress (browser flow open, awaiting approval).
    @Published var isLoggingIn = false
    /// Last login failure, shown on the auth screen.
    @Published var loginError: String?

    /// The active route cannot serve a real turn. This catches both a disconnected subscription and
    /// an API route with no key so a clean install never falls through to the mock daemon unnoticed.
    var needsProviderSetup: Bool {
        needsProviderSetup(for: currentModelAccess)
    }

    private func needsProviderSetup(for access: ModelAccess) -> Bool {
        if ProviderAccountStore.shared.requiresReconnect(access) { return true }
        guard let state = laneStates[access], state.ready else { return false }
        switch access {
        case .claudeSubscription, .codexSubscription, .claudeVertex: return !state.loggedIn
        // Bedrock resolves the ordinary AWS chain in the daemon, so "ready" is the whole signal.
        case .anthropicAPI, .openAIAPI, .claudeBedrock: return state.mode != "sdk"
        }
    }

    var currentModelAccess: ModelAccess { ModelAccess(provider: provider, authMode: authMode) }
    var hasUsableActiveAccount: Bool { isReady && !needsProviderSetup }

    /// Whether the composer may accept a submission.
    ///
    /// Deliberately NOT `hasUsableActiveAccount`. Two different facts wore that one name and only
    /// one of them should gate a keystroke. A lane still starting up is not a reason to swallow
    /// Return: `send()` queues the prompt and says so in the transcript. A lane that needs setup IS
    /// a reason, because otherwise prompts pile up against a lane that can never start while the
    /// Connect banner sits above them. `needsProviderSetup(for:)` returns false for a lane that is
    /// not ready yet, so this is exactly the setup question and not the readiness one (FR-219).
    var composerAcceptsSubmission: Bool { !needsProviderSetup }

    private func isRuntimeReady(_ access: ModelAccess) -> Bool {
        laneStates[access]?.ready == true && runtimes[access]?.isRunning == true
    }

    /// An established turn can still accept an interaction while its lane is busy and therefore
    /// not "ready" to start another turn. Starting and steering are distinct capabilities.
    private func isRuntimeRunning(_ access: ModelAccess) -> Bool {
        runtimes[access]?.isRunning == true
    }

    private func isRuntimeUsable(_ access: ModelAccess) -> Bool {
        isRuntimeReady(access)
            && !needsProviderSetup(for: access)
            && ProviderAccountStore.shared.operation(for: access) == nil
    }

    /// The existing views still observe scalar account fields. Keep them as a projection of the
    /// selected lane while the pool owns authoritative state for every background provider.
    private func projectLaneState(_ access: ModelAccess) {
        let state = laneStates[access] ?? RuntimeLaneState()
        isReady = state.ready && runtimes[access]?.isRunning == true
        mode = state.mode
        loggedIn = state.loggedIn
        codexPlanType = state.codexPlanType
        isLoggingIn = state.isLoggingIn
        loginError = state.loginError
        allowedTools = state.allowedTools
        slashCommands = state.slashCommands
        measuredContextWindows = state.measuredContextWindows
    }

    /// A persisted provider failure may be retried only by the same ready runtime and conversation
    /// route that produced it. Until runtimes are pooled, never switch providers implicitly just
    /// because an old error card's Retry button was pressed.
    func canRetryProviderFailure(_ failure: ProviderFailure, now: Date = Date()) -> Bool {
        // A throttled failure is retryable only once the reset the provider named has arrived.
        // Offering the button before then would be the very thing the old blanket refusal was
        // guarding against, and the instant is the provider's own, not an estimate of ours.
        if let availableAt = failure.retryAvailableAt, now < availableAt { return false }
        return failure.allowsRetry
            && !isStreaming
            && isRuntimeReady(failure.access)
            && !needsProviderSetup(for: failure.access)
            && currentConversation?.modelSelection?.access == failure.access
    }

    private func reportCurrentAccountState() {
        reportAccountState(for: currentModelAccess)
    }

    private func reportAccountState(
        for access: ModelAccess,
        previousRuntimeState: RuntimeLaneState? = nil,
        accountStatus: String? = nil,
        authenticationRejectionMessage: String? = nil
    ) {
        let state = laneStates[access] ?? RuntimeLaneState()
        switch access {
        case .claudeSubscription:
            ProviderAccountStore.shared.report(access: access, connected: state.loggedIn,
                                               detail: state.loggedIn ? "Claude subscription" : nil)
        case .claudeVertex:
            let rejection = ProviderAccountStore.shared.reportRuntimeAccountState(
                access: access,
                connected: state.loggedIn,
                detail: state.loggedIn ? "Claude (Vertex)" : nil,
                previousRuntimeReady: previousRuntimeState?.ready ?? false,
                previousRuntimeLoggedIn: previousRuntimeState?.loggedIn ?? false,
                accountStatus: accountStatus,
                authenticationRejectionMessage: authenticationRejectionMessage)
            if let rejection {
                updateLaneState(access) { $0.loginError = rejection }
            }
        case .claudeBedrock:
            ProviderAccountStore.shared.report(
                access: access, connected: state.loggedIn,
                detail: state.loggedIn ? "AWS credentials found" : nil)
        case .codexSubscription:
            let detail = state.codexPlanType.flatMap { $0.isEmpty ? nil : "ChatGPT \($0.capitalized)" }
            ProviderAccountStore.shared.report(access: access, connected: state.loggedIn, detail: detail)
        case .anthropicAPI, .openAIAPI:
            ProviderAccountStore.shared.reportConfigured(access: access, configured: state.mode == "sdk")
        }
    }

    /// Decode the same provider-neutral failure used by terminal turn cards. Only definitive
    /// Vertex Google reauthentication crosses into lane state; missing first-time credentials and
    /// transient verification failures retain their ordinary Connect/deferred semantics.
    static func runtimeAuthenticationRejectionMessage(
        from readyEvent: [String: Any],
        access: ModelAccess
    ) -> String? {
        guard access == .claudeVertex,
              readyEvent["loggedIn"] as? Bool == false,
              (readyEvent["accountStatus"] as? String)?.lowercased() == "disconnected",
              let event = readyEvent["accountFailure"] as? [String: Any],
              let failure = ProviderFailure.from(event: event, authoritativeAccess: access),
              failure.kind == .authentication,
              failure.requiresGoogleReauthentication else { return nil }
        return failure.userFacingMessage
    }

    /// A permanently rejected refresh token is a process-wide account boundary, not merely one
    /// failed turn. Stop every window from dispatching more work on that lane, preserve their
    /// queues, and keep the provider-owned credential intact for the explicit Reconnect flow.
    @discardableResult
    private static func requireAccountReconnect(for failure: ProviderFailure) -> Bool {
        guard failure.requiresReconnect else { return false }
        let access = failure.access
        for bridge in live.allObjects {
            bridge.updateLaneState(access) { state in
                state.loggedIn = false
                state.isLoggingIn = false
                state.loginError = failure.userFacingMessage
            }
            bridge.agentToolCatalog.invalidate(access: access)
        }
        if access == .codexSubscription { clearCodexCatalogs() }
        ProviderCapabilityStore.shared.invalidate(access: access)
        ProviderAccountStore.shared.reportAuthenticationRejected(
            access: access, message: failure.userFacingMessage)
        return true
    }

    private static func reportBlockedQueuedWorkProcessWide(for access: ModelAccess) {
        for bridge in live.allObjects { bridge.reportBlockedQueuedWorkIfNeeded(for: access) }
    }
    @Published var allowedTools: [String] = []
    // Available skills / slash-commands for this provider lane (drives the skill picker). Claude
    // reports its command catalog; Codex's daemon requests App Server's enabled, cwd-scoped skills.
    @Published var slashCommands: [SlashCommandInfo] = []
    /// Context windows the CURRENT route was measured to serve, by lowercased resolved model id.
    /// Empty until a turn completes on this route, which is the honest state: nothing has checked.
    @Published var measuredContextWindows: [String: Int] = [:]
    /// The skill armed for the NEXT message, from the inspector's Skills tab.
    ///
    /// Ours, not a protocol feature — neither SDK has a notion of "attach for the next turn", so
    /// this is prompt construction: on submit the message uses the provider-native invocation
    /// (`/name` for Claude, `$name` for Codex). Modelled on the file and image attachment pills,
    /// because it behaves the same way: visible, removable, one-shot.
    @Published var armedSkill: SlashCommandInfo?
    @Published var usageIn = 0
    @Published var usageOut = 0
    // Current context-window fill reported for the latest turn — distinct from the cumulative
    // input/output token totals. Codex reports both this and its real denominator at runtime.
    @Published var contextTokens = 0
    @Published private(set) var reportedContextWindow: Int?
    /// The fill at which the provider will compact, when it reports one. Normally well below the
    /// window: a 1M-window conversation was observed compacting 85 times without ever exceeding
    /// 52% of that window, because this is the number that governs and the meter showed the other.
    @Published private(set) var reportedCompactionThreshold: Int?
    @Published private(set) var contextUsageModel: String?
    /// The active model's context-window size. Prefer a provider-reported denominator. Claude's
    /// catalog uses aliases such as `default` and `opus[1m]`, so its fallback must resolve the
    /// catalog identity rather than comparing only one historical bare model id.
    /// The fill the meter should measure against: the point where the provider will compact, when
    /// it reports one, and otherwise the window itself.
    ///
    /// These are different numbers and the difference is the whole complaint. A conversation on a
    /// 1,000,000-token window compacted 85 times without ever exceeding 516,178 tokens, because
    /// compaction answers to the threshold and the meter was showing the maximum. Ignored when it
    /// is not below the window, since then it explains nothing the window does not already.
    var contextCompactionThreshold: Int? {
        Self.compactionThreshold(reported: reportedCompactionThreshold, window: contextWindowMax)
    }

    /// The rule, with both inputs explicit so it can be tested without a live bridge.
    nonisolated static func compactionThreshold(reported: Int?, window: Int?) -> Int? {
        guard let reported, reported > 0, let window, window > 0, reported < window else {
            return nil
        }
        return reported
    }

    var contextWindowMax: Int? {
        let use1M = (UserDefaults.standard.object(forKey: "use1MContext") as? Bool) ?? true
        if provider == "codex" {
            guard contextUsageModel == model else { return nil }
            return reportedContextWindow
        }
        if provider == "openai" {
            if model == "gpt-5.6" || model == "gpt-5.5" || model == "gpt-5.4" || model == "gpt-5.4-pro" { return 1_050_000 }
            return 400_000
        }
        let resolvedModelID = catalogEntry(for: currentModelSelection)?.resolvedModelID
        if let reportedContextWindow, reportedContextWindow > 0 {
            let identities = [model, resolvedModelID]
                .compactMap { $0?.lowercased() }
            if contextUsageModel == nil
                || identities.contains(contextUsageModel?.lowercased() ?? "") {
                return reportedContextWindow
            }
        }
        // A third-party route serves a different window for the same model name, so it decides both
        // whether the bare-Opus upgrade applies and whether a native-1M model is actually 1M here.
        let thirdParty = ProviderFacts.thirdPartyRoutes.contains(
            currentModelAccess.daemonAuthMode)
        // A measurement from a completed turn on this route beats the derivation. The live
        // `reportedContextWindow` above is still preferred over both: it describes THIS session.
        return Self.claudeContextWindow(
            selectedModelID: model,
            resolvedModelID: resolvedModelID,
            use1M: use1M,
            automaticallyUpgradesBareOpus: !thirdParty,
            thirdPartyRoute: thirdParty,
            measured: measuredContextWindows).window
    }

    nonisolated static func anthropicContextWindow(
        selectedModelID: String,
        resolvedModelID: String?,
        use1M: Bool,
        automaticallyUpgradesBareOpus: Bool,
        thirdPartyRoute: Bool = false
    ) -> Int {
        let selected = selectedModelID.lowercased()
        if let resolved = resolvedModelID?.lowercased(), !resolved.isEmpty {
            return millionTokenClaudeModel(resolved, thirdPartyRoute: thirdPartyRoute)
                ? 1_000_000 : 200_000
        }
        if millionTokenClaudeModel(selected, thirdPartyRoute: thirdPartyRoute) {
            return 1_000_000
        }
        if use1M,
           automaticallyUpgradesBareOpus,
           ProviderFacts.millionTokenSuffixUpgrades.contains(selected) {
            return 1_000_000
        }
        return 200_000
    }

    /// Mirrors `effectiveClaudeContextWindow` in agentd/src/claude-turn-options.mjs. Keep in sync.
    ///
    /// The `[1m]` check comes first on purpose and is route-independent. An id only names the
    /// variant outright because something authoritative produced it, including a managed tenant
    /// profile declaring the variant that project was granted. Measured on 2026-08-13: a
    /// profile-declared `claude-opus-4-8[1m]` served a confirmed 1M window on Vertex. The
    /// third-party lists below govern BARE ids; applying them to a named variant would cut a real
    /// 1M window to 200K.
    private nonisolated static func millionTokenClaudeModel(
        _ modelID: String,
        thirdPartyRoute: Bool
    ) -> Bool {
        if modelID.contains("[1m]") { return true }
        guard defaultMillionTokenClaudeModel(modelID) else { return false }
        return thirdPartyRoute ? thirdPartyMillionTokenClaudeModel(modelID) : true
    }

    /// Take the daemon's measured-window snapshot for one route.
    ///
    /// Whole-map replacement, not a merge. The daemon's file is the authority for what it measured,
    /// and it evicts stale and aged-out entries; merging here would resurrect a measurement the
    /// daemon deliberately dropped because the served window changed. An empty or absent map is a
    /// legitimate state (a route that has completed no turns yet) and simply means every window
    /// falls back to the static answer.
    private func applyMeasuredContextWindows(_ event: [String: Any], for access: ModelAccess) {
        guard let raw = event["windows"] as? [String: Any] else { return }
        var measured: [String: Int] = [:]
        for (modelID, value) in raw {
            let id = modelID.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            // Only a positive Int is a window. Anything else means the wire shape changed, and a
            // wrong window is worse than no window in both directions.
            guard !id.isEmpty, let window = value as? Int, window > 0 else { continue }
            measured[id] = window
        }
        updateLaneState(access) { $0.measuredContextWindows = measured }
    }

    /// What a model change is about to cost this conversation, when the answer is "a lot".
    struct ContextDownshiftWarning: Equatable {
        var modelName: String
        var currentWindow: Int
        var newWindow: Int
        var contextTokens: Int
    }

    /// Above this share of the NEW window, the conversation starts compacting more or less
    /// immediately after the change. Below it the switch is unremarkable and must stay silent: a
    /// dialog on every model change would train the user to dismiss the one that matters.
    ///
    /// `nonisolated` because the rule that reads it is nonisolated: it is a constant threshold, not
    /// actor state, and leaving it main-actor-isolated is an error in the Swift 6 language mode.
    nonisolated static let contextDownshiftWarningFill = 0.75

    /// Whether changing to `selection` should be confirmed first.
    ///
    /// Every explicit model change already retires the provider session and replays only a small
    /// bounded excerpt, so some context is always left behind. That alone is not worth a dialog.
    /// What is worth one is the case this was built for: a conversation sized for a large window
    /// moving to a much smaller one, where the loss is not a one-time trim but a lane that will
    /// compact repeatedly from here on. In the incident that prompted this, an image-heavy
    /// conversation moved from a 1M lane to a 200K lane and then auto-compacted ten times at two to
    /// four minutes each, and nothing in the product said the window had changed at all.
    ///
    /// Returns nil whenever we cannot state the numbers honestly, which includes a non-Anthropic
    /// route and an unknown current window. A warning built on a guess would be worse than silence.
    func contextDownshiftWarning(for selection: ModelSelection) -> ContextDownshiftWarning? {
        guard selection != currentModelSelection,
              selection.access.maker == .anthropic,
              currentModelAccess.maker == .anthropic,
              let currentWindow = contextWindowMax else { return nil }
        let thirdParty = ProviderFacts.thirdPartyRoutes.contains(selection.access.daemonAuthMode)
        let next = Self.claudeContextWindow(
            selectedModelID: selection.modelID,
            resolvedModelID: catalogEntry(for: selection)?.resolvedModelID,
            use1M: (UserDefaults.standard.object(forKey: "use1MContext") as? Bool) ?? true,
            automaticallyUpgradesBareOpus: !thirdParty,
            thirdPartyRoute: thirdParty,
            measured: measuredContextWindows(for: selection.access))
        return Self.contextDownshiftWarning(
            modelName: catalogEntry(for: selection)?.versionedDisplayName ?? selection.modelID,
            currentWindow: currentWindow,
            newWindow: next.window,
            contextTokens: contextTokens)
    }

    /// The rule itself, separated from gathering the state it needs so it can be exercised directly.
    nonisolated static func contextDownshiftWarning(
        modelName: String,
        currentWindow: Int,
        newWindow: Int,
        contextTokens: Int
    ) -> ContextDownshiftWarning? {
        guard currentWindow > 0, newWindow > 0, contextTokens > 0 else { return nil }
        // Not a downshift. Moving to an equal or larger window costs nothing worth interrupting for,
        // even though the session is retired either way.
        guard newWindow < currentWindow else { return nil }
        // Small enough to re-establish without noticing. Warning here would be the noise that makes
        // the real warning ignorable.
        guard Double(contextTokens) > Double(newWindow) * contextDownshiftWarningFill else {
            return nil
        }
        return ContextDownshiftWarning(
            modelName: modelName,
            currentWindow: currentWindow,
            newWindow: newWindow,
            contextTokens: contextTokens)
    }

    /// A token count in the compact form the context meter, the picker and the downshift warning all
    /// use. One implementation so "1.0M" in the meter and "1.0M" in the picker cannot drift apart.
    nonisolated static func formattedTokenCount(_ count: Int) -> String {
        if count >= 1_000_000 { return String(format: "%.1fM", Double(count) / 1_000_000) }
        if count >= 1_000 { return String(format: "%.1fK", Double(count) / 1_000) }
        return "\(count)"
    }

    /// Measured windows for ANY route, not just the selected one. The picker lists every configured
    /// account at once, so a row must be able to report its own route's measurement rather than the
    /// one that happens to be current.
    func measuredContextWindows(for access: ModelAccess) -> [String: Int] {
        laneStates[access]?.measuredContextWindows ?? [:]
    }

    /// The window to show for one catalog entry, and whether it has actually been observed.
    ///
    /// Anthropic only. The window rules here are Claude's, and Codex reports its own denominator
    /// through a different path, so claiming a number for a non-Anthropic row would be inventing
    /// one. Returns nil when there is nothing honest to say.
    func claudeContextWindow(for entry: ModelCatalogEntry) -> (window: Int, isMeasured: Bool)? {
        guard entry.selection.access.maker == .anthropic else { return nil }
        let thirdParty = ProviderFacts.thirdPartyRoutes.contains(
            entry.selection.access.daemonAuthMode)
        return Self.claudeContextWindow(
            selectedModelID: entry.selection.modelID,
            resolvedModelID: entry.resolvedModelID,
            use1M: (UserDefaults.standard.object(forKey: "use1MContext") as? Bool) ?? true,
            automaticallyUpgradesBareOpus: !thirdParty,
            thirdPartyRoute: thirdParty,
            measured: measuredContextWindows(for: entry.selection.access))
    }

    /// What this route was measured to serve for a resolved model id, or nil when it never has.
    nonisolated static func measuredContextWindow(
        for modelID: String?,
        in measured: [String: Int]
    ) -> Int? {
        guard let modelID, !measured.isEmpty else { return nil }
        let id = modelID.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard let window = measured[id], window > 0 else { return nil }
        return window
    }

    /// The window to show for a model, and whether anyone has actually checked.
    ///
    /// Mirrors `claudeContextWindowDecision` in agentd/src/claude-turn-options.mjs. The two callers
    /// that matter are user-facing: a picker row and a downshift warning. Both are claims about the
    /// user's own deployment, so they must not present a derivation as a fact. A managed tenant can
    /// declare a model whose real window this build has no static knowledge of, which is exactly the
    /// Vertex case that made the difference between a working 1M lane and a guess.
    nonisolated static func claudeContextWindow(
        selectedModelID: String,
        resolvedModelID: String?,
        use1M: Bool,
        automaticallyUpgradesBareOpus: Bool,
        thirdPartyRoute: Bool,
        measured: [String: Int]
    ) -> (window: Int, isMeasured: Bool) {
        // The resolved id is what the provider reported usage for, so it is the join key. Fall back
        // to the selected id for a lane that never resolves (the ids are equal there).
        if let window = measuredContextWindow(for: resolvedModelID, in: measured)
            ?? measuredContextWindow(for: selectedModelID, in: measured) {
            return (window, true)
        }
        return (anthropicContextWindow(
            selectedModelID: selectedModelID,
            resolvedModelID: resolvedModelID,
            use1M: use1M,
            automaticallyUpgradesBareOpus: automaticallyUpgradesBareOpus,
            thirdPartyRoute: thirdPartyRoute), false)
    }

    /// Third-party catalogs qualify the model id (Bedrock inference profiles, Vertex publisher
    /// paths). Strip the qualifier so a route-shaped id compares as the same canonical name.
    nonisolated static func canonicalClaudeModelID(_ modelID: String) -> String {
        let base = modelID.split(separator: "[", maxSplits: 1).first.map(String.init) ?? modelID
        for prefix in ProviderFacts.thirdPartyModelIDPrefixes where base.hasPrefix(prefix) {
            return String(base.dropFirst(prefix.count))
        }
        return base
    }

    private nonisolated static func defaultMillionTokenClaudeModel(_ modelID: String) -> Bool {
        ProviderFacts.nativeMillionTokenModels.contains(canonicalClaudeModelID(modelID))
    }

    /// The models whose BARE id the pinned engine serves at 1M on Vertex, Bedrock or Foundry. Those
    /// routes gate a bare id's 1M window behind `context.native_1m_3p[route]`; the membership and
    /// the reasoning live in shared/provider-facts.json, which the daemon reads too, so the two can
    /// no longer disagree. This says nothing about an explicitly named `[1m]` variant, which those
    /// routes can and do serve when a project is entitled to it.
    private nonisolated static func thirdPartyMillionTokenClaudeModel(_ modelID: String) -> Bool {
        ProviderFacts.thirdPartyMillionTokenModels.contains(canonicalClaudeModelID(modelID))
    }
    @Published var expandedTools: Set<UUID> = [] // tool cards expanded in the transcript
    // Live cache for images tools produced, keyed by tool-entry id.
    // Durable bytes live in ConversationStore's per-conversation media directory; this cache is
    // cleared on switch so historical images load only when their Activity action is opened.
    @Published var toolImages: [UUID: NSImage] = [:]

    func persistedToolImageURL(for entry: TranscriptEntry) -> URL? {
        guard let conversationID = currentID, let reference = entry.toolImage else { return nil }
        return store.toolImageURL(conversationID: conversationID, reference: reference)
    }

    private struct GeneratedToolImage {
        let data: Data
        let image: NSImage
        let width: Int
        let height: Int
    }

    private static let maximumGeneratedToolImageBytes = 32 * 1024 * 1024
    private static let maximumGeneratedToolImagePixels = 64 * 1024 * 1024
    private static let generatedImageHandoffPrefix = "mechanician-generated-image-"

    /// Consume a daemon-owned one-shot image handoff before route and generation checks. The
    /// provider path never crosses this boundary: only a regular file at the exact random name in
    /// the process temporary directory is admitted, and every admitted handoff is deleted.
    static func resolvingGeneratedImageHandoff(_ event: [String: Any]) -> [String: Any] {
        var resolved = event
        let handoffPath = event["generatedImagePath"] as? String
        let expectedBytes = event["generatedImageBytes"] as? Int
        resolved["generatedImagePath"] = nil
        resolved["generatedImageBytes"] = nil
        guard let handoffPath, !handoffPath.isEmpty,
              let expectedBytes, expectedBytes > 0,
              expectedBytes <= maximumGeneratedToolImageBytes
        else { return generatedImageHandoffFailure(resolved) }

        let url = URL(fileURLWithPath: handoffPath).standardizedFileURL
        let temporaryDirectory = URL(
            fileURLWithPath: NSTemporaryDirectory(), isDirectory: true).standardizedFileURL
        let fileName = url.lastPathComponent
        let stem = String(fileName.dropFirst(generatedImageHandoffPrefix.count).dropLast(6))
        guard url.deletingLastPathComponent() == temporaryDirectory,
              fileName.hasPrefix(generatedImageHandoffPrefix),
              fileName.hasSuffix(".image"),
              UUID(uuidString: stem) != nil
        else { return generatedImageHandoffFailure(resolved) }

        defer { try? FileManager.default.removeItem(at: url) }
        guard let attributes = try? FileManager.default.attributesOfItem(atPath: url.path),
              attributes[.type] as? FileAttributeType == .typeRegular,
              let size = (attributes[.size] as? NSNumber)?.intValue,
              size == expectedBytes,
              size <= maximumGeneratedToolImageBytes,
              let data = try? Data(contentsOf: url, options: .mappedIfSafe),
              data.count == size
        else { return generatedImageHandoffFailure(resolved) }
        resolved["generatedImageData"] = data
        return resolved
    }

    private static func generatedImageHandoffFailure(_ event: [String: Any]) -> [String: Any] {
        var failed = event
        if failed["status"] as? String == "success" {
            failed["status"] = "error"
            failed["result"] = "Image generation completed, but Mechanician could not read the generated image."
        }
        return failed
    }

    /// Re-encode every accepted provider image as PNG: ToolImageReference intentionally names only
    /// UUID.png media, while Codex's App Server does not promise a particular source encoding.
    private static func generatedToolImage(from event: [String: Any]) -> GeneratedToolImage? {
        guard let source = event["generatedImageData"] as? Data,
              !source.isEmpty,
              source.count <= maximumGeneratedToolImageBytes,
              let image = NSImage(data: source),
              let tiff = image.tiffRepresentation,
              let bitmap = NSBitmapImageRep(data: tiff)
        else { return nil }
        let width = bitmap.pixelsWide
        let height = bitmap.pixelsHigh
        guard width > 0, height > 0,
              width <= 16_384, height <= 16_384,
              width <= maximumGeneratedToolImagePixels / height,
              let png = bitmap.representation(using: .png, properties: [:]),
              !png.isEmpty,
              png.count <= maximumGeneratedToolImageBytes
        else { return nil }
        return GeneratedToolImage(data: png, image: image, width: width, height: height)
    }

    /// Persist terminal Codex image output onto its stable tool row. Completion can race a switch,
    /// so a current transcript is saved immediately while a background row is updated durably.
    private func persistGeneratedToolImage(
        _ image: GeneratedToolImage,
        conversationID: UUID,
        entryID: UUID
    ) {
        Task { @MainActor [weak self] in
            guard let self else { return }
            let reference = await self.store.persistToolImage(
                image.data,
                conversationID: conversationID,
                entryID: entryID,
                width: image.width,
                height: image.height)
            guard let reference else { return }
            if self.currentID == conversationID,
               let index = self.entries.firstIndex(where: { $0.id == entryID }) {
                self.toolImages[entryID] = image.image
                self.entries[index].toolImage = reference
                self.currentConversationNeedsPersistence = true
                self.expandedTools.insert(entryID)
                self.persistCurrent()
            } else {
                self.store.update(conversationID) { conversation in
                    guard let index = conversation.messages.firstIndex(where: {
                        $0.id == entryID
                    }) else { return }
                    conversation.messages[index].toolImage = reference
                }
            }
        }
    }

    /// Tool results are presented inline only through this many characters.
    static let toolResultPreviewCharacters = 6_000

    /// Whether the visible tool-result preview looks like a unified diff (auto-expanded + colored).
    /// Bound classification to the text the card can actually show: scanning a multi-megabyte
    /// non-diff result on the main actor delayed the first paint even though everything after this
    /// prefix was immediately truncated.
    static func looksLikeDiff(_ s: String?) -> Bool {
        guard let s else { return false }
        let limit = toolResultPreviewCharacters
        let visible: String
        if let end = s.index(s.startIndex, offsetBy: limit, limitedBy: s.endIndex),
           end != s.endIndex {
            visible = String(s[..<end])
        } else {
            visible = s
        }
        if visible.contains("diff --git") { return true }
        return visible.range(of: "(?m)^@@ ", options: .regularExpression) != nil
    }

    /// Every live bridge (one per open workspace window/tab), weakly held. The quit guard
    /// (AppDelegate.applicationShouldTerminate) scans these for in-flight turns or queued
    /// prompts across ALL windows, since each window owns its own bridge.
    static let live = NSHashTable<AgentBridge>.weakObjects()

    /// Stable identity for this bridge. Every window runs its OWN agentd per lane, so anything
    /// keyed on the lane alone (background-process reports, and the kill that must reach the daemon
    /// actually tracking a pid) would have two windows overwriting each other.
    let bridgeID = UUID()

    /// Exact live tool evidence belongs to this window's daemon pool. Never share it through a
    /// process-global last-writer catalog: two windows may run the same lane with different
    /// conversations, profiles, extension schemas, accounts, and runtime generations.
    let agentToolCatalog = AgentToolCatalog()

    /// This bridge's window, set on becomeKey (see KeyWindowClaim). Used to bring the window that
    /// already owns a conversation to the front — a conversation is live in exactly ONE window.
    weak var window: NSWindow?

    /// The live bridge with acknowledged or provisional provider work for a conversation. A pending
    /// start already owns its hidden queue reservation, so another window must treat it exactly like
    /// an acknowledged turn or it can later persist stale queue state over the restored prompt.
    static func activeOwner(of id: UUID, excluding: AgentBridge? = nil) -> AgentBridge? {
        let others = live.allObjects.filter { $0 !== excluding && $0.window != nil }
        return others.first {
            $0.runningConvs.contains(id) || $0.pendingTurnStartID(for: id) != nil
        }
    }

    /// The live bridge that already "owns" a conversation — the one with provider work, or, failing
    /// that, the one currently viewing it — so explicit open-in-window actions avoid stale duplicates.
    /// Only considers windows we can focus.
    static func owner(of id: UUID, excluding: AgentBridge? = nil) -> AgentBridge? {
        activeOwner(of: id, excluding: excluding)
            ?? live.allObjects.first {
                $0 !== excluding && $0.window != nil
                    && ($0.currentID == id || $0.pendingSelectionID == id)
            }
    }

    /// File promises can finish after their composer navigates away. Keep the original record
    /// resident until its durable pending marker is either replaced or cancelled; otherwise the
    /// completion would see a cache miss and discard bytes that were imported successfully.
    private static var promisedAttachmentResidencyCounts: [UUID: Int] = [:]

    static func retainPromisedAttachmentConversation(_ id: UUID) {
        promisedAttachmentResidencyCounts[id, default: 0] += 1
    }

    static func releasePromisedAttachmentConversation(_ id: UUID) {
        let remaining = (promisedAttachmentResidencyCounts[id] ?? 1) - 1
        if remaining > 0 {
            promisedAttachmentResidencyCounts[id] = remaining
        } else {
            promisedAttachmentResidencyCounts[id] = nil
        }
        ConversationStore.shared.trimResidencyIfNeeded()
    }

    /// Full-record residency is required while any bridge views, is loading, or owns provider work
    /// for the conversation. Wait-mode ownership is process-global and equally non-evictable.
    static func requiresResidentConversation(_ id: UUID) -> Bool {
        live.allObjects.contains {
            $0.currentID == id
                || $0.pendingSelectionID == id
                || $0.runningConvs.contains(id)
                || $0.pendingTurnStartID(for: id) != nil
                || $0.turnRoutes.values.contains {
                    $0.conversationID == id && $0.phase.reservesConversation
                }
        }
            || ActiveWorkspace.shared.runningConversations.contains(id)
            || ActiveWorkspace.shared.waitingConversations.contains(id)
            || promisedAttachmentResidencyCounts[id] != nil
    }

    /// The process-local controller that owns the exact conversation root which can be stopped.
    ///
    /// Duplicate viewers may carry stale published state, and `runningConvs` is only a projection.
    /// Root Stop therefore forwards only to a bridge with a matching conversation-purpose route:
    /// an acknowledged active route wins over a provisional start, then UUID makes an impossible
    /// duplicate-owner race deterministic. Delegate-only evidence is intentionally excluded.
    private static func rootWorkOwner(
        of conversationID: UUID,
        including requester: AgentBridge? = nil
    ) -> AgentBridge? {
        var candidates = live.allObjects
        if let requester, !candidates.contains(where: { $0 === requester }) {
            candidates.append(requester)
        }
        return candidates.compactMap { bridge -> (AgentBridge, Int)? in
            bridge.rootWorkOwnershipRank(for: conversationID).map { (bridge, $0) }
        }
        .sorted {
            if $0.1 != $1.1 { return $0.1 < $1.1 }
            return $0.0.bridgeID.uuidString < $1.0.bridgeID.uuidString
        }
        .first?
        .0
    }

    private func rootWorkOwnershipRank(for conversationID: UUID) -> Int? {
        if turnRoutes.values.contains(where: {
            $0.conversationID == conversationID
                && $0.purpose == .conversation
                && $0.phase.isActive
        }) {
            return 0
        }
        let ownsPendingRoot = pendingTurnStarts.contains { turnID, pending in
            guard pending.route.conversationID == conversationID,
                  pending.route.purpose == .conversation,
                  let route = turnRoutes[turnID],
                  route.conversationID == conversationID,
                  route.purpose == .conversation,
                  case .starting = route.phase
            else { return false }
            return routesMatch(route, pending.route)
        }
        return ownsPendingRoot ? 1 : nil
    }

    /// The process-local controller that can actually stop work for one exact conversation.
    ///
    /// A conversation can be visible in a stale duplicate viewer even though its provider route
    /// and freshest delegate graph belong to another bridge. Prefer an active root reservation,
    /// then the bridge retaining that conversation's route tombstone, then local live delegate
    /// evidence. The UUID tie-break keeps an ambiguous legacy duplicate deterministic.
    private static func stoppableWorkOwner(
        of conversationID: UUID,
        including requester: AgentBridge? = nil
    ) -> AgentBridge? {
        var candidates = live.allObjects
        if let requester, !candidates.contains(where: { $0 === requester }) {
            candidates.append(requester)
        }
        return candidates.compactMap { bridge -> (AgentBridge, Int)? in
            bridge.stoppableOwnershipRank(for: conversationID).map { (bridge, $0) }
        }
        .sorted {
            if $0.1 != $1.1 { return $0.1 < $1.1 }
            return $0.0.bridgeID.uuidString < $1.0.bridgeID.uuidString
        }
        .first?
        .0
    }

    /// Workspace reassignment must use the same definition of "active work" as Stop and the quit
    /// guard. A root route can finish while one of its delegates remains live, so checking only
    /// `runningConvs` would allow the conversation's cwd to change underneath that child.
    static func hasBlockingWorkspaceMoveWork(for conversationID: UUID) -> Bool {
        stoppableWorkOwner(of: conversationID) != nil
    }

    private func stoppableOwnershipRank(for conversationID: UUID) -> Int? {
        let hasReservation = runningConvs.contains(conversationID)
            || pendingTurnStartID(for: conversationID) != nil
            || turnRoutes.values.contains {
                $0.conversationID == conversationID && $0.phase.reservesConversation
            }
        // The ranker can return a value without delegated work only for an active reservation.
        // Take that exact result before reading the durable graph or scanning the retained activity
        // ledger. This path is queried while composing; background publications in another window
        // must not make an idle editor walk thousands of unrelated activity records.
        if hasReservation { return 0 }
        let storedDelegateCount = store.conversation(conversationID).map {
            blockingDelegatedAgentCount(
                subagents: $0.subagents,
                workflowRuns: $0.workflowRuns)
        } ?? 0
        let delegatedCount = max(
            blockingDelegateCount(for: conversationID),
            storedDelegateCount)
        guard delegatedCount > 0 else { return nil }
        let retainedTurnIDs = Set(turnRoutes.compactMap {
            $0.value.conversationID == conversationID ? $0.key : nil
        })
        let exactDelegateOwners = delegateOwnerTurnIDs(
            for: conversationID,
            includeConservativeFallback: false)
        let conservativeDelegateOwners = delegateOwnerTurnIDs(for: conversationID)
        return stoppableWorkOwnershipRank(
            hasReservation: false,
            retainedTurnIDs: retainedTurnIDs,
            exactDelegateOwnerTurnIDs: exactDelegateOwners,
            conservativeDelegateOwnerTurnIDs: conservativeDelegateOwners,
            hasActiveAgentProjection:
                currentID == conversationID && activeAgents > 0,
            hasDelegatedWork: delegatedCount > 0,
            isCurrentViewer:
                currentID == conversationID && storedDelegateCount > 0)
    }

    /// Fresh local state wins for the on-screen conversation; background conversations use their
    /// durable graph. `activeAgents` covers the short interval before provider child identities
    /// arrive and is a maximum, never an additive count that could duplicate mirrored rows.
    private func blockingDelegateCount(for conversationID: UUID) -> Int {
        if currentID == conversationID {
            return max(
                activeAgents,
                blockingDelegatedAgentCount(
                    subagents: subagents,
                    workflowRuns: workflowRuns))
        }
        guard let conversation = store.conversation(conversationID) else { return 0 }
        return blockingDelegatedAgentCount(
            subagents: conversation.subagents,
            workflowRuns: conversation.workflowRuns)
    }

    /// Another live window/tab already shows or is running this conversation — the one-conversation-
    /// one-window policy says focus THAT window instead of opening a duplicate here.
    private func ownedElsewhere(_ id: UUID) -> Bool { AgentBridge.owner(of: id, excluding: self) != nil }

    /// Focus the window/tab that already owns `id` (if any). Returns whether it did — callers use it
    /// to bail out of opening a duplicate.
    @discardableResult
    static func focusOwner(of id: UUID, excluding: AgentBridge? = nil) -> Bool {
        guard let owner = owner(of: id, excluding: excluding), let win = owner.window else { return false }
        owner.select(id)
        win.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
        return true
    }

    /// NotificationCenter observers this bridge registered — removed on shutdown so a closed
    /// window's dead observer doesn't keep firing on every broadcast for the process lifetime.
    private var noteObservers: [NSObjectProtocol] = []

    /// True if anything would be silently abandoned by quitting now: a root turn, a delegate still
    /// owned by one of this bridge's retained routes, or queued composer prompts. A successful
    /// parent can finish while its child intentionally continues, so `runningConvs` alone is not a
    /// lifecycle guard.
    var hasPendingWork: Bool {
        agentBridgeHasPendingWork(
            hasRunningConversations: !runningConvs.isEmpty,
            hasPendingTurnStarts: !pendingTurnStarts.isEmpty,
            currentConversationID: currentID,
            currentWorkflowRuns: workflowRuns,
            currentSubagents: subagents,
            currentQueuedPrompts: queuedPrompts,
            storedConversations: conversations,
            routedConversationIDs: Set(turnRoutes.values.map(\.conversationID)))
    }

