    func restoreInspectorPreferredWidth(store: UserDefaults = .standard) {
        inspectorPreferredWidth = InspectorWidthPreference.width(
            workspaceID: inspectorPreferenceWorkspaceID,
            store: store)
    }

    func userSetInspectorPreferredWidth(
        _ width: Double,
        store: UserDefaults = .standard
    ) {
        guard width.isFinite,
              width >= InspectorWidthPreference.minimum,
              width <= InspectorWidthPreference.maximum else { return }
        inspectorPreferredWidth = width
        InspectorWidthPreference.setWidth(
            width,
            workspaceID: inspectorPreferenceWorkspaceID,
            store: store)
    }

    func userSetTerminalHeight(_ height: Double, store: UserDefaults = .standard) {
        guard height.isFinite, (120.0...400.0).contains(height) else { return }
        terminalHeight = height
        // Legacy/new-window fallback only. Relaunch restoration reads the exact window snapshot.
        store.set(height, forKey: "terminalHeight")
    }

    /// The one tab-visibility authority for this window.
    ///
    /// A folder-backed Workspace deliberately carries `projectID == nil` on its live bridge: its
    /// window is keyed by `cwd`. Its tab preferences are nevertheless per Workspace, so every
    /// reader and writer must resolve that folder to its durable Workspace id first. Mixing the
    /// bridge field into one path and this lookup into another renders a tab whose activation is
    /// rejected as unavailable.
    func visibleInspectorTabs(store: UserDefaults = .standard) -> [InspectorTab] {
        InspectorTabPreference.visible(
            cwd: cwd,
            workspaceID: inspectorPreferenceWorkspaceID,
            store: store)
    }

    /// Change the visible tab set for the Workspace this window is actually displaying.
    func setInspectorTabVisible(
        _ visible: Bool,
        tab: InspectorTab,
        store: UserDefaults = .standard
    ) {
        InspectorTabPreference.setVisible(
            visible,
            tab: tab,
            cwd: cwd,
            workspaceID: inspectorPreferenceWorkspaceID,
            store: store)
    }

    /// Restore the default tab set for the Workspace this window is actually displaying.
    func resetInspectorTabVisibility(store: UserDefaults = .standard) {
        InspectorTabPreference.reset(
            workspaceID: inspectorPreferenceWorkspaceID,
            store: store)
    }

    /// Whether this displayed Workspace has chosen a tab set of its own.
    func hasCustomizedInspectorTabVisibility(store: UserDefaults = .standard) -> Bool {
        InspectorTabPreference.isCustomized(
            workspaceID: inspectorPreferenceWorkspaceID,
            store: store)
    }

    func restoreInspectorTabSelection(store: UserDefaults = .standard) {
        inspectorTab = InspectorTabPreference.selected(
            cwd: cwd,
            workspaceID: inspectorPreferenceWorkspaceID,
            store: store)
    }

    func userSelectedInspectorTab(
        _ tab: InspectorTab,
        store: UserDefaults = .standard
    ) {
        guard visibleInspectorTabs(store: store).contains(tab) else { return }
        inspectorTab = tab
        InspectorTabPreference.setSelected(
            tab,
            cwd: cwd,
            workspaceID: inspectorPreferenceWorkspaceID,
            store: store)
        inspectorTabUserActivationRevision &+= 1
        inspectorTabUserActivation = InspectorTabUserActivation(
            tab: tab,
            revision: inspectorTabUserActivationRevision)
    }
