    /// All conversations across every workspace, newest first. Workspace-scoped surfaces apply
    /// `WorkspaceScope` before presenting this shared inventory.
    var conversationsSorted: [ConversationSummary] {
        store.summaries
    }

    private var conversationWorkspaceScope: WorkspaceScope? {
        WorkspaceScope.resolve(
            projectID: projectID,
            cwd: cwd,
            projects: ProjectStore.shared.projects)
    }

    private func firstUnownedConversationInCurrentWorkspace(
        excluding excludedIDs: Set<UUID> = []
    ) -> ConversationSummary? {
        guard let scope = conversationWorkspaceScope else { return nil }
        return conversationsSorted.first {
            !excludedIDs.contains($0.id)
                && scope.contains($0, projects: ProjectStore.shared.projects)
                && !ownedElsewhere($0.id)
        }
    }

    /// The canonical sidebar order, shared by every sort site (list, load, cross-window merge):
    /// favorites pinned on top, then the hand-ordered position (once the list has been dragged)
    /// or most-recent activity.
    static func order(_ a: Conversation, _ b: Conversation) -> Bool {
        if a.favorite != b.favorite { return a.favorite }            // starred conversations on top
        // Hand-ordered items (real sortIndex) sort above never-reordered ones (nil → Int.max);
        // ties, and the all-nil default, fall back to recency. Using Int.max keeps this a strict
        // weak ordering (a single Int key), so Swift's sort can't hit an intransitive comparator.
        let ai = a.sortIndex ?? Int.max, bi = b.sortIndex ?? Int.max
        if ai != bi { return ai < bi }
        return a.updatedAt > b.updatedAt                             // else newest first
    }

    var currentConversation: Conversation? {
        conversations.first { $0.id == currentID }
    }

    // MARK: Lifecycle

    /// Canonical folder path for a folder-backed launch destination; applied once the daemon is
    /// ready so an unavailable directory produces an actionable fallback instead of a silent load.
    private var pendingInitialFolder: String?
    /// Canonical Project identity for a scoped launch destination, including folder-backed Projects.
    /// Keeping the id alongside the path prevents remove/recreate-at-the-same-path from rebinding it.
    private var pendingInitialProjectID: UUID?
    /// The one conversation this window was opened to show, bound to THIS bridge at construction.
    ///
    /// Replaces `ActiveWorkspace.pendingOpenConversation` for every caller that builds the window
    /// itself. That was a single process-global slot, so two "Open in New Window" gestures in
    /// flight overwrote each other and whichever bridge readied first consumed it — leaving the
    /// other window to mint a blank conversation. Consumed in `restoreLastViewed`, at start rather
    /// than at ready, so a signed-out user or an unstarted runtime cannot strand it.
    private var pendingInitialConversationID: UUID?
    /// A fresh-conversation request bound to this bridge. A Boolean is safe here because it belongs
    /// to one window; the former process-global Boolean collapsed two rapid ⌘T requests into one.
    private var pendingInitialFreshConversation: Bool
    /// The source Conversation's durable provider/model pair, carried only by a fresh native-tab
    /// intent. It is never a process-wide default and is consumed exactly once by this bridge's
    /// initial fresh creation.
    private var pendingInitialTabModelSelection: ModelSelection?
    /// Only an ordinary unbound launch window may consume the legacy process-global cold-route
    /// handoff. A scoped, named, or explicitly fresh window owns a more specific destination.
    let acceptsProcessGlobalOpenConversation: Bool
    /// Presentation state captured for this exact native workspace window at the prior clean quit.
    /// Nil is the additive upgrade path: use the legacy app/workspace preferences instead.
    private let initialWindowLayout: WorkspaceWindowLayout?
    /// Once this window has entered Help, later in-place returns preserve its live panel choice.
    /// A newly constructed Help window resolves the same flag from its restored layout/default.
    private var didResolveHelpInspectorVisibility = false

    /// Explicit navigation or a coordinated workspace mutation supersedes the launch destination.
    /// Retire both the not-yet-sent bootstrap and an already-sent folder control so its late reply
    /// cannot pull the window back after the user moved it somewhere else. The replacement
    /// navigation always queues/sends its own canonical `load` request.
    private func cancelInitialWorkspaceBootstrap() {
        pendingInitialFolder = nil
        pendingInitialProjectID = nil
        pendingInitialConversationID = nil
        pendingInitialFreshConversation = false
        pendingInitialTabModelSelection = nil
        if let latestFolderControlID {
            removeProviderNeutralControlRoute(latestFolderControlID)
        }
    }
    /// Tests can verify preference relaunch semantics without redirecting the whole process or
    /// launching agentd. Production always leaves this nil and uses the normal app-support path.
    private let settingsBaseOverride: URL?
    /// The environment `loadSettings()` reads its dev overrides (`MECHANICIAN_AUTH` /
    /// `MECHANICIAN_PROVIDER`) from. Injectable because those overrides deliberately outrank the
    /// persisted lane, which makes any test of persistence fail whenever the suite happens to run
    /// with them exported — as it does when the app (or `dev.sh`) is the parent process. Production
    /// leaves this nil and reads the real environment.
    private let environmentOverride: [String: String]?
    /// Managed preferences are launch-static. Capturing the resolved policy also gives restart and
    /// account-command tests a deterministic policy without trying to forge macOS forced defaults.
    private let managedEnterprisePolicy: ManagedEnterprisePolicy?
    private var launchEnvironment: [String: String] {
        environmentOverride ?? ProcessInfo.processInfo.environment
    }

    init(initialFolder: String? = nil, initialProjectID: UUID? = nil,
         initialConversationID: UUID? = nil, startsFreshConversation: Bool = false,
         initialTabModelSelection: ModelSelection? = nil,
         initialWindowLayout: WorkspaceWindowLayout? = nil,
         settingsBaseOverride: URL? = nil, environmentOverride: [String: String]? = nil,
         conversationStoreOverride: ConversationStore? = nil,
         managedEnterprisePolicy: ManagedEnterprisePolicy? = ManagedEnterprisePolicy.current) {
        store = conversationStoreOverride ?? .shared
        pendingInitialFolder = initialFolder
        pendingInitialProjectID = initialProjectID
        pendingInitialConversationID = initialConversationID
        pendingInitialFreshConversation = startsFreshConversation
        pendingInitialTabModelSelection = startsFreshConversation && initialConversationID == nil
            ? initialTabModelSelection
            : nil
        acceptsProcessGlobalOpenConversation = initialFolder == nil
            && initialProjectID == nil
            && initialConversationID == nil
            && !startsFreshConversation
        self.initialWindowLayout = initialWindowLayout
        self.settingsBaseOverride = settingsBaseOverride
        self.environmentOverride = environmentOverride
        self.managedEnterprisePolicy = managedEnterprisePolicy
        // Set this window's PLACE synchronously so a still-booting Project window is never transiently
        // seen as Home (projectID==nil && cwd=="") by openHome/openProject/last-location — the startup
        // race that could hijack or duplicate a window.
        cwd = initialFolder ?? ""
        projectID = initialProjectID
        inspectorPreferredWidth = InspectorWidthPreference.default(workspaceID: initialProjectID)
        // Seed the exact restored state before a hosting controller or toolbar observes this bridge.
        // Missing/invalid fields deliberately remain at their safe defaults until `start()` applies
        // the legacy preference fallback.
        if let visible = initialWindowLayout?.showsSidebar { showSidebar = visible }
        if HelpWorkspace.owns(initialProjectID) {
            let defaults = UserDefaults.standard
            let priorGlobalVisibility = defaults.object(forKey: "panel.inspector")
            showInspector = HelpWorkspaceInspectorVisibilityPolicy.resolve(
                restoredVisibility: initialWindowLayout?.showsInspector)
            didResolveHelpInspectorVisibility = true
            // Restored and default Help layout are window-owned. Neither may silently become the
            // inspector fallback inherited by a subsequently created, unrelated workspace.
            if let priorGlobalVisibility {
                defaults.set(priorGlobalVisibility, forKey: "panel.inspector")
            } else {
                defaults.removeObject(forKey: "panel.inspector")
            }
        } else if let visible = initialWindowLayout?.showsInspector {
            showInspector = visible
        }
        if let visible = initialWindowLayout?.showsTerminal { showTerminal = visible }
        if let width = initialWindowLayout?.validInspectorWidth(
            InspectorWidthPreference.minimum...InspectorWidthPreference.maximum
        ) {
            inspectorPreferredWidth = width
        }
        inspectorWidth = CGFloat(inspectorPreferredWidth)
        if let height = initialWindowLayout?.validTerminalHeight(120...400) {
            terminalHeight = height
        }
        // The store is the shared source of truth; forward its changes so views observing THIS
        // bridge (they read `conversations` as a passthrough) refresh when another window/tab
        // creates/renames/deletes/updates a conversation. Its lightweight summaries and explicit
        // resident-boundary notifications are the sync path; raw token accumulation is not.
        store.objectWillChange
            .sink { [weak self] in self?.objectWillChange.send() }
            .store(in: &cancellables)
        // Cross-window recovery (replaces the old applyRemoteRemove): if the conversation THIS
        // window is showing gets removed in another window (delete / Clear All / a placeholder
        // dropped on navigation), migrate off it — otherwise currentID dangles on a nonexistent id
        // (ghost transcript + turns that silently never persist, since store.update no-ops).
        store.$summaries
            .dropFirst() // skip the current-value emission at subscribe time
            .sink { [weak self] list in
                self?.reconcileIfCurrentRemoved(from: list)
                self?.revokeQueuedRepositoryWorkContextSources(
                    availableConversationIDs: Set(list.map(\.id)))
            }
            .store(in: &cancellables)
        store.$conversationWorkEvidenceRevision
            .dropFirst()
            .sink { [weak self] revision in
                self?.reloadConversationWorkEvidence(expectedRevision: revision)
            }
            .store(in: &cancellables)
    }

    /// A delegate that goes silent produces no event, so nothing else can notice it. Every other
    /// reconciliation path is driven by something happening; this one has to be driven by time.
    /// One minute is far finer than the 30-minute judgement it serves, and the check is a couple of
    /// dictionary scans, so the resolution costs nothing and keeps the reap from feeling delayed.
    ///
    /// Started on the first sign of delegated work rather than in `init`, and stopped again when
    /// none is left. A conversation that never delegates should not put a repeating timer on the
    /// main runloop at all — and in tests, where bridges are constructed freely and never torn down,
    /// scheduling one per bridge left a growing pile of them firing into any test that spins the
    /// runloop. That surfaced as an unrelated composer-focus assertion failing on CI.
    private func ensureSilentDelegateReaper() {
        guard silentDelegateReaper == nil else { return }
        silentDelegateReaper = Timer.scheduledTimer(withTimeInterval: 60, repeats: true) {
            [weak self] _ in
            Task { @MainActor in self?.reapSilentDelegatedWork() }
        }
    }

    private func stopSilentDelegateReaperIfIdle() {
        guard silentDelegateReaper != nil,
              !hasNonterminalDelegatedWork(workflowRuns: workflowRuns, subagents: subagents)
        else { return }
        silentDelegateReaper?.invalidate()
        silentDelegateReaper = nil
    }

    /// Settle delegated work in the CURRENT conversation that has stopped reporting.
    ///
    /// Scoped to the conversation this bridge is showing and skipped entirely while a turn is in
    /// flight: a running turn is itself evidence the session is alive, and a delegate can legitimately
    /// be quiet while its parent thinks. Everything else — other windows' conversations, conversations
    /// owned by another daemon — is deliberately untouched, for the same reason `reconcileStuckRuns`
    /// is scoped to `owned`: republishing a false "stopped" would stomp a live run elsewhere.
    private func reapSilentDelegatedWork(at now: Date = Date()) {
        defer { stopSilentDelegateReaperIfIdle() }
        guard let conversationID = currentID, !runningConvs.contains(conversationID) else { return }
        guard delegatedWorkHasGoneSilent(
            workflowRuns: workflowRuns, subagents: subagents, now: now) else { return }
        _ = terminalizeDelegatedWork(
            for: conversationID,
            outcome: .userStopped,
            turnID: nil,
            selection: currentModelSelection,
            durable: true,
            at: now)
    }

    /// If our on-screen `currentID` is no longer in the shared list, move off it exactly like a
    /// local delete does. Deferred to the next runloop because this fires inside the store's willSet
    /// publish, where re-entering a store mutation (select/newConversation) would be unsafe.
    private func reconcileIfCurrentRemoved(from list: [ConversationSummary]) {
        let existing = Set(list.map(\.id))
        let removedTurnOwners = Set(turnRoutes.values.compactMap { route in
            route.phase.reservesConversation && !existing.contains(route.conversationID)
                ? route.conversationID : nil
        })
        let removedCurrent = currentID.map { !existing.contains($0) } ?? false
        guard removedCurrent || !removedTurnOwners.isEmpty else { return }
        DispatchQueue.main.async { [weak self] in
            guard let self else { return }
            for id in removedTurnOwners where !self.store.contains(id) {
                self.cancelTurnsForRemovedConversation(id)
            }
            guard let id = self.currentID, !self.store.contains(id) else { return }
            self.currentID = nil // clear persistCurrent's target so we don't try to re-save the gone id
            if let first = self.firstUnownedConversationInCurrentWorkspace() {
                self.select(first.id)
            } else {
                self.newConversation()
            }
        }
    }

    /// Terminate every provider lane owned by this window when it closes.
    func shutdown() {
        // Stop reacting to the shared store FIRST: this closing bridge outlives the window (the
        // willClose/didBecomeKey observers retain it), and the `persistCurrent` below removes an empty
        // placeholder, which would otherwise fire THIS bridge's own reconcileIfCurrentRemoved and
        // spuriously select/mark-read another conversation. Cancelling also ends the objectWillChange
        // forward so a dead bridge no longer churns on every store change.
        cancellables.removeAll()
        silentDelegateReaper?.invalidate()
        silentDelegateReaper = nil
        gitRefreshScheduler.cancel()
        cancelPendingConversationSelection()
        // A turn whose send was written but never acknowledged is not provider-owned work. Restore
        // its prompt before persisting so closing the window cannot lose it.
        let abandonedTurnOwners = conversationIDsAffectedByProcessTermination(
            turnRoutes.values.map { route in
                (
                    conversationID: route.conversationID,
                    reservesConversation: route.phase.reservesConversation,
                    hasRunningDelegates: hasRunningDelegates(route.conversationID)
                )
            })
        recoverPendingTurnStarts()
        reconcileStuckRuns(owned: abandonedTurnOwners)
        // Fold this window's transcript into the store and drop an unused "New conversation"
        // placeholder before we go — the placeholder is in the SHARED store (visible in every
        // window), so without this it lingers as a phantom row in siblings until relaunch.
        persistCurrent()
        // This window's daemons go with it, and with them the only processes that could report on
        // or stop the work they were tracking.
        BackgroundProcessStore.shared.clearBridge(bridgeID)
        AgentBridge.live.remove(self)
        store.releaseBackNavigationRetention(owner: bridgeID)
        // Account operations are process-wide gates. Route window closure through the same
        // request-owned failure path as every other terminal so sibling windows resume their
        // preserved queues, timers are cancelled, and a temporary Claude re-enable rolls back.
        cancelPendingAccountCommands(
            message: "The account operation stopped because its window closed.")
        Self.retireAccountReloadTarget(bridgeID: bridgeID)
        noteObservers.forEach { NotificationCenter.default.removeObserver($0) }
        noteObservers.removeAll()
        workspaceObservers.forEach { NSWorkspace.shared.notificationCenter.removeObserver($0) }
        workspaceObservers.removeAll()
        // Closing a window mid-turn kills its agentd, so no "turn ended" event ever arrives to
        // clear runningConvs. Left alone, those conversations stay stuck in the cross-window
        // running union (nothing else recomputes it) and every surviving window shows a spinner
        // that never stops. Clear ours and refresh the global set now that we're out of `live`.
        runningConvs.removeAll()
        let departingWaitIDs = waitingConvs
        waitTimer?.invalidate()
        waitTimer = nil
        waitingConvs.removeAll()
        let readySurvivors = AgentBridge.live.allObjects.filter {
            $0.didAdoptPersistedOperativeState
        }
        if let recipientID = PersistedOperativeRecovery.waitHandoffRecipientID(
            departingWaitIDs: departingWaitIDs,
            readySurvivingBridgeIDs: Set(readySurvivors.map(\.bridgeID))),
           let recipient = readySurvivors.first(where: { $0.bridgeID == recipientID }) {
            recipient.adoptPersistedWaits()
        }
        ActiveWorkspace.shared.recomputeRunning()
        clearTurnRouting()
        claimedQueueConversations.removeAll()
        // Remove ownership before stopping so intentional shutdown cannot be mistaken for provider
        // crashes by the runtimes' identity-guarded termination handlers.
        let activeRuntimes = Array(runtimes.values)
        runtimes.removeAll()
        runtimeGenerations.removeAll()
        runtimeCredentialEpochs.removeAll()
        harnessMetricCredentialEpochs.removeAll()
        pendingRuntimeAccountReloads.removeAll()
        laneStates.removeAll()
        pendingConversationLoads.removeAll()
        modelCatalogRequestTimeouts.values.forEach { $0.cancel() }
        modelCatalogRequestTimeouts.removeAll()
        modelCatalogRequestRoutes.removeAll()
        latestModelCatalogRequestIDs.removeAll()
        pendingModelCatalogScopes.removeAll()
        pendingAccountCommands.removeAll()
        pendingAccountCommandTimeouts.values.forEach { $0.cancel() }
        pendingAccountCommandTimeouts.removeAll()
        lastUnexpectedExitAt.removeAll()
        activeRuntimes.forEach { $0.stop() }
    }

    /// Land presentation-coalesced bytes before the process-wide store queues drain. The app
    /// delegate calls this explicitly because notification-observer order is not a persistence
    /// boundary; the per-bridge termination observer keeps the hook as an idempotent backstop.
    func prepareForTermination() {
        let abandonedTurnOwners = conversationIDsAffectedByProcessTermination(
            turnRoutes.values.map { route in
                (
                    conversationID: route.conversationID,
                    reservesConversation: route.phase.reservesConversation,
                    hasRunningDelegates: hasRunningDelegates(route.conversationID)
                )
            })
        recoverPendingTurnStarts()
        reconcileStuckRuns(owned: abandonedTurnOwners)
        persistCurrent()
        // `persistCurrent` covers this window. Background turns already live in the shared store,
        // including turns owned by this bridge but not currently selected; force all of those
        // records across a save boundary before the process-wide queue drain.
        store.prepareForTermination()
        // Cmd-Q does not guarantee each window's willClose callback. Apply the same request-owned
        // account rollback as window shutdown before the process exits.
        cancelPendingAccountCommands(
            message: "The account operation stopped because Mechanician quit.")
    }

    func start() {
        guard !didStart else { return }
        didStart = true
        AgentBridge.live.add(self) // join the quit-guard registry (see hasPendingWork)
        // On quit, fold the live transcript + composer queue into the current conversation,
        // then drain queued conversation writes so nothing async is lost.
        noteObservers.append(NotificationCenter.default.addObserver(
            forName: NSApplication.willTerminateNotification, object: nil, queue: .main) { [weak self] _ in
            MainActor.assumeIsolated {
                self?.prepareForTermination()
                self?.flushSaves()
            }
        })
        // (Cross-window sync used to ride a NotificationCenter broadcast here; the shared
        // ConversationStore's shared publication plane replaces it — this bridge forwards its
        // semantic changes in init.)
        loadSettings()
        loadCachedCommands() // access-tagged; restoreLastViewed projects the matching lane below
        recentFolders = UserDefaults.standard.stringArray(forKey: recentsKey) ?? []
        favoriteFolders = UserDefaults.standard.stringArray(forKey: favoritesKey) ?? []
        // A current session ledger owns presentation per native window. Individual missing fields
        // (including every field in an older ledger) fall back independently to the former global /
        // per-workspace preferences, so upgrades never reset a layout.
        if initialWindowLayout?.showsTerminal == nil {
            showTerminal = UserDefaults.standard.bool(forKey: "panel.terminal")
        }
        if initialWindowLayout?.showsInspector == nil, !HelpWorkspace.owns(projectID) {
            showInspector = UserDefaults.standard.bool(forKey: "panel.inspector")
        }
        if initialWindowLayout?.showsSidebar == nil {
            showSidebar = UserDefaults.standard.object(forKey: "panel.sidebar") as? Bool ?? true
        }
        if initialWindowLayout?.validTerminalHeight(120...400) == nil {
            let saved = UserDefaults.standard.object(forKey: "terminalHeight") as? Double
            terminalHeight = saved.flatMap {
                $0.isFinite && (120...400).contains($0) ? $0 : nil
            } ?? 240
        }
        if initialWindowLayout?.validInspectorWidth(
            InspectorWidthPreference.minimum...InspectorWidthPreference.maximum
        ) == nil {
            restoreInspectorPreferredWidth()
        }
        restoreInspectorTabSelection()
        _ = ArtifactStore.shared // migrate nested artifacts + start the artifacts/ dir watcher
        // Tighten and migrate legacy extensions.json credentials before restoring a conversation:
        // restore can now start its provider runtime while loading the selected workspace.
        // Connections is an optional window, so migration cannot depend on opening its UI.
        _ = ExtensionsStore.shared
        // Boot the default provider lane immediately so the daemon warms up IN PARALLEL with the
        // background corpus decode — the two slowest launch steps now overlap instead of stacking.
        ensureRuntime(for: currentModelAccess)
        // An explicitly scoped window already knows its folder/project from init. Prime that exact
        // catalog now rather than waiting for the unrelated process-wide corpus decode; the
        // post-ready call below remains an idempotent recheck if restore canonicalizes the scope.
        if pendingInitialFolder != nil || pendingInitialProjectID != nil {
            prepareCurrentModelCatalog(force: false)
        }
        // `whenReady` now means the exact SQLite-backed inventory and every intrinsically operative
        // Conversation are available. The selected inert Conversation may still require one
        // asynchronous hydration; `restoreLastViewed` completes the remaining bootstrap only after
        // that exact value arrives. This keeps provider work behind restoration without making the
        // launch inventory wait for every transcript in the corpus.
        store.whenReady { [weak self] in
            guard let self else { return }
            guard InitialConversationHydrationPublication
                .shouldPrepareSQLiteWorkspaceInventory(
                    conversationUsedSQLiteLaunchInventory:
                        self.store.usedSQLiteLaunchInventory) else {
                // A Legacy fallback already loaded Workspace/Home from their current authority.
                // Mixing that Conversation census with an independently cached SQLite Workspace
                // snapshot would create a split launch view.
                self.didPrepareWorkspaceLaunchInventory = true
                self.adoptPersistedOperativeStateIfReady()
                self.restoreLastViewed()
                return
            }
            self.didPrepareWorkspaceLaunchInventory = true
            self.adoptPersistedOperativeStateIfReady()
            self.restoreLastViewed()
        }
    }

    /// Publish the selected initial view exactly once, then release operative recovery and provider
    /// bootstrap. `store.whenReady` is the prerequisite: it guarantees queue/wait/provider-access
    /// records are already resident even though ordinary transcripts remain inventory-only.
    private func completeInitialViewResolution() {
        guard store.isReady, didPrepareWorkspaceLaunchInventory,
              !didResolveInitialView else { return }
        openingConversationID = nil
        initialViewResolutionPending = false
        preReadyConversationSelectionID = nil
        didResolveInitialView = true
        // Everything below runs on the main actor after the flag that lets the transcript paint, so
        // SwiftUI cannot render until it returns. Each call was timed on a real launch and every one
        // measured 0 ms, which is why the segment after this is attributed to first render rather
        // than to provider bootstrap. Do not re-litigate that from the shape of the code.
        adoptPersistedOperativeStateIfReady()
        ensureRuntime(for: currentModelAccess)
        // The provider may have won the launch race and reported ready before inventory/hydration.
        bootstrapWindowIfReady(for: currentModelAccess)
        // Queue the selected workspace's request before agentd becomes ready. Its ready event
        // flushes this scope ahead of the generic home-directory warm-up.
        prepareCurrentModelCatalog(force: false)
    }

    /// Operative recovery belongs to the complete store/Workspace inventory, not to whichever
    /// inert transcript the window is restoring. A corrupt saved transcript must not suppress a
    /// wait, queue, or provider-access request already reconstructed from another Conversation.
    private func adoptPersistedOperativeStateIfReady() {
        guard store.isReady, didPrepareWorkspaceLaunchInventory,
              !didAdoptPersistedOperativeState else { return }
        didAdoptPersistedOperativeState = true
        adoptPersistedWaits()
        adoptPersistedQueues()
        adoptPersistedProviderAccessRequests()
    }

    /// Consume the initial Conversation/Workspace exactly once, but only after both launch gates.
    /// Runtime readiness remains live immediately; this delays only the stateful bootstrap that can
    /// create, select, or load a Conversation.
    private func bootstrapWindowIfReady(for access: ModelAccess) {
        guard access == currentModelAccess else { return }
        guard WorkspaceBootstrapReadiness.shouldBegin(
            storeIsReady: store.isReady,
            initialViewResolved: didResolveInitialView,
            runtimeIsReady: isRuntimeReady(access),
            didBootstrap: didBootstrapWindow
        ) else {
            if didBootstrapWindow {
                flushPendingConversationLoad(for: access)
                scheduleRunnableQueueDrain(for: access)
            }
            return
        }
        didBootstrapWindow = true

        // A window opened for a specific folder adopts it now. The provider's `cwd` reply then
        // finishes that folder's Workspace setup.
        if let folder = pendingInitialFolder {
            let resolvedScope = WorkspaceScope.resolve(
                projectID: nil,
                cwd: folder,
                projects: ProjectStore.shared.projects)
            if WorkspaceBootstrapPolicy.acceptsFolder(
                expectedProjectID: pendingInitialProjectID,
                resolvedScope: resolvedScope) {
                cwd = folder
                if !setFolder(folder) {
                    failInitialFolderBootstrap(
                        folder,
                        message: "Couldn't open that folder because the provider runtime stopped. Open it again to retry.")
                }
                return
            }
            // The Workspace was removed/reassigned (or the path was reused) after restoration.
            // A newer canonical `load` may already be queued; do not strand it here.
            cancelInitialWorkspaceBootstrap()
        }
        if let pid = pendingInitialProjectID {
            // A folder-less topic Workspace: no working folder; the sidebar scopes by identity.
            pendingInitialProjectID = nil
            if let project = ProjectStore.shared.project(pid), project.cwd.isEmpty {
                projectID = pid
                cwd = ""
                let scope = WorkspaceScope.project(pid)
                let projects = ProjectStore.shared.projects
                let available = store.summaries.filter { !ownedElsewhere($0.id) }
                // Store-ready restoration chose the launch-time row, but explicit same-Workspace
                // navigation may have selected or created a newer row while the runtime started.
                let requested = WorkspaceBootstrapPolicy.conversationID(
                    currentSelection: currentID)
                pendingInitialConversationID = nil
                let preferred = scope.preferredConversation(
                    requestedID: requested,
                    among: available,
                    projects: projects)
                let selected = WorkspaceBootstrapPolicy.acceptsPreferredConversation(
                    requestedID: requested,
                    preferredID: preferred?.id) ? preferred : nil
                adopt(
                    selected,
                    cwd: "",
                    newProjectID: pid,
                    requiresProviderLoadOnSameSelection: true)
                focusComposer()
                scheduleRunnableQueueDrain(for: access)
                return
            }
            // Removal or an out-of-band folder assignment superseded the topic bootstrap. Fall
            // through so the current Conversation's canonical pending load can still flush.
            cancelInitialWorkspaceBootstrap()
        }
        if store.summaries.isEmpty {
            // A genuinely empty ready store opens one folder-less Scratch Conversation.
            let selection = inheritedModelSelection(projectID: nil, cwd: "")
            let c = Conversation(title: "New conversation", cwd: "", sdkSessionId: nil,
                                 modelSelection: selection, messages: [], updatedAt: Date(),
                                 projectID: nil)
            currentID = c.id
            cwd = ""
            entries = []
            save(c)
            persistWorkspaceDefault(selection, projectID: nil, cwd: "")
            applyModelSelectionIfCompatible(selection)
            focusComposer()
        } else if let c = currentConversation {
            entries = c.messages
            resetLiveState(keepEntries: true)
            restoreSuggestedPrompt(from: c)
            restoreContextUsage(from: c)
            stagePendingHistoryReplay(c.messages, for: c)
            artifacts = c.artifacts
            selectedArtifact = c.artifacts.last?.title
            workflowRuns = c.workflowRuns
            subagents = c.subagents
            agentActivity = c.agentActivity
            queuedPrompts = c.queuedPrompts
            // Adopt the Conversation's Workspace identity as a pair. Taking only `cwd` let a
            // window's folder drift away from its `projectID`, and the "does a window already show
            // this Workspace?" predicate reads both — which is one of the ways two windows ended up
            // bound to the same Workspace.
            cwd = c.cwd
            if let owningProjectID = c.projectID { projectID = owningProjectID }
            applyModelSelectionIfCompatible(
                c.modelSelection ?? workspaceDefaultSelection(projectID: c.projectID, cwd: c.cwd))
            loadConversation(c, cwd: cwd)
            focusComposer()
        } else {
            // No restored or externally requested destination survived authoritative validation.
            newConversation()
        }
        flushPendingConversationLoad(for: access)
        scheduleRunnableQueueDrain(for: access)
    }

    /// Restart only the selected access lane (for example after changing that lane's credentials).
    /// Other providers and their active turns remain untouched.
    func restartAgentd() {
        restartRuntime(for: currentModelAccess)
    }

    /// Only first-party Claude routes consume the global bare-model 1M alias policy. Vertex and
    /// Bedrock publish their own concrete model ids and deliberately pass through this setting.
    private nonisolated static let oneMillionContextAccesses: Set<ModelAccess> = [
        .claudeSubscription, .anthropicAPI,
    ]

    /// Pure restart planning keeps the process-wide policy independently testable. A bridge must
    /// replace every affected runtime it already owns plus its selected affected lane (which may
    /// still be launching and therefore absent from the runtime dictionary).
    nonisolated static func oneMillionContextRestartAccesses(
        runtimeAccesses: Set<ModelAccess>,
        selectedAccess: ModelAccess?
    ) -> Set<ModelAccess> {
        var accesses = runtimeAccesses.intersection(oneMillionContextAccesses)
        if let selectedAccess, oneMillionContextAccesses.contains(selectedAccess) {
            accesses.insert(selectedAccess)
        }
        return accesses
    }

    nonisolated static func oneMillionContextChangeBlocked(
        activeProviderAccesses: Set<ModelAccess>
    ) -> Bool {
        !activeProviderAccesses.isDisjoint(with: oneMillionContextAccesses)
    }

    @Published private(set) var oneMillionContextChangeMessage: String?

    /// Apply the preference as one main-actor transaction across every live window. The old toggle
    /// changed UserDefaults first and restarted only the Settings window, allowing another window
    /// to resume an opaque session created by the opposite model variant. Here the work audit runs
    /// before mutation, UserDefaults advances once, and every replacement is explicitly force-fresh.
    /// Queued prompts are not blockers and remain owned by their existing conversation queues.
    @discardableResult
    func setOneMillionContextEnabled(_ enabled: Bool) -> Bool {
        let current = (UserDefaults.standard.object(forKey: "use1MContext") as? Bool) ?? true
        guard current != enabled else {
            oneMillionContextChangeMessage = nil
            return true
        }

        var bridges = Array(Self.live.allObjects)
        if !bridges.contains(where: { $0 === self }) { bridges.append(self) }
        let activeProviderAccesses = Set(bridges.flatMap { bridge in
            Self.oneMillionContextAccesses.filter { bridge.ownsActiveProviderWork(for: $0) }
        })
        guard !Self.oneMillionContextChangeBlocked(
            activeProviderAccesses: activeProviderAccesses)
        else {
            oneMillionContextChangeMessage = String(localized:
                "Finish or stop active Claude work before changing the 1M context setting.")
            return false
        }

        // AgentdRuntime snapshots this preference into its launch environment. Publish the new
        // value before replacing any lane so every process in the transaction sees one generation.
        UserDefaults.standard.set(enabled, forKey: "use1MContext")
        for bridge in bridges {
            bridge.oneMillionContextChangeMessage = nil
            bridge.clearOneMillionContextLiveState()
            let accesses = Self.oneMillionContextRestartAccesses(
                runtimeAccesses: Set(bridge.runtimes.keys),
                selectedAccess: bridge.currentModelAccess)
            for access in accesses.sorted(by: { $0.rawValue < $1.rawValue }) {
                bridge.restartRuntime(for: access, forceFresh: true)
            }
        }
        return true
    }

    /// Provider work is broader than the root spinner: provisional roots and live delegates are
    /// process-owned, while extension/browser/account controls are equally unsafe to sever midway.
    /// A 1M change replaces the daemon rather than reloading it in place, so its active builds and
    /// terminals are blockers too; silently ending either would be unrelated data loss.
    private func ownsActiveProviderWork(for access: ModelAccess) -> Bool {
        let hasTurnOrDelegate = !processAffectedConversations(for: access).isEmpty
        return hasTurnOrDelegate
            || extensionControlRoutes.values.contains { $0.access == access }
            || browseControlRoutes.values.contains(access)
            || agentBuildRoutes.values.contains { $0.selection.access == access }
            || userBuildRoutes.values.contains(access)
            || terminalRoutes.values.contains(access)
            || pendingAccountCommands[access] != nil
            || pendingRuntimeAccountReloads[access] != nil
            || stopRetirementsInFlight.contains(access)
            || !(pendingClaudePluginControls[access]?.isEmpty ?? true)
    }

    /// Do not rewrite the conversation corpus. The new session revision invalidates stored and
    /// evicted opaque sessions lazily; only clear window-local telemetry and prewarm state now.
    private func clearOneMillionContextLiveState() {
        guard Self.oneMillionContextAccesses.contains(currentModelAccess) else { return }
        clearLiveProviderSessionContext()
        lastComposerPrewarm = nil
    }

    @discardableResult
    private func ensureRuntime(for access: ModelAccess) -> AgentdRuntime? {
        if let reason = managedEnterprisePolicy?.turnBlockReason(for: access) {
            var state = laneStates[access] ?? RuntimeLaneState()
            state.ready = false
            state.mode = reason
            laneStates[access] = state
            if access == currentModelAccess { projectLaneState(access) }
            return nil
        }
        // Any caller in this window may demand the lane while Stop recovery is still publishing.
        // The transaction itself is the sole authority allowed to cross this generation boundary.
        guard !stopRetirementsInFlight.contains(access) else { return nil }
        if let blocked = stopRecoveryBlockedConversations[access] {
            guard blocked.allSatisfy({ store.isDurablyCurrent($0) }) else {
                var state = laneStates[access] ?? RuntimeLaneState()
                state.ready = false
                state.mode = "recovery save required"
                laneStates[access] = state
                if access == currentModelAccess { projectLaneState(access) }
                return nil
            }
            stopRecoveryBlockedConversations[access] = nil
            if let observer = stopRecoveryReplacementObserverForTesting {
                observer(access)
                return nil
            }
        }
        // A dead process may still be draining its final stdout before its queued exit callback.
        // Do not replace that generation until the callback relinquishes dictionary ownership.
        if let existing = runtimes[access] { return existing }
        var state = laneStates[access] ?? RuntimeLaneState()
        state.ready = false
        state.mode = "starting…"
        laneStates[access] = state
        if access == currentModelAccess { projectLaneState(access) }

        let generation = UUID()
        let credentialEpoch = ProviderAccountStore.shared.credentialEpoch(for: access)
        // A provider process is the only authority capable of naming its current Codex account.
        // Drop prior account gauges at every process generation so a restart after an out-of-band
        // account change cannot blend two accounts' daily buckets.
        clearHarnessAccountMetricSamples(for: access, credentialEpoch: credentialEpoch)
        _ = ModelCatalogStore.shared.alignCredentialEpoch(credentialEpoch, for: access)
        Self.registerAccountReloadTargetIfNeeded(
            bridge: self,
            access: access,
            credentialEpoch: credentialEpoch)
        let newRuntime = AgentdRuntime(
            access: access,
            onEvent: { [weak self] source, event in
                self?.handle(event, from: source, generation: generation)
            },
            onLaunchFailure: { [weak self] source, detail in
                self?.handleDaemonLaunchFailure(
                    from: source, generation: generation, detail: detail)
            },
            onUnexpectedExit: { [weak self] source, exit in
                self?.handleDaemonExit(
                    from: source, generation: generation, exit: exit)
            })
        runtimes[access] = newRuntime
        runtimeGenerations[access] = generation
        runtimeCredentialEpochs[access] = credentialEpoch
        newRuntime.start()
        return newRuntime
    }

    /// A cold Gatekeeper validation can outlive the window or be superseded by a newer generation.
    /// Only the generation that still owns this lane may publish its asynchronous launch failure.
    private func handleDaemonLaunchFailure(
        from access: ModelAccess,
        generation: UUID,
        detail: String
    ) {
        guard runtimes[access] != nil, runtimeGenerations[access] == generation else { return }
        let credentialEpoch = runtimeCredentialEpochs[access]
        let wasAccountReloadTarget = pendingRuntimeAccountReloads[access] != nil
        agentToolCatalog.invalidate(access: access, generation: generation)
        runtimes[access] = nil
        runtimeGenerations[access] = nil
        pendingRuntimeAccountReloads[access] = nil
        if runtimeCredentialEpochs[access] == credentialEpoch {
            runtimeCredentialEpochs[access] = nil
        }
        markModelCatalogRuntimeUnavailable(access, message: "Provider runtime failed to launch")
        var state = laneStates[access] ?? RuntimeLaneState()
        state.ready = false
        state.mode = "launch failed"
        state.isLoggingIn = false
        laneStates[access] = state
        if access == currentModelAccess { projectLaneState(access) }
        let message = "Failed to launch \(access.displayName): \(detail)"
        failPendingClaudePluginControls(for: access, message: message)
        failPendingAccountCommand(for: access, message: message)
        if wasAccountReloadTarget {
            Self.failAccountReloadOwner(for: access, message: message)
        }
        let queued = queuedConversations(for: access)
        if !queued.isEmpty {
            recordRuntimeFailure(for: access, conversations: queued, message: message)
        } else if access == currentModelAccess {
            appendSystem(message)
        }
    }

    private func restartRuntime(
        for access: ModelAccess,
        forceFresh: Bool = false,
        hardStop: Bool = false,
        unacknowledgedStopTurnID: String? = nil
    ) {
        if hardStop, let unacknowledgedStopTurnID {
            beginUnacknowledgedStopRetirement(
                access: access,
                triggerTurnID: unacknowledgedStopTurnID)
            return
        }
        let pendingReload = replacementLoad(
            for: access,
            forceFresh: forceFresh || unacknowledgedStopTurnID != nil)
        let reserved = reservedConversations(for: access)
        let affected = processAffectedConversations(for: access)
        let delegateScopes = runtimeDelegatedWorkTerminationScopes(
            for: access,
            conversations: affected)
        let terminationSelections = runtimeTerminationSelections(
            for: access,
            conversations: affected)
        recoverPendingTurnStarts(for: access)
        let activeRuntime = runtimes.removeValue(forKey: access)
        agentToolCatalog.invalidate(access: access)
        runtimeGenerations[access] = nil
        runtimeCredentialEpochs[access] = nil
        markModelCatalogRuntimeUnavailable(access, message: "Provider runtime is restarting")
        activeRuntime?.stop()
        // `ensureRuntime` stamps the replacement with the current credential epoch. When this
        // restart is serving an account barrier, retain the exact identity expectation so its first
        // ready must still prove which durable account it loaded.
        pendingConversationLoads[access] = pendingReload
        clearTurnRouting(for: access)
        // The tracker died with the daemon; a fresh one re-reports what still exists. Keeping the
        // old rows would offer a Stop button no process can service.
        BackgroundProcessStore.shared.clear(
            BackgroundProcessSource(bridgeID: bridgeID, access: access))
        runningConvs.subtract(reserved)
        reconcileStuckRuns(
            owned: affected,
            scopes: delegateScopes,
            selections: terminationSelections)
        lastUnexpectedExitAt[access] = nil

        var state = laneStates[access] ?? RuntimeLaneState()
        state.ready = false
        state.mode = "restarting…"
        state.isLoggingIn = false
        laneStates[access] = state
        if access == currentModelAccess {
            if mcpStatusAccess == access { resetMcpStatusState() }
            resetVisibleTurnState(ifOwnedBy: reserved)
            projectLaneState(access)
        }
        ensureRuntime(for: access)
    }

    /// Retire one exact provider generation after Stop failed to produce a terminal event. Process
    /// death and durable session retirement are independent prerequisites; replacement starts only
    /// after both have succeeded. Every timeout in the same generation coalesces here.
    private func beginUnacknowledgedStopRetirement(
        access: ModelAccess,
        triggerTurnID: String
    ) {
        guard stopRetirementsInFlight.insert(access).inserted else { return }
        let pendingReload = replacementLoad(for: access, forceFresh: true)
        let reserved = reservedConversations(for: access)
        let affected = processAffectedConversations(for: access)
        let targetConversations = Set(turnRoutes.compactMap { turnID, route in
            route.selection.access == access && stopRequestedTurnIDs.contains(turnID)
                ? route.conversationID : nil
        }).union(turnRoutes[triggerTurnID].map { [$0.conversationID] } ?? [])
        let delegateScopes = runtimeDelegatedWorkTerminationScopes(
            for: access,
            conversations: affected)
        let terminationSelections = runtimeTerminationSelections(
            for: access,
            conversations: affected)

        recoverPendingTurnStarts(for: access)
        if let currentID, affected.contains(currentID) {
            // Materialize interjection/auto-resume work before the transaction snapshot. Nothing
            // recovered from a forced retirement may auto-run against the replacement generation.
            let recoveredResume = autoResumePending ? pendingResume : nil
            resetVisibleTurnState(ifOwnedBy: reserved)
            if let recoveredResume {
                // The recovered interjection is now index zero. Preserve the original prompt as
                // the next quarantined action, ahead of queue entries that predated the redirect.
                queuedPrompts.insert(recoveredResume, at: min(1, queuedPrompts.count))
                updateCurrent { $0.queuedPrompts = queuedPrompts }
            }
            autoResumePending = false
            pendingResume = nil
        }

        let activeRuntime = runtimes.removeValue(forKey: access)
        agentToolCatalog.invalidate(access: access)
        runtimeGenerations[access] = nil
        runtimeCredentialEpochs[access] = nil
        pendingConversationLoads[access] = pendingReload
        markModelCatalogRuntimeUnavailable(access, message: "Provider runtime is retiring")
        clearTurnRouting(for: access)
        BackgroundProcessStore.shared.clear(
            BackgroundProcessSource(bridgeID: bridgeID, access: access))
        runningConvs.subtract(reserved)
        lastUnexpectedExitAt[access] = nil

        var state = laneStates[access] ?? RuntimeLaneState()
        state.ready = false
        state.mode = "retiring after Stop…"
        state.isLoggingIn = false
        laneStates[access] = state
        if access == currentModelAccess {
            if mcpStatusAccess == access { resetMcpStatusState() }
            projectLaneState(access)
        }

        // Collateral work is a provider-lane failure, not a user Stop in that sibling conversation.
        for conversationID in affected {
            let outcome: DelegatedWorkTerminationOutcome = targetConversations.contains(conversationID)
                ? .userStopped
                : .providerFailure(
                    "Stopped because the shared provider lane was retired after Stop did not finish in another conversation.")
            _ = terminalizeDelegatedWork(
                for: conversationID,
                outcome: outcome,
                scope: delegateScopes[conversationID] ?? .conversation,
                turnID: nil,
                selection: terminationSelections[conversationID],
                durable: false)
        }
        if let currentID, affected.contains(currentID) {
            // Fold the recovered queue and collateral/target terminalization into the canonical
            // resident snapshot before the per-conversation durability barrier advances it.
            persistCurrent()
        }

        var durableResults: [UUID: Bool] = [:]
        var processRetired = activeRuntime == nil
        let finishIfReady: () -> Void = { [weak self] in
            guard let self, processRetired, durableResults.count == affected.count else { return }
            self.stopRetirementsInFlight.remove(access)
            guard durableResults.values.allSatisfy({ $0 }) else {
                self.stopRecoveryBlockedConversations[access] = affected
                for conversationID in affected where durableResults[conversationID] == false {
                    let failureNotice = "Mechanician could not save the fresh-session recovery boundary, so \(access.displayName) remains unavailable. Your queued work is preserved and paused."
                    self.store.update(conversationID) { conversation in
                        if Self.shouldAppendSystemNotice(
                            failureNotice,
                            after: conversation.messages.last) {
                            var entry = TranscriptEntry(kind: .system, text: failureNotice)
                            entry.captureOrdinal = self.captureOrdinal(for: conversationID)
                            entry.runtimeRecoveryNotice = true
                            conversation.messages.append(entry)
                        }
                    }
                }
                var failedState = self.laneStates[access] ?? RuntimeLaneState()
                failedState.ready = false
                failedState.mode = "recovery save required"
                self.laneStates[access] = failedState
                if access == self.currentModelAccess { self.projectLaneState(access) }
                return
            }
            if let observer = self.stopRecoveryReplacementObserverForTesting {
                observer(access)
            } else {
                self.ensureRuntime(for: access)
            }
        }

        for conversationID in affected.sorted(by: { $0.uuidString < $1.uuidString }) {
            let isTarget = targetConversations.contains(conversationID)
            let notice = isTarget
                ? "Stop did not finish promptly. Mechanician retired \(access.displayName), ended this turn, and will use a fresh provider session. Queued messages are paused until you resume them."
                : "Mechanician retired \(access.displayName) after Stop did not finish in another conversation using this window. This turn ended without a provider acknowledgement and will use a fresh session. Queued messages are paused until you resume them."
            let ordinal = captureOrdinal(for: conversationID)
            let updated = store.updateAwaitingPersistence(conversationID, { conversation in
                conversation.sdkSessionId = nil
                conversation.sdkSessionRouteIdentity = nil
                conversation.sdkSessionExtensionRevision = nil
                conversation.sdkSessionToolProfile = nil
                conversation.sdkSessionWorkspaceInstructionsRevision = nil
                conversation.claudeEffectiveModel = nil
                conversation.contextTokens = nil
                conversation.contextWindow = nil
                conversation.contextModel = nil
                _ = stopUnfinishedToolEntries(
                    &conversation.messages,
                    captureOrdinal: ordinal)
                _ = Self.finishRunningProviderReview(
                    in: &conversation.messages,
                    status: .stopped,
                    message: "Review stopped because the provider runtime ended.")
                if Self.shouldAppendSystemNotice(notice, after: conversation.messages.last) {
                    var entry = TranscriptEntry(kind: .system, text: notice)
                    entry.captureOrdinal = ordinal
                    entry.runtimeRecoveryNotice = true
                    conversation.messages.append(entry)
                }
            }, completion: { published in
                durableResults[conversationID] = published
                finishIfReady()
            })
            if updated?.queuedPrompts.isEmpty == false {
                _ = store.pauseQueue(conversationID)
            }
        }

        // Refresh every duplicate viewer from the one canonical value and keep all recovered work
        // paused. Another provider lane/window remains entirely untouched.
        for bridge in Self.live.allObjects {
            guard let conversationID = bridge.currentID,
                  affected.contains(conversationID),
                  let conversation = store.conversation(conversationID) else { continue }
            bridge.entries = conversation.messages
            bridge.restoreContextUsage(from: conversation)
            bridge.reportedCompactionThreshold = nil
            bridge.clearPendingHistoryReplay()
            bridge.stagePendingHistoryReplay(conversation.messages, for: conversation)
            bridge.autoResumePending = false
            bridge.pendingResume = nil
            bridge.pendingInterject = nil
            bridge.queuedPrompts = conversation.queuedPrompts
        }

        activeRuntime?.retireImmediately {
            processRetired = true
            finishIfReady()
        }
        finishIfReady()
    }

    /// One lane exited unexpectedly. Recover only work owned by that access; every other provider
    /// process, queue, interaction, and foreground/background turn remains valid.
    private func handleDaemonExit(
        from access: ModelAccess,
        generation: UUID,
        exit: AgentdUnexpectedExit
    ) {
        guard runtimes[access] != nil, runtimeGenerations[access] == generation else { return }
        failPendingAccountCommand(
            for: access,
            message: "\(access.displayName) stopped during the account operation.",
            ownerRuntimeAlreadyExiting: true)
        let pendingReload = replacementLoad(for: access)
        let reserved = reservedConversations(for: access)
        let affected = processAffectedConversations(for: access)
        let delegateScopes = runtimeDelegatedWorkTerminationScopes(
            for: access,
            conversations: affected)
        let terminationSelections = runtimeTerminationSelections(
            for: access,
            conversations: affected)
        let queued = queuedConversations(for: access)
        let now = Date()
        let mayRestart = lastUnexpectedExitAt[access].map {
            now.timeIntervalSince($0) > 30
        } ?? true
        lastUnexpectedExitAt[access] = now
        recoverPendingTurnStarts(for: access)
        agentToolCatalog.invalidate(access: access, generation: generation)
        runtimes[access] = nil
        runtimeGenerations[access] = nil
        runtimeCredentialEpochs[access] = nil
        markModelCatalogRuntimeUnavailable(access, message: "Provider runtime stopped")
        pendingConversationLoads[access] = pendingReload
        clearTurnRouting(for: access)
        BackgroundProcessStore.shared.clear(
            BackgroundProcessSource(bridgeID: bridgeID, access: access))
        runningConvs.subtract(reserved)
        reconcileStuckRuns(
            owned: affected,
            scopes: delegateScopes,
            selections: terminationSelections)
        var state = laneStates[access] ?? RuntimeLaneState()
        state.ready = false
        state.mode = "agentd stopped"
        state.isLoggingIn = false
        laneStates[access] = state
        if access == currentModelAccess {
            if mcpStatusAccess == access { resetMcpStatusState() }
            resetVisibleTurnState(ifOwnedBy: reserved)
            projectLaneState(access)
        }

        let recovery = mayRestart
            ? "Its in-flight work was stopped; that provider is restarting."
            : "Its in-flight work was stopped. Automatic restart was paused after repeated exits; choose that account again to retry."
        let message = "\(access.displayName) exited unexpectedly (\(exit.terminalReason.lowercased())). \(recovery)"
        let hasPendingPluginControls = !(pendingClaudePluginControls[access]?.isEmpty ?? true)
        if !mayRestart, hasPendingPluginControls {
            failPendingClaudePluginControls(for: access, message: message)
        }
        let failureConversations = mayRestart ? affected : affected.union(queued)
        if !failureConversations.isEmpty {
            recordRuntimeFailure(
                for: access,
                conversations: failureConversations,
                message: message,
                errorKind: "unknown",
                providerError: [
                    "code": exit.diagnosticCode,
                    "terminalReason": exit.terminalReason,
                ])
        } else if access == currentModelAccess {
            appendSystem(message)
        }
        if !mayRestart, pendingRuntimeAccountReloads[access] != nil {
            Self.failAccountReloadOwner(for: access, message: message)
            pendingRuntimeAccountReloads[access] = nil
        }

        // A lane with background work must recover even when another provider is selected; otherwise
        // its durable queue can never receive a future `ready` event. Truly idle inactive lanes stay
        // lazy after a repeated failure.
        if mayRestart,
           access == currentModelAccess || !affected.isEmpty || !queued.isEmpty
            || hasPendingPluginControls || pendingRuntimeAccountReloads[access] != nil {
            DispatchQueue.main.async { [weak self] in
                guard let self, self.runtimes[access] == nil else { return }
                self.ensureRuntime(for: access)
            }
        }
    }

    private func reservedConversations(for access: ModelAccess) -> Set<UUID> {
        Set(turnRoutes.values.compactMap { route in
            route.selection.access == access && route.phase.reservesConversation
                ? route.conversationID : nil
        })
    }

    /// Every conversation whose still-live UI state depends on this process. Completed routes stay
    /// as delegate tombstones only for the provider turn that actually owns an active child. A
    /// different provider may have a newer completed route for the same conversation; its runtime
    /// exiting must not terminalize the older lane's delegate.
    private func processAffectedConversations(for access: ModelAccess) -> Set<UUID> {
        let routes = turnRoutes.compactMap {
            turnID, route -> (
                conversationID: UUID,
                turnID: String,
                reservesConversation: Bool
            )? in
            guard route.selection.access == access else { return nil }
            return (
                conversationID: route.conversationID,
                turnID: turnID,
                reservesConversation: route.phase.reservesConversation)
        }
        let conversationIDs = Set(routes.map { $0.conversationID })
        let ownerTurnIDs = Dictionary(uniqueKeysWithValues: conversationIDs.map {
            ($0, delegateOwnerTurnIDs(for: $0))
        })
        return conversationIDsAffectedByScopedProcessTermination(
            routes,
            delegateOwnerTurnIDs: ownerTurnIDs)
    }

    /// Capture the exact delegate lanes owned by one provider runtime before its routes are cleared.
    /// Reserved parent turns are included for children that already point at that turn; completed
    /// tombstones are included only when the delegate-owner projection points back to them.
    private func runtimeDelegatedWorkTerminationScopes(
        for access: ModelAccess,
        conversations: Set<UUID>
    ) -> [UUID: DelegatedWorkTerminationScope] {
        Dictionary(uniqueKeysWithValues: conversations.map { conversationID in
            let providerRoutes = turnRoutes.filter {
                $0.value.conversationID == conversationID
                    && $0.value.selection.access == access
            }
            let providerTurnIDs = Set(providerRoutes.keys)
            let reservedTurnIDs = Set(providerRoutes.compactMap {
                $0.value.phase.reservesConversation ? $0.key : nil
            })
            let exactOwners = delegateOwnerTurnIDs(
                for: conversationID,
                includeConservativeFallback: false)
            let conservativeOwners = delegateOwnerTurnIDs(for: conversationID)
            let fallbackOwners = conservativeOwners.subtracting(exactOwners)
            let ownedTurnIDs = providerTurnIDs.intersection(conservativeOwners)
                .union(reservedTurnIDs)
            return (
                conversationID,
                .owners(
                    turnIDs: ownedTurnIDs,
                    providerAccess: access,
                    includesUnattributed:
                        !ownedTurnIDs.isDisjoint(with: fallbackOwners)))
        })
    }

    private func runtimeTerminationSelections(
        for access: ModelAccess,
        conversations: Set<UUID>
    ) -> [UUID: ModelSelection] {
        Dictionary(uniqueKeysWithValues: conversations.compactMap { conversationID in
            turnRoutes.values.first {
                $0.conversationID == conversationID
                    && $0.selection.access == access
            }.map { (conversationID, $0.selection) }
        })
    }

    private func hasRunningDelegates(_ conversationID: UUID) -> Bool {
        if conversationID == currentID {
            return hasNonterminalDelegatedWork(
                workflowRuns: workflowRuns,
                subagents: subagents)
        }
        guard let conversation = store.conversation(conversationID) else { return false }
        return hasNonterminalDelegatedWork(
            workflowRuns: conversation.workflowRuns,
            subagents: conversation.subagents)
    }

    /// Exact completed-turn ownership for this conversation's currently nonterminal delegates.
    /// Current published maps win over the durable store just as they do for rendering/Stop.
    private func delegateOwnerTurnIDs(
        for conversationID: UUID,
        includeConservativeFallback: Bool = true
    ) -> Set<String> {
        let state: (
            workflowRuns: [String: WorkflowRun],
            subagents: [String: SubagentRun],
            agentActivity: [AgentActivityRecord]
        )?
        if conversationID == currentID {
            state = (workflowRuns, subagents, agentActivity)
        } else if let conversation = store.conversation(conversationID) {
            state = (
                conversation.workflowRuns,
                conversation.subagents,
                conversation.agentActivity)
        } else {
            state = nil
        }
        guard let state else { return [] }

        let completedRoutes = turnRoutes.compactMap {
            turnID, route -> (
                turnID: String,
                completedAt: Date,
                providerAccess: ModelAccess
            )? in
            guard route.conversationID == conversationID,
                  route.purpose == .conversation,
                  let completedAt = route.phase.completedAt else { return nil }
            return (turnID, completedAt, route.selection.access)
        }
        let fallbackTurnID = includeConservativeFallback
            ? conservativeDelegateFallbackTurnID(
                agentActivity: state.agentActivity,
                completedRoutes: completedRoutes)
            : nil
        return activeDelegateOwnerTurnProjection(
            workflowRuns: state.workflowRuns,
            subagents: state.subagents,
            agentActivity: state.agentActivity,
            fallbackTurnID: fallbackTurnID)
            .turnIDs
    }

    private func queuedConversations(for access: ModelAccess) -> Set<UUID> {
        let reservedQueueIDs: Set<UUID> = Set(queueReservations.values.compactMap { reservation in
            reservation.selection?.access == access ? reservation.conversationID : nil
        })
        return Set<UUID>(store.conversations.compactMap { conversation in
            let ownedHere = conversation.id == currentID
                || AgentBridge.owner(of: conversation.id) === self
                || claimedQueueConversations.contains(conversation.id)
                || reservedQueueIDs.contains(conversation.id)
            return ownedHere && conversation.modelSelection?.access == access
                && !conversation.queuedPrompts.isEmpty
                ? conversation.id : nil
        })
    }

    /// Preserve an already-staged force-fresh load, otherwise reload the visible conversation after
    /// replacing its lane so cwd and opaque session ownership never fall back to daemon defaults.
    private func replacementLoad(
        for access: ModelAccess,
        forceFresh: Bool = false
    ) -> PendingConversationLoad? {
        if var pending = pendingConversationLoads[access] {
            if forceFresh { pending.forceFresh = true }
            return pending
        }
        guard let conversation = currentConversation,
              (conversation.modelSelection?.access ?? currentModelAccess) == access else { return nil }
        return PendingConversationLoad(
            conversationID: conversation.id, cwd: conversation.cwd, forceFresh: forceFresh)
    }

    private func recordRuntimeFailure(
        for access: ModelAccess,
        conversations affected: Set<UUID>,
        message: String,
        errorKind: String = "unknown",
        providerError: [String: Any]? = nil
    ) {
        let provider: String
        switch access {
        case .claudeSubscription, .anthropicAPI, .claudeVertex, .claudeBedrock:
            provider = "anthropic"
        case .codexSubscription: provider = "codex"
        case .openAIAPI: provider = "openai"
        }
        var event: [String: Any] = [
            "message": message,
            "errorKind": errorKind,
            "access": access.rawValue,
            "provider": provider,
        ]
        if let providerError { event["providerError"] = providerError }
        for conversationID in affected where store.contains(conversationID) {
            let entry = Self.errorEntry(from: event, access: access)
            let watched = AgentBridge.isActivelyWatched(conversationID)
            if conversationID == currentID {
                appendError(entry)
                store.update(conversationID) { conversation in
                    conversation.errored = true
                    if !watched { conversation.unread = true }
                }
            } else {
                store.update(conversationID) { conversation in
                    conversation.messages.append(capturedTranscriptEntry(
                        entry,
                        conversationID: conversationID))
                    conversation.errored = true
                    if !watched { conversation.unread = true }
                }
            }
            if !watched {
                NotificationManager.shared.notify(
                    title: "Error — \(store.conversation(conversationID)?.displayTitle ?? "Mechanician")",
                    body: message, conversationID: conversationID)
            }
        }
        if let currentID, affected.contains(currentID) { persistCurrent() }
    }

    /// Move provider-specific queued work into a durable app-owned Connect request when its route
    /// starts without usable credentials. The prompt remains visible/recoverable without an error
    /// row plus a second hidden copy in the ordinary queue.
    private func reportBlockedQueuedWorkIfNeeded(for access: ModelAccess) {
        // Use the same three-way account/runtime evidence as provider-setup recovery: starting and
        // credential-mutation lanes wait, verified lanes drain, and only a settled rejection parks.
        guard ProviderSetupRecovery.runtimeEvidence(
            accountOperationInFlight: ProviderAccountStore.shared.operation(for: access) != nil,
            runtimeIsReady: isRuntimeReady(access),
            runtimeIsUsable: isRuntimeUsable(access)
        ) == .rejected else { return }
        let queued = queuedConversations(for: access)
        guard !queued.isEmpty else { return }
        var parkedAny = false
        for conversationID in queued {
            parkedAny = parkBlockedQueuedWork(for: conversationID, access: access) || parkedAny
        }
        if parkedAny, let currentID, queued.contains(currentID) {
            persistCurrent()
        }
    }

    private func resetVisibleTurnState(ifOwnedBy owned: Set<UUID>) {
        guard let currentID, owned.contains(currentID) else { return }
        flushAssistant()
        if let interjection = pendingInterject {
            // No terminal event will arrive to dispatch it. Put it back at the queue head; retain the
            // optional auto-resume prompt so it follows this interjection after the lane recovers.
            enqueueCurrent(interjection, atFront: true)
            pendingInterject = nil
        }
        isStreaming = false
        isWorking = false
        turnStartedAt = nil
        activeAgents = 0
        assistantIndex = nil
        if stopUnfinishedToolEntries(
            &entries,
            captureOrdinal: captureOrdinal(for: currentID)
        ) {
            currentConversationNeedsPersistence = true
        }
        if Self.finishRunningProviderReview(
            in: &entries,
            status: .stopped,
            message: "Review stopped because the provider runtime ended."
        ) {
            currentConversationNeedsPersistence = true
        }
    }

    /// Apply the shared delegate terminalization reducer to one conversation. Foreground callers
    /// mutate the published snapshot and let their surrounding terminal transaction persist it;
    /// background callers use `updateLive` for the same reason. Runtime-exit recovery can request an
    /// immediate durable write because no later provider terminal event is guaranteed.
    @discardableResult
    private func terminalizeDelegatedWork(
        for conversationID: UUID,
        outcome: DelegatedWorkTerminationOutcome,
        scope: DelegatedWorkTerminationScope = .conversation,
        turnID: String?,
        selection: ModelSelection?,
        durable: Bool,
        at observedAt: Date = Date()
    ) -> Bool {
        if conversationID == currentID {
            let changed = terminalizeDelegatedWorkState(
                workflowRuns: &workflowRuns,
                subagents: &subagents,
                agentActivity: &agentActivity,
                outcome: outcome,
                scope: scope,
                turnID: turnID,
                selection: selection,
                at: observedAt,
                captureOrdinal: self.captureOrdinal(for: conversationID))
            if !hasNonterminalDelegatedWork(
                workflowRuns: workflowRuns,
                subagents: subagents) {
                activeAgents = 0
            }
            if changed {
                currentConversationNeedsPersistence = true
                if durable { persistCurrent() }
            }
            return changed
        }

        var changed = false
        let mutation: (inout Conversation) -> Void = { conversation in
            changed = terminalizeDelegatedWorkState(
                workflowRuns: &conversation.workflowRuns,
                subagents: &conversation.subagents,
                agentActivity: &conversation.agentActivity,
                outcome: outcome,
                scope: scope,
                turnID: turnID,
                selection: selection ?? conversation.modelSelection,
                at: observedAt,
                captureOrdinal: self.captureOrdinal(for: conversationID))
        }
        if durable {
            store.update(conversationID, mutation)
        } else {
            store.updateLive(conversationID, mutation)
        }
        return changed
    }

    /// Flip non-terminal workflow/subagent runs to `.stopped` for the conversations THIS bridge's
    /// daemon was driving (`owned` = its in-flight turns) — a run can't outlive the daemon that
    /// drove it, so a lingering `.running` is a stranded spinner.
    ///
    /// Scoped to `owned`, NEVER blanket across the whole store: the store's list also holds
    /// conversations ANOTHER window's daemon is running, and republishing a false "stopped" for
    /// those would stomp that window's live background workflow. A conversation runs in exactly one
    /// daemon, so `owned` (this bridge's in-flight turns) is the exclusive set we may heal.
    private func reconcileStuckRuns(
        owned: Set<UUID>,
        scopes: [UUID: DelegatedWorkTerminationScope]? = nil,
        selections: [UUID: ModelSelection] = [:]
    ) {
        guard !owned.isEmpty else { return }
        let observedAt = Date()
        for id in owned.sorted(by: { $0.uuidString < $1.uuidString }) {
            let selection = selections[id] ?? turnRoutes.values.first(where: {
                $0.conversationID == id
            })?.selection ?? store.conversation(id)?.modelSelection
            let scope = scopes?[id] ?? .conversation
            _ = terminalizeDelegatedWork(
                for: id,
                outcome: .userStopped,
                scope: scope,
                turnID: nil,
                selection: selection,
                durable: false,
                at: observedAt)

            if id == currentID {
                if stopUnfinishedToolEntries(
                    &entries,
                    captureOrdinal: captureOrdinal(for: id)
                ) {
                    currentConversationNeedsPersistence = true
                }
                if Self.finishRunningProviderReview(
                    in: &entries,
                    status: .stopped,
                    message: "Review stopped because the provider runtime ended."
                ) {
                    currentConversationNeedsPersistence = true
                }
                // The shared reducer changed the published maps. Persist that exact snapshot now;
                // a runtime exit has no guaranteed done/error event to flush it later.
                persistCurrent()
            } else {
                store.update(id) { conversation in
                    _ = stopUnfinishedToolEntries(
                        &conversation.messages,
                        captureOrdinal: captureOrdinal(for: id))
                    _ = Self.finishRunningProviderReview(
                        in: &conversation.messages,
                        status: .stopped,
                        message: "Review stopped because the provider runtime ended.")
                }
            }
        }
    }

    // MARK: Sending

    /// Send a prompt — or, if a turn is running, queue it to run after this one.
    /// A "/btw " prefix interjects (interrupt now, then auto-resume the original).
    func send(_ prompt: String) {
        let trimmed = prompt.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        guard currentProviderAccessRequest == nil else { return }
        if let reason = managedEnterprisePolicy?.turnBlockReason(
            for: currentModelAccess) {
            appendSystem(reason)
            return
        }
        if trimmed.lowercased().hasPrefix("/btw ") {
            interject(String(trimmed.dropFirst(5)), autoResume: true)
            return
        }
        if currentConversationHasReservedTurn {
            enqueueCurrent(trimmed)
            return
        }
        // The same conversation can be displayed (idle) in more than one window/tab. NEVER start a
        // second concurrent turn on one SDK session — hand the prompt to the window already live on
        // it and go there (protect the live turn from session corruption).
        if let id = currentID,
           let live = AgentBridge.live.allObjects.first(where: {
               $0 !== self && ($0.runningConvs.contains(id) || $0.pendingTurnStartID(for: id) != nil)
           }) {
            store.update(id) { $0.queuedPrompts.append(trimmed) }
            if live.currentID == id { live.queuedPrompts.append(trimmed) }
            if let win = live.window { win.makeKeyAndOrderFront(nil); NSApp.activate(ignoringOtherApps: true) }
            return
        }
        // The daemon streams turns concurrently — one per conversation — so a turn running
        // in another conversation no longer blocks this one. Each turn carries its own
        // session and working dir, so they run truly in parallel without cross-wiring.
        if !performSend(trimmed) {
            enqueueCurrent(trimmed)
            // A settled disconnected lane promotes the prompt into an actionable provider request
            // inside enqueueCurrent. Do not follow that card with a contradictory generic queue
            // notice; starting/unknown lanes still get the ordinary explanation.
            if currentProviderAccessRequest == nil {
                appendSystem("This conversation's provider runtime is not available yet; the prompt remains queued.")
            }
        }
    }

    /// Deliver feedback to the provider's current turn at its next natural control boundary.
    /// The user message appears immediately, but is not marked delivered until agentd confirms
    /// that the exact provider turn accepted it. A rejection races safely into the next-turn queue.
    @discardableResult
    func guide(
        _ prompt: String,
        preservingEntryID entryID: UUID? = nil,
        author: TranscriptEntry.GuidanceAuthor? = nil
    ) -> Bool {
        let trimmed = prompt.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }
        guard currentProviderAccessRequest == nil else { return false }

        // Consistent steering: steer now if the turn is active; if a turn is still starting under a
        // steer-capable provider, hold the steer and deliver it when the turn goes active; only when
        // no steerable turn is coming does it become the next queued message. Choosing Send next (or
        // any other mode) in the composer routes here explicitly instead.
        switch Self.steerDisposition(
            canSteerNow: canGuideCurrentTurn,
            turnStartingSteerable: startingConversationTurnIsSteerable,
            requiresFreshProviderSession: currentTurnRequiresFreshProviderSession) {
        // Injected guidance is TIMELY, not queued. A remembered policy is worth saying while the
        // action it concerns is in flight; the same words arriving as an ordinary prompt one turn
        // later are a non-sequitur the person never typed. So every route except "steer it now"
        // drops it, and nothing is lost, because the policy is still in the wiki to fire again.
        case .queueAsNext:
            guard author == nil else { return false }
            sendNext(trimmed); return true
        case .bufferUntilActive:
            guard author == nil else { return false }
            bufferStartSteer(trimmed); return true
        case .sendNow:          break
        }
        guard let turnID = currentTurnId, let route = turnRoutes[turnID],
              route.purpose == .conversation, let conversationID = currentID else {
            guard author == nil else { return false }
            sendNext(trimmed)   // defensive: .sendNow implies these hold, but never lose the input
            return true
        }

        // Guidance is a real conversational boundary inside this provider turn. Flush any text
        // already on screen and close that assistant segment before inserting the user row; deltas
        // produced after the provider accepts the guidance must appear beneath it, never continue
        // mutating an earlier assistant row above it.
        closeAssistantBeforeStructuralEntry()
        var entry = TranscriptEntry(kind: .user, text: trimmed)
        if let entryID { entry.id = entryID }
        entry.imagePaths = Self.imagePaths(in: trimmed)
        entry.guidanceAuthor = author
        entry.guidanceState = .sending
        entry = capturedTranscriptEntry(entry, conversationID: conversationID)
        entries.append(entry)
        currentConversationNeedsPersistence = true
        persistCurrent()

        let steerID = UUID().uuidString
        guidanceSequence += 1
        pendingGuidance[steerID] = PendingGuidance(
            conversationID: conversationID,
            turnID: turnID,
            prompt: trimmed,
            entryID: entry.id,
            selection: route.selection,
            sequence: guidanceSequence,
            submittedAt: Date())
        pendingGuidance[steerID]?.author = author
        scheduleGuidanceWatchdog(for: turnID)
        let providerPrompt = Self.providerPrompt(
            from: trimmed,
            conversationID: conversationID,
            store: store)
        // A steer can change provider behavior just as materially as a first prompt or permission
        // response. Do not expose it to the provider until the exact provisional user row has
        // crossed the selected authority's durable publication edge.
        persistCurrent(awaitingPersistence: { [weak self] published in
            guard let self, self.pendingGuidance[steerID] != nil else { return }
            guard published else {
                self.fallbackGuidance(
                    steerID,
                    reason: "The guidance was not sent because the conversation could not be saved.")
                return
            }
            guard let liveRoute = self.turnRoutes[turnID],
                  liveRoute.purpose == .conversation,
                  liveRoute.conversationID == conversationID,
                  liveRoute.phase.isActive else {
                self.fallbackGuidance(
                    steerID,
                    reason: "The turn ended before the saved guidance could be delivered.")
                return
            }
            let interaction = InteractionRoute(turnID: turnID, route: liveRoute)
            let request: [String: Any] = [
                "type": "steer",
                "id": turnID,
                "turnId": turnID,
                "steerId": steerID,
                "prompt": providerPrompt,
            ]
            guard self.write(request, to: interaction) else {
                self.fallbackGuidance(
                    steerID,
                    reason: "The provider connection was unavailable when guidance was sent.")
                return
            }
        })
        return true
    }

    /// Explicitly preserve a message for the next turn even when native steering is available.
    func sendNext(_ prompt: String) {
        let trimmed = prompt.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        guard currentProviderAccessRequest == nil else { return }
        if currentConversationHasReservedTurn {
            enqueueCurrent(trimmed)
        } else {
            send(trimmed)
        }
    }

    private func markGuidanceDelivered(_ steerID: String) {
        guard let pending = pendingGuidance.removeValue(forKey: steerID) else { return }
        // Recorded on the acknowledgement rather than on submission: `steer_ack` is the daemon's
        // proof that the guidance actually crossed into the running turn. A steer that never landed
        // says nothing about the work.
        //
        // ONLY when the person wrote it. `.steered` means "they redirected the work"; app-authored
        // guidance must never be attributed to the person as a correction.
        cancelGuidanceWatchdogIfIdle(for: pending.turnID)
        recordAgentActivity(
            .interjection(
                pending.prompt,
                disposition: .delivered,
                turnID: pending.turnID,
                at: pending.submittedAt),
            conversationID: pending.conversationID,
            turnID: pending.turnID,
            selection: pending.selection,
            durable: pending.conversationID != currentID)
        if pending.conversationID == currentID {
            if let index = entries.firstIndex(where: { $0.id == pending.entryID }) {
                entries[index].guidanceState = .delivered
                entries[index].guidanceFailureReason = nil
                currentConversationNeedsPersistence = true
            }
            persistCurrent()
        } else {
            store.update(pending.conversationID) { conversation in
                if let index = conversation.messages.firstIndex(where: { $0.id == pending.entryID }) {
                    conversation.messages[index].guidanceState = .delivered
                    conversation.messages[index].guidanceFailureReason = nil
                }
            }
        }
    }

    /// If the provider cannot accept guidance (including a terminal race), move the provisional
    /// user row into the durable FIFO queue. Undelivered text is pending work, not transcript
    /// history; representing it in both places made cancellation ambiguous and looked like a
    /// duplicate send.
    private func fallbackGuidance(_ steerID: String, reason _: String) {
        guard let pending = pendingGuidance.removeValue(forKey: steerID) else { return }
        cancelGuidanceWatchdogIfIdle(for: pending.turnID)
        // Injected guidance is dropped, never queued. The ordinary fallback appends the prompt to
        // `queuedPrompts`, which would send a policy the person never typed as their next message.
        guard pending.author == nil else {
            if pending.conversationID == currentID {
                Self.removeUndeliveredGuidanceEntry(pending.entryID, from: &entries)
                currentConversationNeedsPersistence = true
                persistCurrent()
            } else {
                store.update(pending.conversationID) { conversation in
                    Self.removeUndeliveredGuidanceEntry(
                        pending.entryID, from: &conversation.messages)
                }
            }
            return
        }
        recordAgentActivity(
            .interjection(
                pending.prompt,
                disposition: .queued,
                turnID: pending.turnID,
                at: pending.submittedAt),
            conversationID: pending.conversationID,
            turnID: pending.turnID,
            selection: pending.selection,
            durable: pending.conversationID != currentID)
        claimedQueueConversations.insert(pending.conversationID)
        if pending.conversationID == currentID {
            Self.removeUndeliveredGuidanceEntry(pending.entryID, from: &entries)
            queuedPrompts.append(pending.prompt)   // FIFO: keep the order the user typed the steers
            currentConversationNeedsPersistence = true
            persistCurrent()
            updateCurrent { conversation in
                Self.stampLegacySelection(pending.selection, on: &conversation)
            }
        } else {
            store.update(pending.conversationID) { conversation in
                Self.removeUndeliveredGuidanceEntry(pending.entryID, from: &conversation.messages)
                conversation.queuedPrompts.append(pending.prompt)   // FIFO: keep typed order
                Self.stampLegacySelection(pending.selection, on: &conversation)
            }
        }
        synchronizeVisibleQueue(for: pending.conversationID)
    }

    private func fallbackPendingGuidance(for turnID: String, reason: String) {
        // Re-queue in the order the user typed the steers, not the arbitrary order a dictionary
        // yields — otherwise several steers that fall back together reverse and shuffle in the queue.
        let steerIDs = Self.orderedFallbackSteerIDs(
            pendingGuidance.compactMap { key, value in
                value.turnID == turnID ? (key: key, sequence: value.sequence) : nil
            })
        for steerID in steerIDs { fallbackGuidance(steerID, reason: reason) }
    }

    /// Steers that fall back to the queue must re-enter it in the order they were typed, not the
    /// arbitrary order a dictionary yields. Returns the steerIDs sorted by typed sequence.
    static func orderedFallbackSteerIDs(_ pending: [(key: String, sequence: Int)]) -> [String] {
        pending.sorted { $0.sequence < $1.sequence }.map(\.key)
    }

    /// Guidance waits for the provider's next control boundary, which a healthy long turn can push
    /// well past any fixed deadline. Bind patience to turn *liveness*: this watchdog resets on every
    /// turn activity (noteTurnActivity) and only falls the steer back to the durable queue after the
    /// turn falls silent for the stall window. Turn-end (completeTurn) and connection loss (a failed
    /// write) remain the primary resolutions; this only catches a wedged-but-alive provider.
    private func scheduleGuidanceWatchdog(for turnID: String) {
        let deadline = Date().addingTimeInterval(Self.turnInactivityTimeout)
        if let timer = guidanceWatchdogs[turnID], timer.isValid {
            timer.fireDate = deadline
            return
        }
        let timer = Timer(fire: deadline, interval: 0, repeats: false) { [weak self] _ in
            Task { @MainActor in
                guard let self else { return }
                self.guidanceWatchdogs[turnID] = nil
                self.fallbackPendingGuidance(
                    for: turnID,
                    reason: "The provider went idle before confirming guidance; it was queued for the next turn.")
            }
        }
        guidanceWatchdogs[turnID] = timer
        RunLoop.main.add(timer, forMode: .common)
    }

    private func cancelGuidanceWatchdogIfIdle(for turnID: String) {
        guard !pendingGuidance.values.contains(where: { $0.turnID == turnID }) else { return }
        guidanceWatchdogs.removeValue(forKey: turnID)?.invalidate()
    }

    /// Retract an in-flight steer the user sent by mistake. It has not entered provider history yet,
    /// so drop the local pending state, stop the watchdog, best-effort ask the runtime to discard it,
    /// and remove the provisional transcript row. A steer the provider already ingested at its boundary
    /// cannot be recalled; this is the honest best-effort retraction before that delivery.
    @discardableResult
    private func retractInFlightGuidance(_ entryID: UUID) -> PendingGuidance? {
        guard let steerID = pendingGuidance.first(where: { $0.value.entryID == entryID })?.key,
              let pending = pendingGuidance.removeValue(forKey: steerID) else { return nil }
        cancelGuidanceWatchdogIfIdle(for: pending.turnID)
        if let route = turnRoutes[pending.turnID] {
            _ = write([
                "type": "steer_cancel",
                "id": pending.turnID,
                "turnId": pending.turnID,
                "steerId": steerID,
            ], to: InteractionRoute(turnID: pending.turnID, route: route))
        }
        if pending.conversationID == currentID {
            Self.removeUndeliveredGuidanceEntry(pending.entryID, from: &entries)
            currentConversationNeedsPersistence = true
            persistCurrent()
        } else {
            store.update(pending.conversationID) { conversation in
                Self.removeUndeliveredGuidanceEntry(pending.entryID, from: &conversation.messages)
            }
        }
        return pending
    }

    /// Remove guidance buffered behind a root that is still awaiting `turn_started`. It has not
    /// reached agentd yet, so no protocol cancellation is necessary.
    private func retractBufferedStartGuidance(_ entryID: UUID) -> TranscriptEntry? {
        guard let owner = currentID else { return nil }
        return Self.takeBufferedStartGuidance(
            entryID,
            conversationID: owner,
            from: &pendingStartSteers)
    }

    /// Conversation-scoped extraction shared by Cancel and Stop-and-Redirect. A stale action from a
    /// previous conversation must never retract a same-process steer owned by another tab/window.
    static func takeBufferedStartGuidance(
        _ entryID: UUID,
        conversationID: UUID,
        from pending: inout [UUID: [TranscriptEntry]]
    ) -> TranscriptEntry? {
        guard var steers = pending[conversationID],
              let index = steers.firstIndex(where: { $0.id == entryID }) else { return nil }
        let entry = steers.remove(at: index)
        if steers.isEmpty {
            pending[conversationID] = nil
        } else {
            pending[conversationID] = steers
        }
        return entry
    }

    func cancelInFlightGuidance(_ entryID: UUID) {
        if retractBufferedStartGuidance(entryID) != nil { return }
        _ = retractInFlightGuidance(entryID)
    }

    /// Upgrade guidance that is still waiting for provider acknowledgement to Stop-and-Redirect.
    /// Retraction owns the steer exactly once, so a late acknowledgement or a repeated click cannot
    /// both deliver the old steer and start the redirect.
    @discardableResult
    func redirectInFlightGuidance(_ entryID: UUID) -> Bool {
        if let buffered = retractBufferedStartGuidance(entryID) {
            stopAndRedirect(buffered.text)
            return true
        }
        guard pendingGuidance.values.contains(where: {
            $0.entryID == entryID && $0.conversationID == currentID
        }), let pending = retractInFlightGuidance(entryID) else { return false }
        stopAndRedirect(pending.prompt)
        return true
    }

    @discardableResult
    static func removeUndeliveredGuidanceEntry(
        _ entryID: UUID,
        from messages: inout [TranscriptEntry]
    ) -> Bool {
        guard let index = messages.firstIndex(where: { $0.id == entryID }),
              let state = messages[index].guidanceState,
              state == .sending || state == .queued || state == .cancelled else { return false }
        messages.remove(at: index)
        return true
    }

    private func handleGuidanceEvent(_ event: [String: Any], accepted: Bool) {
        guard let steerID = event["steerId"] as? String,
              let pending = pendingGuidance[steerID],
              event["id"] as? String == pending.turnID else { return }
        if accepted { markGuidanceDelivered(steerID) }
        else {
            fallbackGuidance(
                steerID,
                reason: event["message"] as? String
                    ?? "The provider rejected guidance for this turn.")
        }
    }

    /// Interrupt the running turn and run this prompt now, remembering the original
    /// so it can be resumed (auto-resumed for /btw).
    func interject(_ prompt: String, autoResume: Bool = false) {
        let trimmed = prompt.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        guard currentProviderAccessRequest == nil else { return }
        if let currentID, pendingTurnStartID(for: currentID) != nil {
            // The original prompt has not been accepted yet, so there is no running turn to
            // interrupt or resume. Preserve the interjection as the next FIFO item without arming
            // pendingInterject/auto-resume state that could later duplicate it.
            enqueueCurrent(trimmed, atFront: true)
            return
        }
        if let currentID,
           let owner = AgentBridge.live.allObjects.first(where: {
               $0 !== self && ($0.runningConvs.contains(currentID)
                   || $0.pendingTurnStartID(for: currentID) != nil)
           }) {
            store.update(currentID) { $0.queuedPrompts.insert(trimmed, at: 0) }
            if owner.currentID == currentID { owner.queuedPrompts.insert(trimmed, at: 0) }
            return
        }
        guard let activeTurnID = currentTurnId else {
            if !performSend(trimmed) { enqueueCurrent(trimmed) }
            return
        }
        if let route = turnRoutes[activeTurnID], case .codexReview = route.purpose {
            // Review has no user prompt to resume. Queue the redirect after the targeted Stop,
            // without resurrecting the last historical prompt as a misleading resume chip.
            pendingResume = nil
            autoResumePending = false
            pendingInterject = trimmed
            interrupt()
            return
        }
        if let lastUser = entries.last(where: { $0.kind == .user }) { pendingResume = lastUser.text }
        autoResumePending = autoResume
        pendingInterject = trimmed
        interrupt() // agentd ends the turn → done/error dispatches the interject
    }

    /// Stop every active root/delegate owned by this conversation, then run the new direction once.
    ///
    /// This is deliberately stronger than `interject`: an ordinary interjection may preserve
    /// legitimate background delegates, while the explicit Stop-and-Redirect action means the user
    /// is abandoning the current direction. The live UI caught the distinction: interrupting only
    /// the root started the new prompt while four old agent cards kept running.
    func stopAndRedirect(_ prompt: String, autoResume: Bool = false) {
        let trimmed = prompt.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        guard currentProviderAccessRequest == nil else { return }
        if hasStoppableConversationWork {
            stopConversationWork()
        }
        // An active root remains routed until its terminal event arrives. `interject` stages the
        // exact prompt for dispatch at that boundary; `interrupt()` is idempotent for that route.
        // Delegate-only work was terminalized synchronously above, so this starts immediately.
        interject(trimmed, autoResume: autoResume)
    }

    /// Re-run the prompt that was interrupted by an interjection.
    func resume() {
        guard let p = pendingResume else { return }
        pendingResume = nil
        send(p)
    }

    /// Dismiss the resume chip without re-running the interrupted prompt. Clears the private
    /// interject/auto-resume flags too, so a later turn can't stray-dispatch the discarded prompt.
    func cancelResume() {
        pendingResume = nil
        pendingInterject = nil
        autoResumePending = false
    }

    func clearQueue() {
        let guidanceIDs = Self.queuedGuidanceEntryIDs(
            prompts: queuedPrompts, messages: entries).compactMap { $0 }
        entries.removeAll { guidanceIDs.contains($0.id) }
        queuedPrompts.removeAll()
        if let currentID {
            claimedQueueConversations.remove(currentID)
            pendingStartRetryBarriers[currentID] = nil
        }
        updateCurrent {
            $0.queuedPrompts = queuedPrompts
            $0.messages.removeAll { guidanceIDs.contains($0.id) }
        }
    }
    func removeQueued(at index: Int) {
        guard queuedPrompts.indices.contains(index) else { return }
        let guidanceID = Self.queuedGuidanceEntryIDs(
            prompts: queuedPrompts, messages: entries)[index]
        queuedPrompts.remove(at: index)
        if let guidanceID { entries.removeAll { $0.id == guidanceID } }
        if queuedPrompts.isEmpty, let currentID {
            claimedQueueConversations.remove(currentID)
            pendingStartRetryBarriers[currentID] = nil
        }
        updateCurrent {
            $0.queuedPrompts = queuedPrompts
            if let guidanceID { $0.messages.removeAll { $0.id == guidanceID } }
        }
    }

    /// Remove one exact queue row and upgrade it to Stop-and-Redirect. The caller supplies the
    /// queue snapshot that rendered its button; if a turn-end drain or another edit won the race,
    /// the stale action is ignored instead of redirecting a different row at the shifted index.
    @discardableResult
    func redirectQueued(at index: Int, expectedQueue: [String]) -> Bool {
        guard let prompt = Self.takeQueuedPromptForRedirect(
            at: index,
            expectedQueue: expectedQueue,
            prompts: &queuedPrompts,
            messages: &entries) else { return false }
        if let currentID {
            // The user explicitly chose this recovered row. That decision, unlike an automatic
            // queue drain, is allowed to try the unchanged lane again.
            pendingStartRetryBarriers[currentID] = nil
        }
        if queuedPrompts.isEmpty, let currentID {
            claimedQueueConversations.remove(currentID)
        }
        let remainingPrompts = queuedPrompts
        let remainingEntries = entries
        updateCurrent {
            $0.queuedPrompts = remainingPrompts
            $0.messages = remainingEntries
        }
        stopAndRedirect(prompt)
        return true
    }

    /// Pure queue extraction used by the action above and its race/order regression tests.
    static func takeQueuedPromptForRedirect(
        at index: Int,
        expectedQueue: [String],
        prompts: inout [String],
        messages: inout [TranscriptEntry]
    ) -> String? {
        guard prompts == expectedQueue, prompts.indices.contains(index) else { return nil }
        let guidanceID = queuedGuidanceEntryIDs(
            prompts: prompts,
            messages: messages)[index]
        let prompt = prompts.remove(at: index)
        if let guidanceID { messages.removeAll { $0.id == guidanceID } }
        return prompt
    }

    /// Replace a queued prompt in place (inline editing before it runs).
    func updateQueued(at index: Int, _ text: String) {
        guard queuedPrompts.indices.contains(index) else { return }
        let guidanceID = Self.queuedGuidanceEntryIDs(
            prompts: queuedPrompts, messages: entries)[index]
        queuedPrompts[index] = text
        if let guidanceID,
           let entryIndex = entries.firstIndex(where: { $0.id == guidanceID }) {
            entries[entryIndex].text = text
            entries[entryIndex].imagePaths = Self.imagePaths(in: text)
        }
        updateCurrent {
            $0.queuedPrompts = queuedPrompts
            if let guidanceID,
               let entryIndex = $0.messages.firstIndex(where: { $0.id == guidanceID }) {
                $0.messages[entryIndex].text = text
                $0.messages[entryIndex].imagePaths = Self.imagePaths(in: text)
            }
        }
    }

    /// Map queue rows to their failed-guidance transcript rows. Fallbacks now append to the queue in
    /// typed order (matching the transcript), so consume candidates oldest-first, without reusing one
    /// row for identical guidance text.
    static func queuedGuidanceEntryIDs(
        prompts: [String],
        messages: [TranscriptEntry]
    ) -> [UUID?] {
        var candidates = messages.filter { $0.guidanceState == .queued }
        return prompts.map { prompt in
            guard let index = candidates.firstIndex(where: { $0.text == prompt }) else { return nil }
            return candidates.remove(at: index).id
        }
    }

    private func enqueueCurrent(_ prompt: String, atFront: Bool = false) {
        if atFront { queuedPrompts.insert(prompt, at: 0) }
        else { queuedPrompts.append(prompt) }
        if let currentID { claimedQueueConversations.insert(currentID) }
        let fallbackSelection = currentModelSelection
        updateCurrent {
            $0.queuedPrompts = queuedPrompts
            Self.stampLegacySelection(fallbackSelection, on: &$0)
        }
        let access = currentConversation?.modelSelection?.access ?? fallbackSelection.access
        let operationInFlight = ProviderAccountStore.shared.operation(for: access) != nil
        let evidence = ProviderSetupRecovery.runtimeEvidence(
            accountOperationInFlight: operationInFlight,
            runtimeIsReady: isRuntimeReady(access),
            runtimeIsUsable: isRuntimeUsable(access))
        if evidence == .rejected {
            reportBlockedQueuedWorkIfNeeded(for: access)
        } else if evidence == .waiting, !operationInFlight, !isRuntimeReady(access) {
            ensureRuntime(for: access)
        }
    }

    /// Reserve the exact FIFO head under a UUID before writing it. The visible string queue no
    /// longer exposes that item for editing/removal; failure restores that reservation exactly once.
    private func drainQueuedPrompt(for conversationID: UUID) {
        guard !store.isQueuePaused(conversationID),
              store.conversation(conversationID)?.pendingTurnPrompt == nil,
              store.conversation(conversationID)?
                .providerAccessRequest?.hasAuthenticationRecovery != true,
              !automaticQueueRetryIsBlocked(for: conversationID),
              !runningConvs.contains(conversationID),
              pendingTurnStartID(for: conversationID) == nil else { return }

        if store.usesSQLiteAuthority {
            reserveQueuedPromptAwaitingPersistence(for: conversationID) { [weak self] reservation in
                guard let self else { return }
                guard let reservation else { return }
                if !self.startReservedPrompt(reservation) {
                    self.restoreQueueReservation(reservation.id)
                }
            }
            return
        }

        guard let reservation = reserveQueuedPrompt(for: conversationID) else { return }
        if !startReservedPrompt(reservation) { restoreQueueReservation(reservation.id) }
    }

    private func startReservedPrompt(_ reservation: QueueReservation) -> Bool {
        let started: Bool
        if reservation.conversationID == currentID {
            started = performSend(
                reservation.prompt,
                origin: .queued(reservation.id))
        } else {
            started = backgroundSend(
                reservation.conversationID,
                reservation.prompt,
                origin: .queued(reservation.id))
        }
        return started
    }

    /// Pure generation/head check for the acknowledgement-timeout retry barrier. Exact prompt
    /// identity matters because editing/removing the recovered head is an explicit user decision;
    /// provider generation matters because a replacement process cannot still own the timed-out
    /// wire request.
    static func blocksAutomaticRecoveredPromptRetry(
        recoveredPrompt: String,
        queueHead: String?,
        timedOutAccess: ModelAccess,
        currentAccess: ModelAccess?,
        timedOutGeneration: UUID?,
        currentGeneration: UUID?
    ) -> Bool {
        queueHead == recoveredPrompt
            && currentAccess == timedOutAccess
            && currentGeneration == timedOutGeneration
    }

    private func automaticQueueRetryIsBlocked(for conversationID: UUID) -> Bool {
        guard let barrier = pendingStartRetryBarriers[conversationID] else { return false }
        let conversation = store.conversation(conversationID)
        let queueHead = conversationID == currentID
            ? queuedPrompts.first
            : conversation?.queuedPrompts.first
        let blocked = Self.blocksAutomaticRecoveredPromptRetry(
            recoveredPrompt: barrier.prompt,
            queueHead: queueHead,
            timedOutAccess: barrier.access,
            currentAccess: conversation?.modelSelection?.access ?? barrier.access,
            timedOutGeneration: barrier.runtimeGeneration,
            currentGeneration: runtimeGenerations[barrier.access])
        if !blocked {
            pendingStartRetryBarriers[conversationID] = nil
        }
        return blocked
    }

    private func scheduleCurrentQueueDrain() {
        guard let id = currentID else { return }
        DispatchQueue.main.async { [weak self] in self?.drainQueuedPrompt(for: id) }
    }

    /// When a provider lane becomes available, resume every idle queue that this bridge owns. A
    /// conversation currently shown/running in a window belongs to that bridge; otherwise the first
    /// compatible live bridge claims it. Main-actor serialization makes the provisional reservation
    /// atomic even though `runningConvs` changes only after agentd acknowledges the turn.
    private func drainRunnableQueues(for access: ModelAccess) {
        guard PersistedOperativeRecovery.canDrainQueues(
                storeIsReady: store.isReady,
                workspaceInventoryIsReady: didPrepareWorkspaceLaunchInventory,
                operativeStateWasAdopted: didAdoptPersistedOperativeState),
              isRuntimeUsable(access) else { return }
        for conversation in store.conversations where !conversation.queuedPrompts.isEmpty {
            guard conversation.modelSelection?.access == access,
                  !store.isQueuePaused(conversation.id),
                  !ActiveWorkspace.shared.runningConversations.contains(conversation.id),
                  !AgentBridge.live.allObjects.contains(where: {
                      $0.pendingTurnStartID(for: conversation.id) != nil
                  }) else { continue }
            if let owner = AgentBridge.owner(of: conversation.id) {
                guard owner === self else {
                    claimedQueueConversations.remove(conversation.id)
                    if owner.currentID == conversation.id {
                        owner.queuedPrompts = conversation.queuedPrompts
                    }
                    owner.ensureRuntime(for: access)
                    owner.scheduleRunnableQueueDrain(for: access)
                    continue
                }
            } else if let claimant = AgentBridge.live.allObjects.first(where: {
                $0.claimedQueueConversations.contains(conversation.id)
            }), claimant !== self {
                claimant.ensureRuntime(for: access)
                claimant.scheduleRunnableQueueDrain(for: access)
                continue
            }
            if conversation.id == currentID { queuedPrompts = conversation.queuedPrompts }
            drainQueuedPrompt(for: conversation.id)
        }
    }

    private func scheduleRunnableQueueDrain(for access: ModelAccess) {
        DispatchQueue.main.async { [weak self] in self?.drainRunnableQueues(for: access) }
    }

    // MARK: Provider-access requests

    /// Persist an agent-owned request without keeping its tool invocation alive. A conversation can
    /// carry one provider-family request at a time; repeated requests for that same family append
    /// their standalone tasks, while a conflicting family request fails closed instead of replacing
    /// work the user has not yet approved or cancelled.
    @discardableResult
    private func stageProviderAccessRequest(
        for conversationID: UUID,
        maker: ModelMaker,
        reason: String,
        prompts: [String],
        selectedAccess: ModelAccess? = nil,
        recoveryAccess: ModelAccess? = nil,
        recoveryPromptEntryID: UUID? = nil
    ) -> UUID? {
        guard selectedAccess == nil || selectedAccess?.maker == maker else { return nil }
        let normalizedReason = reason.trimmingCharacters(in: .whitespacesAndNewlines)
        let normalizedPrompts = prompts.compactMap { raw -> String? in
            let value = raw.trimmingCharacters(in: .whitespacesAndNewlines)
            return value.isEmpty ? nil : value
        }
        guard !normalizedPrompts.isEmpty else { return nil }
        let providerName = maker == .anthropic ? "Anthropic" : "OpenAI"
        let requestReason = normalizedReason.isEmpty
            ? "This work needs " + providerName + " access."
            : normalizedReason
        var acceptedID: UUID?
        store.update(conversationID) { conversation in
            acceptedID = conversation.stageProviderAccessRequest(
                maker: maker,
                reason: requestReason,
                resumePrompts: normalizedPrompts,
                selectedAccess: selectedAccess,
                recoveryAccess: recoveryAccess,
                recoveryPromptEntryID: recoveryPromptEntryID)
            guard acceptedID != nil else { return }
            if !AgentBridge.isActivelyWatched(conversationID) { conversation.unread = true }
        }
        guard let acceptedID else { return nil }
        if !AgentBridge.isActivelyWatched(conversationID) {
            NotificationManager.shared.notify(
                title: "Provider access needed",
                body: "Choose how Mechanician may connect to " + providerName + ".",
                conversationID: conversationID)
        }
        return acceptedID
    }

    /// Move a blocked queue into the durable request in the same store mutation. The request now
    /// owns those strings, so queue editing/cancellation cannot accidentally target a duplicate.
    @discardableResult
    private func parkBlockedQueuedWork(
        for conversationID: UUID,
        access: ModelAccess
    ) -> Bool {
        var didPark = false
        store.update(conversationID) { conversation in
            guard conversation.preserveQueuedPromptsForProviderAccess(
                access: access,
                requiresReconnect: ProviderAccountStore.shared.requiresReconnect(access)
            ) else { return }
            if !AgentBridge.isActivelyWatched(conversationID) { conversation.unread = true }
            didPark = true
        }
        guard didPark else { return false }
        claimedQueueConversations.remove(conversationID)
        // The authority mutation above moved these exact prompts into the provider request. Every
        // idle viewer must now project that canonical empty queue; otherwise a stale second window
        // can later fold its old queue snapshot back into the record and duplicate the preserved
        // work when provider recovery concatenates request prompts with ordinary queued prompts.
        synchronizeVisibleQueue(for: conversationID)
        return true
    }

    private func providerAccessRequest(
        from event: [String: Any]
    ) -> (maker: ModelMaker, reason: String, task: String, requestID: String?)? {
        let maker: ModelMaker
        switch ((event["maker"] as? String) ?? (event["provider"] as? String))?.lowercased() {
        case "anthropic": maker = .anthropic
        case "openai": maker = .openAI
        default: return nil
        }
        let task = (event["task"] as? String ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !task.isEmpty else { return nil }
        let reason = (event["reason"] as? String ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        return (maker, reason, task, event["reqId"] as? String)
    }

    private func acknowledgeProviderAccessRequest(
        _ requestID: String?,
        turnID: String,
        route: TurnRoute,
        accepted: Bool
    ) {
        guard let requestID, !requestID.isEmpty else { return }
        _ = write([
            "type": "provider_access_response",
            "id": turnID,
            "reqId": requestID,
            "accepted": accepted,
            "message": accepted
                ? "Provider access request preserved."
                : "Resolve the existing provider access request before requesting another provider.",
        ], to: InteractionRoute(turnID: turnID, route: route))
    }

    /// User chooses an account route; the agent never does. Merely choosing persists intent and
    /// starts/verifies that lane. Fulfillment remains gated on authoritative runtime usability.
    func chooseProviderAccessRequest(_ requestID: UUID, access: ModelAccess) {
        guard let conversationID = currentID else { return }
        var selected = false
        store.update(conversationID) { conversation in
            selected = conversation.selectProviderAccess(access, requestID: requestID)
        }
        guard selected else { return }
        _ = ensureRuntime(for: access)
        resumeProviderAccessRequests(for: access)
    }

    func cancelProviderAccessRequest(_ requestID: UUID) {
        guard let conversationID = currentID,
              let request = store.conversation(conversationID)?.providerAccessRequest,
              request.id == requestID else { return }
        var cancelled = false
        let updated = store.update(conversationID) { conversation in
            cancelled = conversation.cancelProviderAccess(requestID: requestID)
        }
        guard cancelled, let updated else { return }
        synchronizeVisibleQueue(for: conversationID)
        guard !updated.queuedPrompts.isEmpty else { return }

        // Authentication recovery deliberately fences newer FIFO work until its rejected root is
        // either recovered or cancelled. Cancelling removes that fence; if the current lane never
        // disconnected (an API authentication failure can do exactly that), no later ready event is
        // guaranteed to release the queue for us. Resume it now when possible, or make sure a cold
        // usable account gets the ordinary ready edge that will do so.
        claimedQueueConversations.insert(conversationID)
        let access = updated.modelSelection?.access ?? currentModelAccess
        if isRuntimeUsable(access) {
            scheduleCurrentQueueDrain()
        } else if ProviderAccountStore.shared.operation(for: access) == nil,
                  !ProviderAccountStore.shared.requiresReconnect(access),
                  !isRuntimeReady(access) {
            _ = ensureRuntime(for: access)
        }
    }

    /// Resume requests this bridge can safely own. The account and daemon must both be usable, the
    /// originating turn/delegates must be terminal, and the selected access must still match the
    /// requested provider family. Duplicate callbacks are harmless because fulfillment clears the
    /// request before scheduling its queue.
    func resumeProviderAccessRequests(for access: ModelAccess) {
        guard isRuntimeUsable(access),
              ProviderAccountStore.shared.operation(for: access) == nil else { return }
        let candidates = store.conversations.filter {
            $0.providerAccessRequest?.selectedAccess == access
        }
        for candidate in candidates {
            if let owner = AgentBridge.owner(of: candidate.id), owner !== self { continue }
            guard let request = candidate.providerAccessRequest,
                  !conversationHasReservedTurn(candidate.id),
                  !hasRunningDelegates(candidate.id),
                  (request.hasAuthenticationRecovery || candidate.queuedPrompts.isEmpty),
                  candidate.armedTrigger == nil,
                  candidate.pendingTurnPrompt == nil else { continue }
            let scope = access.maker == .anthropic ? turnCwd(for: candidate) : ""
            let modelID: String
            if let override = providerAccessModelIDOverridesForTesting[access] {
                modelID = override
            } else {
                let models = ModelCatalogStore.shared.entries(for: access, scope: scope)
                guard let selectedModel = models.first(where: { $0.isDefault }) ?? models.first else {
                    continue
                }
                modelID = selectedModel.selection.modelID
            }
            let previousAccess = candidate.modelSelection?.access
            var fulfilled = false
            store.update(candidate.id) { conversation in
                fulfilled = conversation.fulfillProviderAccess(
                    requestID: request.id, access: access, modelID: modelID)
            }
            guard fulfilled, let updated = store.conversation(candidate.id) else { continue }
            // A relaunch quarantines every persisted nonempty queue. Verified authentication
            // recovery is the explicit user-visible action that authorizes this one conversation's
            // rejected root and newer FIFO work to run; leaving its launch pause in place makes the
            // scheduled drain below a permanent no-op. Generic access requests never reach this
            // branch, and no other recovered conversation is released.
            if request.hasAuthenticationRecovery {
                _ = store.resumeQueue(candidate.id)
            }
            claimedQueueConversations.insert(candidate.id)
            let selection = updated.modelSelection ?? ModelSelection(access: access, modelID: modelID)
            for bridge in AgentBridge.live.allObjects where bridge.currentID == candidate.id {
                if let previousAccess,
                   bridge.pendingConversationLoads[previousAccess]?.conversationID == candidate.id {
                    bridge.pendingConversationLoads[previousAccess] = nil
                }
                bridge.pendingConversationLoads[selection.access] = nil
                bridge.adoptFulfilledProviderAccessState(updated)
                bridge.applyModelSelectionIfCompatible(selection)
                bridge.loadConversation(updated, cwd: updated.cwd, forceFresh: true)
            }
            scheduleRunnableQueueDrain(for: access)
        }
    }

    /// Converge a foreground viewer to the store mutation that rewound an authentication failure
    /// before any recovered queue item can start. The live transcript used to retain the rejected
    /// user/error pair; acknowledgement then appended a second user row and `persistCurrent`
    /// resurrected the pair the store had removed.
    func adoptFulfilledProviderAccessState(_ updated: Conversation) {
        guard currentID == updated.id else { return }
        assistantFlush?.cancel()
        assistantFlush = nil
        pendingAssistant = ""
        pendingAssistantFrame = nil
        pendingAssistantCaptureOrdinal = nil
        entries = updated.messages
        assistantIndex = nil
        openAssistantEntryByConversation[updated.id] = nil
        toolIndexByID.removeAll()
        toolImages.removeAll()
        permIndexByID.removeAll()
        questionIndexByID.removeAll()
        lastComposerPrewarm = nil
        queuedPrompts = updated.queuedPrompts
        stagePendingHistoryReplay(updated.messages, for: updated)
        clearLiveProviderSessionContext()
        restoreContextUsage(from: updated)
    }

    private static func resumeProviderAccessRequestsProcessWide(for access: ModelAccess) {
        for bridge in AgentBridge.live.allObjects {
            bridge.resumeProviderAccessRequests(for: access)
        }
    }

    private static func resumeReadyProviderAccessRequestsProcessWide() {
        for access in ModelAccess.selectableCases {
            resumeProviderAccessRequestsProcessWide(for: access)
        }
    }

    /// Only a verified, user-initiated Connect/Reconnect may pull focus back from the provider's
    /// browser. A direct Settings/onboarding action uses ordinary app activation so macOS restores
    /// its last app window; only a durable provider-access task forces one exact conversation.
    private func reactivateAfterVerifiedAccountConnection(for access: ModelAccess) {
        NSApp.activate(ignoringOtherApps: true)
        guard let conversation = ConversationStore.shared.conversations.first(where: {
            $0.providerAccessRequest?.selectedAccess == access
        }) else { return }
        if let owner = AgentBridge.owner(of: conversation.id), let window = owner.window {
            window.makeKeyAndOrderFront(nil)
        }
    }

    private func adoptPersistedProviderAccessRequests() {
        for conversation in store.conversations {
            guard let access = conversation.providerAccessRequest?.selectedAccess else { continue }
            _ = ensureRuntime(for: access)
        }
    }

    /// After a turn ends, run the next interjection or queued prompt.
    private func dispatchAfterTurn() {
        if let inj = pendingInterject {
            if performSend(inj) { pendingInterject = nil }
            else { pendingInterject = nil; enqueueCurrent(inj, atFront: true) }
        } else if autoResumePending, let p = pendingResume {
            if performSend(p) {
                autoResumePending = false
                pendingResume = nil
            } else {
                autoResumePending = false
                pendingResume = nil
                enqueueCurrent(p, atFront: true)
            }
        } else if let id = currentID {
            drainQueuedPrompt(for: id)
        }
    }

    @discardableResult
    private func performSend(
        _ trimmed: String,
        origin: TurnStartOrigin = .manual
    ) -> Bool {
        guard let conversationID = currentID, let conversation = currentConversation else { return false }
        if conversation.providerAccessRequest != nil,
           case .manual = origin {
            return false
        }
        let queuedReservation: QueueReservation?
        switch origin {
        case .committedRecovery(let committedID):
            guard committedID == conversationID,
                  conversation.pendingTurnPrompt == trimmed else { return false }
            queuedReservation = nil
        case .queued(let reservationID):
            // Queue reservation deliberately moves the FIFO head into this crash-recovery slot
            // before provider I/O. Only the exact in-memory reservation may consume that exact
            // durable prompt; every other origin still fails closed while a slot is occupied.
            guard let reservation = queueReservations[reservationID],
                  reservation.conversationID == conversationID,
                  reservation.prompt == trimmed,
                  conversation.pendingTurnPrompt == trimmed else { return false }
            queuedReservation = reservation
        case .manual, .review:
            guard conversation.pendingTurnPrompt == nil else { return false }
            queuedReservation = nil
        }
        guard !runningConvs.contains(conversationID),
              pendingTurnStartID(for: conversationID) == nil,
              !AgentBridge.live.allObjects.contains(where: {
                  $0 !== self && ($0.runningConvs.contains(conversationID)
                      || $0.pendingTurnStartID(for: conversationID) != nil)
              }) else { return false }
        let existingUserEntryID: UUID?
        if let reservation = queuedReservation {
            existingUserEntryID = reservation.existingUserEntryID
        } else {
            existingUserEntryID = nil
        }
        let priorSelection = conversation.modelSelection
        // Heal before the turn is built, not after it fails: an undeclared stamp 404s on every send,
        // so the only place that can rescue this conversation is ahead of the request.
        guard let healing = healStampedSelection(
            priorSelection ?? currentModelSelection, in: conversation) else { return false }
        let selection = healing.selection
        guard managedEnterprisePolicy?.turnBlockReason(for: selection.access) == nil else {
            return false
        }
        let toolProfile = Self.toolProfile(for: conversation)
        let mcpReadinessClaims: [MCPReadinessClaim]
        let mcpAuthorizationAttempts: [MCPPendingAuthorizationAttempt]
        let mcpAuthorizationPreparationInFlight: Bool
        if toolProfile.awaitsExternalExtensionReadiness {
            let extensions = ExtensionsStore.shared
            mcpReadinessClaims = extensions.pendingMCPReadinessClaims(for: selection.access)
            mcpAuthorizationAttempts = extensions.pendingMCPAuthorizationAttempts(
                for: selection.access)
            mcpAuthorizationPreparationInFlight = Self.hasMCPAuthorizationPreparation(
                for: selection.access)
        } else {
            mcpReadinessClaims = []
            mcpAuthorizationAttempts = []
            mcpAuthorizationPreparationInFlight = false
        }
        guard !MCPAuthorizationProviderExposurePolicy.isBlocked(
            preparationInFlight: mcpAuthorizationPreparationInFlight,
            hasPendingAttempt: !mcpAuthorizationAttempts.isEmpty
        ) else {
            appendSystem(
                "A connection change is still being verified for this provider. Mechanician will not send your message until that authorization is reconciled.")
            if !mcpAuthorizationAttempts.isEmpty {
                reconcilePendingMCPAuthorization(for: selection.access)
            }
            return false
        }
        let instructionResolution = workspaceInstructionResolution(
            for: conversation, selection: selection)
        let instructionSnapshot = instructionResolution.snapshot
        let sessionConfiguration = providerSessionConfigurationEnvelope(
            for: conversation,
            selection: selection,
            instructionSnapshot: instructionSnapshot,
            permissionMode: permissionMode)
        let extensionRevision = sessionConfiguration.revision
        let workspaceInstructionsRevision =
            sessionConfiguration.workspaceInstructionsRevision
        let resumableSessionID = (
            priorSelection == nil || healing.requiresFreshSession || !mcpReadinessClaims.isEmpty
                || !mcpAuthorizationAttempts.isEmpty
        ) ? nil : Self.resumableSessionID(
            for: conversation, access: selection.access, profile: TenantProfile.current,
            extensionRevision: extensionRevision,
            workspaceInstructionsRevision: workspaceInstructionsRevision,
            toolProfile: sessionConfiguration.toolProfile)
        // The caller stages an unavailable lane's prompt durably before starting it. That ordering
        // lets synchronous launch failures see and attribute the queue instead of stranding a prompt
        // that did not exist yet when process launch failed.
        guard isRuntimeUsable(selection.access) else { return false }
        revokeQueuedRepositoryWorkContextSources(availableConversationIDs: Set(
            pendingRepositoryWorkContextSources.compactMap { source in
                store.contains(source.conversationID) ? source.conversationID : nil
            }))
        let repositoryWorkContext: RepositoryWorkContextPacket?
        if pendingRepositoryWorkContextTargetID == conversationID,
           !pendingRepositoryWorkContextSources.isEmpty {
            guard let repositoryID = git.repositoryEvidence.repositoryIdentity else {
                appendSystem(
                    "Repository work context is still being verified. Refresh Changes, or remove the attachment before sending.")
                return false
            }
            let matchingSources = pendingRepositoryWorkContextSources.filter {
                $0.repositoryID == repositoryID
            }
            guard matchingSources.count == pendingRepositoryWorkContextSources.count,
                  let packet = repositoryWorkContextPacket(sources: matchingSources) else {
                appendSystem(
                    "Repository work context could not be attached without omitting evidence. Remove the Conversation attachment before sending; its packet exceeds the current size limit.")
                return false
            }
            repositoryWorkContext = packet
        } else {
            repositoryWorkContext = nil
        }
        let plannedCredentialEpoch = ProviderAccountStore.shared.credentialEpoch(
            for: selection.access)
        let plannedRuntimeGeneration = runtimeGenerations[selection.access]
        // A manual attempt takes ownership away from wait-mode even if the provider start later
        // needs to be recovered into the queue; otherwise the watcher could enqueue a duplicate
        // resume while this exact prompt is provisionally awaiting acknowledgement.
        if store.conversation(conversationID)?.armedTrigger != nil {
            store.update(conversationID) { $0.armedTrigger = nil }
            waitingConvs.remove(conversationID)
        }
        var userEntry = TranscriptEntry(kind: .user, text: trimmed)
        userEntry.imagePaths = Self.imagePaths(in: trimmed)
        userEntry = capturedTranscriptEntry(userEntry, conversationID: conversationID)
        let turnId = UUID().uuidString
        let claudePreferences = conversation.claudeSessionPreferences
        var route = TurnRoute(
            conversationID: conversationID,
            selection: selection,
            toolProfile: sessionConfiguration.toolProfile,
            permissionMode: permissionMode,
            extensionRevision: extensionRevision,
            claudePreferences: claudePreferences,
            workspaceInstructionsRevision: workspaceInstructionsRevision,
            rootPromptEntryID: existingUserEntryID ?? userEntry.id,
            mcpReadinessClaims: mcpReadinessClaims,
            mcpAuthorizationAttemptIDs: Set(mcpAuthorizationAttempts.map(\.id)))
        route.repositoryWorkContextConversationIDs =
            repositoryWorkContext?.delivery.conversationIDs ?? []
        route.repositoryWorkContextDelivery = repositoryWorkContext?.delivery
        stampToolSurfaceIdentity(
            on: &route,
            conversation: conversation,
            runtimeGeneration: plannedRuntimeGeneration,
            credentialEpoch: plannedCredentialEpoch)
        turnRoutes[turnId] = route
        let turnConfiguration = turnConfiguration(for: selection)
        let plannedHistory = pendingHistoryReplayPlan ?? replayFidelityPlan(
            entries,
            for: conversation,
            conversationID: conversationID)
        let priorHistory = pendingHistoryReplay ?? plannedHistory.providerPayload
        let needsFreshHistoryReplay = resumableSessionID == nil && !priorHistory.isEmpty
        let replayContinuationCategories = Self.continuationDiagnosticCategories(
            planned: plannedHistory,
            providerPayload: priorHistory,
            isFreshSessionReplay: needsFreshHistoryReplay)
        let baseProviderPrompt = Self.providerPrompt(
            from: trimmed,
            conversationID: conversationID,
            store: store)
        let providerPrompt: String
        if let repositoryWorkContext {
            providerPrompt = baseProviderPrompt + "\n\n" + repositoryWorkContext.prompt
        } else {
            providerPrompt = baseProviderPrompt
        }
        var req: [String: Any] = [
            "type": "send", "id": turnId, "prompt": providerPrompt,
            "model": selection.modelID,
            "permissionMode": permissionMode, "ultracode": turnConfiguration.ultracode,
            // Each turn is fully self-contained in the multi-stream daemon: it resumes
            // THIS conversation's session and runs in THIS conversation's folder, so
            // concurrent turns in different conversations never cross-wire.
            // A legacy conversation has no trustworthy provider identity for its opaque session.
            // Replay its durable transcript into a fresh session instead of guessing the lane.
            "sessionId": resumableSessionID ?? NSNull(),
            "convId": conversationID.uuidString,
            "cwd": turnCwd(for: conversation),
        ]
        if let catalogResolvedModel = catalogResolvedModelID(
            for: selection, conversation: conversation
        ) {
            req["catalogResolvedModel"] = catalogResolvedModel
        }
        if let effort = turnConfiguration.effort {
            req["effort"] = effort
        }
        if !mcpReadinessClaims.isEmpty {
            req["mcpReadinessClaims"] = mcpReadinessClaims.map(\.wireValue)
        }
        // Claude-only preferences stay nested so they can never leak into a Codex/OpenAI request.
        // Absent when every preference is default, which keeps this request identical to the release
        // that predates the option block.
        if let claude = claudePreferences.requestPayload(for: selection.access) {
            req["claude"] = claude
        }
        // OpenAI's privacy-preserving first implementation keeps continuity in the
        // app's durable transcript rather than a server-stored conversation. Claude
        // ignores this until it needs its existing stale-session replay fallback.
        let history = priorHistory + historyPayload([userEntry])
        if !history.isEmpty { req["history"] = history }
        if needsFreshHistoryReplay { req["replayHistory"] = true }
        Self.applyProviderSessionConfiguration(
            sessionConfiguration,
            instructionSnapshot: instructionSnapshot,
            access: selection.access,
            to: &req)
        // A `.starting` route participates in process-wide account exclusion immediately. Pair it
        // with the same visible, stoppable pending-start owner used after the daemon write before
        // crossing any asynchronous persistence fence. The provider acknowledgement timeout is
        // deliberately not armed until bytes reach agentd: SQLite owns its own bounded retries and
        // completion path, and a slow COMMIT must not be mistaken for an unacknowledged provider
        // request. Previously this route existed alone while SQLite committed: it blocked reconnect
        // and queued later prompts, yet Root showed no work and Stop had nothing it could retire.
        stagePendingTurnStart(
            turnID: turnId,
            route: route,
            prompt: trimmed,
            userEntry: existingUserEntryID == nil ? userEntry : nil,
            existingUserEntryID: existingUserEntryID,
            origin: origin,
            replayContinuationCategories: replayContinuationCategories,
            retiresSuggestedPrompt: false,
            armsProviderAcknowledgementTimeout: false)
        let dispatchPreparedTurn: () -> Bool = { [weak self] in
            guard let self,
                  self.turnRoutes[turnId]?.conversationID == route.conversationID else {
                return false
            }
            // The account can be demoted or replaced while the durability fence is waiting. Never
            // let its late completion write a request prepared for the old credential/runtime.
            guard ProviderAccountStore.shared.operation(for: selection.access) == nil,
                  ProviderAccountStore.shared.credentialEpoch(for: selection.access)
                    == plannedCredentialEpoch,
                  self.runtimeGenerations[selection.access] == plannedRuntimeGeneration,
                  self.isRuntimeUsable(selection.access) else {
                self.discardPendingTurnStartWithoutQueue(turnId)
                return false
            }
            guard self.write(req, to: selection.access) else {
                self.discardPendingTurnStartWithoutQueue(turnId)
                return false
            }
            self.clearPendingHistoryReplay()
            self.stagePendingTurnStart(
                turnID: turnId,
                route: route,
                prompt: trimmed,
                userEntry: existingUserEntryID == nil ? userEntry : nil,
                existingUserEntryID: existingUserEntryID,
                origin: origin,
                    replayContinuationCategories: replayContinuationCategories)
            return true
        }

        // Catalog healing changes both the serving model and the meaning of the opaque session.
        // `healStampedSelection` updates the resident authority value synchronously, but its save
        // is asynchronous. Queue reservations may already have committed under the old model, so
        // place an explicit file-first fence here: no daemon byte can escape until the healed model
        // and retired session are durably current. Revalidate after COMMIT so a newer picker click
        // wins without the stale healed request being sent.
        if healing.requiresFreshSession {
            var fenceApplies = false
            let deferredStore = store
            let quarantineDeferredDispatch: () -> Void = { [weak self] in
                if let self {
                    self.discardPendingTurnStartWithoutQueue(turnId)
                    if case .queued(let reservationID) = origin {
                        self.queueReservations[reservationID] = nil
                    }
                }
                Self.quarantineCommittedFreshRetryPrompt(
                    trimmed,
                    conversationID: conversationID,
                    store: deferredStore)
                self?.reportBlockedQueuedWorkIfNeeded(for: selection.access)
            }
            let staged = deferredStore.updateAwaitingPersistence(
                conversationID,
                { conversation in
                    fenceApplies = conversation.modelSelection == selection
                        && conversation.sdkSessionId == nil
                    if fenceApplies {
                        if SuggestedPromptFallback.shouldRetireExistingSuggestion(for: trimmed) {
                            conversation.suggestedPrompt = nil
                        }
                        if case .manual = origin {
                            conversation.pendingTurnPrompt = trimmed
                        }
                    }
                }
            ) { [weak self] committed in
                guard fenceApplies else { return }
                guard committed,
                      let self,
                      self.turnRoutes[turnId]?.conversationID == conversationID,
                      let canonical = deferredStore.conversation(conversationID),
                      canonical.modelSelection == selection,
                      canonical.sdkSessionId == nil,
                      canonical.pendingTurnPrompt == trimmed,
                      dispatchPreparedTurn() else {
                    quarantineDeferredDispatch()
                    return
                }
            }
            guard staged != nil, fenceApplies else {
                discardPendingTurnStartWithoutQueue(turnId)
                return false
            }
            return true
        }

        // Under SQLite authority, acceptance means COMMIT, not merely enqueueing work onto the
        // repository queue. The provider is unreachable until pendingTurnPrompt is recoverable
        // from library.db. Legacy keeps its existing synchronous staging/write ordering unchanged.
        if case .manual = origin, store.usesSQLiteAuthority {
            return stageManualPromptAwaitingPersistence(
                trimmed,
                conversationID: conversationID,
                selection: selection,
                turnID: turnId,
                dispatchPreparedTurn: dispatchPreparedTurn)
        }

        // A queued-origin send already crossed the same persistence fence while reserving its
        // head. Legacy manual sends preserve the prior sidecar staging behavior here.
        if case .manual = origin {
            updateCurrent {
                $0.pendingTurnPrompt = trimmed
                if SuggestedPromptFallback.shouldRetireExistingSuggestion(for: trimmed) {
                    $0.suggestedPrompt = nil
                }
            }
        }
        guard dispatchPreparedTurn() else {
            if case .manual = origin {
                updateCurrent { $0.pendingTurnPrompt = nil }
            }
            return false
        }
        return true
    }

    /// Keep an accepted manual prompt recoverable until its provider write takes ownership. The
    /// persistence waiter must not depend on the initiating window still existing: a window can close
    /// while SQLite is inside COMMIT, and abandoning that callback used to leave `pendingTurnPrompt`
    /// resident and block every other window until a full app relaunch healed it. A vanished owner now
    /// takes the same visible, paused quarantine path as Retry Fresh.
    @discardableResult
    private func stageManualPromptAwaitingPersistence(
        _ prompt: String,
        conversationID: UUID,
        selection: ModelSelection,
        turnID: String,
        dispatchPreparedTurn: @escaping () -> Bool,
        resolution: ((Bool) -> Void)? = nil
    ) -> Bool {
        let deferredStore = store
        let staged = deferredStore.updateAwaitingPersistence(
            conversationID,
            {
                $0.pendingTurnPrompt = prompt
                if SuggestedPromptFallback.shouldRetireExistingSuggestion(for: prompt) {
                    $0.suggestedPrompt = nil
                }
            }
        ) { [weak self] committed in
            guard let self else {
                Self.quarantineCommittedFreshRetryPrompt(
                    prompt,
                    conversationID: conversationID,
                    store: deferredStore)
                resolution?(false)
                return
            }
            guard committed, dispatchPreparedTurn() else {
                self.discardPendingTurnStartWithoutQueue(turnID)
                Self.quarantineCommittedFreshRetryPrompt(
                    prompt,
                    conversationID: conversationID,
                    store: deferredStore)
                self.reportBlockedQueuedWorkIfNeeded(for: selection.access)
                resolution?(false)
                return
            }
            resolution?(true)
        }
        if staged == nil { discardPendingTurnStartWithoutQueue(turnID) }
        return staged != nil
    }

#if DEBUG
    /// Deterministic owner-loss fixture for SQLite's COMMIT boundary. The production send path uses
    /// the same helper; tests supply a side-effect-free dispatch and then release the bridge while
    /// `ConversationStore.authorityCommitTestHook` holds the database transaction.
    func stageManualPromptForOwnerLossTesting(
        _ prompt: String,
        conversationID: UUID,
        selection: ModelSelection,
        resolution: @escaping (Bool) -> Void
    ) -> Bool {
        stageManualPromptAwaitingPersistence(
            prompt,
            conversationID: conversationID,
            selection: selection,
            turnID: "owner-loss-test",
            dispatchPreparedTurn: { true },
            resolution: resolution)
    }

    /// Exercise the production pre-COMMIT ownership invariant without launching agentd. A route
    /// that excludes account mutation must have a matching visible pending root before persistence
    /// can wait, and Stop must make its eventual COMMIT callback harmless.
    func stageBoundedManualPromptForPersistenceTesting(
        _ prompt: String,
        conversationID: UUID,
        selection: ModelSelection,
        dispatchSucceeds: Bool = true,
        resolution: @escaping (Bool) -> Void
    ) -> Bool {
        let turnID = "bounded-persistence-test-\(UUID().uuidString)"
        let route = TurnRoute(
            conversationID: conversationID,
            selection: selection,
            toolProfile: .standard,
            permissionMode: permissionMode)
        turnRoutes[turnID] = route
        var userEntry = TranscriptEntry(kind: .user, text: prompt)
        userEntry = capturedTranscriptEntry(userEntry, conversationID: conversationID)
        stagePendingTurnStart(
            turnID: turnID,
            route: route,
            prompt: prompt,
            userEntry: userEntry,
            origin: .manual,
            retiresSuggestedPrompt: false,
            armsProviderAcknowledgementTimeout: false)
        return stageManualPromptAwaitingPersistence(
            prompt,
            conversationID: conversationID,
            selection: selection,
            turnID: turnID,
            dispatchPreparedTurn: { [weak self] in
                guard let self, self.turnRoutes[turnID] != nil else { return false }
                self.discardPendingTurnStartWithoutQueue(turnID)
                return dispatchSucceeds
            },
            resolution: resolution)
    }

